update public.learning_topics set short_description='Learn first normal form through meaningful domains, repeating memberships, row identity and lossless relationship modeling, with concrete campus design exercises.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Learn first normal form through meaningful domains, repeating memberships, row identity and lossless relationship modeling, with concrete campus design exercises.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for 1NF.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-21-1nf' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-test-1nf-2','MCQ Test 2',category,10,10,'Application and scenarios for 1NF.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-21-1nf' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-1nf-1','pt-dbms-sql-21-1nf','Why does storing ''C1:Database Systems, C2:Operating Systems'' in a single Courses cell violate 1NF?','["Because the cell contains a colon character", "Because the cell holds multiple values (a repeating group) instead of one atomic value per attribute", "Because CourseName should never appear alongside CourseID", "Because the cell is too long"]'::jsonb,1,'1NF requires each cell to hold exactly one atomic value; packing multiple course memberships into one delimited string is a repeating group, the classic 1NF violation.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-1nf-2','pt-dbms-sql-21-1nf','How should independent unordered learner-skill memberships be represented in this model?','["One learner biography containing every code", "One LearnerSkills row per learner_id,skill_code membership", "A new skill column for each learner", "One global skill list without ownership"]'::jsonb,1,'Separate entity rows from membership rows and preserve the learner identity in each relationship.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-1nf-3','pt-dbms-sql-21-1nf','Can a table with one scalar domain value per cell still have partial or transitive dependency problems?','["No, all dependencies disappear", "Yes, first-normal-form shape alone does not establish 2NF or 3NF", "Only if no primary key exists", "Only if strings contain commas"]'::jsonb,1,'The shape test and higher dependency tests are separate. No historical course table is assumed.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-1nf-4','pt-dbms-sql-21-1nf','Why is skill1,skill2,skill3 a poor representation for an unbounded collection of independent memberships?','["Every numbered attribute is forbidden regardless of meaning", "It encodes repeating facts in fixed slots and makes collection growth require schema changes", "Three columns always violate every normal form", "The database cannot store a fourth row"]'::jsonb,1,'The problem is the repeated membership fact and arbitrary slot limit, not merely a number in a column name.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-1nf-5','pt-dbms-sql-21-1nf','For independently managed skill, phone and hobby memberships in this conventional relational model, which design is NOT a 1NF problem?','["A single cell holding ''Python, Java, SQL'' for a Skills attribute", "A StudentName column split into separate FirstName and LastName columns", "A single cell holding a JSON array of multiple phone numbers", "Three columns Hobby1, Hobby2, Hobby3 used to store a variable number of hobbies"]'::jsonb,1,'Splitting a name into FirstName/LastName is a granularity design choice, not a 1NF issue — each of those columns still holds one atomic value. The other three options all encode multiple values of one conceptual attribute.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-1nf-6','pt-dbms-sql-21-1nf','Why does an ordinary foreign key on a delimited skill-list column not validate each embedded skill separately?','["Foreign keys cannot reference strings", "It compares the whole column value, not every parsed list element", "Every comma is automatically a foreign key", "Foreign keys validate every substring automatically"]'::jsonb,1,'Independent membership values allow ordinary relational references to validate the intended individual codes.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-1nf-7','pt-dbms-sql-21-1nf','What is the core requirement of First Normal Form?','["Every non-key attribute must depend on the whole key", "Every attribute value in every row must be atomic (single-valued), with no repeating groups", "Every determinant must be a candidate key", "There must be no transitive dependencies"]'::jsonb,1,'1NF''s sole concern is atomicity of values — the whole-key and transitive-dependency conditions belong to 2NF and 3NF respectively, which are separate, additional requirements.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-1nf-8','pt-dbms-sql-21-1nf','After converting the BEFORE table (one row per student, comma-separated courses) into the AFTER table (one row per student-course pair), what new capability is gained?','["The ability to store more students", "The ability to run a simple, indexable query like WHERE CourseID = ''C1'' to find all students in that course, and to enforce a real foreign key into a Course table", "Automatic removal of all update anomalies", "The elimination of the need for a primary key"]'::jsonb,1,'Achieving 1NF makes each course membership an atomic, queryable, indexable, and foreign-key-able value — but it does NOT by itself remove the update/insertion/deletion anomalies, which need 2NF/3NF.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-1nf-9','pt-dbms-sql-21-1nf','What is the strongest reason to separate learner skills into rows?','["Each membership is independently queried and constrained", "Every comma is forbidden in SQL", "Strings can never be domain values", "A date must be split into characters"]'::jsonb,0,'The independent fact determines the relational shape.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-1nf-10','pt-dbms-sql-21-1nf','Does a comma in a biography necessarily violate 1NF?','["Yes always", "No", "Only when an index exists", "Only in MySQL"]'::jsonb,1,'One document value differs from a hidden collection of relationships.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-1nf-11','cx-test-1nf-2','A learner adds a fourth independently managed skill after the old design reached skill1,skill2,skill3. What does the relationship-row design allow?','["Drop an earlier skill to reuse its slot", "Add a fourth permanent column for every learner", "Add one membership row without changing the schema", "Store the extra skill in the learner name"]'::jsonb,2,'A row-per-membership design lets collection size grow as facts, while fixed slots tie capacity to the schema.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-1nf-12','cx-test-1nf-2','What does a learner with no memberships require?','["Deleting the learner", "A fake SQL skill", "One NULL skill row for every possible code", "A learner row and no membership rows"]'::jsonb,3,'Entity existence is separate from membership existence.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-1nf-13','cx-test-1nf-2','When is learner_id,skill_code a suitable candidate key?','["When at most one such membership is allowed", "Whenever the columns are printed first", "Even when repeated awards are separate events", "Only if skill codes are numeric"]'::jsonb,0,'Key choice follows permitted multiplicity.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-1nf-14','cx-test-1nf-2','What can a surrogate row ID fail to prevent?','["Identification of a stored row", "Duplicate business memberships", "Every possible query", "All foreign keys"]'::jsonb,1,'A row identifier is not automatically business-pair uniqueness.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-1nf-15','cx-test-1nf-2','Why carry learner_id into membership rows?','["To sort skill names automatically", "To replace every other key", "To preserve ownership of each relationship", "To prohibit empty memberships"]'::jsonb,2,'Without the relationship key reconstruction loses the original associations.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-1nf-16','cx-test-1nf-2','Does 1NF eliminate every update anomaly?','["Yes, every dependency is resolved", "Only when SELECT * is used", "Only with integer IDs", "No"]'::jsonb,3,'Higher normal forms examine additional dependencies.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
