if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-2nf-1' and (question_text,options,correct_index,explanation) is distinct from ('Why is the original StudentCourse table NOT in 2NF?','["Because it contains a comma-separated list", "Because non-key attributes like StudentName and CourseName are only partially dependent on the composite key {StudentID, CourseID}, not fully dependent on the whole key", "Because it lacks a primary key entirely", "Because InstructorOffice is nullable"]'::jsonb,1,'2NF requires every non-key attribute to be fully dependent on the whole key; here, StudentName depends on StudentID alone and CourseName on CourseID alone, both partial dependencies.') and (question_text,options,correct_index,explanation) is distinct from ('Why is the original StudentCourse table NOT in 2NF?','["Because it contains a comma-separated list", "Because non-key attributes like StudentName and CourseName are only partially dependent on the composite key {StudentID, CourseID}, not fully dependent on the whole key", "Because it lacks a primary key entirely", "Because InstructorOffice is nullable"]'::jsonb,1,'2NF requires every non-key attribute to be fully dependent on the whole key; here, StudentName depends on StudentID alone and CourseName on CourseID alone, both partial dependencies.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-2nf-1'; end if;
