if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-2nf-2' and (question_text,options,correct_index,explanation) is distinct from ('Which decomposition correctly achieves 2NF for StudentCourse?','["Merging all attributes into one wider table with more indexes", "Student(StudentID, StudentName), Course(CourseID, CourseName, InstructorID, InstructorName, InstructorOffice), Enrollment(StudentID, CourseID, EnrollmentDate)", "Simply removing the EnrollmentDate column", "Sorting the table by StudentID"]'::jsonb,1,'Each partially-dependent attribute is relocated to a relation keyed by exactly the subset of the key it truly depends on, leaving only the fully-dependent EnrollmentDate with the composite key.') and (question_text,options,correct_index,explanation) is distinct from ('Which decomposition correctly achieves 2NF for StudentCourse?','["Merging all attributes into one wider table with more indexes", "Student(StudentID, StudentName), Course(CourseID, CourseName, InstructorID, InstructorName, InstructorOffice), Enrollment(StudentID, CourseID, EnrollmentDate)", "Simply removing the EnrollmentDate column", "Sorting the table by StudentID"]'::jsonb,1,'Each partially-dependent attribute is relocated to a relation keyed by exactly the subset of the key it truly depends on, leaving only the fully-dependent EnrollmentDate with the composite key.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-2nf-2'; end if;
