if not exists(select 1 from public.test_questions where id='tq-dbms-sql-21-2nf-3' and test_id='pt-dbms-sql-21-2nf') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-21-2nf-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-2nf-3' and (question_text,options,correct_index,explanation) is distinct from ('Why is a relation with a single-attribute primary key automatically in 2NF once it satisfies 1NF?','["Because single-attribute keys never have functional dependencies", "Because partial dependency requires a proper non-empty subset of the key to test against, which a single-attribute key does not have", "Because 2NF only applies to relations with more than 5 attributes", "Because single-attribute keys are always surrogate keys"]'::jsonb,1,'Partial dependency is only possible relative to a composite key''s subsets; with just one key attribute, there is nothing smaller to be ''partially'' dependent on.') and (question_text,options,correct_index,explanation) is distinct from ('If every candidate key is a singleton and no nontrivial empty-determinant dependencies apply, why is ordinary partial-key violation absent?','["Singleton keys have no functional dependencies", "No candidate key has a proper nonempty subset that can determine a nonprime attribute", "2NF applies only above five columns", "Singleton keys are always surrogate"]'::jsonb,1,'A singleton PRIMARY KEY alone is not enough if another composite candidate key exists. The all-key and empty-determinant assumptions scope the statement.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-2nf-3'; end if;
