if not exists(select 1 from public.test_questions where id='tq-dbms-sql-21-2nf-4' and test_id='pt-dbms-sql-21-2nf') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-21-2nf-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-2nf-4' and (question_text,options,correct_index,explanation) is distinct from ('After the 2NF decomposition, is the new Course(CourseID, CourseName, InstructorID, InstructorName, InstructorOffice) relation itself in 2NF?','["No, because InstructorOffice still causes a partial dependency", "Yes \u2014 CourseID is a single-attribute key here, so partial dependency is impossible; but it still has a transitive dependency issue that 2NF doesn''t address", "No, because it now has too many attributes", "Yes, and it has no remaining design issues of any kind"]'::jsonb,1,'2NF is satisfied since the key is single-attribute (no partial dependency possible), but InstructorName/InstructorOffice are reached transitively through InstructorID — a separate issue that 3NF targets.') and (question_text,options,correct_index,explanation) is distinct from ('After the 2NF decomposition, is the new Course(CourseID, CourseName, InstructorID, InstructorName, InstructorOffice) relation itself in 2NF?','["No, because InstructorOffice still causes a partial dependency", "Yes \u2014 CourseID is a single-attribute key here, so partial dependency is impossible; but it still has a transitive dependency issue that 2NF doesn''t address", "No, because it now has too many attributes", "Yes, and it has no remaining design issues of any kind"]'::jsonb,1,'Under the stated dependencies CourseID is the only candidate key and no empty determinant applies, so the relation is 2NF. InstructorID still creates a transitive issue that later normalization addresses.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-2nf-4'; end if;
