if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-3nf-1' and (question_text,options,correct_index,explanation) is distinct from ('Why is Course(CourseID, CourseName, InstructorID, InstructorName, InstructorOffice) NOT in 3NF, even though it is in 2NF?','["Because CourseID is not unique", "Because InstructorName and InstructorOffice are transitively dependent on CourseID via the non-key attribute InstructorID", "Because it has too many columns", "Because CourseName is nullable"]'::jsonb,1,'2NF only rules out partial dependency; the transitive chain CourseID -> InstructorID -> InstructorOffice remains, which specifically violates 3NF.') and (question_text,options,correct_index,explanation) is distinct from ('Course has CourseID as its only candidate key, CourseID → CourseName, InstructorID and InstructorID → InstructorName, InstructorOffice. Why is it in 2NF but not 3NF?','["Because CourseID is not unique", "InstructorName and InstructorOffice depend on the nonkey determinant InstructorID", "Because it has too many columns", "Because CourseName is nullable"]'::jsonb,1,'The single attribute key avoids partial dependencies, but InstructorID is not a superkey and its dependent name and office are nonprime.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-3nf-1'; end if;
