if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-3nf-3' and (question_text,options,correct_index,explanation) is distinct from ('In the formal 3NF condition ''for every FD X -> Y, X is a superkey OR Y consists only of prime attributes,'' what is the second clause specifically meant to permit?','["Any transitive dependency whatsoever", "Certain FDs to a prime (candidate-key-participating) attribute to be allowed even when X is not a superkey, avoiding unnecessary over-decomposition in schemas with overlapping candidate keys", "Composite keys to be split into single attributes", "All non-key attributes to be treated as if they were keys"]'::jsonb,1,'This escape clause is precisely what 3NF relaxes compared to BCNF — it tolerates certain dependencies into prime attributes that BCNF would still flag as violations.') and (question_text,options,correct_index,explanation) is distinct from ('In the formal 3NF condition ''for every FD X -> Y, X is a superkey OR Y consists only of prime attributes, '' what is the second clause specifically meant to permit?','["Any transitive dependency whatsoever", "Certain FDs to a prime (candidate-key-participating) attribute to be allowed even when X is not a superkey, avoiding unnecessary over-decomposition in schemas with overlapping candidate keys", "Composite keys to be split into single attributes", "All non-key attributes to be treated as if they were keys"]'::jsonb,1,'This escape clause is precisely what 3NF relaxes compared to BCNF — it tolerates certain dependencies into prime attributes that BCNF would still flag as violations.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-3nf-3'; end if;
