update public.learning_topics set short_description='Understand third normal form through candidate keys, transitive dependencies, lossless decomposition, and a worked mentor assignment design.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Understand third normal form through candidate keys, transitive dependencies, lossless decomposition, and a worked mentor assignment design.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for 3NF.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-21-3nf' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-3nf-application','MCQ Test 2',category,10,10,'Application and scenarios for 3NF.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-21-3nf' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-3nf-1','pt-dbms-sql-21-3nf','Course has CourseID as its only candidate key, CourseID → CourseName, InstructorID and InstructorID → InstructorName, InstructorOffice. Why is it in 2NF but not 3NF?','["Because CourseID is not unique", "InstructorName and InstructorOffice depend on the nonkey determinant InstructorID", "Because it has too many columns", "Because CourseName is nullable"]'::jsonb,1,'The single attribute key avoids partial dependencies, but InstructorID is not a superkey and its dependent name and office are nonprime.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-3nf-2','pt-dbms-sql-21-3nf','For Course(CourseID, CourseName, InstructorID, InstructorName, InstructorOffice), with CourseID → CourseName, InstructorID and InstructorID → InstructorName, InstructorOffice, which decomposition removes the instructor detail dependency?','["Merging Course and Enrollment into one table", "Instructor(InstructorID, InstructorName, InstructorOffice) and Course(CourseID, CourseName, InstructorID), referencing Instructor", "Removing InstructorID from Course entirely with no replacement", "Adding a composite key of CourseID and InstructorID to Course"]'::jsonb,1,'The office and name belong under InstructorID; course identity and its instructor reference remain under CourseID.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-3nf-3','pt-dbms-sql-21-3nf','In the formal 3NF condition ''for every FD X -> Y, X is a superkey OR Y consists only of prime attributes, '' what is the second clause specifically meant to permit?','["Any transitive dependency whatsoever", "Certain FDs to a prime (candidate-key-participating) attribute to be allowed even when X is not a superkey, avoiding unnecessary over-decomposition in schemas with overlapping candidate keys", "Composite keys to be split into single attributes", "All non-key attributes to be treated as if they were keys"]'::jsonb,1,'This escape clause is precisely what 3NF relaxes compared to BCNF — it tolerates certain dependencies into prime attributes that BCNF would still flag as violations.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-3nf-4','pt-dbms-sql-21-3nf','Instructor(InstructorID, Name, Office) exists independently, and Course references it. Can a new instructor with no assigned course be recorded?','["It is still impossible, since Course requires an InstructorID", "Yes, insert one Instructor row without requiring a Course or Enrollment row", "He must first be added as a placeholder student", "He can only be added by an administrator with special privileges"]'::jsonb,1,'The independent Instructor relation stores the instructor fact before any course assignment exists.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-3nf-5','pt-dbms-sql-21-3nf','Why can a dependency-preserving 3NF design be useful when choosing between 3NF and BCNF decompositions?','["Because it is the only normal form that actually exists in practice", "3NF synthesis can preserve dependencies locally, while a BCNF decomposition may lose dependency preservation", "Because SQL databases cannot enforce normal forms beyond 3NF", "Because 3NF requires fewer tables than 1NF"]'::jsonb,1,'The trade off is constraint preservation; 3NF does not universally eliminate every possible anomaly, and stricter normal forms are not merely rare exceptions.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-3nf-6','pt-dbms-sql-21-3nf','Each current office is stored once in Instructor(InstructorID, Name, Office), keyed by InstructorID. How many rows must change when one instructor moves?','["One row in Instructor", "Three rows, one per course he teaches", "Zero rows, since offices cannot be changed", "All rows in the Enrollment table"]'::jsonb,0,'The office fact has one authoritative row for the specified instructor under this declared design.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-3nf-7','pt-dbms-sql-21-3nf','Student, Course, and Instructor facts are stored independently, with Enrollment storing only their relationship. What happens to the previously illustrated anomalies caused by repeating those independent facts in Enrollment?','["All three anomalies (insertion, update, deletion) from 21.2-21.4 still remain", "Those specific insertion, update, and deletion anomalies are removed by this declared decomposition", "Only the deletion anomaly remains", "Only the insertion anomaly remains"]'::jsonb,1,'The claim concerns the specified duplicated student, course, and instructor facts; it is not a universal assertion that every 3NF design has no anomalies.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-3nf-8','pt-dbms-sql-21-3nf','In Course(CourseID, CourseName, InstructorID, InstructorName, InstructorOffice), CourseID is the only candidate key and an instructor can teach many courses. If InstructorID determines only instructor name and office, is InstructorID a superkey?','["Yes, because it determines InstructorName and InstructorOffice", "No, it does not determine CourseID or CourseName", "Yes, because it is a foreign key", "No, because InstructorID is never functionally dependent on anything"]'::jsonb,1,'Its closure lacks course identity and course name, so InstructorID does not determine every attribute.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-3nf-fundamentals-9','pt-dbms-sql-21-3nf','Which fact establishes a functional dependency in a design?','["A rule holding in every valid state", "Three coincidentally matching sample rows", "The physical ordering of rows", "The name of a column"]'::jsonb,0,'Functional dependencies express constraints over valid states, not accidental sample patterns.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-3nf-fundamentals-10','pt-dbms-sql-21-3nf','In Assignment(student, mentor, office), student determines mentor and mentor determines office. Why split it?','["Every table must have two columns", "Office depends on a nonkey mentor determinant", "All foreign keys violate 3NF", "A single column key violates 2NF"]'::jsonb,1,'Mentor is not a superkey and office is nonprime under the stated rules.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-3nf-application-1','cx-3nf-application','What is a prime attribute?','["Only the first primary key column", "An attribute belonging to any candidate key", "Any integer column", "Any foreign key column"]'::jsonb,1,'Prime membership considers every candidate key.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-3nf-application-2','cx-3nf-application','For each nontrivial X → A, which condition permits 3NF?','["X must always be a single column", "A must always be nonprime", "X is a superkey or A is prime", "X must be a foreign key"]'::jsonb,2,'The formal 3NF rule includes the prime attribute alternative.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-3nf-application-3','cx-3nf-application','Does adding a surrogate identifier remove instructor → course?','["Yes, all dependencies disappear", "Yes, if its type is integer", "Only if rows are sorted", "No, the business dependency remains"]'::jsonb,3,'A new identifier does not alter the original business rule.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-3nf-application-4','cx-3nf-application','Why is the mentor decomposition lossless?','["The common mentor identifier is a key of MentorOffice", "The tables have equal row counts", "Both names contain mentor", "There are exactly two tables"]'::jsonb,0,'A common attribute determining one side supports the binary lossless join test.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-3nf-application-5','cx-3nf-application','What does dependency preservation allow?','["Avoiding every join query forever", "Checking original dependencies locally in decomposed relations", "Removing all foreign keys", "Guaranteeing faster reads"]'::jsonb,1,'Preservation concerns constraint enforcement without joining the pieces.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-3nf-application-6','cx-3nf-application','For R(A, B, C) with AB → C and C → B, which pair is also a candidate key?','["BC", "B alone", "AC", "C alone"]'::jsonb,2,'AC determines B through C, so it determines all attributes and is minimal.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-3nf-application-7','cx-3nf-application','Why can R(A, B, C), AB → C and C → B, be 3NF but fail BCNF?','["B is nonprime while C is a superkey", "3NF forbids all composite keys", "BCNF permits only one key", "B is prime while C is not a superkey"]'::jsonb,3,'The prime attribute exception admits C → B in 3NF.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-3nf-application-8','cx-3nf-application','What should a synthesis procedure add if no generated relation contains an original candidate key?','["A relation containing a candidate key", "A duplicate of every relation", "A nullable office field everywhere", "A random single attribute table"]'::jsonb,0,'A key relation is part of the classical synthesis lossless guarantee.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-3nf-application-9','cx-3nf-application','Which assumption would invalidate mentor_id → current_office?','["Several students share a mentor", "One mentor can have several current offices", "An office name contains spaces", "The mentor identifier is indexed"]'::jsonb,1,'Multiple current office values for one mentor contradict the dependency.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-3nf-application-10','cx-3nf-application','What should happen before declaring a normalized schema ready?','["Assume sample uniqueness proves all keys", "Delete all reporting views", "Check dependencies, reconstruction, and business scenarios", "Remove every repeated identifier"]'::jsonb,2,'Normal form classification is only one part of a correct schema design.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
