if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-4nf-1' and (question_text,options,correct_index,explanation) is distinct from ('Why does StudentContact(StudentID, Hobby, PhoneNumber) require 4 rows for a student with 2 hobbies and 2 phone numbers?','["Because the database engine requires at least 4 rows per student", "Because combining two independent multi-valued facts in one table forces a spurious cross-product of every hobby with every phone number, even though they have no real connection", "Because Hobby and PhoneNumber must always be paired one-to-one", "Because StudentID is not unique"]'::jsonb,1,'Since hobbies and phone numbers are independent facts about the student, the relational model is forced to enumerate every combination to represent ''both facts are true,'' producing a spurious cross-product.') and (question_text,options,correct_index,explanation) is distinct from ('Under the independence rule and a complete nonnull triple representation, why do two hobbies and two phone numbers yield four rows?','["Because the database engine requires at least 4 rows per student", "Every hobby combines with every phone under the declared MVD, redundantly representing the two independent lists", "Because Hobby and PhoneNumber must always be paired one-to-one", "Because StudentID is not unique"]'::jsonb,1,'The four combinations are required under that interpretation; they are not separately selected hobby-phone permissions.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-4nf-1'; end if;
