if not exists(select 1 from public.test_questions where id='tq-dbms-sql-21-4nf-2' and test_id='pt-dbms-sql-21-4nf') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-21-4nf-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-4nf-2' and (question_text,options,correct_index,explanation) is distinct from ('Is StudentContact(StudentID, Hobby, PhoneNumber) in BCNF?','["No, because its only key is not a superkey", "Yes \u2014 its only candidate key is the full {StudentID, Hobby, PhoneNumber}, which is trivially a superkey, yet the design is still badly flawed", "No, because it has a transitive dependency", "Yes, but only because it has no functional dependencies at all"]'::jsonb,1,'Since every attribute is needed to uniquely identify a row, the whole-attribute set is the only key, trivially satisfying BCNF — this shows that BCNF alone does not catch multi-valued dependency problems; that requires 4NF.') and (question_text,options,correct_index,explanation) is distinct from ('Assume Contact(Student,Hobby,Phone) has no nontrivial functional dependencies and only its full triple is a candidate key. Does it satisfy BCNF?','["No, because its only key is not a superkey", "Yes \u2014 its only candidate key is the full {StudentID, Hobby, PhoneNumber}, which is trivially a superkey, yet the design is still badly flawed", "No, because it has a transitive dependency", "Yes, but only because it has no functional dependencies at all"]'::jsonb,1,'Every nontrivial FD has a superkey determinant vacuously because none are assumed. This does not establish4NF when a nonsuperkey Student has a nontrivial MVD.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-4nf-2'; end if;
