if not exists(select 1 from public.test_questions where id='tq-dbms-sql-21-4nf-3' and test_id='pt-dbms-sql-21-4nf') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-21-4nf-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-4nf-3' and (question_text,options,correct_index,explanation) is distinct from ('What is the correct 4NF decomposition of StudentContact?','["Keep it as one table but add a UNIQUE constraint", "Split into StudentHobby(StudentID, Hobby) and StudentPhone(StudentID, PhoneNumber), separating the two independent multi-valued facts", "Merge Hobby and PhoneNumber into a single combined column", "Add a fourth attribute to disambiguate the pairing"]'::jsonb,1,'Since hobbies and phone numbers are independent facts about a student, each gets its own relation keyed by StudentID plus that one fact, eliminating the spurious cross-product.') and (question_text,options,correct_index,explanation) is distinct from ('What is the correct 4NF decomposition of StudentContact?','["Keep it as one table but add a UNIQUE constraint", "Split into StudentHobby(StudentID, Hobby) and StudentPhone(StudentID, PhoneNumber), separating the two independent multi-valued facts", "Merge Hobby and PhoneNumber into a single combined column", "Add a fourth attribute to disambiguate the pairing"]'::jsonb,1,'Since hobbies and phone numbers are independent facts about a student, each gets its own relation keyed by StudentID plus that one fact, eliminating the spurious cross-product.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-4nf-3'; end if;
