if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-4nf-5' and (question_text,options,correct_index,explanation) is distinct from ('What formally defines a multi-valued dependency X ->> Y?','["X and Y must always be the same data type", "For a given value of X, the set of Y values associated with it is independent of any other attribute in the relation", "X must be a foreign key referencing Y", "Y must always be a single atomic value"]'::jsonb,1,'An MVD captures that Y''s multiple values for a given X don''t depend on any other attribute present — which is exactly what causes the spurious cross-product when two such MVDs are combined in one table.') and (question_text,options,correct_index,explanation) is distinct from ('What formally defines a multi-valued dependency X ->> Y?','["X and Y must always be the same data type", "For a fixed X, the Y values vary independently of the remaining attributes outside X and Y", "X must be a foreign key referencing Y", "Y must always be a single atomic value"]'::jsonb,1,'Independence is relative to the specified attribute partition of the full relation.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-4nf-5'; end if;
