if not exists(select 1 from public.test_questions where id='tq-dbms-sql-21-4nf-6' and test_id='pt-dbms-sql-21-4nf') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-21-4nf-6'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-4nf-6' and (question_text,options,correct_index,explanation) is distinct from ('Would StudentHobby(StudentID, Hobby) alone, with no PhoneNumber column, be a 4NF violation?','["Yes, any multi-valued attribute always violates 4NF", "No \u2014 a single multi-valued fact about an entity is just a normal one-to-many relationship; 4NF violations require two or more INDEPENDENT multi-valued facts combined in the same table", "Yes, because Hobby is not atomic", "No, because 4NF only applies to numeric attributes"]'::jsonb,1,'4NF''s concern is specifically about combining multiple independent multi-valued facts, causing a cross-product; a single multi-valued attribute in its own table is unproblematic and normal.') and (question_text,options,correct_index,explanation) is distinct from ('Would StudentHobby(StudentID, Hobby) alone, with no PhoneNumber column, be a 4NF violation?','["Yes, any multi-valued attribute always violates 4NF", "No under the stated binary model: Student multivalued-determines Hobby is trivial because together they cover the relation", "Yes, because Hobby is not atomic", "No, because 4NF only applies to numeric attributes"]'::jsonb,1,'The formal nontrivial-MVD/superkey test governs4NF; do not replace it with a universal count of visible collection columns.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-4nf-6'; end if;
