if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-4nf-8' and (question_text,options,correct_index,explanation) is distinct from ('Which of the following best summarizes the telltale symptom that signals a 4NF violation?','["The table has a composite primary key", "The row count for an entity multiplies as the cross-product of two or more independent multi-valued facts, even though those facts have no real connection to each other", "The table contains a NULL value", "The table has more than three columns"]'::jsonb,1,'The defining red flag is the cross-product row explosion (e.g., 2 hobbies x 2 phones = 4 rows) representing facts that are logically unrelated to each other.') and (question_text,options,correct_index,explanation) is distinct from ('Which of the following best summarizes the telltale symptom that signals a 4NF violation?','["The table has a composite primary key", "The row count for an entity multiplies as the cross-product of two or more independent multi-valued facts, even though those facts have no real connection to each other", "The table contains a NULL value", "The table has more than three columns"]'::jsonb,1,'The defining red flag is the cross-product row explosion (e.g., 2 hobbies x 2 phones = 4 rows) representing facts that are logically unrelated to each other.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-4nf-8'; end if;
