if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-5nf-2' and (question_text,options,correct_index,explanation) is distinct from ('How commonly do real-world production schemas encounter a genuine 5NF violation, according to standard practice?','["Extremely commonly \u2014 nearly every schema needs a 5NF pass", "Very rarely \u2014 5NF issues require a specific irreducible three-way interdependency that most everyday schemas never produce", "Only in schemas without foreign keys", "5NF violations are more common than 1NF violations"]'::jsonb,1,'5NF is the most advanced and least frequently needed normal form; genuine irreducible three-way join dependencies are uncommon in typical business schemas.') and (question_text,options,correct_index,explanation) is distinct from ('What is another name for5NF?','["Primary-index form", "Project-join normal form", "Pair-only normal form", "Null-free form"]'::jsonb,1,'The name emphasizes projection and reconstruction by join.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-5nf-2'; end if;
