insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-acid-4','pt-dbms-sql-22-acid','Is ACID''s ''Consistency'' the same concept as the ''Consistency'' in the CAP theorem?','["Yes, identical concepts", "No: ACID consistency concerns valid-state invariants, while CAP consistency is generally linearizability", "CAP theorem doesn''t have a Consistency concept", "ACID Consistency only applies to distributed databases"]'::jsonb,1,'Linearizability describes observations appearing to occur at a single point between invocation and response, rather than merely eventual replica agreement.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-acid-5','pt-dbms-sql-22-acid','Why is choosing a transactional storage engine a prerequisite for ACID guarantees?','["It isn''t actually required", "Multi-statement rollback requires transaction-capable participants; a nontransactional table is outside that guarantee", "ACID guarantees are provided by the SQL language itself, independent of storage engine", "Only Consistency requires a transactional engine"]'::jsonb,1,'ACID is only meaningful when the underlying engine actually implements transaction support.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-acid-6','pt-dbms-sql-22-acid','How do Atomicity and Consistency interact?','["They are completely unrelated", "Atomicity partly enables Consistency — an incomplete (non-atomic) update could leave the database in an invalid, inconsistent state", "Consistency makes Atomicity unnecessary", "They are exact synonyms"]'::jsonb,1,'The four ACID properties aren''t fully independent — atomicity helps guarantee consistency is achievable.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
