update public.learning_topics set short_description='Choose advanced index structures through B+ tree fan-out, composite key access, skip scan limits, and engine-specific bitmap, spatial, and full-text labs.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Choose advanced index structures through B+ tree fan-out, composite key access, skip scan limits, and engine-specific bitmap, spatial, and full-text labs.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Advanced Index Selection Lab.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='cx-advanced-index-selection-lab-fundamentals' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-advanced-index-selection-lab-application','MCQ Test 2',category,10,10,'Application and scenarios for Advanced Index Selection Lab.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='cx-advanced-index-selection-lab-fundamentals' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-advanced-index-selection-lab-fundamentals-1','cx-advanced-index-selection-lab-fundamentals','What is B+ tree fan-out?','["The number of child routes in an internal node", "The number of user accounts", "The count of SQL aliases", "The number of view names"]'::jsonb,0,'Fan-out describes routing capacity at an internal tree node.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-advanced-index-selection-lab-fundamentals-2','cx-advanced-index-selection-lab-fundamentals','Why can narrow routing keys help tree depth?','["They delete leaf records", "More entries can fit in comparable page space", "They guarantee every query is covered", "They remove all duplicates"]'::jsonb,1,'Higher routing capacity can address more leaves with fewer levels.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
