insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-advanced-index-selection-lab-application-2','cx-advanced-index-selection-lab-application','What should be fixed before tuning a spatial boundary query?','["Only a shorter table name", "Only the chosen color", "Coordinates and exact boundary semantics", "Only the SELECT alias"]'::jsonb,2,'Correct spatial meaning precedes physical optimization.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
