if exists(select 1 from public.test_questions where id='tq-dbms-sql-14-aggregate-functions-1' and (question_text,options,correct_index,explanation) is distinct from ('What is the defining characteristic of an aggregate function in SQL?','["It transforms a single row''s value into another value", "It collapses multiple rows into a single summary value", "It only works on VARCHAR columns", "It must always be used with a WHERE clause"]'::jsonb,1,'Aggregate functions (COUNT, SUM, AVG, MIN, MAX) take a set of rows and produce one summary value, unlike scalar functions which act row by row.') and (question_text,options,correct_index,explanation) is distinct from ('What does an ordinary aggregate describe?','["A random input row", "A summary over an input population", "A table rename", "A client-side font choice"]'::jsonb,1,'The measure combines facts rather than choosing arbitrary detail.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-14-aggregate-functions-1'; end if;
