if exists(select 1 from public.test_questions where id='tq-dbms-sql-14-aggregate-functions-4' and (question_text,options,correct_index,explanation) is distinct from ('Which statement about NULL and aggregate functions is TRUE?','["SUM() treats NULL as 0 when adding values", "All aggregate functions, including COUNT(*), ignore NULL rows entirely", "SUM, AVG, MIN, and MAX ignore NULL values in the target column; only COUNT(*) does not look at a specific column''s NULL status", "AVG() divides by the total row count including NULLs"]'::jsonb,2,'COUNT(*), SUM, AVG, MIN, MAX all skip NULLs when evaluating a column, but COUNT(*) counts every row regardless of column contents since it isn''t examining a column value.') and (question_text,options,correct_index,explanation) is distinct from ('What does GROUP BY event_code establish?','["A descending display order automatically", "One row per original response", "One output group for each represented event code", "A physical table for every event"]'::jsonb,2,'Grouping changes the result grain.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-14-aggregate-functions-4'; end if;
