if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-aggregate-query-optimization-1' and (question_text,options,correct_index,explanation) is distinct from ('Which of the following is the single most impactful optimization for an aggregate query with a row-level filter condition?','["Adding ORDER BY to the result", "Pushing the row-level condition into WHERE instead of HAVING, so it filters rows before grouping/aggregation happens", "Always using CUBE instead of GROUP BY", "Removing all indexes before aggregating"]'::jsonb,1,'WHERE eliminates rows before the (more expensive) grouping/aggregation step runs, whereas an equivalent HAVING condition aggregates everything first and then discards groups.') and (question_text,options,correct_index,explanation) is distinct from ('What must an aggregate optimization preserve?','["Only the query length", "Population and output grain", "Only the caption", "Only the index name"]'::jsonb,1,'A faster query is valid only when it still answers the defined question.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-aggregate-query-optimization-1'; end if;
