if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-aggregate-query-optimization-4' and (question_text,options,correct_index,explanation) is distinct from ('Why is one GROUP BY GROUPING SETS ((region), (product), ()) query generally more efficient than three separate GROUP BY queries combined with UNION ALL?','["It returns fewer rows", "It lets the engine compute all requested grouping levels from a single logical scan of the base table, instead of one scan per separate query", "UNION ALL is always disallowed with GROUP BY", "GROUPING SETS uses a completely different, faster aggregate algorithm unrelated to scanning"]'::jsonb,1,'GROUPING SETS (and ROLLUP/CUBE) let the engine derive multiple grouping levels from one pass over the base data, avoiding the redundant re-scans that separate UNIONed GROUP BY queries require.') and (question_text,options,correct_index,explanation) is distinct from ('What can a one-to-many tag join do to SUM?','["Automatically deduplicate identities", "Repeat a sale''s amount", "Make every total null", "Prove authorization"]'::jsonb,1,'Each matching tag can produce another appearance of the same fact.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-aggregate-query-optimization-4'; end if;
