if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-aggregate-query-optimization-6' and (question_text,options,correct_index,explanation) is distinct from ('Can an index on the WHERE column speed up a HAVING condition on an aggregate like SUM(amount) > 400?','["Yes, indexes always speed up HAVING directly", "No \u2014 HAVING conditions run against already-computed group aggregates, not raw table rows, so raw-column indexes cannot speed up the HAVING check itself", "Only if the index is a composite index", "Only in MySQL"]'::jsonb,1,'HAVING filters aggregated results after grouping is complete; an index can speed up the underlying scan/grouping (e.g. via WHERE or GROUP BY column ordering) but not the HAVING comparison itself, which operates on already-computed aggregate values.') and (question_text,options,correct_index,explanation) is distinct from ('Which predicate can test tag eligibility without projecting tag multiplicity?','["An unrestricted cross join", "EXISTS", "ORDER BY amount", "A renamed amount alias"]'::jsonb,1,'Existence is a Boolean decision for each outer fact.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-aggregate-query-optimization-6'; end if;
