update public.learning_topics set short_description='Find entities with no qualifying related rows using NOT EXISTS or a reliable left-join marker, avoiding NULL traps and misplaced eligibility filters.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Find entities with no qualifying related rows using NOT EXISTS or a reliable left-join marker, avoiding NULL traps and misplaced eligibility filters.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Anti Join.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-16-anti-join' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
