insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-anti-join-1','pt-dbms-sql-16-anti-join','What does an anti join return?','["Every matching pair", "Left rows without qualifying right matches", "Only right labels", "All duplicate values"]'::jsonb,1,'The absence test is defined relative to a candidate left population.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
