if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-atomicity-1' and (question_text,options,correct_index,explanation) is distinct from ('What does Atomicity guarantee?','["Fast query execution", "All of a transaction''s statements succeed together, or none do", "Data is always encrypted", "Only one user can access the database at a time"]'::jsonb,1,'Atomicity is specifically the all-or-nothing guarantee.') and (question_text,options,correct_index,explanation) is distinct from ('What does Atomicity guarantee?','["Fast query execution", "Supported transaction changes commit together, or partial supported work does not remain committed when the transaction aborts", "Data is always encrypted", "Only one user can access the database at a time"]'::jsonb,1,'Atomicity concerns the transaction commit outcome. Some statement errors leave earlier work pending until the caller completes or abandons the transaction.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-atomicity-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-atomicity-2' and test_id<>'pt-dbms-sql-22-atomicity') then raise exception 'Question ID collision: %', 'tq-dbms-sql-22-atomicity-2'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-22-atomicity-2' and test_id='pt-dbms-sql-22-atomicity') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-22-atomicity-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-atomicity-2' and (question_text,options,correct_index,explanation) is distinct from ('In the bank transfer example, what does atomicity prevent?','["The transfer from ever succeeding", "A partial transfer \u2014 money debited from one account with no corresponding credit to the other", "The need for a WHERE clause", "Multiple transfers happening in the same session"]'::jsonb,1,'This is exactly the scenario atomicity is designed to prevent.') and (question_text,options,correct_index,explanation) is distinct from ('When both required debit and credit writes participate in one correctly closed transactional operation, which commit outcome does atomicity exclude?','["The transfer from ever succeeding", "Committing only one of those participating writes as a partial transaction", "The need for a WHERE clause", "Multiple transfers happening in the same session"]'::jsonb,1,'Atomicity excludes a partial transaction commit. Required row existence, valid amounts and other business effect checks remain separate responsibilities.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-atomicity-2'; end if;
