if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-atomicity-3' and (question_text,options,correct_index,explanation) is distinct from ('If a CHECK constraint is violated partway through a multi-statement transaction, what does atomicity guarantee?','["Only the violating statement is rolled back; earlier statements remain applied", "The entire transaction rolls back, undoing everything already done in it", "The constraint is temporarily disabled to let the transaction proceed", "Nothing \u2014 constraints don''t interact with atomicity"]'::jsonb,1,'A constraint violation anywhere in the transaction triggers the same whole-transaction rollback atomicity guarantees.') and (question_text,options,correct_index,explanation) is distinct from ('An InnoDB CHECK failure rolls back only its statement after an earlier transfer debit. What must the caller do if the business transfer failed?','["Only the violating statement is rolled back; earlier statements remain applied", "Explicitly roll back the unsuccessful transaction and handle cleanup or outcome uncertainty", "The constraint is temporarily disabled to let the transaction proceed", "Nothing \u2014 constraints don''t interact with atomicity"]'::jsonb,1,'A statement-scope constraint error need not undo earlier pending statements; the caller must close the failed business operation deliberately.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-atomicity-3'; end if;
