if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-atomicity-4' and (question_text,options,correct_index,explanation) is distinct from ('Does atomicity cover coordination with systems OUTSIDE the database, like an external payment API call?','["Yes, atomicity automatically covers any external system involved", "No \u2014 atomicity only covers the database''s own operations; external coordination needs additional patterns beyond plain ACID", "Only if the external call is made from a stored procedure", "This scenario is impossible in practice"]'::jsonb,1,'Plain ACID atomicity is scoped to the database transaction itself, not external side effects.') and (question_text,options,correct_index,explanation) is distinct from ('Does atomicity cover coordination with systems OUTSIDE the database, like an external payment API call?','["Yes, atomicity automatically covers any external system involved", "No \u2014 atomicity only covers the database''s own operations; external coordination needs additional patterns beyond plain ACID", "Only if the external call is made from a stored procedure", "This scenario is impossible in practice"]'::jsonb,1,'Plain ACID atomicity is scoped to the database transaction itself, not external side effects.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-atomicity-4'; end if;
