if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-atomicity-5' and (question_text,options,correct_index,explanation) is distinct from ('Does atomicity work on a MyISAM table?','["Yes, identically to InnoDB", "No \u2014 MyISAM has no real atomicity guarantee across multiple statements, as verified practically in this course", "Atomicity only matters for SELECT statements, so engine choice is irrelevant", "MyISAM provides stronger atomicity than InnoDB"]'::jsonb,1,'Atomicity requires actual transaction support from the storage engine, which MyISAM lacks.') and (question_text,options,correct_index,explanation) is distinct from ('Does atomicity work on a MyISAM table?','["Yes, identically to InnoDB", "No; MyISAM writes do not provide InnoDB-style multi-statement transactional rollback", "Atomicity only matters for SELECT statements, so engine choice is irrelevant", "MyISAM provides stronger atomicity than InnoDB"]'::jsonb,1,'This is the documented engine distinction, not a claim of provider or course execution evidence.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-atomicity-5'; end if;
