if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-atomicity-6' and (question_text,options,correct_index,explanation) is distinct from ('What triggers an automatic rollback under atomicity?','["Only an explicit ROLLBACK statement", "Any failure occurring before COMMIT, such as a constraint violation or a crash", "Only a SELECT statement returning zero rows", "Atomicity never triggers automatic rollback"]'::jsonb,1,'Various failure types before commit all trigger atomicity''s automatic undo behavior.') and (question_text,options,correct_index,explanation) is distinct from ('Which error-handling distinction is necessary for a MySQL transaction?','["Only an explicit ROLLBACK statement", "Some errors undo only a statement, while others undo the whole transaction; use the documented scope and close failed work", "Only a SELECT statement returning zero rows", "Atomicity never triggers automatic rollback"]'::jsonb,1,'Atomicity does not imply every precommit exception automatically rolls back the whole transaction.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-atomicity-6'; end if;
