if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-atomicity-7' and (question_text,options,correct_index,explanation) is distinct from ('Is a ''partial transfer'' (debit without credit) ever a valid, visible outcome under atomicity?','["Yes, in rare edge cases", "No \u2014 atomicity specifically guarantees this can never be a real, visible outcome", "Only if the transaction is very long", "Only on weekends, due to batch processing windows"]'::jsonb,1,'Preventing exactly this outcome is atomicity''s defining purpose.') and (question_text,options,correct_index,explanation) is distinct from ('In a correctly handled explicit transfer transaction containing both required supported writes, what does atomicity say about its commit outcome?','["Yes, in rare edge cases", "It does not partially commit the transaction; interim observations and validation are separate concerns", "Only if the transaction is very long", "Only on weekends, due to batch processing windows"]'::jsonb,1,'Own-session pending reads and missing business validation must not be confused with a partial transaction commit.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-atomicity-7'; end if;
