insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-atomicity-1','pt-dbms-sql-22-atomicity','What does Atomicity guarantee?','["Fast query execution", "Supported transaction changes commit together, or partial supported work does not remain committed when the transaction aborts", "Data is always encrypted", "Only one user can access the database at a time"]'::jsonb,1,'Atomicity concerns the transaction commit outcome. Some statement errors leave earlier work pending until the caller completes or abandons the transaction.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-atomicity-2','pt-dbms-sql-22-atomicity','When both required debit and credit writes participate in one correctly closed transactional operation, which commit outcome does atomicity exclude?','["The transfer from ever succeeding", "Committing only one of those participating writes as a partial transaction", "The need for a WHERE clause", "Multiple transfers happening in the same session"]'::jsonb,1,'Atomicity excludes a partial transaction commit. Required row existence, valid amounts and other business effect checks remain separate responsibilities.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-atomicity-3','pt-dbms-sql-22-atomicity','An InnoDB CHECK failure rolls back only its statement after an earlier transfer debit. What must the caller do if the business transfer failed?','["Only the violating statement is rolled back; earlier statements remain applied", "Explicitly roll back the unsuccessful transaction and handle cleanup or outcome uncertainty", "The constraint is temporarily disabled to let the transaction proceed", "Nothing — constraints don''t interact with atomicity"]'::jsonb,1,'A statement-scope constraint error need not undo earlier pending statements; the caller must close the failed business operation deliberately.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
