insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-autocommit-1','pt-dbms-sql-22-autocommit','With MySQL autocommit enabled and no explicit transaction active, what happens to a successful standalone transactional DML statement?','["Groups all statements in a session into one transaction", "It completes its own transaction without requiring a separate COMMIT statement.", "Disables all COMMIT statements", "Prevents any transaction from ever failing"]'::jsonb,1,'This scope excludes an active explicit transaction and statement-specific implicit-commit behavior.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-autocommit-2','pt-dbms-sql-22-autocommit','Two related InnoDB UPDATE statements run as standalone autocommitted statements outside an explicit transaction. A crash occurs between them. What partial effect can remain?','["Both updates are automatically rolled back together", "The first statement''s change is permanently committed with no corresponding second change — exactly the partial-transfer problem", "Neither statement ever executes", "The crash is impossible under autocommit"]'::jsonb,1,'This is exactly why relying on autocommit alone for related multi-statement operations is dangerous.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
