insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-autocommit-c-new-11','pt-dbms-sql-22-autocommit-application','Which evidence supports the current connection mode?','["Another session setting alone", "The application function name", "A check on that session plus driver behavior inspection", "A migration filename"]'::jsonb,2,'The relevant behavior is connection-specific.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-autocommit-c-new-12','pt-dbms-sql-22-autocommit-application','What is the safest ownership model for transaction completion?','["Every helper independently commits", "UI navigation chooses the database outcome", "A random retry decides", "One clearly coordinated layer chooses commit or rollback"]'::jsonb,3,'Uncoordinated transaction control creates accidental boundaries and cleanup errors.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
