select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-14-sql-functions/avg' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'avg'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'avg'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('ec8133ffad5031b025389d553a6598e2','5f10466cb84b9220faf60c74445aa542')) then raise exception 'Notes changed since seed; review before applying: %', 'avg'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-14-avg' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'avg'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-14-avg' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'avg'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-14-avg','pt-dbms-sql-14-avg-application')) then raise exception 'Extra topic tests require manual integration: %', 'avg'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-14-avg-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'avg'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "The mean follows known observations, not every row", "description": "Four sample records contain durations ten, twenty, unknown and thirty minutes. Only the three known durations enter the denominator, giving sixty divided by three equals twenty minutes.", "columns": ["Observation", "Minutes", "Contribution to sum", "Contribution to count"], "rows": [["1", "10", "10", "1"], ["2", "20", "20", "1"], ["3", "NULL", "0", "0"], ["4", "30", "30", "1"], ["Summary", "Mean 20", "Sum 60", "Known count 3"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'avg'; end if;
