if exists(select 1 from public.test_questions where id='tq-dbms-sql-14-avg-1' and (question_text,options,correct_index,explanation) is distinct from ('Given order amounts 250.00, NULL, 400.00, 150.00, 300.00, what does AVG(amount) return?','["220.00", "275.00", "250.00", "1100.00"]'::jsonb,1,'AVG divides the sum of non-NULL values (1100) by the count of non-NULL values (4), giving 275.00 — not by the total row count of 5.') and (question_text,options,correct_index,explanation) is distinct from ('For amounts 250, NULL, 400, 150 and 300, what is AVG(amount)?','["220", "275", "250", "1100"]'::jsonb,1,'The four known amounts sum to 1100; divide by four, not five.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-14-avg-1'; end if;
