if exists(select 1 from public.test_questions where id='tq-dbms-sql-14-avg-3' and (question_text,options,correct_index,explanation) is distinct from ('What does AVG(amount) return for the completed orders only, with amounts 250.00, 400.00, and 300.00?','["316.67 (approximately)", "950.00", "300.00", "250.00"]'::jsonb,0,'(250 + 400 + 300) / 3 = 950 / 3 = 316.666..., which rounds to about 316.67.') and (question_text,options,correct_index,explanation) is distinct from ('Completed orders have amounts 250, 400 and 300. What is their mean, rounded to two decimal places?','["316.67", "950.00", "300.00", "250.00"]'::jsonb,0,'Their total is 950 across three observations; final rounding gives 316.67.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-14-avg-3'; end if;
