if exists(select 1 from public.test_questions where id='tq-dbms-sql-14-avg-4' and (question_text,options,correct_index,explanation) is distinct from ('A table has 5 amount values: 100, NULL, NULL, 200, 300. What does AVG(amount) return?','["120.00", "200.00", "600.00", "150.00"]'::jsonb,1,'Sum of non-NULL values = 100+200+300 = 600, count of non-NULL values = 3, so 600/3 = 200.00.') and (question_text,options,correct_index,explanation) is distinct from ('For values 100, NULL, NULL, 200 and 300, what is AVG(amount)?','["120", "200", "600", "150"]'::jsonb,1,'Only three known values contribute: 600 divided by three.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-14-avg-4'; end if;
