if exists(select 1 from public.test_questions where id='tq-dbms-sql-14-avg-6' and (question_text,options,correct_index,explanation) is distinct from ('Why is manually computing SUM(int_col) / COUNT(int_col) sometimes riskier than just using AVG(int_col)?','["SUM and COUNT can never be combined in one expression", "If both operands remain integer types, some dialects perform integer division and truncate the decimal part, unlike AVG which is designed to avoid this", "COUNT always returns a decimal, causing a type mismatch", "SUM(int_col) always returns NULL for integer columns"]'::jsonb,1,'AVG is built to return a proper fractional result, but a manual division of two integer-typed expressions can trigger integer division truncation in some dialects — the same nuance covered for the / operator in Chapter 8.') and (question_text,options,correct_index,explanation) is distinct from ('Which MySQL operator explicitly performs integer division and can discard a fractional mean?','["AVG", "DIV", "COUNT", "DISTINCT"]'::jsonb,1,'MySQL DIV performs integer division. Do not transfer another engine''s slash-division typing rules to MySQL.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-14-avg-6'; end if;
