if exists(select 1 from public.test_questions where id='tq-dbms-sql-14-avg-7' and (question_text,options,correct_index,explanation) is distinct from ('Given amounts 250.00, 250.00, and 400.00, what would AVG(DISTINCT amount) return (compared to a plain AVG)?','["325.00 (average of 250 and 400 only, duplicate removed)", "300.00 (average of all three values including the duplicate)", "The same value as AVG(amount) always", "An error, since DISTINCT cannot be used with AVG"]'::jsonb,0,'AVG(DISTINCT amount) removes the duplicate 250.00 first, leaving 250 and 400, so the average is (250+400)/2 = 325.00 — different from the plain AVG of 300.00.') and (question_text,options,correct_index,explanation) is distinct from ('For 250, 250 and 400, what does AVG(DISTINCT amount) average?','["250 and 400 once each, giving 325", "All three observations, giving 300", "Only the repeated value, giving 250", "Only the maximum value, giving 400"]'::jsonb,0,'DISTINCT removes duplicate expression values, changing the weighting.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-14-avg-7'; end if;
