if exists(select 1 from public.test_questions where id='tq-dbms-sql-14-avg-8' and (question_text,options,correct_index,explanation) is distinct from ('Which statement about AVG() and outliers/median is TRUE in standard SQL?','["AVG() automatically excludes the highest and lowest values like a trimmed mean", "AVG() computes the ordinary arithmetic mean and has no built-in awareness of medians or outlier trimming", "AVG() always returns the median value of the column", "AVG() requires a GROUP BY clause to function at all"]'::jsonb,1,'AVG is a plain arithmetic mean; it is sensitive to outliers and standard SQL has no separate built-in median function among the core five aggregates (some dialects add specialized functions like PERCENTILE_CONT for that).') and (question_text,options,correct_index,explanation) is distinct from ('Which description of AVG and outliers is correct?','["AVG always returns the median", "AVG computes an arithmetic mean and does not automatically trim extreme values", "AVG ignores the highest and lowest values", "AVG requires GROUP BY in every query"]'::jsonb,1,'Extreme values remain part of the mean unless the query explicitly excludes them.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-14-avg-8'; end if;
