if exists(select 1 from public.test_questions where id='pt-dbms-sql-14-avg-application-new-8' and (question_text,options,correct_index,explanation) is distinct from ('Why retain group sums and known counts rather than only rounded group means?','["They allow a correctly weighted combined mean without reconstructing discarded precision", "They guarantee every group has the same size", "They make all missing observations become zeros", "They make every aggregate constant time"]'::jsonb,0,'Combine total known amounts and total known observations.') and (question_text,options,correct_index,explanation) is distinct from ('Why retain group sums and known counts rather than only rounded group means?','["They allow a correctly weighted combined mean without reconstructing discarded precision", "They guarantee every group has the same size", "They make all missing observations become zeros", "They make every aggregate constant time"]'::jsonb,0,'Combine total known amounts and total known observations.')) then raise exception 'Edited question requires review: %', 'pt-dbms-sql-14-avg-application-new-8'; end if;
