update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for AVG.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-14-avg' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-14-avg-application','MCQ Test 2',category,10,10,'Application and scenarios for AVG.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-14-avg' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-avg-1','pt-dbms-sql-14-avg','For amounts 250, NULL, 400, 150 and 300, what is AVG(amount)?','["220", "275", "250", "1100"]'::jsonb,1,'The four known amounts sum to 1100; divide by four, not five.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-avg-2','pt-dbms-sql-14-avg','With at least one known value, which expression describes the mean of x?','["SUM(x) / COUNT(*) regardless of NULLs", "SUM(x) / COUNT(x)", "MAX(x) - MIN(x)", "COUNT(x) / SUM(x)"]'::jsonb,1,'The denominator counts the same known expression values included in the sum.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-avg-3','pt-dbms-sql-14-avg','Completed orders have amounts 250, 400 and 300. What is their mean, rounded to two decimal places?','["316.67", "950.00", "300.00", "250.00"]'::jsonb,0,'Their total is 950 across three observations; final rounding gives 316.67.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-avg-4','pt-dbms-sql-14-avg','For values 100, NULL, NULL, 200 and 300, what is AVG(amount)?','["120", "200", "600", "150"]'::jsonb,1,'Only three known values contribute: 600 divided by three.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-avg-5','pt-dbms-sql-14-avg','An ungrouped AVG query matches no rows. What is its aggregate value?','["0", "NULL", "1", "An obligatory error"]'::jsonb,1,'There is no known value from which to calculate a mean.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-avg-6','pt-dbms-sql-14-avg','Which MySQL operator explicitly performs integer division and can discard a fractional mean?','["AVG", "DIV", "COUNT", "DISTINCT"]'::jsonb,1,'MySQL DIV performs integer division. Do not transfer another engine''s slash-division typing rules to MySQL.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-avg-7','pt-dbms-sql-14-avg','For 250, 250 and 400, what does AVG(DISTINCT amount) average?','["250 and 400 once each, giving 325", "All three observations, giving 300", "Only the repeated value, giving 250", "Only the maximum value, giving 400"]'::jsonb,0,'DISTINCT removes duplicate expression values, changing the weighting.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-avg-8','pt-dbms-sql-14-avg','Which description of AVG and outliers is correct?','["AVG always returns the median", "AVG computes an arithmetic mean and does not automatically trim extreme values", "AVG ignores the highest and lowest values", "AVG requires GROUP BY in every query"]'::jsonb,1,'Extreme values remain part of the mean unless the query explicitly excludes them.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-14-avg-new-9','pt-dbms-sql-14-avg','Which count is useful alongside AVG(minutes) to show its denominator?','["COUNT(minutes)", "COUNT(*) even when minutes is NULL", "COUNT(DISTINCT minutes) for all means", "The largest observation identifier"]'::jsonb,0,'COUNT(minutes) reports how many known durations contributed.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-14-avg-new-10','pt-dbms-sql-14-avg','For one known zero duration, what does AVG(minutes) return?','["NULL", "Zero", "No aggregate row", "An automatic division error"]'::jsonb,1,'A measured zero is a known observation; it contributes zero to the sum and one to the count.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-14-avg-application-new-1','pt-dbms-sql-14-avg-application','Two labs have means 10 and 30 with known counts 2 and 8. What is the overall observation mean?','["20", "26", "40", "10"]'::jsonb,1,'Weight by counts: (10*2 + 30*8) / 10 = 26.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-14-avg-application-new-2','pt-dbms-sql-14-avg-application','What is the effect of AVG(COALESCE(minutes,0)) when durations are missing?','["It ignores every missing duration exactly like AVG(minutes)", "It changes only the final display of an empty mean", "It includes missing durations as zero-valued observations", "It removes known zeros"]'::jsonb,2,'The transformation happens before averaging, so those rows now enter the denominator.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-14-avg-application-new-3','pt-dbms-sql-14-avg-application','Why is AVG(DISTINCT repair_minutes) usually a poor fix for a parts join that repeats repairs?','["DISTINCT always adds every repeated duration", "MySQL forbids every DISTINCT aggregate", "Repairs with multiple parts necessarily have identical durations", "Different repairs can have equal durations and must remain separate observations"]'::jsonb,3,'Repair grain and numeric-value uniqueness are different properties.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-14-avg-application-new-4','pt-dbms-sql-14-avg-application','An ungrouped all-NULL input and an ungrouped empty input produce which AVG values?','["Both produce NULL", "Both produce zero", "Only the empty input produces zero", "Only the all-NULL input produces an error"]'::jsonb,0,'Neither input supplies a known numeric expression value.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-14-avg-application-new-5','pt-dbms-sql-14-avg-application','What happens when a GROUP BY query has no qualifying rows at all?','["It manufactures a row for each possible department", "It has no groups to return", "It always returns one zero-valued group", "It ignores the WHERE predicate"]'::jsonb,1,'An ungrouped aggregate''s single summary row should not be confused with grouped output.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-14-avg-application-new-6','pt-dbms-sql-14-avg-application','In AVG(CASE WHEN priority=''urgent'' THEN minutes END), which values contribute?','["Zero for every nonurgent row", "Every known duration regardless of priority", "Known minutes from urgent rows", "Only rows whose priority is NULL"]'::jsonb,2,'The implicit ELSE NULL excludes nonurgent rows from this mean.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
