update public.learning_topics set short_description='Understand B+ tree navigation, linked-leaf ranges, splits, InnoDB clustered and secondary payloads, and the limits of index ordering claims.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Understand B+ tree navigation, linked-leaf ranges, splits, InnoDB clustered and secondary payloads, and the limits of index ordering claims.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for B Plus Tree.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-20-b-plus-tree' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-20-b-plus-tree-application','MCQ Test 2',category,10,10,'Application and scenarios for B Plus Tree.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-20-b-plus-tree' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-b-plus-tree-1','pt-dbms-sql-20-b-plus-tree','What is the defining structural difference between a B+ Tree and a plain B-Tree?','["A B+ Tree has no root node", "In a B+ Tree, all data pointers live only in leaf nodes, while internal nodes hold keys purely for navigation", "A B+ Tree cannot be balanced", "A B+ Tree stores data in random order"]'::jsonb,1,'This is the core distinction: B+ Tree internal nodes are pure navigation aids, while ALL data pointers live in leaves.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-b-plus-tree-2','pt-dbms-sql-20-b-plus-tree','What additional feature do B+ Tree leaf nodes have that plain B-Tree leaves typically do not?','["They are compressed using a hash function", "They are linked together in a chain (e.g., a linked list) in sorted order", "They store data out of order", "They are duplicated across every level of the tree"]'::jsonb,1,'B+ Tree leaves are linked together, letting the engine walk sequentially across them for range scans.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-b-plus-tree-3','pt-dbms-sql-20-b-plus-tree','Why is a B+ Tree particularly efficient for a query like `WHERE gpa BETWEEN 3.0 AND 3.5`?','["Because BETWEEN queries never use indexes", "Because after locating the starting leaf, the engine can walk the linked leaf chain to collect the rest of the range without re-traversing the tree", "Because B+ Trees convert ranges into hash lookups", "Because internal nodes store the full row data for ranges"]'::jsonb,1,'The linked leaf chain lets a range scan proceed sequentially once the start point is found, avoiding repeated top-down traversals.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-b-plus-tree-4','pt-dbms-sql-20-b-plus-tree','In the textbook B+ tree model, what do internal nodes contain?','["Separator keys and child-page pointers; row payload is stored in leaves.", "The full row data for every record", "A random sample of leaf keys", "Nothing; internal nodes are empty placeholders"]'::jsonb,0,'Navigation requires child pointers; absence of row payload does not mean absence of all pointers.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-b-plus-tree-5','pt-dbms-sql-20-b-plus-tree','Which database index structure is more commonly used in practice for general-purpose indexing: plain B-Tree or B+ Tree?','["Plain B-Tree, because it is simpler", "B+ Tree, because its linked leaves make range scans efficient in addition to fast equality lookups", "Neither; hash indexes are always used instead", "They are used with exactly equal frequency in all engines"]'::jsonb,1,'Nearly every mainstream relational database''s default index (PostgreSQL btree, MySQL InnoDB, SQL Server) is actually a B+ Tree variant.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-b-plus-tree-6','pt-dbms-sql-20-b-plus-tree','Why might a B+ Tree end up shallower than an equivalent plain B-Tree over the same data?','["Because B+ Tree leaves store no data at all", "Its internal separator keys and child-page pointers can omit full row payload, allowing higher fanout under comparable page assumptions.", "Because B+ Trees are always stored entirely in RAM", "Because B+ Trees skip the balancing step"]'::jsonb,1,'Compact routing entries may fit more children per page; actual height depends on key width, occupancy and implementation.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-b-plus-tree-7','pt-dbms-sql-20-b-plus-tree','A query needs `ORDER BY gpa` with no other filter. How can a B+ Tree index on gpa help?','["It cannot help with ORDER BY at all", "Walking the linked leaf chain in order can satisfy the sort without a separate sorting step", "It requires converting the index to a hash index first", "ORDER BY always ignores indexes"]'::jsonb,1,'Since B+ Tree leaves are linked in sorted key order, an in-order leaf walk directly produces sorted output.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-b-plus-tree-8','pt-dbms-sql-20-b-plus-tree','True or false: in a B+ Tree, a key value used for navigation in an internal node is often also duplicated in a leaf node.','["False, keys never repeat across levels", "True, this redundancy is intentional and supports the self-sufficient leaf chain", "False, internal nodes and leaf nodes never share any keys", "True, but only in hash indexes"]'::jsonb,1,'It''s normal and by design for a signpost key in an internal node to also appear in a leaf, since leaves must independently hold the full sorted data.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-20-b-plus-tree-c-new-1','pt-dbms-sql-20-b-plus-tree','Which pointer must an internal B+ tree node contain?','["Child-page pointers", "Email addresses", "Every full application row", "Only the final SQL result"]'::jsonb,0,'Internal nodes route searches to their children.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
