if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-b-tree-1' and (question_text,options,correct_index,explanation) is distinct from ('In a B-Tree index, where do sorted keys act as signposts directing a search toward the correct subtree?','["Only in leaf nodes", "In internal (and root) nodes", "Nowhere; B-Trees are unsorted", "Only in a separate lookup table"]'::jsonb,1,'Internal nodes (including the root) hold sorted keys used purely to navigate toward the correct child during a search.') and (question_text,options,correct_index,explanation) is distinct from ('What is a B-tree designed to keep short?','["Every SQL query string", "Page-oriented search paths", "Every data value", "Only table names"]'::jsonb,1,'High fan-out reduces the number of levels needed to reach a key region.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-b-tree-1'; end if;
