if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-b-tree-2' and (question_text,options,correct_index,explanation) is distinct from ('Why does a B-Tree remain ''shallow'' even over a table with a million rows?','["Because it only stores 100 rows total", "Because each node can hold many keys/children, so tree depth grows logarithmically with data size", "Because it stores data in RAM only", "Because it deletes old rows automatically"]'::jsonb,1,'High branching factor per node means the tree needs only a few levels (roughly log base branching-factor of n) to index huge amounts of data.') and (question_text,options,correct_index,explanation) is distinct from ('What does fan-out describe?','["The total SQL row count", "The branching capacity of a node", "The number of grants", "The length of an alias"]'::jsonb,1,'One node can direct searches into many child ranges.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-b-tree-2'; end if;
