if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-b-tree-3' and (question_text,options,correct_index,explanation) is distinct from ('What does ''balanced'' mean in the context of a B-Tree?','["Every node has exactly two children", "Every path from root to a leaf has the same length", "The tree never needs to be updated", "Keys are stored in random, not sorted, order"]'::jsonb,1,'Balance means uniform depth across all leaves, which the tree maintains via splitting/merging as data changes.') and (question_text,options,correct_index,explanation) is distinct from ('What guides a child choice?','["Random output ordering", "Ordered separator keys", "A display caption", "The current username"]'::jsonb,1,'Separators divide the key space into searchable regions.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-b-tree-3'; end if;
