if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-b-tree-4' and (question_text,options,correct_index,explanation) is distinct from ('Roughly how many levels would a B-Tree need to index 1,000,000 rows if each node holds about 100 keys/children?','["About 1,000,000", "About 500,000", "About 3", "Exactly 1"]'::jsonb,2,'log base 100 of 1,000,000 is about 3 — a wide branching factor keeps the tree very shallow even for large tables.') and (question_text,options,correct_index,explanation) is distinct from ('Where does key30 route under separators20 and40?','["The region below20", "The region above40", "The middle region", "Every region always"]'::jsonb,2,'Thirty lies between the two separators.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-b-tree-4'; end if;
