if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-b-tree-5' and (question_text,options,correct_index,explanation) is distinct from ('What operation keeps a B-Tree balanced as rows are inserted and it grows too full at a node?','["Node splitting", "Deleting random rows", "Converting to a hash index", "Sorting the whole table"]'::jsonb,0,'When a node exceeds its capacity, it splits into two nodes, propagating a new key upward, which keeps the tree balanced.') and (question_text,options,correct_index,explanation) is distinct from ('What is the standard balance invariant?','["Leaves occur at the same depth", "Every node has identical occupancy", "All keys have equal values", "Every node has two children"]'::jsonb,0,'The tree bounds search height without requiring equal key counts per node.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-b-tree-5'; end if;
