if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-b-tree-6' and (question_text,options,correct_index,explanation) is distinct from ('Why is minimizing node reads (tree depth) especially important for disk-backed database indexes?','["Because RAM cannot store trees at all", "Because each node read can correspond to a disk I/O operation, and disk I/O is comparatively slow", "Because SQL syntax forbids reading more than 3 nodes", "It isn''t important; depth is irrelevant to performance"]'::jsonb,1,'Disk I/O is orders of magnitude slower than in-memory comparisons, so a shallow tree that needs few node reads dramatically improves real-world performance.') and (question_text,options,correct_index,explanation) is distinct from ('Does balanced mean every node is full?','["Yes", "No", "Only for leaves", "Only for integers"]'::jsonb,1,'Permitted occupancy varies while structural bounds remain satisfied.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-b-tree-6'; end if;
