if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-b-tree-7' and (question_text,options,correct_index,explanation) is distinct from ('Compared to a plain binary search tree, why is a B-Tree generally better suited to database indexing?','["A B-Tree cannot be balanced, which simplifies coding", "A B-Tree''s high branching factor per node yields a much shallower tree, reducing the number of node accesses needed", "A binary search tree cannot store sorted keys", "A B-Tree stores keys in reverse order"]'::jsonb,1,'Wider nodes (many keys/children each) mean fewer levels overall compared to a binary tree, where every node has at most 2 children.') and (question_text,options,correct_index,explanation) is distinct from ('Why state an order or degree convention?','["It changes row permissions", "Textbooks define capacity notation differently", "It eliminates leaf nodes", "It sorts SQL output"]'::jsonb,1,'The same symbol can refer to different minimum or maximum capacities.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-b-tree-7'; end if;
