if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-b-tree-8' and (question_text,options,correct_index,explanation) is distinct from ('What happens to a B-Tree node when too many rows are deleted, leaving it underfull?','["Nothing; underfull nodes are ignored forever", "It may merge with a sibling node to maintain balance and structure", "The entire tree is rebuilt from scratch on every delete", "The table becomes unqueryable"]'::jsonb,1,'Underfull nodes can merge with siblings as part of ongoing rebalancing, which is part of the index maintenance overhead (20.14).') and (question_text,options,correct_index,explanation) is distinct from ('What can wider keys do?','["Guarantee a shorter tree", "Reduce entries per page", "Remove all writes", "Make ordering irrelevant"]'::jsonb,1,'Wider entries consume page space and can lower effective fan-out.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-b-tree-8'; end if;
