insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-bcnf-1','pt-dbms-sql-21-bcnf','What is the single defining difference between 3NF and BCNF?','["BCNF requires 1NF but 3NF does not", "3NF allows a non-superkey determinant if the attribute it determines is prime; BCNF requires every determinant to be a superkey with no exceptions", "BCNF only applies to relations with a single attribute", "3NF is stricter than BCNF"]'::jsonb,1,'This ''prime attribute'' escape clause is precisely what 3NF relaxes and BCNF removes — BCNF has zero tolerance for non-superkey determinants.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-bcnf-2','pt-dbms-sql-21-bcnf','In SectionAssignment(StudentID, CourseID, InstructorID) with FDs {StudentID, CourseID}->InstructorID and InstructorID->CourseID, why does InstructorID->CourseID violate BCNF?','["Because InstructorID is never functionally dependent on anything", "Because InstructorID''s closure alone does not reach StudentID, so InstructorID is not a superkey, yet it determines CourseID", "Because CourseID cannot appear on the right-hand side of any FD", "Because InstructorID and CourseID have the same data type"]'::jsonb,1,'BCNF requires every determinant to be a superkey. InstructorID alone only determines {InstructorID, CourseID}, missing StudentID, so it fails the superkey test outright.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
