insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-bcnf-application-10','cx-bcnf-application','Why does the independently populated two-table example not refute losslessness?','["It lacks an ORDER BY alias", "Lossless means no constraints exist", "It is not the projection of a legal original relation", "The table names are different"]'::jsonb,2,'Losslessness reconstructs legal original states, not every arbitrary independent component state.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
