insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-between-1','pt-dbms-sql-12-between','Does ordinary numeric BETWEEN include its endpoints?','["Neither endpoint", "Yes, both lower and upper endpoints", "Only the lower endpoint", "Only the upper endpoint"]'::jsonb,1,'It describes a closed interval.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-between-2','pt-dbms-sql-12-between','Which explicit numeric condition matches quantity BETWEEN 2 AND 6?','["quantity>2 AND quantity<6", "quantity>=2 AND quantity<=6", "quantity>=2 OR quantity<=6", "quantity=2 OR quantity=6"]'::jsonb,1,'Both inclusive comparisons must hold.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-between-3','pt-dbms-sql-12-between','Can BETWEEN be used with suitably typed dates?','["No, only integers are permitted", "Yes, the values use their comparison semantics", "Only with a separate RANGE keyword", "Only when both dates match"]'::jsonb,1,'Temporal boundaries still need precise interpretation.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-between-4','pt-dbms-sql-12-between','For known numeric bounds, what does BETWEEN 6 AND 2 do?','["Automatically swaps the bounds", "No known numeric value can satisfy the reversed interval", "Always raises a syntax error", "Matches every row"]'::jsonb,1,'MySQL ordinary BETWEEN does not normalize reversed input.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-between-5','pt-dbms-sql-12-between','Why can a date-only final-day bound miss DATETIME events?','["BETWEEN forbids all temporal columns", "It can represent midnight at the beginning of that day", "It always becomes the next month", "Every date literal means noon"]'::jsonb,1,'Later times on the same calendar date can exceed the bound.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-between-6','pt-dbms-sql-12-between','For known quantity, what does NOT BETWEEN 2 AND 6 admit?','["Values below 2 or above 6", "Only 2 and 6", "Every value including NULL", "Only values strictly inside the interval"]'::jsonb,0,'The original endpoints remain inside and are excluded by negation.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-between-7','pt-dbms-sql-12-between','What does BETWEEN 4 AND 4 admit for known numeric values?','["No values", "Exactly 4", "Every value", "Only NULL"]'::jsonb,1,'Equal inclusive bounds define a valid singleton interval.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-between-8','pt-dbms-sql-12-between','Why translate everyday uses of between carefully?','["SQL always guesses the intended endpoints", "The intended endpoint policy may differ from SQL inclusiveness", "All English intervals mean exclusive", "BETWEEN ignores its bounds"]'::jsonb,1,'The requirement must specify endpoint meaning.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-12-between-new-9','pt-dbms-sql-12-between','Does a NULL quantity qualify for a known numeric BETWEEN range in WHERE?','["No, the predicate is UNKNOWN", "Yes, it becomes zero", "Yes, it becomes the lower bound", "It always raises an exception"]'::jsonb,0,'WHERE retains only TRUE.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-12-between-new-10','pt-dbms-sql-12-between','Does NOT BETWEEN automatically include NULL quantities?','["Yes, every missing value is outside", "No, negation does not make an unknown range result true", "Only with ORDER BY", "Only when bounds differ"]'::jsonb,1,'Add an explicit missingness branch when the contract requires it.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-12-between-application-new-1','pt-dbms-sql-12-between-application','What expresses January as a full DATETIME month?','["Between January 1 and January 31 midnight only", "At or after January 1 and strictly before February 1", "Equal to January 31", "After February 1 only"]'::jsonb,1,'The half-open interval includes all final-day times.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-12-between-application-new-2','pt-dbms-sql-12-between-application','Why avoid an invented last fractional instant of a day?','["SQL cannot store fractional times", "Every last second is always identical", "The next exclusive boundary avoids dependence on column precision", "A time range needs only one bound"]'::jsonb,2,'Use a robust interval shape for timestamp-like values.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-12-between-application-new-3','pt-dbms-sql-12-between-application','What should an API do with reversed numeric bounds?','["Assume MySQL silently sorts them", "Silently remove every filter", "Always convert them to NULL", "Apply its explicit reject-or-normalize contract"]'::jsonb,3,'Normalization is an application decision.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-12-between-application-new-4','pt-dbms-sql-12-between-application','How should a missing maximum be represented in an open-ended search?','["Build the supported one-sided condition deliberately", "Pass NULL as an unlimited upper bound", "Use a random large number without a contract", "Reverse the bounds"]'::jsonb,0,'NULL is not automatically positive infinity.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-12-between-application-new-5','pt-dbms-sql-12-between-application','Why is text BETWEEN not a substitute for two named allowed categories?','["It always means exactly the two endpoints", "It admits an ordering interval, potentially including other strings", "Text has no comparison rules", "It always converts labels to dates"]'::jsonb,1,'Use explicit membership for a category list.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-12-between-application-new-6','pt-dbms-sql-12-between-application','What can affect text interval membership?','["Only the query line breaks", "Only the number of indexes", "Types and collation", "Only the file encoding of the SQL comment"]'::jsonb,2,'Comparison semantics determine ordering.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
