insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cp-dbms-sql-mid-range-prices',null::text,'Mid-Range Prices','Easy','mid-range-prices','Return id,name,price for products priced from 200 through 1000 inclusive, ordered by id. Preserve the original required-price schema and do not add category or stock conditions.

**MySQL dialect.**

```sql
CREATE TABLE products (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  price INTEGER NOT NULL,
  stock INTEGER
);
INSERT INTO products (id, name, category, price, stock) VALUES
(1, ''ProLaptop'', ''Electronics'', 85000, 12),
(2, ''Notebook'', ''Stationery'', 40, NULL),
(3, ''Python Basics'', ''Books'', 350, 5),
(4, ''ProPhone'', ''Electronics'', 45000, 0),
(5, ''Novel'', ''Books'', 220, NULL),
(6, ''Desk Lamp'', ''Home'', 900, 8);
```

**Required ordering:** As explicitly ordered in the result query.

**Edge cases:**
- Exactly 200 and 1000 qualify.
- Prices 199 and 1001 do not qualify.','[{"input": "INSERT INTO products (id, name, category, price, stock) VALUES\n(1, ''ProLaptop'', ''Electronics'', 85000, 12),\n(2, ''Notebook'', ''Stationery'', 40, NULL),\n(3, ''Python Basics'', ''Books'', 350, 5),\n(4, ''ProPhone'', ''Electronics'', 45000, 0),\n(5, ''Novel'', ''Books'', 220, NULL),\n(6, ''Desk Lamp'', ''Home'', 900, 8);", "output": "id\tname\tprice\n3\tPython Basics\t350\n5\tNovel\t220\n6\tDesk Lamp\t900", "explanation": "The closed interval includes exactly 200 and 1000. Category and stock do not restrict this retained requirement.", "check_sql": ""}]'::jsonb,'[{"seed_sql": "INSERT INTO products (id, name, category, price, stock) VALUES\n(1, ''ProTablet'', ''Electronics'', 32000, 4),\n(2, ''Pencil Set'', ''Stationery'', 60, NULL),\n(3, ''SQL Guide'', ''Books'', 500, 10),\n(4, ''ProSpeaker'', ''Electronics'', 6000, 0);", "expected": "id\tname\tprice\n3\tSQL Guide\t500", "hidden": true}, {"seed_sql": "INSERT INTO products VALUES (1,''Low'',''Books'',200,0),(2,''High'',''Books'',1000,0),(3,''Below'',''Books'',199,0),(4,''Above'',''Books'',1001,0);", "expected": "id\tname\tprice\n1\tLow\t200\n2\tHigh\t1000", "hidden": true}, {"seed_sql": "INSERT INTO products VALUES (1,''Outside'',''Books'',1001,0);", "expected": "", "hidden": true}]'::jsonb,'["Use only the supplied synthetic tables and requested transition.", "Preserve unrelated rows."]'::jsonb,'["Use both inclusive price endpoints.", "Keep all original output roles and id ordering."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The closed interval includes exactly 200 and 1000. Category and stock do not restrict this retained requirement.','{"sql": "SELECT id,name,price FROM products WHERE price BETWEEN 200 AND 1000 ORDER BY id;"}'::jsonb,'The closed interval includes exactly 200 and 1000. Category and stock do not restrict this retained requirement.',array['sql'],'CREATE TABLE products (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  price INTEGER NOT NULL,
  stock INTEGER
);','INSERT INTO products (id, name, category, price, stock) VALUES
(1, ''ProLaptop'', ''Electronics'', 85000, 12),
(2, ''Notebook'', ''Stationery'', 40, NULL),
(3, ''Python Basics'', ''Books'', 350, 5),
(4, ''ProPhone'', ''Electronics'', 45000, 0),
(5, ''Novel'', ''Books'', 220, NULL),
(6, ''Desk Lamp'', ''Home'', 900, 8);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-12-between' on conflict(id) do update set description=excluded.description,examples=excluded.examples,test_cases=excluded.test_cases,constraints=excluded.constraints,hints=excluded.hints,editorial=excluded.editorial,solution_code=excluded.solution_code,solution_approach=excluded.solution_approach,updated_at=now() where (dsa_problems.description,dsa_problems.examples,dsa_problems.test_cases,dsa_problems.constraints,dsa_problems.hints,dsa_problems.editorial,dsa_problems.solution_code,dsa_problems.solution_approach) is distinct from (excluded.description,excluded.examples,excluded.test_cases,excluded.constraints,excluded.hints,excluded.editorial,excluded.solution_code,excluded.solution_approach);
