if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-cascadeless-schedule-1' and (question_text,options,correct_index,explanation) is distinct from ('What additional problem does a merely-recoverable (but not cascadeless) schedule risk that a cascadeless schedule avoids?','["Deadlock", "Cascading rollback \u2014 a chain reaction where one transaction''s abort forces other transactions (that read its dirty data) to also abort", "Data type mismatch errors", "Running out of disk space"]'::jsonb,1,'Recoverability only guarantees the schedule CAN eventually be reconciled; it doesn''t prevent a costly chain reaction of forced rollbacks if a transaction that others read dirty data from ends up aborting.') and (question_text,options,correct_index,explanation) is distinct from ('What additional problem does a merely-recoverable (but not cascadeless) schedule risk that a cascadeless schedule avoids?','["Deadlock", "Cascading rollback \u2014 a chain reaction where one transaction''s abort forces other transactions (that read its dirty data) to also abort", "Data type mismatch errors", "Running out of disk space"]'::jsonb,1,'Recoverability only guarantees the schedule CAN eventually be reconciled; it doesn''t prevent a costly chain reaction of forced rollbacks if a transaction that others read dirty data from ends up aborting.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-cascadeless-schedule-1'; end if;
