if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-cascadeless-schedule-2' and (question_text,options,correct_index,explanation) is distinct from ('What is the precise definition of a cascadeless schedule?','["No transaction may ever abort", "A transaction may only read a data item after the transaction that last wrote it has already committed \u2014 dirty reads are never permitted", "All transactions must commit in the order they started", "Two transactions may never touch the same data item"]'::jsonb,1,'Cascadelessness requires the read itself (not just the reader''s eventual commit) to happen only after the writer commits, eliminating dirty reads entirely.') and (question_text,options,correct_index,explanation) is distinct from ('What is the precise definition of a cascadeless schedule?','["No transaction may ever abort", "A transaction reads a value written by another transaction only after that writer has committed", "All transactions commit in start order", "Two transactions never touch the same item"]'::jsonb,1,'The cross-transaction read-from condition excludes dirty reads; a transaction may still read its own pending writes.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-cascadeless-schedule-2'; end if;
