if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-cascadeless-schedule-4' and (question_text,options,correct_index,explanation) is distinct from ('Is every cascadeless schedule also recoverable?','["No, they are unrelated properties", "Yes \u2014 if reads only ever happen after the writer commits, the writer trivially commits before the reader even reads, let alone commits, satisfying recoverability automatically", "Only if there are exactly two transactions", "Only for read-only transactions"]'::jsonb,1,'Cascadelessness is strictly stronger than recoverability: enforcing ''commit before read'' automatically satisfies the weaker ''commit before commit'' requirement of recoverability.') and (question_text,options,correct_index,explanation) is distinct from ('Is every cascadeless schedule also recoverable?','["No, they are unrelated properties", "Yes \u2014 if reads only ever happen after the writer commits, the writer trivially commits before the reader even reads, let alone commits, satisfying recoverability automatically", "Only if there are exactly two transactions", "Only for read-only transactions"]'::jsonb,1,'Cascadelessness is strictly stronger than recoverability: enforcing ''commit before read'' automatically satisfies the weaker ''commit before commit'' requirement of recoverability.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-cascadeless-schedule-4'; end if;
