if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-cascadeless-schedule-5' and (question_text,options,correct_index,explanation) is distinct from ('Is every recoverable schedule also cascadeless?','["Yes, they are equivalent definitions", "No \u2014 a schedule can be recoverable (correct commit order) while still permitting dirty reads that would trigger cascading rollback if the writer aborted", "Yes, but only for schedules with fewer than 3 transactions", "No such recoverable-but-not-cascadeless schedule can exist"]'::jsonb,1,'Recoverability only fixes the commit ORDER; it doesn''t forbid dirty reads outright, which is exactly the gap cascadelessness closes.') and (question_text,options,correct_index,explanation) is distinct from ('Is every recoverable schedule also cascadeless?','["Yes, they are equivalent definitions", "No \u2014 a schedule can be recoverable (correct commit order) while still permitting dirty reads that would trigger cascading rollback if the writer aborted", "Yes, but only for schedules with fewer than 3 transactions", "No such recoverable-but-not-cascadeless schedule can exist"]'::jsonb,1,'Recoverability only fixes the commit ORDER; it doesn''t forbid dirty reads outright, which is exactly the gap cascadelessness closes.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-cascadeless-schedule-5'; end if;
