if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-cascadeless-schedule-8' and (question_text,options,correct_index,explanation) is distinct from ('In a worst-case cascading rollback scenario where T3 reads dirty data from T2, which in turn read dirty data from T1, what happens if T1 aborts?','["Only T1 is affected", "T2 must abort (it read invalid data from T1), and T3 must also abort (it read invalid data from the now-aborted T2) \u2014 a rollback chain reaction", "T3 is unaffected because it never touched T1''s data directly", "The database automatically repairs itself without any rollbacks"]'::jsonb,1,'Cascading rollback ripples through every transaction in the dependency chain: T1''s abort invalidates T2, which invalidates T3, and so on for however long the chain of dirty reads extends.') and (question_text,options,correct_index,explanation) is distinct from ('In a worst-case cascading rollback scenario where T3 reads dirty data from T2, which in turn read dirty data from T1, what happens if T1 aborts?','["Only T1 is affected", "T2 must abort (it read invalid data from T1), and T3 must also abort (it read invalid data from the now-aborted T2) \u2014 a rollback chain reaction", "T3 is unaffected because it never touched T1''s data directly", "The database automatically repairs itself without any rollbacks"]'::jsonb,1,'Cascading rollback ripples through every transaction in the dependency chain: T1''s abort invalidates T2, which invalidates T3, and so on for however long the chain of dirty reads extends.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-cascadeless-schedule-8'; end if;
