update public.learning_topics set short_description='Trace read-from dependencies to distinguish cascadeless, recoverable and strict schedules, with rollback chains, blind-write counterexamples and solved exercises.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Trace read-from dependencies to distinguish cascadeless, recoverable and strict schedules, with rollback chains, blind-write counterexamples and solved exercises.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Cascadeless Schedule.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-23-cascadeless-schedule' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-cascadeless-schedule-application','MCQ Test 2',category,10,10,'Application and scenarios for Cascadeless Schedule.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-23-cascadeless-schedule' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-cascadeless-schedule-1','pt-dbms-sql-23-cascadeless-schedule','What additional problem does a merely-recoverable (but not cascadeless) schedule risk that a cascadeless schedule avoids?','["Deadlock", "Cascading rollback — a chain reaction where one transaction''s abort forces other transactions (that read its dirty data) to also abort", "Data type mismatch errors", "Running out of disk space"]'::jsonb,1,'Recoverability only guarantees the schedule CAN eventually be reconciled; it doesn''t prevent a costly chain reaction of forced rollbacks if a transaction that others read dirty data from ends up aborting.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-cascadeless-schedule-2','pt-dbms-sql-23-cascadeless-schedule','What is the precise definition of a cascadeless schedule?','["No transaction may ever abort", "A transaction reads a value written by another transaction only after that writer has committed", "All transactions commit in start order", "Two transactions never touch the same item"]'::jsonb,1,'The cross-transaction read-from condition excludes dirty reads; a transaction may still read its own pending writes.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-cascadeless-schedule-3','pt-dbms-sql-23-cascadeless-schedule','In the ''Recoverable but NOT Cascadeless'' worked example, T2 reads A at step 2 before T1 commits at step 3, yet the overall schedule commits successfully. Why is this schedule still classified as NOT cascadeless?','["Because T2 eventually committed after T1", "Because the schedule''s STRUCTURE permitted a dirty read (T2 read before T1''s commit) — had T1 aborted instead, T2 would have been forced into a cascading rollback, regardless of what actually happened", "Because T1 never wrote anything", "Because cascadelessness only applies to writes, not reads"]'::jsonb,1,'Cascadelessness is about whether the schedule''s structure ever ALLOWS a dirty read to occur — it did here — not about whether things happened to work out because T1 committed rather than aborted.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-cascadeless-schedule-4','pt-dbms-sql-23-cascadeless-schedule','Is every cascadeless schedule also recoverable?','["No, they are unrelated properties", "Yes — if reads only ever happen after the writer commits, the writer trivially commits before the reader even reads, let alone commits, satisfying recoverability automatically", "Only if there are exactly two transactions", "Only for read-only transactions"]'::jsonb,1,'Cascadelessness is strictly stronger than recoverability: enforcing ''commit before read'' automatically satisfies the weaker ''commit before commit'' requirement of recoverability.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-cascadeless-schedule-5','pt-dbms-sql-23-cascadeless-schedule','Is every recoverable schedule also cascadeless?','["Yes, they are equivalent definitions", "No — a schedule can be recoverable (correct commit order) while still permitting dirty reads that would trigger cascading rollback if the writer aborted", "Yes, but only for schedules with fewer than 3 transactions", "No such recoverable-but-not-cascadeless schedule can exist"]'::jsonb,1,'Recoverability only fixes the commit ORDER; it doesn''t forbid dirty reads outright, which is exactly the gap cascadelessness closes.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-cascadeless-schedule-6','pt-dbms-sql-23-cascadeless-schedule','How do lock-based concurrency control protocols typically implement cascadelessness?','["By disallowing all locks", "By retaining the writer’s conflicting exclusive lock until commit or abort, or otherwise withholding its uncommitted value from readers", "By requiring every transaction to run serially", "By allowing dirty reads and marking them later"]'::jsonb,1,'Writer lock retention can make conflicting reads wait; multiversion committed reads can instead use an older committed version.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-cascadeless-schedule-7','pt-dbms-sql-23-cascadeless-schedule','What does cascadelessness explicitly NOT restrict, which the even-stronger strict schedule property (23.9) adds?','["It doesn''t restrict reads at all", "It doesn''t restrict two transactions both writing the same uncommitted item (a blind-write scenario) before either commits", "It doesn''t allow any transaction to ever abort", "It doesn''t apply to bank account examples"]'::jsonb,1,'Cascadelessness is purely about avoiding dirty READS; it says nothing about a second transaction overwriting an uncommitted write, which strict schedules additionally forbid.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-cascadeless-schedule-8','pt-dbms-sql-23-cascadeless-schedule','In a worst-case cascading rollback scenario where T3 reads dirty data from T2, which in turn read dirty data from T1, what happens if T1 aborts?','["Only T1 is affected", "T2 must abort (it read invalid data from T1), and T3 must also abort (it read invalid data from the now-aborted T2) — a rollback chain reaction", "T3 is unaffected because it never touched T1''s data directly", "The database automatically repairs itself without any rollbacks"]'::jsonb,1,'Cascading rollback ripples through every transaction in the dependency chain: T1''s abort invalidates T2, which invalidates T3, and so on for however long the chain of dirty reads extends.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-cascadeless-schedule-fundamentals-9','pt-dbms-sql-23-cascadeless-schedule','Does cascadeless mean no transaction may abort?','["No", "Yes, by definition", "Only for read-only transactions", "Only after a checkpoint"]'::jsonb,0,'It prevents dirty-read dependency cascades, not every independent failure.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-cascadeless-schedule-fundamentals-10','pt-dbms-sql-23-cascadeless-schedule','Which event must precede R2(A) when it reads T1’s write in a cascadeless schedule?','["C2 only", "C1", "W2(A) only", "Any unrelated commit"]'::jsonb,1,'The source writer must commit before the dependent read.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-cascadeless-schedule-application-1','cx-cascadeless-schedule-application','Is W1(A), R2(A), C1, C2 cascadeless?','["Yes, both eventually committed", "No, R2 read too early", "Only if A is numeric", "Only if transaction names are short"]'::jsonb,1,'Later commit order does not remove the earlier dirty read.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-cascadeless-schedule-application-2','cx-cascadeless-schedule-application','Which property does that sequence satisfy for its read dependency?','["Strictness", "No-write execution", "Recoverability", "Deadlock freedom"]'::jsonb,2,'The writer commits before its dependent reader commits.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-cascadeless-schedule-application-3','cx-cascadeless-schedule-application','Is reading your own pending write a cross-transaction dirty read?','["Yes, always", "Only for an INSERT", "Only before a SELECT", "No"]'::jsonb,3,'The restriction concerns values obtained from another unfinished transaction.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-cascadeless-schedule-application-4','cx-cascadeless-schedule-application','Why can a no-read schedule satisfy cascadelessness?','["There are no cross-transaction reads violating the condition", "It has no writes necessarily", "Every transaction has committed already", "It must be serial"]'::jsonb,0,'The read restriction can hold vacuously while other hazards remain.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-cascadeless-schedule-application-5','cx-cascadeless-schedule-application','Which additional access does strictness prohibit after an unfinished write?','["Every read of unrelated committed data", "Another transaction’s write to that same item", "Every future commit", "All independent calculations"]'::jsonb,1,'Strictness constrains dirty writes as well as dirty reads.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-cascadeless-schedule-application-6','cx-cascadeless-schedule-application','What does a cycle in a conflict graph establish?','["Failure of every recovery property automatically", "That no transaction can commit", "Failure of conflict serializability", "That a backup is missing"]'::jsonb,2,'Recovery dependency properties and serial-equivalence properties require separate tests.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-cascadeless-schedule-application-7','cx-cascadeless-schedule-application','Can a multiversion read avoid dirty data without blocking on the current writer?','["No, every reader must block", "Only if it deletes the writer", "Only if it disables transactions", "Yes, by using an appropriate committed version"]'::jsonb,3,'Committed-version visibility is another implementation mechanism.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-cascadeless-schedule-application-8','cx-cascadeless-schedule-application','T3 reads a T2 result derived from T1’s dirty value. Can T1’s abort affect T3?','["Yes, through the dependency chain", "No, only direct readers matter", "Only if names are consecutive", "Only if T3 updates A itself"]'::jsonb,0,'Indirect dependencies can invalidate downstream work.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-cascadeless-schedule-application-9','cx-cascadeless-schedule-application','What is needed to prove a schedule cascadeless?','["Check only the final output total", "Check every relevant read source and preceding writer commit", "Sort transaction identifiers", "Count primary keys"]'::jsonb,1,'One safe read does not establish the condition for all other reads.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
