select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-12-select-and-filtering/case' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'case'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'case'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('eabc4d682888992e82cab3bacdaac954','4ad65fbdb2d72331b01d28ff5c2fa393')) then raise exception 'Notes changed since seed; review before applying: %', 'case'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-12-case' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'case'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-12-case' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'case'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-12-case','pt-dbms-sql-12-case-application')) then raise exception 'Extra topic tests require manual integration: %', 'case'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-12-case-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'case'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "The first true price condition determines the retained tier", "description": "Price is required by the retained source schema, and both middle-tier boundaries are included.", "columns": ["Price", "Below 300", "At most 1000", "Chosen tier"], "rows": [["299", "TRUE", "Not reached for result", "Budget"], ["300", "FALSE", "TRUE", "Mid"], ["1000", "FALSE", "TRUE", "Mid"], ["1001", "FALSE", "FALSE", "Premium"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'case'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "The first true price condition determines the retained tier", "description": "Price is required by the retained source schema, and both middle-tier boundaries are included.", "columns": ["Price", "Below 300", "At most 1000", "Chosen tier"], "rows": [["299", "TRUE", "Not reached for result", "Budget"], ["300", "FALSE", "TRUE", "Mid"], ["1000", "FALSE", "TRUE", "Mid"], ["1001", "FALSE", "FALSE", "Premium"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "The first true price condition determines the retained tier", "description": "Price is required by the retained source schema, and both middle-tier boundaries are included.", "columns": ["Price", "Below 300", "At most 1000", "Chosen tier"], "rows": [["299", "TRUE", "Not reached for result", "Budget"], ["300", "FALSE", "TRUE", "Mid"], ["1000", "FALSE", "TRUE", "Mid"], ["1001", "FALSE", "FALSE", "Premium"]]}]'::jsonb;
if exists(select 1 from public.test_questions where test_id='pt-dbms-sql-12-case' and id not in ('tq-dbms-sql-12-case-1','tq-dbms-sql-12-case-2','tq-dbms-sql-12-case-3','tq-dbms-sql-12-case-4','tq-dbms-sql-12-case-5','tq-dbms-sql-12-case-6','tq-dbms-sql-12-case-7','tq-dbms-sql-12-case-8','pt-dbms-sql-12-case-new-9','pt-dbms-sql-12-case-new-10')) then raise exception 'Unexpected questions require review: %', 'pt-dbms-sql-12-case'; end if;
