if not exists(select 1 from public.test_questions where id='tq-dbms-sql-12-case-1' and test_id='pt-dbms-sql-12-case') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-12-case-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-12-case-1' and (question_text,options,correct_index,explanation) is distinct from ('What does CASE WHEN...THEN...ELSE...END do?','["Filters rows", "Evaluates conditions in order and returns the value tied to the first TRUE one (or ELSE if none match)", "Sorts rows by a condition", "Groups rows by a condition"]'::jsonb,1,'CASE is SQL''s conditional expression, producing a value based on the first matching condition.') and (question_text,options,correct_index,explanation) is distinct from ('What does a searched CASE expression return?','["Every THEN value concatenated", "The value associated with its first TRUE condition, or the fallback", "Only rows satisfying all branches", "A new table definition"]'::jsonb,1,'It produces a value, not an automatic row filter.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-12-case-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-12-case-2' and test_id<>'pt-dbms-sql-12-case') then raise exception 'Question ID collision: %', 'tq-dbms-sql-12-case-2'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-12-case-2' and test_id='pt-dbms-sql-12-case') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-12-case-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-12-case-2' and (question_text,options,correct_index,explanation) is distinct from ('In what order are CASE''s WHEN conditions evaluated?','["In random order", "Top to bottom, with the FIRST TRUE condition''s value being returned", "Bottom to top", "All conditions simultaneously, picking the most specific"]'::jsonb,1,'Order matters — evaluation proceeds top-to-bottom and stops at the first match.') and (question_text,options,correct_index,explanation) is distinct from ('If two WHEN conditions are TRUE, which one supplies the result?','["The most specific automatically", "The earlier one in the decision chain", "The later one", "A random branch"]'::jsonb,1,'Branch order expresses priority.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-12-case-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-12-case-3' and test_id<>'pt-dbms-sql-12-case') then raise exception 'Question ID collision: %', 'tq-dbms-sql-12-case-3'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-12-case-3' and test_id='pt-dbms-sql-12-case') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-12-case-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-12-case-3' and (question_text,options,correct_index,explanation) is distinct from ('What does CASE return if no WHEN condition matches and there''s no ELSE clause?','["An error is raised", "NULL", "The value 0", "An empty string"]'::jsonb,1,'Without ELSE, an unmatched row''s CASE expression silently evaluates to NULL.') and (question_text,options,correct_index,explanation) is distinct from ('No WHEN is true and ELSE is omitted. What is returned?','["Zero automatically", "NULL", "An empty string automatically", "A syntax error always"]'::jsonb,1,'The implicit fallback is missing.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-12-case-3'; end if;
