if not exists(select 1 from public.test_questions where id='tq-dbms-sql-12-case-4' and test_id='pt-dbms-sql-12-case') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-12-case-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-12-case-4' and (question_text,options,correct_index,explanation) is distinct from ('Can CASE be used inside a WHERE clause, not just SELECT?','["No, CASE can only appear in SELECT", "Yes \u2014 CASE is an expression usable almost anywhere a value is expected, including WHERE, ORDER BY, and inside function calls", "CASE can only appear in ORDER BY", "CASE requires its own separate statement"]'::jsonb,1,'As an expression rather than a statement, CASE is broadly usable throughout a query.') and (question_text,options,correct_index,explanation) is distinct from ('Can a CASE expression be used in ORDER BY?','["No, only SELECT supports it", "Yes, as a compatible value expression", "Only in a stored procedure", "Only if no THEN appears"]'::jsonb,1,'An ordering clause can use computed priority values.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-12-case-4'; end if;
