if exists(select 1 from public.test_questions where id='tq-dbms-sql-12-case-5' and (question_text,options,correct_index,explanation) is distinct from ('What is the ''simple CASE'' form?','["A CASE with no WHEN branches at all", "CASE column WHEN val1 THEN ... WHEN val2 THEN ... END, which tests equality against one column, more concisely than the full WHEN-condition form", "A CASE that can only return TRUE or FALSE", "A deprecated, no-longer-supported CASE syntax"]'::jsonb,1,'The simple form is a shorthand specifically for equality-only branches against a single column.') and (question_text,options,correct_index,explanation) is distinct from ('What does simple CASE primarily express?','["Arbitrary procedural loops", "Equality alternatives for one tested expression", "A table schema", "A guaranteed NULL-safe match"]'::jsonb,1,'Use searched CASE for range and missingness conditions.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-12-case-5'; end if;
