update public.learning_topics set short_description='Compute attribute closures step by step, prove superkeys and minimal candidate keys, and test dependency implications without confusing sample data with invariants.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Compute attribute closures step by step, prove superkeys and minimal candidate keys, and test dependency implications without confusing sample data with invariants.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Closure of Attributes.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-21-closure-of-attributes' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-closure-of-attributes-application','MCQ Test 2',category,10,10,'Application and scenarios for Closure of Attributes.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-21-closure-of-attributes' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-closure-of-attributes-1','pt-dbms-sql-21-closure-of-attributes','What does computing {CourseID}+ over the running example''s FD set yield?','["All eight attributes of the relation", "{CourseID, CourseName, InstructorID, InstructorName, InstructorOffice} — five attributes, missing the student-side and EnrollmentDate", "Just {CourseID, CourseName}", "{CourseID, StudentID, StudentName}"]'::jsonb,1,'CourseID reaches CourseName and InstructorID directly, then InstructorName and InstructorOffice transitively via InstructorID — but nothing determines StudentID, StudentName, or EnrollmentDate from CourseID alone.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-closure-of-attributes-2','pt-dbms-sql-21-closure-of-attributes','Why does {StudentID, CourseID}+ equal the entire set of eight attributes?','["Because StudentID and CourseID are alphabetically first", "Because starting from both together, every FD in the set can eventually be applied: StudentName and CourseName directly, InstructorID/Name/Office via the transitive chain, and EnrollmentDate via the composite-key FD", "Because closures always equal all attributes", "Because CourseID alone already reaches everything"]'::jsonb,1,'Every attribute is reachable: F1, F2, F3 apply immediately, F4/F5 apply once InstructorID is added, and F6 applies since both StudentID and CourseID are present from the start.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-closure-of-attributes-3','pt-dbms-sql-21-closure-of-attributes','In computing {StudentID, InstructorID}+, why does the closure NOT include CourseID?','["Because CourseID is not part of any functional dependency", "Because no FD in the set has a left-hand side reachable from {StudentID, InstructorID} that produces CourseID — InstructorID determines InstructorName/Office, not CourseID, since one instructor can teach multiple courses", "Because StudentID and InstructorID are incompatible data types", "Because CourseID must always be listed first in a closure"]'::jsonb,1,'The FD set only has CourseID -> InstructorID, never the reverse; nothing derives CourseID from InstructorID, so the closure of {StudentID, InstructorID} stops short of including it.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-closure-of-attributes-4','pt-dbms-sql-21-closure-of-attributes','What is the correct general algorithm for computing X+?','["List every attribute in the relation regardless of FDs", "Start with result = X; repeatedly scan all FDs and add an FD''s right-hand side whenever its left-hand side is already a subset of result, until a pass adds nothing new", "Apply only the first matching FD once and stop", "Compute it by counting the number of candidate keys"]'::jsonb,1,'Closure computation is an iterative fixed-point process: keep re-scanning the whole FD set, adding newly-determined attributes, until no more can be added.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-closure-of-attributes-5','pt-dbms-sql-21-closure-of-attributes','Why is it a mistake to stop the closure computation for {CourseID}+ right after applying F2 and F3 (before checking F4 and F5)?','["It is not a mistake — F4 and F5 never apply to CourseID''s closure", "F4 and F5 only become applicable AFTER InstructorID (added by F3) is already in the result, so stopping early would incorrectly omit InstructorName and InstructorOffice", "Because F4 and F5 must always be applied before F2 and F3", "Because closure computations must process FDs in numerical order only"]'::jsonb,1,'Closure requires repeated passes: F4 (InstructorID -> InstructorName) can''t fire until InstructorID has been added to the result by F3, so an early stop would miss transitively reachable attributes.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-closure-of-attributes-6','pt-dbms-sql-21-closure-of-attributes','If X+ turns out to equal the full set of attributes of the relation, what can be concluded about X?','["X is definitely a minimal candidate key", "X is a superkey (it functionally determines every attribute), though it may or may not be minimal", "X must be a foreign key", "X cannot contain more than two attributes"]'::jsonb,1,'X+ = all attributes proves X is a superkey. Whether X is a candidate key additionally requires checking that no proper subset of X also has this property (21.10).',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-closure-of-attributes-7','pt-dbms-sql-21-closure-of-attributes','Does the order in which applicable functional dependencies are applied during closure computation change the final result of X+?','["Yes, applying FDs in a different order can yield a different final closure", "No — as long as every applicable FD is eventually applied across repeated passes, the final closure is the same regardless of order", "Yes, but only for composite determinants", "No, because only one FD can ever apply to a given attribute set"]'::jsonb,1,'Closure is a deterministic fixed point; the order of applying applicable FDs doesn''t matter, only that the process continues until no pass adds anything new.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-closure-of-attributes-8','pt-dbms-sql-21-closure-of-attributes','What is {StudentID}+ alone (ignoring CourseID) over the running example''s FD set?','["All eight attributes", "{StudentID, StudentName} only, since no other FD has StudentID alone (without CourseID) on its left-hand side", "{StudentID, CourseID, StudentName}", "The empty set"]'::jsonb,1,'Only F1 (StudentID -> StudentName) has StudentID as a subset of its left-hand side without needing CourseID; F6 requires the composite {StudentID, CourseID}, which isn''t available here.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-closure-of-attributes-fundamentals-9','pt-dbms-sql-21-closure-of-attributes','Can a closure algorithm apply AB→C when only A is available?','["No, all determinant attributes are required", "Yes, one is enough", "Only for numeric columns", "Always after sorting"]'::jsonb,0,'A composite determinant requires its complete left-hand side.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-closure-of-attributes-fundamentals-10','pt-dbms-sql-21-closure-of-attributes','What makes the closure algorithm terminate over a finite relation?','["It deletes a row each time", "Only finitely many attributes can be added", "It guesses a fixed number of keys", "It stops after the first dependency"]'::jsonb,1,'The set grows monotonically within a finite attribute universe.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-closure-of-attributes-application-1','cx-closure-of-attributes-application','Does a superkey proof alone establish candidate-key minimality?','["Yes, by definition", "No", "Only if a name column exists", "Only if SQL returns no rows"]'::jsonb,1,'A superkey can contain removable attributes.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-closure-of-attributes-application-2','cx-closure-of-attributes-application','What must a key contain if an attribute appears on no dependency right-hand side?','["Only the first alphabetical attribute", "No attributes", "That attribute", "Only a generated number"]'::jsonb,2,'Such an attribute cannot be derived unless supplied initially.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-closure-of-attributes-application-3','cx-closure-of-attributes-application','How is X→Y implication tested?','["Check whether X has fewer letters", "Reverse every dependency", "Count current table rows", "Check whether Y is contained in X+"]'::jsonb,3,'Closure contains exactly the attributes determined under F.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-closure-of-attributes-application-4','cx-closure-of-attributes-application','When testing whether one rule is redundant, which F should be used?','["The remaining rules without that rule", "Only the rule itself", "An unrelated database schema", "Every possible dependency"]'::jsonb,0,'A rule must not be allowed to prove its own redundancy.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-closure-of-attributes-application-5','cx-closure-of-attributes-application','Can current sample uniqueness establish a dependency for every future legal state?','["Yes, after one SELECT", "No", "Only if the sample is sorted", "Only with short identifiers"]'::jsonb,1,'An instance observation is narrower than a domain invariant.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-closure-of-attributes-application-6','cx-closure-of-attributes-application','Does A→B imply B→A automatically?','["Yes, always", "Only for text", "No", "Only after COMMIT"]'::jsonb,2,'Functional dependency is directional.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-closure-of-attributes-application-7','cx-closure-of-attributes-application','For A→B, B→C, C→D, what is A+?','["A only", "B, C only", "D only", "A, B, C, D"]'::jsonb,3,'Repeated application reaches the full chain.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-closure-of-attributes-application-8','cx-closure-of-attributes-application','After removing B→C from that chain, what is A+?','["A, B", "A, B, C, D", "C, D", "The empty set"]'::jsonb,0,'No remaining rule connects the available A, B set to C.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-closure-of-attributes-application-9','cx-closure-of-attributes-application','What does COUNT(DISTINCT InstructorID) omit in the diagnostic?','["Every repeated course row", "NULL instructor values", "Every nonnull identifier", "All numeric values"]'::jsonb,1,'COUNT DISTINCT ignores NULL, so missingness needs separate treatment.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-closure-of-attributes-application-10','cx-closure-of-attributes-application','What does inclusion-minimal candidate key mean?','["It has the smallest identifier numbers", "It uses every relation attribute", "No proper subset remains a superkey", "It has the shortest display label"]'::jsonb,2,'Minimality concerns removability rather than spelling or one global size.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
