select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-20-indexes-and-access-paths/clustered-index' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'clustered-index'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'clustered-index'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('ee32a1f0ce326b011c1492dc96fc05d3','137b700357382e23d03744e882bbd9a1')) then raise exception 'Notes changed since seed; review before applying: %', 'clustered-index'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-20-clustered-index' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'clustered-index'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-20-clustered-index' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'clustered-index'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-20-clustered-index','cx-clustered-index-application')) then raise exception 'Extra topic tests require manual integration: %', 'clustered-index'; end if;
if exists(select 1 from public.practice_tests where id='cx-clustered-index-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'clustered-index'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Two routes to an InnoDB row", "columns": ["Access path", "Search value", "Destination"], "rows": [["Clustered primary key", "loan_id", "Leaf record with row data"], ["Secondary title index", "title", "Clustered key, then row if needed"]], "description": "The conceptual lookup paths distinguish full row storage from another search order."}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'clustered-index'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Two routes to an InnoDB row", "columns": ["Access path", "Search value", "Destination"], "rows": [["Clustered primary key", "loan_id", "Leaf record with row data"], ["Secondary title index", "title", "Clustered key, then row if needed"]], "description": "The conceptual lookup paths distinguish full row storage from another search order."}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Two routes to an InnoDB row", "columns": ["Access path", "Search value", "Destination"], "rows": [["Clustered primary key", "loan_id", "Leaf record with row data"], ["Secondary title index", "title", "Clustered key, then row if needed"]], "description": "The conceptual lookup paths distinguish full row storage from another search order."}]'::jsonb;
if exists(select 1 from public.test_questions where test_id='pt-dbms-sql-20-clustered-index' and id not in ('tq-dbms-sql-20-clustered-index-1','tq-dbms-sql-20-clustered-index-2','tq-dbms-sql-20-clustered-index-3','tq-dbms-sql-20-clustered-index-4','tq-dbms-sql-20-clustered-index-5','tq-dbms-sql-20-clustered-index-6','tq-dbms-sql-20-clustered-index-7','tq-dbms-sql-20-clustered-index-8','cx-clustered-index-fundamentals-9','cx-clustered-index-fundamentals-10')) then raise exception 'Unexpected questions require review: %', 'pt-dbms-sql-20-clustered-index'; end if;
