if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-clustered-index-1' and (question_text,options,correct_index,explanation) is distinct from ('What does a clustered index determine that a non-clustered index does not?','["The number of columns a table can have", "The physical storage order of the table''s rows on disk", "Whether NULL values are allowed", "The table''s primary key name"]'::jsonb,1,'A clustered index physically arranges the table''s rows in key order; it is not a separate pointer structure.') and (question_text,options,correct_index,explanation) is distinct from ('What does a clustered index determine that a non-clustered index does not?','["The number of columns a table can have", "The clustered B-tree leaf organization contains the row records in key order, without guaranteeing contiguous disk addresses", "Whether NULL values are allowed", "The table''s primary key name"]'::jsonb,1,'InnoDB clustered leaves store row data in ordered key ranges. Logical page order does not prove contiguous physical storage.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-clustered-index-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-clustered-index-2' and test_id<>'pt-dbms-sql-20-clustered-index') then raise exception 'Question ID collision: %', 'tq-dbms-sql-20-clustered-index-2'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-20-clustered-index-2' and test_id='pt-dbms-sql-20-clustered-index') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-20-clustered-index-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-clustered-index-2' and (question_text,options,correct_index,explanation) is distinct from ('How many clustered indexes can a single table have?','["Unlimited", "Exactly two", "At most one", "Exactly zero, always"]'::jsonb,2,'Since a clustered index defines physical row order, and rows can only be arranged one way at a time, a table can have at most one.') and (question_text,options,correct_index,explanation) is distinct from ('How many clustered indexes can a single table have?','["Unlimited", "Exactly two", "At most one", "Exactly zero, always"]'::jsonb,2,'Since a clustered index defines physical row order, and rows can only be arranged one way at a time, a table can have at most one.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-clustered-index-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-clustered-index-3' and test_id<>'pt-dbms-sql-20-clustered-index') then raise exception 'Question ID collision: %', 'tq-dbms-sql-20-clustered-index-3'; end if;
