if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-clustered-index-3' and (question_text,options,correct_index,explanation) is distinct from ('Why is the primary key often chosen as a table''s clustered index?','["Because primary keys cannot be indexed any other way", "Because primary-key lookups and joins are extremely common and benefit most from direct, no-extra-hop access to row data", "Because clustered indexes are required by the SQL standard to be on the primary key", "Because it reduces the table to zero rows"]'::jsonb,1,'Given how frequently primary keys are used for lookups and joins, clustering on them maximizes the benefit of avoiding an extra pointer-following step.') and (question_text,options,correct_index,explanation) is distinct from ('Why is the primary key often chosen as a table''s clustered index?','["Because primary keys cannot be indexed any other way", "Because primary-key lookups and joins are extremely common and benefit most from direct, no-extra-hop access to row data", "Because clustered indexes are required by the SQL standard to be on the primary key", "Because it reduces the table to zero rows"]'::jsonb,1,'Given how frequently primary keys are used for lookups and joins, clustering on them maximizes the benefit of avoiding an extra pointer-following step.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-clustered-index-3'; end if;
