if not exists(select 1 from public.test_questions where id='tq-dbms-sql-20-clustered-index-4' and test_id='pt-dbms-sql-20-clustered-index') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-20-clustered-index-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-clustered-index-4' and (question_text,options,correct_index,explanation) is distinct from ('Why is updating a clustered-index key value potentially expensive?','["It is never expensive; clustered keys can''t be updated", "It may require physically relocating the row on disk to maintain sorted order", "It always deletes the row permanently", "It automatically creates a new non-clustered index"]'::jsonb,1,'Since row order reflects the clustered key, changing that key can force the engine to physically move the row to keep the table sorted.') and (question_text,options,correct_index,explanation) is distinct from ('Why is updating a clustered-index key value potentially expensive?','["It is never expensive; clustered keys can''t be updated", "It can require changes to ordered leaf placement, page splits and secondary entries carrying the clustered key", "It always deletes the row permanently", "It automatically creates a new non-clustered index"]'::jsonb,1,'Changing the clustered identity can require structural maintenance and related secondary-index updates; it is not a promise to rearrange one contiguous disk array.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-clustered-index-4'; end if;
