insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-clustered-index-1','pt-dbms-sql-20-clustered-index','What does a clustered index determine that a non-clustered index does not?','["The number of columns a table can have", "The clustered B-tree leaf organization contains the row records in key order, without guaranteeing contiguous disk addresses", "Whether NULL values are allowed", "The table''s primary key name"]'::jsonb,1,'InnoDB clustered leaves store row data in ordered key ranges. Logical page order does not prove contiguous physical storage.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-clustered-index-2','pt-dbms-sql-20-clustered-index','How many clustered indexes can a single table have?','["Unlimited", "Exactly two", "At most one", "Exactly zero, always"]'::jsonb,2,'Since a clustered index defines physical row order, and rows can only be arranged one way at a time, a table can have at most one.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-clustered-index-3','pt-dbms-sql-20-clustered-index','Why is the primary key often chosen as a table''s clustered index?','["Because primary keys cannot be indexed any other way", "Because primary-key lookups and joins are extremely common and benefit most from direct, no-extra-hop access to row data", "Because clustered indexes are required by the SQL standard to be on the primary key", "Because it reduces the table to zero rows"]'::jsonb,1,'Given how frequently primary keys are used for lookups and joins, clustering on them maximizes the benefit of avoiding an extra pointer-following step.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-clustered-index-4','pt-dbms-sql-20-clustered-index','Why is updating a clustered-index key value potentially expensive?','["It is never expensive; clustered keys can''t be updated", "It can require changes to ordered leaf placement, page splits and secondary entries carrying the clustered key", "It always deletes the row permanently", "It automatically creates a new non-clustered index"]'::jsonb,1,'Changing the clustered identity can require structural maintenance and related secondary-index updates; it is not a promise to rearrange one contiguous disk array.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-clustered-index-5','pt-dbms-sql-20-clustered-index','In a clustered index''s B+ Tree structure, what do the leaf nodes contain?','["Pointers to a separate location where row data lives", "The actual row data itself", "Only column names", "Nothing; leaves are empty in a clustered index"]'::jsonb,1,'Unlike a non-clustered index, a clustered index''s leaves ARE the actual table rows, not pointers to them elsewhere.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-clustered-index-6','pt-dbms-sql-20-clustered-index','Why might using a random UUID as a clustered primary key cause performance problems?','["UUIDs cannot be stored in a database", "Scattered insertion points can increase page activity, splits and cache costs under some workloads", "UUIDs are always duplicated", "It removes the need for any index at all"]'::jsonb,1,'The effect depends on key width, distribution, occupancy, concurrency and storage. Ordered leaf organization does not require contiguous physical disk placement.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
