insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cp-dbms-sql-stock-with-a-default',null::text,'Stock With a Default','Easy','stock-with-a-default','Return id,name and stock with NULL stock displayed as 0, preserving known stock values and all source rows. This is an output convention, not a stored measurement repair. Order by id.

**MySQL dialect.**

```sql
CREATE TABLE products (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  price INTEGER NOT NULL,
  stock INTEGER
);
INSERT INTO products (id, name, category, price, stock) VALUES
(1, ''ProLaptop'', ''Electronics'', 85000, 12),
(2, ''Notebook'', ''Stationery'', 40, NULL),
(3, ''Python Basics'', ''Books'', 350, 5),
(4, ''ProPhone'', ''Electronics'', 45000, 0),
(5, ''Novel'', ''Books'', 220, NULL),
(6, ''Desk Lamp'', ''Home'', 900, 8);
```

**Required ordering:** As explicitly ordered in the result query.

**Edge cases:**
- Known zero is already present.
- NULL becomes zero only in the returned expression.','[{"input": "INSERT INTO products (id, name, category, price, stock) VALUES\n(1, ''ProLaptop'', ''Electronics'', 85000, 12),\n(2, ''Notebook'', ''Stationery'', 40, NULL),\n(3, ''Python Basics'', ''Books'', 350, 5),\n(4, ''ProPhone'', ''Electronics'', 45000, 0),\n(5, ''Novel'', ''Books'', 220, NULL),\n(6, ''Desk Lamp'', ''Home'', 900, 8);", "output": "id\tname\tstock\n1\tProLaptop\t12\n2\tNotebook\t0\n3\tPython Basics\t5\n4\tProPhone\t0\n5\tNovel\t0\n6\tDesk Lamp\t8", "explanation": "The first present candidate supplies the output. Known zero remains zero and missing stock uses the explicit fallback without changing stored facts.", "check_sql": ""}]'::jsonb,'[{"seed_sql": "INSERT INTO products (id, name, category, price, stock) VALUES\n(1, ''ProTablet'', ''Electronics'', 32000, 4),\n(2, ''Pencil Set'', ''Stationery'', 60, NULL),\n(3, ''SQL Guide'', ''Books'', 500, 10),\n(4, ''ProSpeaker'', ''Electronics'', 6000, 0);", "expected": "id\tname\tstock\n1\tProTablet\t4\n2\tPencil Set\t0\n3\tSQL Guide\t10\n4\tProSpeaker\t0", "hidden": true}, {"seed_sql": "INSERT INTO products VALUES (1,''Unknown'',''Books'',1,NULL),(2,''Empty'',''Books'',1,0),(3,''Known'',''Books'',1,7);", "expected": "id\tname\tstock\n1\tUnknown\t0\n2\tEmpty\t0\n3\tKnown\t7", "hidden": true}]'::jsonb,'["Use only the supplied synthetic tables and requested transition.", "Preserve unrelated rows."]'::jsonb,'["Use a result expression rather than UPDATE.", "Preserve the original output alias and ordering."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The first present candidate supplies the output. Known zero remains zero and missing stock uses the explicit fallback without changing stored facts.','{"sql": "SELECT id,name,COALESCE(stock,0) AS stock FROM products ORDER BY id;"}'::jsonb,'The first present candidate supplies the output. Known zero remains zero and missing stock uses the explicit fallback without changing stored facts.',array['sql'],'CREATE TABLE products (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  price INTEGER NOT NULL,
  stock INTEGER
);','INSERT INTO products (id, name, category, price, stock) VALUES
(1, ''ProLaptop'', ''Electronics'', 85000, 12),
(2, ''Notebook'', ''Stationery'', 40, NULL),
(3, ''Python Basics'', ''Books'', 350, 5),
(4, ''ProPhone'', ''Electronics'', 45000, 0),
(5, ''Novel'', ''Books'', 220, NULL),
(6, ''Desk Lamp'', ''Home'', 900, 8);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-12-coalesce' on conflict(id) do update set description=excluded.description,examples=excluded.examples,test_cases=excluded.test_cases,constraints=excluded.constraints,hints=excluded.hints,editorial=excluded.editorial,solution_code=excluded.solution_code,solution_approach=excluded.solution_approach,updated_at=now() where (dsa_problems.description,dsa_problems.examples,dsa_problems.test_cases,dsa_problems.constraints,dsa_problems.hints,dsa_problems.editorial,dsa_problems.solution_code,dsa_problems.solution_approach) is distinct from (excluded.description,excluded.examples,excluded.test_cases,excluded.constraints,excluded.hints,excluded.editorial,excluded.solution_code,excluded.solution_approach);
