if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-commit-1' and (question_text,options,correct_index,explanation) is distinct from ('What does COMMIT do?','["Cancels the transaction", "Ends the transaction successfully, making its changes permanent and visible to others", "Pauses the transaction", "Deletes the transaction log"]'::jsonb,1,'COMMIT is the successful, permanent conclusion of a transaction.') and (question_text,options,correct_index,explanation) is distinct from ('What does COMMIT do?','["Cancels the transaction", "Successfully completes the transaction under its documented commit contract; visibility in other readers follows their isolation and snapshot rules", "Pauses the transaction", "Deletes the transaction log"]'::jsonb,1,'Statement completion is not commit completion. Confirmed commit establishes the supported database outcome without forcing every existing snapshot to refresh.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-commit-1'; end if;
