if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-commit-2' and (question_text,options,correct_index,explanation) is distinct from ('Before COMMIT runs, can other transactions see the changes made so far?','["Yes, always immediately", "No \u2014 under proper isolation, other transactions still see the old values until COMMIT succeeds", "Only if isolation is disabled entirely", "Only SELECT statements can see uncommitted changes"]'::jsonb,1,'Isolation (22.7) keeps uncommitted changes invisible to other transactions until commit.') and (question_text,options,correct_index,explanation) is distinct from ('Under InnoDB READ COMMITTED or REPEATABLE READ, can an ordinary consistent read in another transaction consume the writer’s uncommitted replacement values?','["Yes, always immediately", "No; it uses an appropriate committed version, while locking reads can have different waiting behavior", "Only if isolation is disabled entirely", "Only SELECT statements can see uncommitted changes"]'::jsonb,1,'The stated levels prevent dirty reads. READ UNCOMMITTED can permit them, so isolation must be named rather than labeled proper.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-commit-2'; end if;
