if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-commit-3' and (question_text,options,correct_index,explanation) is distinct from ('Can a transaction be undone after COMMIT has completed?','["Yes, using ROLLBACK", "No \u2014 once committed, changes are permanent; correcting them requires a new, separate transaction", "Yes, but only within the same session", "Yes, automatically after 24 hours"]'::jsonb,1,'COMMIT is a one-way, irreversible boundary — ROLLBACK cannot undo an already-committed transaction.') and (question_text,options,correct_index,explanation) is distinct from ('Can a transaction be undone after COMMIT has completed?','["Yes, using ROLLBACK", "No \u2014 once committed, changes are permanent; correcting them requires a new, separate transaction", "Yes, but only within the same session", "Yes, automatically after 24 hours"]'::jsonb,1,'COMMIT is a one-way, irreversible boundary — ROLLBACK cannot undo an already-committed transaction.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-commit-3'; end if;
