insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-commit-1','pt-dbms-sql-22-commit','What does COMMIT do?','["Cancels the transaction", "Successfully completes the transaction under its documented commit contract; visibility in other readers follows their isolation and snapshot rules", "Pauses the transaction", "Deletes the transaction log"]'::jsonb,1,'Statement completion is not commit completion. Confirmed commit establishes the supported database outcome without forcing every existing snapshot to refresh.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-commit-2','pt-dbms-sql-22-commit','Under InnoDB READ COMMITTED or REPEATABLE READ, can an ordinary consistent read in another transaction consume the writer’s uncommitted replacement values?','["Yes, always immediately", "No; it uses an appropriate committed version, while locking reads can have different waiting behavior", "Only if isolation is disabled entirely", "Only SELECT statements can see uncommitted changes"]'::jsonb,1,'The stated levels prevent dirty reads. READ UNCOMMITTED can permit them, so isolation must be named rather than labeled proper.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-commit-3','pt-dbms-sql-22-commit','Can a transaction be undone after COMMIT has completed?','["Yes, using ROLLBACK", "No — once committed, changes are permanent; correcting them requires a new, separate transaction", "Yes, but only within the same session", "Yes, automatically after 24 hours"]'::jsonb,1,'COMMIT is a one-way, irreversible boundary — ROLLBACK cannot undo an already-committed transaction.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-commit-4','pt-dbms-sql-22-commit','Can COMMIT fail, and how should deferred-constraint examples be scoped across engines?','["No, COMMIT always succeeds unconditionally", "Yes; for example PostgreSQL can reject a deferred constraint at commit, while InnoDB does not support that deferred foreign-key mechanism", "Only network failures can cause COMMIT to fail", "COMMIT failures are impossible in SQL databases"]'::jsonb,1,'Commit failure must be handled, but PostgreSQL deferred constraints must not be presented as InnoDB deferred foreign-key support.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-commit-5','pt-dbms-sql-22-commit','Under autocommit mode, when does an explicit COMMIT become meaningful?','["It''s always meaningless under autocommit", "Only once you''ve explicitly opened a multi-statement transaction with START TRANSACTION, overriding the per-statement autocommit behavior", "Only on Mondays", "Autocommit and explicit COMMIT cannot coexist in any database"]'::jsonb,1,'Explicitly starting a transaction is what makes a later explicit COMMIT meaningful, distinct from autocommit''s implicit per-statement commits.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-commit-6','pt-dbms-sql-22-commit','Why does ROLLBACK not reverse MyISAM table writes as it can reverse pending InnoDB changes?','["MyISAM doesn''t support SQL at all", "MyISAM is nontransactional, so its writes do not participate in InnoDB-style transaction rollback", "COMMIT is disabled entirely on MyISAM", "MyISAM only supports SELECT statements"]'::jsonb,1,'This is an engine capability distinction, not evidence that the course judge or any hosted provider was verified.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-commit-7','pt-dbms-sql-22-commit','Which ACID property concerns persistence of committed changes within the documented settings and failure contract?','["Only Isolation", "Durability, with guarantees bounded by the actual persistence settings, storage and failure scope", "Only Atomicity", "None of the ACID properties relate to COMMIT"]'::jsonb,1,'A successful live commit does not prove survival of every disaster or replace backup and restore verification.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-commit-8','pt-dbms-sql-22-commit','In the two-account transfer example, what happens to the debit and credit updates once COMMIT succeeds?','["They remain private forever", "They become committed under the documented persistence contract; fresh eligible reads can observe them while existing snapshots may retain older versions", "Only the debit can commit", "COMMIT reverses both changes"]'::jsonb,1,'Both supported changes commit together; other readers’ visibility still follows their isolation and snapshot rules.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
