if exists(select 1 from public.test_questions where id='pt-dbms-sql-12-comparison-operators-application-new-9' and (question_text,options,correct_index,explanation) is distinct from ('What should be verified before changing comparison types for speed?','["Only whether the query is shorter", "That the result semantics remain correct", "Whether all values can be displayed", "That UNKNOWN has been disabled"]'::jsonb,1,'An optimization must preserve the answer.') and (question_text,options,correct_index,explanation) is distinct from ('What should be verified before changing comparison types for speed?','["Only whether the query is shorter", "That the result semantics remain correct", "Whether all values can be displayed", "That UNKNOWN has been disabled"]'::jsonb,1,'An optimization must preserve the answer.')) then raise exception 'Edited question requires review: %', 'pt-dbms-sql-12-comparison-operators-application-new-9'; end if;
