update public.learning_topics set short_description='Use SQL comparison operators for numbers, text, and dates; understand inclusive boundaries, collations, NULL, and MySQL NULL-safe equality.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Use SQL comparison operators for numbers, text, and dates; understand inclusive boundaries, collations, NULL, and MySQL NULL-safe equality.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Comparison Operators.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-12-comparison-operators' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-12-comparison-operators-application','MCQ Test 2',category,10,10,'Application and scenarios for Comparison Operators.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-12-comparison-operators' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-comparison-operators-1','pt-dbms-sql-12-comparison-operators','Which spelling is standard SQL for not equal?','["><", "<>", "NOT=", "=="]'::jsonb,1,'MySQL also accepts !=, but <> is the standard form.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-comparison-operators-2','pt-dbms-sql-12-comparison-operators','What is the ordinary comparison NULL = NULL?','["TRUE", "UNKNOWN", "FALSE", "A syntax error"]'::jsonb,1,'NULL represents missing information under ordinary comparison semantics.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-comparison-operators-3','pt-dbms-sql-12-comparison-operators','Which predicate finds unknown prices?','["price = NULL", "price IS NULL", "price <> NULL", "price < NULL"]'::jsonb,1,'Missingness has an explicit predicate.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-comparison-operators-4','pt-dbms-sql-12-comparison-operators','What can determine whether differently cased labels compare equal?','["Only the equals character", "The applicable text collation", "Only the source row count", "The query indentation"]'::jsonb,1,'Text comparison is governed by more than operator spelling.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-comparison-operators-5','pt-dbms-sql-12-comparison-operators','Why avoid careless cross-type comparisons?','["All cross-type comparisons are forbidden", "Implicit conversion can alter meaning and index use", "Conversion always preserves every identifier", "Types never affect comparisons"]'::jsonb,1,'Bind and validate the intended operand types.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-comparison-operators-6','pt-dbms-sql-12-comparison-operators','Can DATE values use ordering comparisons?','["No, only text can be ordered", "Yes, correctly typed dates have chronological order", "Only with a DATE_COMPARE keyword", "Only equality works"]'::jsonb,1,'Temporal type and boundary interpretation still matter.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-comparison-operators-7','pt-dbms-sql-12-comparison-operators','Which group contains ordinary ordering operators?','["AND, OR and NOT", "<, >, <= and >=", "SELECT, FROM and WHERE", "IS, AS and ON"]'::jsonb,1,'These operators distinguish strict from inclusive endpoints.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-comparison-operators-8','pt-dbms-sql-12-comparison-operators','Which not-equal alternative does MySQL accept?','["><", "!=", "==!", "NOT="]'::jsonb,1,'Dialect acceptance should not be confused with standard spelling.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-12-comparison-operators-new-9','pt-dbms-sql-12-comparison-operators','What does price <= 600 include?','["A known price exactly 600", "Only prices below 600", "NULL prices automatically", "Every text code"]'::jsonb,0,'The inclusive endpoint permits equality.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-12-comparison-operators-new-10','pt-dbms-sql-12-comparison-operators','Why is 2 <= quantity <= 6 a poor MySQL range expression?','["MySQL requires every range to use LIKE", "It can compare an intermediate truth value rather than express both range tests", "All quantities become NULL", "It always raises a syntax error"]'::jsonb,1,'Use quantity>=2 AND quantity<=6.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-12-comparison-operators-application-new-1','pt-dbms-sql-12-comparison-operators-application','Does price <> 200 retain NULL prices in WHERE?','["Yes, NULL is every value except 200", "No, the comparison is UNKNOWN", "Only with an index", "Always when sorted"]'::jsonb,1,'Add a deliberate IS NULL branch if missing prices belong in the report.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-12-comparison-operators-application-new-2','pt-dbms-sql-12-comparison-operators-application','What does MySQL NULL-safe equality return for two NULL operands?','["UNKNOWN", "FALSE", "TRUE", "A missing result row"]'::jsonb,2,'The dialect-specific operator deliberately treats both missing values as equal.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-12-comparison-operators-application-new-3','pt-dbms-sql-12-comparison-operators-application','What does NULL-safe equality return when only one operand is NULL?','["TRUE", "UNKNOWN", "The non-NULL operand", "FALSE"]'::jsonb,3,'This supports explicit optional-value mismatch detection.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
