insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-composite-index-1','pt-dbms-sql-20-composite-index','In a composite index on (department, gpa), which column determines the primary sort order?','["gpa, always sorted first", "department, since it is listed first", "Whichever column has more distinct values", "Neither; both are sorted independently"]'::jsonb,1,'Composite index entries are sorted by the first declared column, then by the second within groups of the first.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-composite-index-2','pt-dbms-sql-20-composite-index','What is the ''leftmost-prefix rule'' for composite indexes?','["Only the rightmost column in the index can be used in a WHERE clause", "A composite index on (A, B, C) can efficiently serve queries on A, or A+B, or A+B+C, but generally not B alone or C alone", "Composite indexes can only have exactly 2 columns", "All columns in a composite index must be used together, always"]'::jsonb,1,'Leading-prefix predicates support straightforward lookup and range reasoning. Nonleading predicates can still benefit from an index scan,coverage or supported skip-scan strategies; inspect the actual plan.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-composite-index-3','pt-dbms-sql-20-composite-index','Which predicate supplies the straightforward leading department equality followed by a GPA range for index(department,gpa)?','["WHERE gpa > 3.5 (alone)", "WHERE department = ''CS'' AND gpa > 3.5", "WHERE email = ''x@example.com''", "WHERE name LIKE ''%Doe%''"]'::jsonb,1,'Fixing the leading department identifies a department region, then the GPA condition bounds the following key range. Other access patterns may be possible but do not supply this leading-prefix shape.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-composite-index-4','pt-dbms-sql-20-composite-index','Why does a GPA-only predicate lack the straightforward leading-prefix lookup offered by an index on (department,gpa)?','["Because gpa is a floating point number", "Because the index is sorted by department first, so gpa values are only sorted within each department group, not across the whole table", "Because composite indexes never store gpa values", "Because gpa cannot be indexed under any circumstances"]'::jsonb,1,'Without knowing the department, matching gpa values are scattered across many department groups rather than contiguous.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-composite-index-5','pt-dbms-sql-20-composite-index','What analogy best explains the leftmost-prefix behavior of composite indexes?','["A dictionary sorted randomly", "A phone book sorted by last name then first name — easy to find by last name, but finding by first name alone requires scanning the whole book", "A single-column list sorted numerically", "A hash table with no ordering at all"]'::jsonb,1,'This classic analogy captures why leading-column filters are efficient but trailing-column-only filters are not.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-composite-index-6','pt-dbms-sql-20-composite-index','Can a composite index on (department, gpa) help satisfy `ORDER BY department, gpa` without an extra sort step?','["No, composite indexes never help with sorting", "Yes, a compatible chosen index scan can provide that order; the actual plan must confirm it", "Only if a separate index also exists on gpa alone", "Only for tables smaller than 1000 rows"]'::jsonb,1,'The key order can satisfy compatible ordering, but the optimizer may choose another strategy. Keep ORDER BY explicit for the output contract.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-composite-index-7','pt-dbms-sql-20-composite-index','An application frequently filters by gpa alone but rarely by department alone or together. What''s the implication for index design?','["An index on (department, gpa) is still the best choice regardless of query patterns", "A separate index with gpa as the leading column (or gpa alone) would better match this query pattern", "Composite indexes cannot ever include gpa", "No index is needed since gpa is a decimal"]'::jsonb,1,'Column order should reflect actual query filter patterns; if gpa-alone filtering dominates, gpa should lead (or have its own index).',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-composite-index-8','pt-dbms-sql-20-composite-index','In MySQL, why might extra ordinary key columns beyond filtering columns be added to an index?','["To make the index unusable for any query", "To turn the composite index into a covering index that can answer a query without a separate row lookup", "To force the table to become a heap", "To remove the leftmost-prefix restriction entirely"]'::jsonb,1,'Adding required output values as key columns can make an access path covering. MySQL syntax differs from engines offering a separate INCLUDE clause, and extra width has costs.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-20-composite-index-new-9','pt-dbms-sql-20-composite-index','Are indexes on (learner_id,registered_at) and (registered_at,learner_id) equivalent?','["Yes, columns are matched by name", "No, the leading order changes access and ordering options", "Only if both are integers", "Only if the table is empty"]'::jsonb,1,'Ordered keys compare leading components before following ones.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
