if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-concurrent-execution-1' and (question_text,options,correct_index,explanation) is distinct from ('In the running example, what is T2 computing when it executes step 2 (`A = A * 1.10`)?','["A withdrawal of \u20b9100 from A", "10% interest credited on A''s balance", "A transfer from A to B", "A rollback of T1''s change"]'::jsonb,1,'T2 is defined as crediting 10% interest to both A and B; step 2 multiplies A''s current value by 1.10.') and (question_text,options,correct_index,explanation) is distinct from ('A transaction reads balance A and computes A = A * 1.10. What arithmetic effect is it computing?','["A withdrawal of \u20b9100 from A", "A ten percent increase of the value it read", "A transfer from A to B", "A rollback of T1''s change"]'::jsonb,1,'Multiplying the read value by 1.10 adds ten percent; whether the later write is safe depends on the concurrent schedule.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-concurrent-execution-1'; end if;
