if not exists(select 1 from public.test_questions where id='tq-dbms-sql-23-concurrent-execution-3' and test_id='pt-dbms-sql-23-concurrent-execution') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-23-concurrent-execution-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-concurrent-execution-3' and (question_text,options,correct_index,explanation) is distinct from ('What is the ''correctness challenge'' that concurrent execution introduces?','["Concurrent transactions might use different SQL dialects", "Interleaved operations may produce a database state that no serial execution of the same transactions could have produced", "Concurrent execution always corrupts the database", "Concurrent execution is slower than serial execution"]'::jsonb,1,'Arbitrary interleaving can cause one transaction to read a stale value the other was about to overwrite, yielding a result impossible under any one-at-a-time ordering — that''s the problem serializability theory addresses.') and (question_text,options,correct_index,explanation) is distinct from ('What is the ''correctness challenge'' that concurrent execution introduces?','["Concurrent transactions might use different SQL dialects", "Interleaved operations may produce a database state that no serial execution of the same transactions could have produced", "Concurrent execution always corrupts the database", "Concurrent execution is slower than serial execution"]'::jsonb,1,'Arbitrary interleaving can cause one transaction to read a stale value the other was about to overwrite, yielding a result impossible under any one-at-a-time ordering — that''s the problem serializability theory addresses.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-concurrent-execution-3'; end if;
