if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-concurrent-execution-5' and (question_text,options,correct_index,explanation) is distinct from ('Which pair of transactions could safely be interleaved in ANY order with zero correctness risk?','["Two transactions that both read and write the same account balance", "Two transactions that touch completely disjoint data items", "T1 and T2 as defined in the running example", "Any two transactions, as long as both eventually commit"]'::jsonb,1,'Concurrency control issues only arise when transactions'' data accesses overlap; disjoint data means no conflicting operations exist, so any interleaving is safe.') and (question_text,options,correct_index,explanation) is distinct from ('In the classical independent-item schedule model, assuming no shared predicates or cross-item business dependencies, which pair can interleave without cross-transaction conflicts?','["Two transactions that both read and write the same account balance", "Two transactions accessing completely disjoint logical items", "T1 and T2 as defined in the running example", "Any two transactions, as long as both eventually commit"]'::jsonb,1,'The conclusion depends on complete independence in the stated model; real predicates, shared resources, or cross-item invariants may introduce additional dependencies.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-concurrent-execution-5'; end if;
