if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-concurrent-execution-7' and (question_text,options,correct_index,explanation) is distinct from ('A single-user embedded database that never has two connections open at once needs which of the following?','["Full concurrency control machinery, just in case", "No concurrency control at all, since no two transactions are ever ''in flight'' simultaneously", "Only view serializability checking", "Precedence graphs for every query"]'::jsonb,1,'Concurrency control exists to manage interleaving between multiple in-flight transactions; with only one transaction ever active, the problem this chapter addresses simply doesn''t arise.') and (question_text,options,correct_index,explanation) is distinct from ('If a system truly permits only one transaction to be active at a time, what intertransaction concern is absent in that model?','["Full concurrency control machinery, just in case", "Interleaving between simultaneously active transactions", "Only view serializability checking", "Precedence graphs for every query"]'::jsonb,1,'One active transaction rules out the particular overlap problem; it does not remove validation, atomicity, durability, or other requirements, and a connection count alone is not the definition.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-concurrent-execution-7'; end if;
