if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-concurrent-execution-8' and (question_text,options,correct_index,explanation) is distinct from ('What is the ultimate correctness property the DBMS wants to guarantee under concurrent execution?','["That every transaction runs faster than it would serially", "That the result of any interleaved execution is equivalent to the result of some serial execution of the same transactions", "That no transaction ever waits for another", "That all transactions read the same values"]'::jsonb,1,'This is the definition of serializability — the formal goal that lets the DBMS gain interleaving''s performance benefits without sacrificing the illusion that transactions ran one at a time.') and (question_text,options,correct_index,explanation) is distinct from ('When a database promises serializable execution under its documented model, what relationship should admitted concurrent results have?','["That every transaction runs faster than it would serially", "They are equivalent to some permitted serial execution of the same transactions", "That no transaction ever waits for another", "That all transactions read the same values"]'::jsonb,1,'This is a serializable contract; weaker isolation levels can allow histories that do not satisfy it.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-concurrent-execution-8'; end if;
