update public.learning_topics set short_description='Explore database interleavings, lost updates, atomic updates, locks, MVCC, version checks, and deadlocks through worked concurrent scenarios.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Explore database interleavings, lost updates, atomic updates, locks, MVCC, version checks, and deadlocks through worked concurrent scenarios.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Concurrent Execution.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-23-concurrent-execution' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-concurrent-execution-application','MCQ Test 2',category,10,10,'Application and scenarios for Concurrent Execution.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-23-concurrent-execution' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-concurrent-execution-1','pt-dbms-sql-23-concurrent-execution','A transaction reads balance A and computes A = A * 1.10. What arithmetic effect is it computing?','["A withdrawal of ₹100 from A", "A ten percent increase of the value it read", "A transfer from A to B", "A rollback of T1''s change"]'::jsonb,1,'Multiplying the read value by 1.10 adds ten percent; whether the later write is safe depends on the concurrent schedule.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-concurrent-execution-2','pt-dbms-sql-23-concurrent-execution','Why can a database interleave multiple transactions instead of always running them one at a time?','["Interleaving is required by the SQL standard", "To overlap eligible work during waits and potentially improve throughput or response time", "It is the only way to prevent transactions from reading each other''s data", "It guarantees correctness automatically"]'::jsonb,1,'The benefit depends on workload and contention; concurrency does not guarantee a universal speedup.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-concurrent-execution-3','pt-dbms-sql-23-concurrent-execution','What is the ''correctness challenge'' that concurrent execution introduces?','["Concurrent transactions might use different SQL dialects", "Interleaved operations may produce a database state that no serial execution of the same transactions could have produced", "Concurrent execution always corrupts the database", "Concurrent execution is slower than serial execution"]'::jsonb,1,'Arbitrary interleaving can cause one transaction to read a stale value the other was about to overwrite, yielding a result impossible under any one-at-a-time ordering — that''s the problem serializability theory addresses.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-concurrent-execution-4','pt-dbms-sql-23-concurrent-execution','T1 reads A to compute a decrement; before T1 writes, T2 also reads A to compute an increase, and both later write absolute replacements. What risk needs analysis?','["No risk — A is never touched by both transactions", "A stale replacement may overwrite another intended effect, producing a result outside the required serial behavior", "T1 will automatically abort", "The database will refuse to allow this interleaving"]'::jsonb,1,'The reads alone do not prove an anomaly, but the full read-compute-overwrite history can lose an effect; inspect the writes and engine conflict handling.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-concurrent-execution-5','pt-dbms-sql-23-concurrent-execution','In the classical independent-item schedule model, assuming no shared predicates or cross-item business dependencies, which pair can interleave without cross-transaction conflicts?','["Two transactions that both read and write the same account balance", "Two transactions accessing completely disjoint logical items", "T1 and T2 as defined in the running example", "Any two transactions, as long as both eventually commit"]'::jsonb,1,'The conclusion depends on complete independence in the stated model; real predicates, shared resources, or cross-item invariants may introduce additional dependencies.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-concurrent-execution-6','pt-dbms-sql-23-concurrent-execution','What is the key distinction between ''concurrency'' and ''parallelism'' as used in this chapter?','["They are exactly the same thing", "Concurrency means simultaneous execution on multiple cores; parallelism means interleaving on one core", "Concurrency means interleaving execution (even on a single core via time-slicing); parallelism means literally simultaneous execution on multiple cores — both raise the same correctness issues", "Parallelism only applies to read-only transactions"]'::jsonb,2,'Even a single-core system interleaving transactions via time-slicing faces the same correctness questions this chapter covers; parallelism (true simultaneity) is a separate, additional case.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-concurrent-execution-7','pt-dbms-sql-23-concurrent-execution','If a system truly permits only one transaction to be active at a time, what intertransaction concern is absent in that model?','["Full concurrency control machinery, just in case", "Interleaving between simultaneously active transactions", "Only view serializability checking", "Precedence graphs for every query"]'::jsonb,1,'One active transaction rules out the particular overlap problem; it does not remove validation, atomicity, durability, or other requirements, and a connection count alone is not the definition.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-concurrent-execution-8','pt-dbms-sql-23-concurrent-execution','When a database promises serializable execution under its documented model, what relationship should admitted concurrent results have?','["That every transaction runs faster than it would serially", "They are equivalent to some permitted serial execution of the same transactions", "That no transaction ever waits for another", "That all transactions read the same values"]'::jsonb,1,'This is a serializable contract; weaker isolation levels can allow histories that do not satisfy it.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-concurrent-execution-fundamentals-9','pt-dbms-sql-23-concurrent-execution','What distinguishes concurrency from physical parallelism?','["Concurrent work can interleave on one processor", "Concurrency always requires several processors", "Parallelism means no overlap", "Concurrency forbids interleaving"]'::jsonb,0,'Overlapping progress can occur through interleaving without simultaneous execution.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-concurrent-execution-fundamentals-10','pt-dbms-sql-23-concurrent-execution','Two transactions read 10 and each writes 11 after intending an increment. Which anomaly is illustrated?','["Lossless join", "Lost update", "Durable commit", "Foreign key cascade"]'::jsonb,1,'A stale replacement overwrites the effect of the other increment.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-concurrent-execution-application-1','cx-concurrent-execution-application','Why prefer SET visits = visits + 1 for a shared counter?','["It disables all locking", "It expresses an arithmetic operation on the protected row", "It guarantees every crossrow invariant", "It prevents every deadlock"]'::jsonb,1,'The engine can coordinate a row update without relying on a stale client replacement.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-concurrent-execution-application-2','cx-concurrent-execution-application','A version-checked UPDATE affects zero rows. What must the caller do?','["Assume the new version was stored", "Commit an unrelated value", "Handle the failed condition instead of claiming success", "Delete the version column"]'::jsonb,2,'The optimistic condition or target row did not match.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-concurrent-execution-application-3','cx-concurrent-execution-application','What does MVCC primarily provide?','["Automatic removal of every anomaly", "No need for transaction boundaries", "Only one transaction at a time", "Visibility of suitable row versions for readers"]'::jsonb,3,'Version visibility can reduce blocking while still depending on isolation semantics.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-concurrent-execution-application-4','cx-concurrent-execution-application','Why does uniqueness of student and course not enforce capacity one?','["Different students can still enroll in the same course", "Unique constraints never work", "The course identifier must be text", "Capacity is always a primary key"]'::jsonb,0,'Capacity is a set level invariant beyond duplicate enrollment prevention.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-concurrent-execution-application-5','cx-concurrent-execution-application','Which evidence exercises a concurrency decision window?','["Only a sequential SELECT", "An ordered two-session test with final invariant checks", "A formatted SQL snippet", "A successful schema import"]'::jsonb,1,'A multi-session schedule must actually overlap the competing operations.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-concurrent-execution-application-6','cx-concurrent-execution-application','What defines a deadlock?','["Any slow query", "Any transaction with two statements", "A cycle of incompatible transaction waits", "Any row lock"]'::jsonb,2,'A cycle prevents all participating transactions from progressing without intervention.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-concurrent-execution-application-7','cx-concurrent-execution-application','Why retry the coherent transaction after a deadlock victim rollback?','["The last statement always contains the whole business action", "Retries remove all locks permanently", "A deadlock proves invalid SQL syntax", "Earlier reads and assumptions may need reevaluation"]'::jsonb,3,'A safe retry repeats the decision under a new valid transaction state.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
