select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-15-group-by-and-aggregation/conditional-aggregation' and lower(g.slug)='dbms-sql-tutorial';
