update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "One regional group can feed several different measures", "description": "Widget and Gadget rows remain in one regional population. Each CASE selects its own contribution; global filtering would remove rows before another measure could use them.", "columns": ["North input", "Widget sum contribution", "Gadget sum contribution"], "rows": [["Widget 200", "200", "0"], ["Gadget 150", "0", "150"], ["Widget 300", "300", "0"], ["Regional result", "500", "150"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "One regional group can feed several different measures", "description": "Widget and Gadget rows remain in one regional population. Each CASE selects its own contribution; global filtering would remove rows before another measure could use them.", "columns": ["North input", "Widget sum contribution", "Gadget sum contribution"], "rows": [["Widget 200", "200", "0"], ["Gadget 150", "0", "150"], ["Widget 300", "300", "0"], ["Regional result", "500", "150"]]}]'::jsonb;
if exists(select 1 from public.test_questions where test_id='pt-dbms-sql-15-conditional-aggregation' and id not in ('tq-dbms-sql-15-conditional-aggregation-1','tq-dbms-sql-15-conditional-aggregation-2','tq-dbms-sql-15-conditional-aggregation-3','tq-dbms-sql-15-conditional-aggregation-4','tq-dbms-sql-15-conditional-aggregation-5','tq-dbms-sql-15-conditional-aggregation-6','tq-dbms-sql-15-conditional-aggregation-7','tq-dbms-sql-15-conditional-aggregation-8','cx-conditional-aggregation-fundamentals-9','cx-conditional-aggregation-fundamentals-10')) then raise exception 'Unexpected questions require review: %', 'pt-dbms-sql-15-conditional-aggregation'; end if;
