if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-conditional-aggregation-1' and test_id<>'pt-dbms-sql-15-conditional-aggregation') then raise exception 'Question ID collision: %', 'tq-dbms-sql-15-conditional-aggregation-1'; end if;
