if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-conditional-aggregation-1' and (question_text,options,correct_index,explanation) is distinct from ('What is the purpose of putting a CASE WHEN expression inside an aggregate function like SUM?','["To sort the aggregate results", "To compute multiple differently-conditioned aggregate values in a single GROUP BY pass, one per column", "To filter out NULL rows automatically", "To convert the aggregate to a string"]'::jsonb,1,'Conditional aggregation lets one query produce several conditionally-computed aggregate columns per group, avoiding multiple separate queries.') and (question_text,options,correct_index,explanation) is distinct from ('What is the purpose of putting a CASE WHEN expression inside an aggregate function like SUM?','["To sort aggregate results", "To express several differently qualified measures at one grouping grain; physical work remains plan-dependent", "To remove every NULL row", "To convert aggregates to text"]'::jsonb,1,'A grouped expression states contribution rules logically; it does not guarantee a particular physical scan count.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-conditional-aggregation-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-conditional-aggregation-2' and test_id<>'pt-dbms-sql-15-conditional-aggregation') then raise exception 'Question ID collision: %', 'tq-dbms-sql-15-conditional-aggregation-2'; end if;
