if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-conditional-aggregation-2' and (question_text,options,correct_index,explanation) is distinct from ('Given `SUM(CASE WHEN product = ''Widget'' THEN amount ELSE 0 END)` grouped by region, what is the East region''s result?','["310 (all East orders)", "160 (East''s Widget-only orders: 100 + 60)", "150 (East''s Gadget order)", "0"]'::jsonb,1,'Only East''s two Widget orders (100 and 60) contribute their amount; the Gadget order contributes 0, so the sum is 160.') and (question_text,options,correct_index,explanation) is distinct from ('East has Widget orders 100 and 60 and a Gadget order 150. What is SUM(CASE WHEN product=''Widget'' THEN amount ELSE 0 END) for East?','["310 (all East orders)", "160 (East''s Widget-only orders: 100 + 60)", "150 (East''s Gadget order)", "0"]'::jsonb,1,'The two Widget amounts contribute 160 and the Gadget contributes zero.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-conditional-aggregation-2'; end if;
