if not exists(select 1 from public.test_questions where id='tq-dbms-sql-15-conditional-aggregation-3' and test_id='pt-dbms-sql-15-conditional-aggregation') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-15-conditional-aggregation-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-conditional-aggregation-3' and (question_text,options,correct_index,explanation) is distinct from ('Why must the ELSE branch of a CASE inside SUM use 0, not NULL?','["SUM ignores 0 just like NULL, so it doesn''t matter", "SUM ignores NULLs when summing, so using NULL for non-matching rows works too, and either can be defensible \u2014 but 0 makes the additive intent explicit and guarantees a non-NULL result even if a group has zero matches", "NULL would cause a syntax error inside CASE", "0 makes SUM return a string instead of a number"]'::jsonb,1,'SUM ignores NULLs during aggregation, so ELSE NULL(default) also works for SUM; ELSE 0 is the conventional choice because it also guarantees SUM never returns NULL for a group with zero matches.') and (question_text,options,correct_index,explanation) is distinct from ('With nullable amounts, does ELSE 0 in conditional SUM universally guarantee a nonnull result?','["Yes, even empty input has a zero row", "No; all matching amounts can be NULL, and empty ungrouped input also yields NULL; choose an explicit missing-value policy", "NULL causes a CASE syntax error", "ELSE 0 always makes SUM textual"]'::jsonb,1,'ELSE 0 handles evaluated nonmatching rows, but cannot supply a value for absent rows or replace NULL selected by a matching branch.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-conditional-aggregation-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-conditional-aggregation-4' and test_id<>'pt-dbms-sql-15-conditional-aggregation') then raise exception 'Question ID collision: %', 'tq-dbms-sql-15-conditional-aggregation-4'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-15-conditional-aggregation-4' and test_id='pt-dbms-sql-15-conditional-aggregation') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-15-conditional-aggregation-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-conditional-aggregation-4' and (question_text,options,correct_index,explanation) is distinct from ('Why should COUNT(CASE WHEN product=''Widget'' THEN 1 END) omit the ELSE clause rather than using ELSE 0?','["ELSE 0 causes a syntax error in COUNT", "COUNT(expr) skips NULLs but counts every non-NULL value including 0, so ELSE 0 would incorrectly count non-matching rows too", "COUNT cannot be used with CASE at all", "Omitting ELSE makes the query run faster with no functional difference"]'::jsonb,1,'COUNT(expr) counts all non-NULL values. If ELSE 0 is used, non-matching rows produce 0 (not NULL) and get counted, inflating the result; omitting ELSE defaults to NULL, which COUNT correctly skips.') and (question_text,options,correct_index,explanation) is distinct from ('Why should COUNT(CASE WHEN product=''Widget'' THEN 1 END) omit the ELSE clause rather than using ELSE 0?','["ELSE 0 causes a syntax error in COUNT", "COUNT(expr) skips NULLs but counts every non-NULL value including 0, so ELSE 0 would incorrectly count non-matching rows too", "COUNT cannot be used with CASE at all", "Omitting ELSE makes the query run faster with no functional difference"]'::jsonb,1,'COUNT(expr) counts all non-NULL values. If ELSE 0 is used, non-matching rows produce 0 (not NULL) and get counted, inflating the result; omitting ELSE defaults to NULL, which COUNT correctly skips.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-conditional-aggregation-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-conditional-aggregation-5' and test_id<>'pt-dbms-sql-15-conditional-aggregation') then raise exception 'Question ID collision: %', 'tq-dbms-sql-15-conditional-aggregation-5'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-15-conditional-aggregation-5' and test_id='pt-dbms-sql-15-conditional-aggregation') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-15-conditional-aggregation-5'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-conditional-aggregation-5' and (question_text,options,correct_index,explanation) is distinct from ('What does `COUNT(CASE WHEN product = ''Widget'' THEN 1 END)` return for the West region, given West has orders 3 (Widget), 4 (Widget), and 5 (Gadget)?','["3", "1", "2", "0"]'::jsonb,2,'West has exactly 2 Widget orders (id 3 and id 4); the Gadget order (id 5) produces NULL and is skipped by COUNT.') and (question_text,options,correct_index,explanation) is distinct from ('West has two Widget orders and one Gadget order. What is COUNT(CASE WHEN product=''Widget'' THEN 1 END)?','["3", "1", "2", "0"]'::jsonb,2,'The two matching constants are counted; the Gadget produces NULL and is skipped.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-conditional-aggregation-5'; end if;
