insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-conditional-aggregation-3','pt-dbms-sql-15-conditional-aggregation','With nullable amounts, does ELSE 0 in conditional SUM universally guarantee a nonnull result?','["Yes, even empty input has a zero row", "No; all matching amounts can be NULL, and empty ungrouped input also yields NULL; choose an explicit missing-value policy", "NULL causes a CASE syntax error", "ELSE 0 always makes SUM textual"]'::jsonb,1,'ELSE 0 handles evaluated nonmatching rows, but cannot supply a value for absent rows or replace NULL selected by a matching branch.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-conditional-aggregation-4','pt-dbms-sql-15-conditional-aggregation','Why should COUNT(CASE WHEN product=''Widget'' THEN 1 END) omit the ELSE clause rather than using ELSE 0?','["ELSE 0 causes a syntax error in COUNT", "COUNT(expr) skips NULLs but counts every non-NULL value including 0, so ELSE 0 would incorrectly count non-matching rows too", "COUNT cannot be used with CASE at all", "Omitting ELSE makes the query run faster with no functional difference"]'::jsonb,1,'COUNT(expr) counts all non-NULL values. If ELSE 0 is used, non-matching rows produce 0 (not NULL) and get counted, inflating the result; omitting ELSE defaults to NULL, which COUNT correctly skips.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
