update public.learning_topics set short_description='Choose clear CASE branches for dispatch charges, missing values, and priority rules while distinguishing vendor conditional functions.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Choose clear CASE branches for dispatch charges, missing values, and priority rules while distinguishing vendor conditional functions.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Conditional Functions.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-14-conditional-functions' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-conditional-functions-application','MCQ Test 2',category,10,10,'Application and scenarios for Conditional Functions.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-14-conditional-functions' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-conditional-functions-1','pt-dbms-sql-14-conditional-functions','In the price_tier CASE expression, what value does an order with amount = 400.00 receive (given branches: <200 ''low'', <350 ''medium'', else ''high'')?','["''low''", "''medium''", "''high''", "''unknown''"]'::jsonb,2,'400.00 is not less than 200 or 350, so it falls through to the ELSE branch, ''high''.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-conditional-functions-2','pt-dbms-sql-14-conditional-functions','What does a CASE expression return if none of its WHEN conditions match and there is no ELSE clause?','["0", "An empty string", "NULL", "It raises an error"]'::jsonb,2,'Without an ELSE, a CASE expression with no matching WHEN simply evaluates to NULL rather than erroring.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-conditional-functions-3','pt-dbms-sql-14-conditional-functions','Which dialect does NOT support IF() or IIF() as a shorthand conditional function, requiring full CASE WHEN instead?','["MySQL", "SQLite", "SQL Server", "PostgreSQL"]'::jsonb,3,'Conditional function support is engine and version specific: MySQL provides IF, SQL Server provides IIF, and SQLite documents iif and version-dependent if aliases and argument counts. CASE is the portable starting point.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-conditional-functions-4','pt-dbms-sql-14-conditional-functions','In a searched CASE expression, what order are the WHEN clauses evaluated in?','["Bottom to top", "In random order chosen by the optimizer", "Top to bottom, stopping at the first match", "All at once, and ties are resolved alphabetically"]'::jsonb,2,'CASE evaluates WHEN clauses in the order they''re written and returns the value from the first one that matches.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-conditional-functions-5','pt-dbms-sql-14-conditional-functions','What does IIF(amount > 300, ''expensive'', ''affordable'') evaluate to for amount = 250.00?','["''expensive''", "''affordable''", "NULL", "An error"]'::jsonb,1,'250.00 is not greater than 300, so the false branch, ''affordable'', is returned.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-conditional-functions-6','pt-dbms-sql-14-conditional-functions','Which SQL Server expression is functionally equivalent to CASE WHEN amount > 300 THEN ''expensive'' ELSE ''affordable'' END?','["IF(amount > 300, ''expensive'', ''affordable'')", "IIF(amount > 300, ''expensive'', ''affordable'')", "SWITCH(amount > 300, ''expensive'', ''affordable'')", "COALESCE(amount > 300, ''expensive'', ''affordable'')"]'::jsonb,1,'IIF() is SQL Server''s two-branch conditional shorthand, directly equivalent to a simple CASE WHEN...ELSE...END with one condition.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-conditional-functions-7','pt-dbms-sql-14-conditional-functions','Why can a single MySQL IF or SQL Server IIF call not directly express four output tiers without nesting?','["IF()/IIF() can handle any number of branches natively", "IF()/IIF() only support exactly two outcomes (true/false branches), so more than two tiers require nested IFs or a full CASE WHEN", "IF()/IIF() cannot return string values", "IF()/IIF() are aggregate functions and cannot be used per-row"]'::jsonb,1,'For the MySQL IF and SQL Server IIF forms discussed here, the conditional function takes a condition and two result arguments. This statement is not a universal rule for newer SQLite variadic iif/if forms.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-conditional-functions-8','pt-dbms-sql-14-conditional-functions','What is a likely consequence of mixing incompatible return types across CASE branches, e.g. returning a number in one branch and text in another?','["SQL always silently converts everything to VARCHAR with no issue", "It can trigger an implicit-conversion surprise or an outright type error, depending on the engine", "CASE expressions ignore type mismatches entirely", "The query always returns NULL for every row in that case"]'::jsonb,1,'CASE branches should return compatible types; mismatched types can force implicit conversion (sometimes unexpected) or cause a hard type error, depending on the specific engine''s rules.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
