if exists(select 1 from public.dsa_problems where id='cx-conditional-functions-action' and description is distinct from 'Return order_id and action: status C means ignore, otherwise NULL overdue_days means review, positive overdue_days means chase, and every other row means wait.

**MySQL dialect.**

```sql
CREATE TABLE dispatch_orders (order_id INT PRIMARY KEY, charge DECIMAL(8,2), status_code CHAR(1), overdue_days INT);
INSERT INTO dispatch_orders VALUES (1,180,''P'',0),(2,200,''P'',3),(3,349,''S'',0),(4,350,''C'',7),(5,NULL,''P'',NULL);
```

**Required ordering:** order_id ascending

**Edge cases:**
- Cancelled overdue orders are ignored.
- Zero overdue days means wait.
- NULL delay means review for an active order.') then raise exception 'New coding ID already has other content: %', 'cx-conditional-functions-action'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-conditional-functions-action',null::text,'Prioritize dispatch actions','Medium','conditional-functions-action','Return order_id and action: status C means ignore, otherwise NULL overdue_days means review, positive overdue_days means chase, and every other row means wait.

**MySQL dialect.**

```sql
CREATE TABLE dispatch_orders (order_id INT PRIMARY KEY, charge DECIMAL(8,2), status_code CHAR(1), overdue_days INT);
INSERT INTO dispatch_orders VALUES (1,180,''P'',0),(2,200,''P'',3),(3,349,''S'',0),(4,350,''C'',7),(5,NULL,''P'',NULL);
```

**Required ordering:** order_id ascending

**Edge cases:**
- Cancelled overdue orders are ignored.
- Zero overdue days means wait.
- NULL delay means review for an active order.','[{"input": "INSERT INTO dispatch_orders VALUES (1,180,''P'',0),(2,200,''P'',3),(3,349,''S'',0),(4,350,''C'',7),(5,NULL,''P'',NULL);", "output": "order_id\taction\n1\twait\n2\tchase\n3\twait\n4\tignore\n5\treview", "explanation": "Cancellation has higher priority than overdue status; the remaining rows follow the delay policy."}]'::jsonb,'[{"seed_sql": "INSERT INTO dispatch_orders VALUES (8,10,''C'',NULL),(9,20,''P'',-1),(10,30,''P'',1);", "expected": "order_id\taction\n8\tignore\n9\twait\n10\tchase", "hidden": true}]'::jsonb,'[]'::jsonb,'["Encode cancellation before delay.", "Use IS NULL for the review branch."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'Cancellation has higher priority than overdue status; the remaining rows follow the delay policy.','{"sql": "SELECT order_id, CASE WHEN status_code=''C'' THEN ''ignore'' WHEN overdue_days IS NULL THEN ''review'' WHEN overdue_days>0 THEN ''chase'' ELSE ''wait'' END AS action FROM dispatch_orders ORDER BY order_id;"}'::jsonb,'Cancellation has higher priority than overdue status; the remaining rows follow the delay policy.',array['sql'],'CREATE TABLE dispatch_orders (order_id INT PRIMARY KEY, charge DECIMAL(8,2), status_code CHAR(1), overdue_days INT);','INSERT INTO dispatch_orders VALUES (1,180,''P'',0),(2,200,''P'',3),(3,349,''S'',0),(4,350,''C'',7),(5,NULL,''P'',NULL);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-14-conditional-functions' on conflict(id) do nothing;
