update public.learning_topics set short_description='Recognize read-write conflicts, transform interleavings and build precedence graphs with worked acyclic and cyclic examples, recovery distinctions and SQL trace caveats.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Recognize read-write conflicts, transform interleavings and build precedence graphs with worked acyclic and cyclic examples, recovery distinctions and SQL trace caveats.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Conflict Serializability.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-23-conflict-serializability' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-23-conflict-serializability-application','MCQ Test 2',category,10,10,'Application and scenarios for Conflict Serializability.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-23-conflict-serializability' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-conflict-serializability-1','pt-dbms-sql-23-conflict-serializability','Which pair of operations on the same data item A, from different transactions, does NOT count as a conflict?','["R(A) and W(A)", "W(A) and W(A)", "R(A) and R(A)", "W(A) and R(A)"]'::jsonb,2,'Two reads never interfere with each other since neither changes data — R-R is the only pairing on the same item that is not a conflict.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-conflict-serializability-2','pt-dbms-sql-23-conflict-serializability','What are the three conditions required for two operations to ''conflict''?','["Same transaction, same data item, same timestamp", "Different transactions, same data item, at least one is a write", "Different transactions, different data items, both are writes", "Same transaction, different data items, at least one is a read"]'::jsonb,1,'Conflict requires operations from two different transactions, touching the same data item, with at least one of the two being a write.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-conflict-serializability-3','pt-dbms-sql-23-conflict-serializability','In the worked example, schedule S1 was shown to be conflict-serializable by transforming it into which serial schedule?','["<T2, T1>", "<T1, T2>", "No serial schedule — S1 is not conflict-serializable", "A schedule involving a third transaction T3"]'::jsonb,1,'Move T1 operations on B across T2 operations on A using valid adjacent intertransaction swaps; this preserves conflict order and yields T1 then T2.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-conflict-serializability-4','pt-dbms-sql-23-conflict-serializability','In schedule S2 (T1: R(A), W(B); T2: R(B), W(A) interleaved as R1(A) R2(B) W1(B) W2(A)), why is it NOT conflict-serializable?','["Because R1(A) and R2(B) conflict", "Because the conflicts force T2 to precede T1 (on B) and simultaneously force T1 to precede T2 (on A) — a contradiction no swap sequence can resolve", "Because it has more than 4 operations", "Because neither transaction ever commits"]'::jsonb,1,'The B-conflict (R2 before W1) demands T2 before T1, while the A-conflict (R1 before W2) demands T1 before T2 — contradictory ordering requirements mean no serial-equivalent order exists.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-conflict-serializability-5','pt-dbms-sql-23-conflict-serializability','What operation is legal when checking conflict serializability by swapping?','["Swapping any two operations anywhere in the schedule, conflicting or not", "Swapping adjacent nonconflicting operations from different transactions while preserving each transaction program order", "Swapping only operations belonging to the same transaction", "Swapping conflicting operations as long as they are on different data items"]'::jsonb,1,'Legal exchanges preserve both conflict order and internal transaction order.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-conflict-serializability-6','pt-dbms-sql-23-conflict-serializability','If two transactions access completely disjoint sets of data items, what can be said about any schedule interleaving them?','["It can never be conflict-serializable", "It is trivially conflict-serializable, since there are no conflicting operations to worry about", "It depends on the isolation level", "It is only serializable if run serially"]'::jsonb,1,'With zero conflicting operation pairs, every interleaving is automatically equivalent to any serial order, making the schedule trivially conflict-serializable.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-conflict-serializability-7','pt-dbms-sql-23-conflict-serializability','How can an appropriate classical two-phase locking protocol enforce conflict serializability without a swap proof for each execution?','["It runs the full swap-checking algorithm on every schedule before executing it", "Its lock acquisition and release rules admit conflict-serializable histories in the stated model", "It disallows all non-serial schedules", "It only allows read-only transactions to run concurrently"]'::jsonb,1,'This is a property of the appropriate protocol and model, not a claim that every real engine isolation level admits only conflict-serializable histories.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-conflict-serializability-8','pt-dbms-sql-23-conflict-serializability','Which statement about swap validity is correct?','["Any two operations that are far apart in the schedule can be swapped directly in one step", "Swaps must be performed one adjacent pair at a time, and every intermediate swap in the sequence must itself involve non-conflicting operations", "Only the first and last operations of a schedule can ever be swapped", "Swapping is unrelated to whether a schedule is conflict-serializable"]'::jsonb,1,'Conflict serializability is checked by a sequence of adjacent swaps, each individually valid (non-conflicting) — you cannot ''jump'' an operation past a conflicting one even indirectly.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-conflict-serializability-new-9','pt-dbms-sql-23-conflict-serializability','What direction does r1(A) before w2(A) impose?','["T1 to T2", "T2 to T1", "No direction because reads never conflict", "T1 to itself"]'::jsonb,0,'A read-write pair on one item orders the distinct transactions.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-conflict-serializability-new-10','pt-dbms-sql-23-conflict-serializability','Why is S1 conflict serializable?','["It has no writes", "All its conflicts agree with T1 before T2", "Its operations were originally serial", "Commit markers erase conflicts"]'::jsonb,1,'The acyclic graph admits that serial order.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-conflict-serializability-application-new-1','pt-dbms-sql-23-conflict-serializability-application','Which graph property proves conflict serializability in the stated model?','["A cycle of any length", "Every vertex having an edge", "Acyclicity", "Equal transaction names"]'::jsonb,2,'A topological order provides a conflict equivalent serial sequence.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-conflict-serializability-application-new-2','pt-dbms-sql-23-conflict-serializability-application','Can a graph have several valid serial orders?','["No, every graph has exactly one order", "Only if all transactions abort", "Only when every pair conflicts", "Yes, independent transactions may be ordered differently"]'::jsonb,3,'Missing precedence constraints permit several topological orders.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-conflict-serializability-application-new-3','pt-dbms-sql-23-conflict-serializability-application','Why do r1(A) and r2(A) produce no conflict edge?','["Neither operation writes the item", "They belong to one transaction", "A is not a logical item", "Reads always commit immediately"]'::jsonb,0,'Two reads do not change each other observed value.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-conflict-serializability-application-new-4','pt-dbms-sql-23-conflict-serializability-application','What is wrong with swapping two distant operations directly?','["Distant operations always touch one item", "Intervening adjacent exchanges may cross conflicts", "Only the first operation matters", "Transaction order is irrelevant"]'::jsonb,1,'Every adjacent step needs its own valid justification.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-conflict-serializability-application-new-5','pt-dbms-sql-23-conflict-serializability-application','S2 has T1 to T2 and T2 to T1. What does this imply?','["Both serial orders work", "A read-read pair caused the cycle", "No conflict equivalent serial order exists", "Commit order automatically repairs it"]'::jsonb,2,'The required precedence directions contradict each other.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-conflict-serializability-application-new-6','pt-dbms-sql-23-conflict-serializability-application','Does an acyclic conflict graph alone rule out dirty reads?','["Yes, every acyclic history is strict", "Only with integer items", "Only with two transactions", "No, recovery and visibility properties need separate tests"]'::jsonb,3,'Conflict serializability is separate from cascadelessness.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-conflict-serializability-application-new-7','pt-dbms-sql-23-conflict-serializability-application','What must remain unchanged during legal intertransaction swaps?','["Each transaction own operation order", "Only the final operation count", "The visual spacing", "All unrelated table names"]'::jsonb,0,'Program order is part of the schedule definition.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-conflict-serializability-application-new-8','pt-dbms-sql-23-conflict-serializability-application','Why can matching final values be insufficient evidence?','["Outputs cannot be queried", "An inadmissible dependency pattern can happen to yield the same numbers", "Values determine the transaction names", "Graphs never describe writes"]'::jsonb,1,'Conflict equivalence preserves dependency order rather than one lucky fixture.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-conflict-serializability-application-new-9','pt-dbms-sql-23-conflict-serializability-application','What extra care does a multiversion SQL trace require?','["Treat every read as a dirty read", "Ignore isolation settings", "Identify actual versions and predicate dependencies", "Drop all read operations"]'::jsonb,2,'The implementation model can differ from a simple single-version history.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-conflict-serializability-application-new-10','pt-dbms-sql-23-conflict-serializability-application','A three-transaction cycle exists. Does removing an unrelated read fix it?','["Yes, every shorter history is serializable", "Only if the read used an alias", "Only if there are no commit markers", "No, the actual cycle edges remain"]'::jsonb,3,'Only a change to a dependency on the cycle can remove that cycle.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
