if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-consistency-1' and (question_text,options,correct_index,explanation) is distinct from ('What does ACID Consistency guarantee?','["Fast transaction execution", "The database moves from one valid state (respecting all constraints) to another valid state", "All users see the same query results", "Data is never deleted"]'::jsonb,1,'Consistency is about preserving the validity of declared constraints across a transaction.') and (question_text,options,correct_index,explanation) is distinct from ('What does ACID Consistency guarantee?','["Fast transaction execution", "The database moves from one valid state (respecting all constraints) to another valid state", "All users see the same query results", "Data is never deleted"]'::jsonb,1,'Consistency is about preserving the validity of declared constraints across a transaction.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-consistency-1'; end if;
