if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-consistency-2' and (question_text,options,correct_index,explanation) is distinct from ('If a transaction would violate a CHECK (balance >= 0) constraint, what does Consistency guarantee?','["The constraint is temporarily relaxed to let the transaction succeed", "The transaction is rejected, preventing the database from ever entering that invalid state", "Only a warning is logged, but the transaction proceeds", "The balance is automatically set to 0 instead"]'::jsonb,1,'Consistency means the database refuses to complete a transaction that would violate a declared constraint.') and (question_text,options,correct_index,explanation) is distinct from ('An InnoDB UPDATE violates an enforced CHECK constraint. What must application error handling recognize?','["The constraint is temporarily relaxed to let the transaction succeed", "The failing statement is rejected; earlier successful statements can remain pending until explicit transaction cleanup.", "Only a warning is logged, but the transaction proceeds", "The balance is automatically set to 0 instead"]'::jsonb,1,'Do not assume every statement error automatically rolls back the entire transaction.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-consistency-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-consistency-3' and test_id<>'pt-dbms-sql-22-consistency') then raise exception 'Question ID collision: %', 'tq-dbms-sql-22-consistency-3'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-22-consistency-3' and test_id='pt-dbms-sql-22-consistency') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-22-consistency-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-consistency-3' and (question_text,options,correct_index,explanation) is distinct from ('Does ACID Consistency guarantee that data is ''correct'' in every real-world business sense?','["Yes, it guarantees full business correctness", "No \u2014 it only guarantees adherence to constraints actually DECLARED in the schema; undeclared business rules aren''t protected", "It guarantees correctness only for numeric columns", "Consistency has nothing to do with correctness at all"]'::jsonb,1,'Only explicitly declared constraints are enforced — Consistency doesn''t cover business rules the schema doesn''t express.') and (question_text,options,correct_index,explanation) is distinct from ('Does ACID consistency guarantee every real-world business fact is correct?','["Yes, it guarantees full business correctness", "No; declared constraints and correct trusted transaction logic must encode the required invariants.", "It guarantees correctness only for numeric columns", "Consistency has nothing to do with correctness at all"]'::jsonb,1,'Both database enforcement and application logic contribute; undeclared rules are not invented by the engine.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-consistency-3'; end if;
