if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-consistency-4' and (question_text,options,correct_index,explanation) is distinct from ('Is ACID Consistency the same concept as CAP theorem Consistency?','["Yes, they are identical", "No \u2014 ACID Consistency is about respecting a single database''s own constraints; CAP Consistency is about distributed nodes agreeing on data", "CAP theorem doesn''t apply to databases", "ACID Consistency only exists in distributed databases"]'::jsonb,1,'These are genuinely different concepts that happen to share a name — a classic point of confusion.') and (question_text,options,correct_index,explanation) is distinct from ('How does ACID consistency differ from CAP consistency?','["Yes, they are identical", "ACID consistency concerns valid-state invariants; CAP consistency is generally linearizability.", "CAP theorem doesn''t apply to databases", "ACID Consistency only exists in distributed databases"]'::jsonb,1,'Replica agreement alone is not a precise definition of CAP consistency.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-consistency-4'; end if;
