if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-consistency-5' and (question_text,options,correct_index,explanation) is distinct from ('Whose responsibility is it to design the RIGHT constraints matching actual business rules?','["The database automatically infers this", "The schema designer \u2014 the database only enforces whatever constraints are actually declared", "This is not possible to do with ACID Consistency", "Only the DBA can declare constraints, never a schema designer"]'::jsonb,1,'Consistency enforcement is a joint responsibility — the database enforces, but a human must design the right rules.') and (question_text,options,correct_index,explanation) is distinct from ('Whose responsibility is it to design the RIGHT constraints matching actual business rules?','["The database automatically infers this", "The schema designer \u2014 the database only enforces whatever constraints are actually declared", "This is not possible to do with ACID Consistency", "Only the DBA can declare constraints, never a schema designer"]'::jsonb,1,'Consistency enforcement is a joint responsibility — the database enforces, but a human must design the right rules.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-consistency-5'; end if;
