if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-consistency-6' and (question_text,options,correct_index,explanation) is distinct from ('Does Consistency apply whether a transaction commits or rolls back?','["Only when it commits", "Yes \u2014 the database remains in a valid state whether the transaction commits successfully or rolls back entirely", "Only when it rolls back", "Consistency only matters for SELECT statements"]'::jsonb,1,'Both outcomes (commit and rollback) must leave the database in a state respecting all constraints.') and (question_text,options,correct_index,explanation) is distinct from ('Does Consistency apply whether a transaction commits or rolls back?','["Only when it commits", "Yes \u2014 the database remains in a valid state whether the transaction commits successfully or rolls back entirely", "Only when it rolls back", "Consistency only matters for SELECT statements"]'::jsonb,1,'Both outcomes (commit and rollback) must leave the database in a state respecting all constraints.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-consistency-6'; end if;
