if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-consistency-7' and (question_text,options,correct_index,explanation) is distinct from ('Which chapter covers CAP theorem Consistency, to contrast with ACID Consistency?','["Chapter 10", "Chapter 38 (Distributed Databases)", "Chapter 5", "Chapter 14"]'::jsonb,1,'The distributed-systems CAP theorem is covered later, in Chapter 38.') and (question_text,options,correct_index,explanation) is distinct from ('Which conceptual distinction matters when comparing ACID with distributed consistency?','["ACID automatically guarantees linearizable observations in every replica", "Database-state invariants differ from distributed observation guarantees.", "Eventual replica agreement proves every business calculation is valid", "A primary key alone proves every remote read sees the latest write"]'::jsonb,1,'The identical word names different contracts.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-consistency-7'; end if;
