update public.learning_topics set short_description='Understand ACID consistency through explicit invariants, CHECK and NULL behavior, multirow transfers, statement-error cleanup and concurrent write paths.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Understand ACID consistency through explicit invariants, CHECK and NULL behavior, multirow transfers, statement-error cleanup and concurrent write paths.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Consistency.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-22-consistency' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-22-consistency-application','MCQ Test 2',category,10,10,'Application and scenarios for Consistency.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-22-consistency' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-consistency-1','pt-dbms-sql-22-consistency','What does ACID Consistency guarantee?','["Fast transaction execution", "The database moves from one valid state (respecting all constraints) to another valid state", "All users see the same query results", "Data is never deleted"]'::jsonb,1,'Consistency is about preserving the validity of declared constraints across a transaction.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-consistency-2','pt-dbms-sql-22-consistency','An InnoDB UPDATE violates an enforced CHECK constraint. What must application error handling recognize?','["The constraint is temporarily relaxed to let the transaction succeed", "The failing statement is rejected; earlier successful statements can remain pending until explicit transaction cleanup.", "Only a warning is logged, but the transaction proceeds", "The balance is automatically set to 0 instead"]'::jsonb,1,'Do not assume every statement error automatically rolls back the entire transaction.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-consistency-3','pt-dbms-sql-22-consistency','Does ACID consistency guarantee every real-world business fact is correct?','["Yes, it guarantees full business correctness", "No; declared constraints and correct trusted transaction logic must encode the required invariants.", "It guarantees correctness only for numeric columns", "Consistency has nothing to do with correctness at all"]'::jsonb,1,'Both database enforcement and application logic contribute; undeclared rules are not invented by the engine.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-consistency-4','pt-dbms-sql-22-consistency','How does ACID consistency differ from CAP consistency?','["Yes, they are identical", "ACID consistency concerns valid-state invariants; CAP consistency is generally linearizability.", "CAP theorem doesn''t apply to databases", "ACID Consistency only exists in distributed databases"]'::jsonb,1,'Replica agreement alone is not a precise definition of CAP consistency.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-consistency-5','pt-dbms-sql-22-consistency','Whose responsibility is it to design the RIGHT constraints matching actual business rules?','["The database automatically infers this", "The schema designer — the database only enforces whatever constraints are actually declared", "This is not possible to do with ACID Consistency", "Only the DBA can declare constraints, never a schema designer"]'::jsonb,1,'Consistency enforcement is a joint responsibility — the database enforces, but a human must design the right rules.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-consistency-6','pt-dbms-sql-22-consistency','Does Consistency apply whether a transaction commits or rolls back?','["Only when it commits", "Yes — the database remains in a valid state whether the transaction commits successfully or rolls back entirely", "Only when it rolls back", "Consistency only matters for SELECT statements"]'::jsonb,1,'Both outcomes (commit and rollback) must leave the database in a state respecting all constraints.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-consistency-7','pt-dbms-sql-22-consistency','Which conceptual distinction matters when comparing ACID with distributed consistency?','["ACID automatically guarantees linearizable observations in every replica", "Database-state invariants differ from distributed observation guarantees.", "Eventual replica agreement proves every business calculation is valid", "A primary key alone proves every remote read sees the latest write"]'::jsonb,1,'The identical word names different contracts.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-consistency-8','pt-dbms-sql-22-consistency','How does Atomicity relate to enabling Consistency?','["They are unrelated", "Atomicity''s all-or-nothing guarantee is part of what makes it possible to never leave the database in a partially-updated, invalid state", "Consistency makes Atomicity redundant", "Atomicity only applies to SELECT statements, unlike Consistency"]'::jsonb,1,'Without atomicity, a partially-completed transaction could leave constraints violated — the two properties work together.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-consistency-c-new-1','pt-dbms-sql-22-consistency','A transfer debits4 and credits5 atomically. What fails?','["The conservation invariant", "Atomicity necessarily", "The primary-key format", "Every foreign key"]'::jsonb,0,'All-or-nothing execution does not repair incorrect arithmetic.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-consistency-c-new-2','pt-dbms-sql-22-consistency','An UPDATE matches no destination row. Must MySQL raise an error?','["Yes, always", "No; the caller must check required effects", "Only if an alias is short", "It automatically creates the row"]'::jsonb,1,'A zero-row update can be successful as a statement but fail the business request.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-consistency-c-new-3','pt-dbms-sql-22-consistency-application','Why combine NOT NULL with a nonnegative CHECK when availability must be known?','["CHECK always turns NULL into zero", "NOT NULL creates a foreign key", "UNKNOWN does not fail a CHECK like FALSE", "NULL values are negative"]'::jsonb,2,'Required presence and permitted numeric range are different conditions.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-consistency-c-new-4','pt-dbms-sql-22-consistency-application','Does every InnoDB statement error undo earlier transaction statements?','["Yes, always", "Only for SELECT", "Only if a table has two rows", "No; error scope depends on the failure"]'::jsonb,3,'Explicit cleanup is necessary when the transaction should fail as a whole.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-consistency-c-new-5','pt-dbms-sql-22-consistency-application','What is a cross-row invariant here?','["The combined seat total stays unchanged", "An identifier is nonnull", "A label is shorter than40 characters", "A row has one bucket_id"]'::jsonb,0,'Conservation spans the source and destination effects.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-consistency-c-new-6','pt-dbms-sql-22-consistency-application','Does a disabled UI button enforce a trusted data rule?','["Yes for every caller", "No", "Only if the button is blue", "Only on mobile"]'::jsonb,1,'Other writers can reach the actual data boundary.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-consistency-c-new-7','pt-dbms-sql-22-consistency-application','Can concurrent individually plausible checks violate a shared rule?','["No, checks serialize by name", "Only without SELECT", "Yes, when both act on stale eligibility observations", "Only for empty tables"]'::jsonb,2,'A race can invalidate the joint outcome unless enforcement accounts for concurrency.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-consistency-c-new-8','pt-dbms-sql-22-consistency-application','What is CAP consistency generally modeled as?','["A nonnegative CHECK only", "Eventual agreement alone", "A primary-key naming rule", "Linearizability"]'::jsonb,3,'The contract concerns externally observed operation ordering.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-consistency-c-new-9','pt-dbms-sql-22-consistency-application','What should a failed operation leave before a pooled connection is reused?','["A resolved transaction or an unusable connection discarded", "An unknown open transaction", "A hidden pending commit", "Disabled constraints"]'::jsonb,0,'Connection reuse must not leak locks or pending work.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-consistency-c-new-10','pt-dbms-sql-22-consistency-application','Why inspect administrative and import write paths?','["They cannot write rows", "They may bypass a rule enforced only in one workflow", "They automatically inherit every UI check", "They prove provider certification"]'::jsonb,1,'Shared data invariants must survive all authorized writers.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-consistency-c-new-11','pt-dbms-sql-22-consistency-application','What must change when a balance model adds currencies?','["Nothing, all sums remain meaningful", "Only text color", "The invariant and enforcement must account for units", "The definition of NULL"]'::jsonb,2,'Adding unlike units makes an old unqualified total invalid.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
