update public.learning_topics set short_description='Write correlated SQL subqueries with explicit outer aliases, compare rows to their own groups, handle NULL and empty matches, and assess rewrites without execution myths.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Write correlated SQL subqueries with explicit outer aliases, compare rows to their own groups, handle NULL and empty matches, and assess rewrites without execution myths.';
