insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-correlated-subquery-1','pt-dbms-sql-17-correlated-subquery','What defines a correlated subquery?','["It uses GROUP BY", "It references a column from the outer query", "It always returns multiple rows", "It must use EXISTS"]'::jsonb,1,'Correlation means the subquery reaches out to a column belonging to the outer query.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-correlated-subquery-2','pt-dbms-sql-17-correlated-subquery','In `WHERE salary > (SELECT AVG(salary) FROM employees WHERE department = e.department)`, conceptually how many times is the inner AVG computed for 8 outer rows (naive execution)?','["Once total", "Once per distinct department only", "Once per outer row (8 times)", "Never — it''s a syntax error"]'::jsonb,2,'A naive execution model re-evaluates the correlated subquery separately for each outer row.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-correlated-subquery-3','pt-dbms-sql-17-correlated-subquery','For a deterministic expression and a fixed statement view of data, an uncorrelated subquery differs because it:','["Always uses IN", "References nothing from the outer query, so it can be evaluated once and reused", "Can never appear in WHERE", "Always returns zero rows"]'::jsonb,1,'It has no outer-column dependency and may be computed independently. Volatile expressions and engine execution rules require separate consideration.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-correlated-subquery-4','pt-dbms-sql-17-correlated-subquery','Why can naive execution of a correlated subquery be slower than an equivalent JOIN on large tables?','["Correlated subqueries always use more disk space", "Work scales as outer-rows × inner-query-cost when re-run per row", "JOINs are not allowed to appear alongside subqueries", "Correlated subqueries can''t use indexes at all"]'::jsonb,1,'Re-running the inner query for every outer row multiplies cost by the outer row count.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-correlated-subquery-5','pt-dbms-sql-17-correlated-subquery','Do modern query optimizers always execute correlated subqueries literally once per outer row?','["Yes, always, with no exceptions", "No — they often rewrite them into joins/semi-joins internally, though not guaranteed for every case", "No, they refuse to run them", "Yes, and this is unfixable"]'::jsonb,1,'Optimizers frequently transform correlated subqueries into more efficient join plans, though this isn''t universal.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-correlated-subquery-6','pt-dbms-sql-17-correlated-subquery','Engineering has Alice 90000 and Bob 60000; Sales has Eve 80000 and Dave 60000; Marketing has Grace 70000 and Heidi 50000. Who earns above their own department average?','["All 8 employees", "Alice, Eve, Grace", "Bob, Dave, Heidi", "Only Alice"]'::jsonb,1,'The department averages are 75000,70000 and60000 respectively. Alice,Eve and Grace exceed their own group averages.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-correlated-subquery-7','pt-dbms-sql-17-correlated-subquery','Where else, besides WHERE, do correlated subqueries commonly appear?','["Only in ORDER BY", "The SELECT list and EXISTS clauses", "Only in table names", "Never anywhere else"]'::jsonb,1,'Correlated subqueries are also very common as computed SELECT columns (17.9) and inside EXISTS (17.5).',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-correlated-subquery-8','pt-dbms-sql-17-correlated-subquery','Which statement most accurately reflects the performance nuance of correlation?','["Correlation always means slow queries", "Correlation alone does not establish slowness; an EXISTS plan may stop after a qualifying match or use another optimized strategy", "Correlated subqueries can never be optimized", "Only uncorrelated subqueries can use indexes"]'::jsonb,1,'An existence decision needs no more than one match, but the chosen access and transformation strategy is plan-dependent.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
