insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-14-count-application-new-4','pt-dbms-sql-14-count-application','What can an attendee join do to COUNT(booking_id)?','["Multiply appearances of the same booking", "Guarantee unique bookings automatically", "Make every result zero", "Remove every child row"]'::jsonb,0,'Recheck grain after another one-to-many relationship.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
