insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-14-count-application-new-6','pt-dbms-sql-14-count-application','What does MySQL COUNT(DISTINCT a,b) omit?','["All repeated a values regardless of b", "Only combinations where both are numeric", "Combinations where either expression is NULL", "Every row with a primary key"]'::jsonb,2,'This is MySQL-specific multi-expression distinct-count behavior.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
