insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-14-count-application-new-8','pt-dbms-sql-14-count-application','Can COUNT(nullable_value)=0 coexist with COUNT(*)>0?','["Yes, rows exist but all expression values are missing", "No, counts must agree", "Only after corrupting the table", "Only when the SQL fails"]'::jsonb,0,'Row existence and known-value existence are distinct.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
