if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-covering-index-1' and (question_text,options,correct_index,explanation) is distinct from ('What defines a covering index for a specific query?','["Any index on the primary key", "An index that contains every column the query filters on AND every column it selects, so the query can be answered entirely from the index", "An index that spans the entire table''s storage", "A hash index used for exact matches only"]'::jsonb,1,'A covering index must include all filter and output columns for that particular query so the engine never needs the actual row.') and (question_text,options,correct_index,explanation) is distinct from ('What makes an index covering?','["Its name says cover", "It contains the values needed by a particular query", "It has the most columns globally", "It is unique"]'::jsonb,1,'Coverage depends on the query''s complete column requirements.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-covering-index-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-covering-index-2' and test_id<>'pt-dbms-sql-20-covering-index') then raise exception 'Question ID collision: %', 'tq-dbms-sql-20-covering-index-2'; end if;
