if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-covering-index-2' and (question_text,options,correct_index,explanation) is distinct from ('What is the performance benefit of a covering index compared to a regular non-clustered index for a matching query?','["It removes the need for a WHERE clause", "It eliminates the extra bookmark lookup back to the actual table row, since all needed data is in the index", "It converts the table into a hash table", "It automatically doubles storage space with no benefit"]'::jsonb,1,'Since all needed columns are present in the index, the engine can skip the second lookup step (fetching the row) entirely.') and (question_text,options,correct_index,explanation) is distinct from ('Can one index cover one query but not another?','["No", "Yes", "Only if renamed", "Only after restart"]'::jsonb,1,'Adding a required field can change coverage without changing the index.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-covering-index-2'; end if;
