if not exists(select 1 from public.test_questions where id='tq-dbms-sql-20-covering-index-3' and test_id='pt-dbms-sql-20-covering-index') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-20-covering-index-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-covering-index-3' and (question_text,options,correct_index,explanation) is distinct from ('What is this scenario, where a query is answered purely from an index without touching the table, commonly called?','["A full table scan", "An index-only scan", "A hash collision", "A clustered rebuild"]'::jsonb,1,'When the engine can satisfy a query entirely from the index without visiting the base table, it''s called an index-only scan.') and (question_text,options,correct_index,explanation) is distinct from ('Which columns matter besides projected columns?','["Only table captions", "Predicate join grouping and ordering requirements", "Only aliases", "Only comments"]'::jsonb,1,'The engine needs values used to evaluate the query as well as display its output.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-covering-index-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-covering-index-4' and test_id<>'pt-dbms-sql-20-covering-index') then raise exception 'Question ID collision: %', 'tq-dbms-sql-20-covering-index-4'; end if;
