if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-covering-index-4' and (question_text,options,correct_index,explanation) is distinct from ('Given index (department, id) and query `SELECT id, department FROM students WHERE department = ''CS''`, why is this index covering for this query?','["Because it includes gpa and email too", "Because both the filter column (department) and the selected column (id) are present in the index", "Because the index is a hash index", "Because it is the table''s clustered index"]'::jsonb,1,'Since department (filter) and id (select) are both in the index, the query never needs to visit the actual row.') and (question_text,options,correct_index,explanation) is distinct from ('Does coverage imply a selective lookup?','["Always", "No", "Only for integers", "Only for primary keys"]'::jsonb,1,'A covering structure can still require scanning many entries.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-covering-index-4'; end if;
