update public.learning_topics set short_description='Define clear MySQL view contracts with explicit columns, understand live query behavior and replacement risks, and distinguish reusable SQL presentation from trusted authorization.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Define clear MySQL view contracts with explicit columns, understand live query behavior and replacement risks, and distinguish reusable SQL presentation from trusted authorization.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for CREATE VIEW.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-19-create-view' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-19-create-view-application','MCQ Test 2',category,10,10,'Application and scenarios for CREATE VIEW.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-19-create-view' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-create-view-1','pt-dbms-sql-19-create-view','What does CREATE VIEW actually store?','["A physical copy of the query''s result rows", "The defining query and its column metadata, rather than a separate stored copy of the result rows", "An index over the base table", "A compressed snapshot refreshed nightly"]'::jsonb,1,'An ordinary view catalogs a query definition. Reads obey the underlying data visibility rules and optimizer execution strategy.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-create-view-2','pt-dbms-sql-19-create-view','In PostgreSQL, what permission-related benefit does CREATE OR REPLACE VIEW have compared with dropping and recreating a view?','["It runs faster on large tables", "It generally preserves existing GRANT permissions attached to the view object", "It allows removing columns freely", "It converts the view into a materialized view"]'::jsonb,1,'PostgreSQL replacement retains the existing view object and its ownership and permissions. A definition change still requires dependency and security review; do not transfer this drop/grant claim blindly to MySQL.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-create-view-3','pt-dbms-sql-19-create-view','In PostgreSQL, which change is typically REJECTED when using CREATE OR REPLACE VIEW?','["Changing the WHERE clause''s filter value", "Adding a new column at the end of the SELECT list", "Removing or reordering existing output columns", "Renaming the view''s internal query comment"]'::jsonb,2,'PostgreSQL replacement requires existing columns to keep their names, order and types, while permitting new columns at the end. Other defining-query changes can be possible if that interface is preserved.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-create-view-4','pt-dbms-sql-19-create-view','What does DROP VIEW high_earners; do to the employees table?','["Deletes all rows matching the view''s WHERE clause", "Deletes the employees table entirely", "Nothing — the base table and its data are untouched", "Locks the employees table for writes"]'::jsonb,2,'Dropping an ordinary view removes its definition rather than deleting base-table rows. Dependencies and concurrent locking behavior are separate engine concerns.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-create-view-5','pt-dbms-sql-19-create-view','What is the purpose of the optional column-alias list in `CREATE VIEW dept_headcount (dept_name, num_employees) AS ...`?','["It restricts which rows are visible", "It renames the view''s output columns independently of the underlying SELECT''s own expressions/aliases", "It creates an index on those columns", "It is required syntax with no functional effect"]'::jsonb,1,'The column-alias list lets you give clean, explicit names to the view''s output columns, which is especially useful when the underlying SELECT includes expressions like COUNT(e.id) that don''t have natural names.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-create-view-6','pt-dbms-sql-19-create-view','In PostgreSQL, what happens when DROP VIEW dept_summary uses default RESTRICT behavior while another view depends on dept_summary?','["Both views are dropped automatically", "The drop fails unless CASCADE is specified", "Only dept_summary''s data is dropped, not its dependents", "The dependent view is automatically rewritten to bypass dept_summary"]'::jsonb,1,'PostgreSQL rejects the drop under RESTRICT when dependent objects require the view. CASCADE has destructive dependency consequences and needs separate explicit authorization.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-create-view-7','pt-dbms-sql-19-create-view','Can a view''s defining query reference another view?','["No, only base tables can be referenced", "Yes, as long as the referenced view already exists at creation time", "Yes, but only materialized views can be referenced", "Only in Oracle"]'::jsonb,1,'A view''s SELECT can reference other views (nested views), but the referenced view must already exist, since view creation validates the query against the current catalog.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-create-view-8','pt-dbms-sql-19-create-view','Which statement correctly contrasts an ordinary view with a materialized view in terms of CREATE VIEW semantics?','["Both store the result physically and require REFRESH", "An ordinary view defines a query over visible source data; a materialized view stores result data maintained under its engine-specific refresh policy", "An ordinary view is faster in every case", "A materialized view cannot be created with CREATE VIEW syntax variants at all"]'::jsonb,1,'Materialized results can become stale until their configured refresh or maintenance occurs. Refresh can be explicit or automated depending on engine and design; stored results are not universally faster for every workload.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-19-create-view-new-9','pt-dbms-sql-19-create-view','Why should a maintained MySQL view avoid relying on SELECT star to expose future added base columns?','["The star always creates a syntax error", "The selected column list is fixed at view creation rather than automatically adopting later additions", "Views can expose only one column", "The star automatically grants base-table access"]'::jsonb,1,'Use explicit projected columns and review any interface additions deliberately.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-19-create-view-new-10','pt-dbms-sql-19-create-view','Can a caller directly reference a base-table column omitted from a view projection?','["Yes, every base column is implicitly exposed", "Only through ORDER BY", "No, it is outside that view output contract", "Only if the name is short"]'::jsonb,2,'The projected columns define the row-source interface.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-19-create-view-application-new-1','pt-dbms-sql-19-create-view-application','Does an active-workshops view create a historical snapshot of yesterday?','["Yes, automatically", "Only when workshop_id is selected", "Only when ordered", "No"]'::jsonb,3,'A live named query does not preserve past mutable state.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-19-create-view-application-new-2','pt-dbms-sql-19-create-view-application','Where should a caller specify a guaranteed final display order?','["In its outer ORDER BY", "Only in the view alias", "In a column comment", "By relying on current storage order"]'::jsonb,0,'A view row source does not establish a portable caller display sequence.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-19-create-view-application-new-3','pt-dbms-sql-19-create-view-application','What happens to a zero-registration workshop in a grouped registration-count view?','["It automatically has count zero", "It has no group unless the population is constructed to preserve it", "It becomes a NULL workshop ID", "It receives the global count"]'::jsonb,1,'Grouping existing registration facts does not invent missing workshops.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
