update public.learning_topics set short_description='Understand every grouping level in a two-dimensional SQL cube, distinguish subtotal labels from missing data, and build an explicit MySQL UNION ALL equivalent.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Understand every grouping level in a two-dimensional SQL cube, distinguish subtotal labels from missing data, and build an explicit MySQL UNION ALL equivalent.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for CUBE Concept.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-15-cube-concept' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-15-cube-concept-application','MCQ Test 2',category,10,10,'Application and scenarios for CUBE Concept.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-15-cube-concept' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-cube-concept-1','pt-dbms-sql-15-cube-concept','What does `CUBE(region, product)` compute that plain `ROLLUP(region, product)` does not?','["Nothing extra — they are identical", "Product-only subtotal rows (ignoring region), in addition to everything ROLLUP produces", "Only the grand total row", "Region-only subtotal rows"]'::jsonb,1,'CUBE computes every possible combination of the grouping columns, including product-only subtotals that ROLLUP''s strict right-to-left hierarchy never produces.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-cube-concept-2','pt-dbms-sql-15-cube-concept','How many grouping sets does `CUBE(region, product)` expand to?','["2: (region), (product)", "3: (region, product), (region), ()", "4: (region, product), (region), (product), ()", "6, one per (region, product) combination"]'::jsonb,2,'CUBE produces every subset of its column list: full detail, each single column alone, and the empty set — 4 total for 2 columns (2^2).',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-cube-concept-3','pt-dbms-sql-15-cube-concept','A nonempty source has six observed region-product pairs, three regions and two products. How many rows does a complete two-dimensional cube produce?','["6", "10", "12", "16"]'::jsonb,2,'6 detail rows + 3 region subtotals + 2 product subtotals + 1 grand total = 12.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-cube-concept-4','pt-dbms-sql-15-cube-concept','Widget facts have amounts 100, 200, 50, 120 and 60 across regions. What is the Widget product-only subtotal?','["160", "250", "530", "1060"]'::jsonb,2,'Summing all Widget orders across every region (100+200+50+120+60) gives 530.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-cube-concept-5','pt-dbms-sql-15-cube-concept','How many grouping sets does `CUBE(a, b, c)` (three columns) produce?','["3", "4", "6", "8"]'::jsonb,3,'CUBE produces 2^n grouping sets for n columns; with 3 columns that''s 2^3 = 8, covering every possible subset.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-cube-concept-6','pt-dbms-sql-15-cube-concept','Which of the following databases support the standard `GROUP BY CUBE(...)` syntax?','["MySQL only", "PostgreSQL, SQL Server, and Oracle", "SQLite only", "No mainstream database supports it"]'::jsonb,1,'PostgreSQL, SQL Server, and Oracle support CUBE natively; MySQL does not support CUBE at all, only the simpler WITH ROLLUP.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-cube-concept-7','pt-dbms-sql-15-cube-concept','What is a language-level advantage of native CUBE compared with spelling out every grouping subset using UNION ALL?','["CUBE produces fewer rows overall", "It expresses all grouping subsets declaratively in one grouping construct", "CUBE is the only way to compute a grand total", "There is no advantage; they are equivalent in every way"]'::jsonb,1,'CUBE describes the complete collection of grouping sets concisely. Physical scans, sharing and materialization depend on the engine and actual plan; neither syntax proves a fixed number of scans.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-cube-concept-8','pt-dbms-sql-15-cube-concept','In `GROUP BY CUBE(region, product)`, how would you programmatically distinguish the grand total row from a region-only subtotal row?','["Grand total always sorts first alphabetically", "Check GROUPING(region) and GROUPING(product): the grand total has both equal to 1, while a region-only subtotal has GROUPING(region)=0 and GROUPING(product)=1", "It is impossible to distinguish them", "Check if total_amount is negative"]'::jsonb,1,'GROUPING(column) identifies an omitted grouping dimension. A grand total omits both dimensions; a region-only subtotal retains region and omits product. Source NULL values need not be summary placeholders.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
