if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-11-data-modification-transactions' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'data-modification-transactions'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-11-data-modification-transactions' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'data-modification-transactions'; end if;
