if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-modification-transactions-1' and (question_text,options,correct_index,explanation) is distinct from ('What guarantee does wrapping multiple DML statements in a transaction provide?','["The statements will run faster", "The statements succeed or fail together as a single atomic unit", "The statements are automatically validated for correctness", "The statements will run in a random order"]'::jsonb,1,'Atomicity — all-or-nothing — is exactly what a transaction guarantees for its contained statements.') and (question_text,options,correct_index,explanation) is distinct from ('What does a correctly handled transaction provide for related InnoDB DML?','["Automatic correctness of every predicate", "One commit-or-rollback boundary for the transactional changes", "Automatic authorization", "A guarantee that no statement can fail"]'::jsonb,1,'Atomicity concerns acceptance of transactional work, not all business correctness.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-data-modification-transactions-1'; end if;
