if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-modification-transactions-2' and (question_text,options,correct_index,explanation) is distinct from ('In the classic bank-transfer example, why must the debit and credit UPDATEs be in one transaction?','["To make the two UPDATEs run in parallel", "So that if only one UPDATE succeeds, the whole operation can be rolled back instead of leaving money debited from one account with nothing credited to the other", "Transactions are required syntax for any UPDATE", "To avoid needing a WHERE clause on either UPDATE"]'::jsonb,1,'This is the canonical illustration of why atomicity matters for related data changes.') and (question_text,options,correct_index,explanation) is distinct from ('Why group subtraction and addition for a stock movement?','["To remove all WHERE clauses", "A partial accepted result would violate the movement invariant", "To avoid naming the stores", "To guarantee parallel execution"]'::jsonb,1,'Both changes represent one accepted business transition.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-data-modification-transactions-2'; end if;
