if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-modification-transactions-3' and (question_text,options,correct_index,explanation) is distinct from ('What is ''auto-commit mode''?','["A mode where transactions never commit", "The common default where each individual statement is implicitly committed on its own, unless an explicit transaction is started", "A mode exclusive to read-only queries", "A deprecated legacy feature no longer used"]'::jsonb,1,'Auto-commit means each statement stands alone as its own transaction by default.') and (question_text,options,correct_index,explanation) is distinct from ('What does enabled autocommit normally do outside an explicit transaction?','["Defers every write forever", "Completes each successful transactional statement independently", "Rolls back every SELECT", "Combines unrelated connections"]'::jsonb,1,'A later rollback cannot undo an earlier independently committed statement.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-data-modification-transactions-3'; end if;
