if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-modification-transactions-4' and (question_text,options,correct_index,explanation) is distinct from ('Why should transactions generally be kept as short as possible?','["Short transactions are required by the SQL standard", "A long-held open transaction can hold locks and block other users'' work for as long as it stays open", "Long transactions always fail automatically after a timeout", "Transaction length has no practical effect on other users"]'::jsonb,1,'Held locks from an open transaction can block concurrent work regardless of whether the transaction is actively doing anything.') and (question_text,options,correct_index,explanation) is distinct from ('Why avoid an idle open transaction?','["Every transaction must end within one second", "It can hold locks and retain resources needed by others", "SQL forbids any pause", "It always deletes older rows"]'::jsonb,1,'Keep protected work focused and promptly completed.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-data-modification-transactions-4'; end if;
