if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-modification-transactions-5' and (question_text,options,correct_index,explanation) is distinct from ('Should an archive-then-delete DML sequence (INSERT INTO archive SELECT ...; DELETE FROM original ...) be wrapped in a transaction?','["No, each statement is independently safe", "Yes \u2014 a failure between the two steps could otherwise leave data duplicated or lost, exactly the kind of multi-statement dependency transactions protect against", "Only if the tables are very large", "Transactions cannot wrap an INSERT and a DELETE together"]'::jsonb,1,'This is a direct real-world example of statements that depend on each other for overall correctness.') and (question_text,options,correct_index,explanation) is distinct from ('Why does archive-then-delete need more than two individually valid statements?','["INSERT and DELETE can never share a transaction", "Their dependency and matching membership must be accepted together", "The SQL parser requires an archive keyword", "Deleting always rolls back the archive"]'::jsonb,1,'Both boundary and consistent membership matter.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-data-modification-transactions-5'; end if;
