if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-modification-transactions-6' and (question_text,options,correct_index,explanation) is distinct from ('What practice helps avoid a transaction holding locks longer than necessary?','["Opening the transaction as early as possible in the application, regardless of unrelated work in between", "Opening the transaction right before the related statements and committing immediately after, avoiding slow unrelated work in the middle", "Never using COMMIT at all", "Running all application logic inside a single transaction for the entire session"]'::jsonb,1,'Minimizing the time a transaction stays open reduces its potential to block other work.') and (question_text,options,correct_index,explanation) is distinct from ('When should unrelated remote preparation occur?','["While every relevant row stays locked", "Before opening the short protected database interval where possible", "Only after a timeout", "Inside an unlimited transaction"]'::jsonb,1,'Avoid holding database resources for unrelated waits.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-data-modification-transactions-6'; end if;
