update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Data Modification Transactions.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-11-data-modification-transactions' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-11-data-modification-transactions-application','MCQ Test 2',category,10,10,'Application and scenarios for Data Modification Transactions.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-11-data-modification-transactions' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-data-modification-transactions-1','pt-dbms-sql-11-data-modification-transactions','What does a correctly handled transaction provide for related InnoDB DML?','["Automatic correctness of every predicate", "One commit-or-rollback boundary for the transactional changes", "Automatic authorization", "A guarantee that no statement can fail"]'::jsonb,1,'Atomicity concerns acceptance of transactional work, not all business correctness.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-data-modification-transactions-2','pt-dbms-sql-11-data-modification-transactions','Why group subtraction and addition for a stock movement?','["To remove all WHERE clauses", "A partial accepted result would violate the movement invariant", "To avoid naming the stores", "To guarantee parallel execution"]'::jsonb,1,'Both changes represent one accepted business transition.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-data-modification-transactions-3','pt-dbms-sql-11-data-modification-transactions','What does enabled autocommit normally do outside an explicit transaction?','["Defers every write forever", "Completes each successful transactional statement independently", "Rolls back every SELECT", "Combines unrelated connections"]'::jsonb,1,'A later rollback cannot undo an earlier independently committed statement.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-data-modification-transactions-4','pt-dbms-sql-11-data-modification-transactions','Why avoid an idle open transaction?','["Every transaction must end within one second", "It can hold locks and retain resources needed by others", "SQL forbids any pause", "It always deletes older rows"]'::jsonb,1,'Keep protected work focused and promptly completed.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-data-modification-transactions-5','pt-dbms-sql-11-data-modification-transactions','Why does archive-then-delete need more than two individually valid statements?','["INSERT and DELETE can never share a transaction", "Their dependency and matching membership must be accepted together", "The SQL parser requires an archive keyword", "Deleting always rolls back the archive"]'::jsonb,1,'Both boundary and consistent membership matter.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-data-modification-transactions-6','pt-dbms-sql-11-data-modification-transactions','When should unrelated remote preparation occur?','["While every relevant row stays locked", "Before opening the short protected database interval where possible", "Only after a timeout", "Inside an unlimited transaction"]'::jsonb,1,'Avoid holding database resources for unrelated waits.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-data-modification-transactions-7','pt-dbms-sql-11-data-modification-transactions','Which commands express explicit transaction control in this package?','["CREATE, DROP and ALTER", "START TRANSACTION, COMMIT and ROLLBACK", "GRANT, REVOKE and DENY", "SELECT, DISTINCT and ORDER BY"]'::jsonb,1,'The examples keep schema setup outside their DML boundary.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-data-modification-transactions-8','pt-dbms-sql-11-data-modification-transactions','Does each statement being sensible alone establish a complete multi-step operation?','["Yes, atomicity follows from indentation", "No, partial failure and dependencies still need handling", "Yes, if comments mention a transaction", "Only if every identifier is numeric"]'::jsonb,1,'Business correctness spans the related sequence.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-11-data-modification-transactions-new-9','pt-dbms-sql-11-data-modification-transactions','Can an UPDATE matching no destination rows finish without a SQL exception?','["Yes, zero matches need explicit outcome handling", "No, it always raises a foreign-key error", "Only if the source was empty", "Only outside a transaction"]'::jsonb,0,'Do not infer required work occurred from statement success alone.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-11-data-modification-transactions-new-10','pt-dbms-sql-11-data-modification-transactions','Does every InnoDB error roll back the entire transaction?','["Yes, with no exceptions", "No, some errors roll back only the statement", "Only errors inside SELECT do", "Errors never affect transactional work"]'::jsonb,1,'The client must handle the documented error scope.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
