insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-11-data-modification-transactions-application-new-10','pt-dbms-sql-11-data-modification-transactions-application','What is an appropriate deadlock retry boundary?','["Only the last update regardless of earlier rollback", "Every external notification unconditionally", "The complete operation under a bounded policy with state rechecks", "All unrelated work in the request"]'::jsonb,2,'The engine rolled back the whole transaction, so retry semantics must match.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
if exists(select 1 from public.dsa_problems where learning_topic_id=topic_uuid and id not in ('cx-transaction-discard-stock-change','cx-transaction-commit-stock-movement')) then raise exception 'Existing coding problems require explicit integration: %', 'data-modification-transactions'; end if;
if exists(select 1 from public.dsa_problems where (id='cx-transaction-discard-stock-change' or slug='transaction-discard-stock-change') and (id<>'cx-transaction-discard-stock-change' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cx-transaction-discard-stock-change'; end if;
if exists(select 1 from public.dsa_problems where id='cx-transaction-discard-stock-change' and description is distinct from 'Within one explicit transaction, subtract 2 from store 1 and then roll back. Fixtures guarantee store 1 has at least 2. Return store_id,quantity after rollback, ordered by store_id. Preserve every initial row.

**MySQL dialect.**

```sql
CREATE TABLE store_stock(store_id INT PRIMARY KEY,quantity INT NOT NULL CHECK(quantity>=0)) ENGINE=InnoDB;
INSERT INTO store_stock VALUES (1,8),(2,5);
```

**Required ordering:** As explicitly ordered in the result query.

**Edge cases:**
- A source exactly at the permitted lower fixture boundary still returns its original quantity.
- Unrelated stores must remain intact.') then raise exception 'New coding ID already has other content: %', 'cx-transaction-discard-stock-change'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-transaction-discard-stock-change',null::text,'Observe a rolled-back stock adjustment','Easy','transaction-discard-stock-change','Within one explicit transaction, subtract 2 from store 1 and then roll back. Fixtures guarantee store 1 has at least 2. Return store_id,quantity after rollback, ordered by store_id. Preserve every initial row.

**MySQL dialect.**

```sql
CREATE TABLE store_stock(store_id INT PRIMARY KEY,quantity INT NOT NULL CHECK(quantity>=0)) ENGINE=InnoDB;
INSERT INTO store_stock VALUES (1,8),(2,5);
```

**Required ordering:** As explicitly ordered in the result query.

**Edge cases:**
- A source exactly at the permitted lower fixture boundary still returns its original quantity.
- Unrelated stores must remain intact.','[{"input": "INSERT INTO store_stock VALUES (1,8),(2,5);", "output": "store_id\tquantity\n1\t8\n2\t5", "explanation": "The update belongs to the explicit InnoDB transaction. ROLLBACK cancels it before the final query, so the original state reappears."}]'::jsonb,'[{"seed_sql": "INSERT INTO store_stock VALUES (1,2),(7,9);", "expected": "store_id\tquantity\n1\t2\n7\t9", "hidden": true}, {"seed_sql": "INSERT INTO store_stock VALUES (1,12);", "expected": "store_id\tquantity\n1\t12", "hidden": true}]'::jsonb,'["Use only the supplied synthetic tables and requested transition.", "Preserve unrelated rows."]'::jsonb,'["Begin the transaction before the update.", "Query only after rolling back."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The update belongs to the explicit InnoDB transaction. ROLLBACK cancels it before the final query, so the original state reappears.','{"sql": "START TRANSACTION; UPDATE store_stock SET quantity=quantity-2 WHERE store_id=1; ROLLBACK; SELECT store_id,quantity FROM store_stock ORDER BY store_id;"}'::jsonb,'The update belongs to the explicit InnoDB transaction. ROLLBACK cancels it before the final query, so the original state reappears.',array['sql'],'CREATE TABLE store_stock(store_id INT PRIMARY KEY,quantity INT NOT NULL CHECK(quantity>=0)) ENGINE=InnoDB;','INSERT INTO store_stock VALUES (1,8),(2,5);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-11-data-modification-transactions' on conflict(id) do nothing;
if exists(select 1 from public.dsa_problems where (id='cx-transaction-commit-stock-movement' or slug='transaction-commit-stock-movement') and (id<>'cx-transaction-commit-stock-movement' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cx-transaction-commit-stock-movement'; end if;
if exists(select 1 from public.dsa_problems where id='cx-transaction-commit-stock-movement' and description is distinct from 'Move exactly 3 units from store 1 to store 2 in one explicit transaction, then return store_id,quantity ordered by store_id. Each fixture guarantees both distinct stores exist and store 1 has at least 3; there are no concurrent writers or triggers. Do not change other stores. Real applications must validate and lock changing state and handle statement outcomes before COMMIT.

**MySQL dialect.**

```sql
CREATE TABLE store_stock(store_id INT PRIMARY KEY,quantity INT NOT NULL CHECK(quantity>=0)) ENGINE=InnoDB;
INSERT INTO store_stock VALUES (1,9),(2,4),(8,7);
```

**Required ordering:** As explicitly ordered in the result query.

**Edge cases:**
- The source may become exactly zero.
- An unrelated store with a small balance must not change.') then raise exception 'New coding ID already has other content: %', 'cx-transaction-commit-stock-movement'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-transaction-commit-stock-movement',null::text,'Commit a fixed two-store movement','Medium','transaction-commit-stock-movement','Move exactly 3 units from store 1 to store 2 in one explicit transaction, then return store_id,quantity ordered by store_id. Each fixture guarantees both distinct stores exist and store 1 has at least 3; there are no concurrent writers or triggers. Do not change other stores. Real applications must validate and lock changing state and handle statement outcomes before COMMIT.

**MySQL dialect.**

```sql
CREATE TABLE store_stock(store_id INT PRIMARY KEY,quantity INT NOT NULL CHECK(quantity>=0)) ENGINE=InnoDB;
INSERT INTO store_stock VALUES (1,9),(2,4),(8,7);
```

**Required ordering:** As explicitly ordered in the result query.

**Edge cases:**
- The source may become exactly zero.
- An unrelated store with a small balance must not change.','[{"input": "INSERT INTO store_stock VALUES (1,9),(2,4),(8,7);", "output": "store_id\tquantity\n1\t6\n2\t7\n8\t7", "explanation": "Under the stated valid-fixture preconditions, both updates are committed together and total stock is preserved. The exercise does not claim the script alone validates absent destinations or concurrent availability."}]'::jsonb,'[{"seed_sql": "INSERT INTO store_stock VALUES (1,3),(2,0);", "expected": "store_id\tquantity\n1\t0\n2\t3", "hidden": true}, {"seed_sql": "INSERT INTO store_stock VALUES (1,12),(2,10),(3,1);", "expected": "store_id\tquantity\n1\t9\n2\t13\n3\t1", "hidden": true}]'::jsonb,'["Use only the supplied synthetic tables and requested transition.", "Preserve unrelated rows."]'::jsonb,'["Place both updates between START TRANSACTION and COMMIT.", "Subtract and add the same amount using stored quantities."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'Under the stated valid-fixture preconditions, both updates are committed together and total stock is preserved. The exercise does not claim the script alone validates absent destinations or concurrent availability.','{"sql": "START TRANSACTION; UPDATE store_stock SET quantity=quantity-3 WHERE store_id=1; UPDATE store_stock SET quantity=quantity+3 WHERE store_id=2; COMMIT; SELECT store_id,quantity FROM store_stock ORDER BY store_id;"}'::jsonb,'Under the stated valid-fixture preconditions, both updates are committed together and total stock is preserved. The exercise does not claim the script alone validates absent destinations or concurrent availability.',array['sql'],'CREATE TABLE store_stock(store_id INT PRIMARY KEY,quantity INT NOT NULL CHECK(quantity>=0)) ENGINE=InnoDB;','INSERT INTO store_stock VALUES (1,9),(2,4),(8,7);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-11-data-modification-transactions' on conflict(id) do nothing;
