insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-data-redundancy-application-1','cx-data-redundancy-application','What should a new instructor’s office not require?','["A valid instructor identity", "A fabricated enrollment", "A defined office policy", "Appropriate authorized storage"]'::jsonb,1,'An independent instructor fact should not require an invented student-course relationship.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
