insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-data-redundancy-application-3','cx-data-redundancy-application','What does COUNT(DISTINCT instructor_office) omit?','["Every known office", "All repeated instructor identifiers", "All numeric office labels", "NULL office values"]'::jsonb,3,'Missing and conflicting values need distinct checks.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-data-redundancy-application-4','cx-data-redundancy-application','Why is arbitrary MIN not a source-of-truth resolution?','["It chooses by ordering rather than business authority", "It is invalid SQL everywhere", "It always produces NULL", "It proves every copy correct"]'::jsonb,0,'Conflicting values require a reviewed authoritative decision.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-data-redundancy-application-5','cx-data-redundancy-application','Does repeated text in a joined report necessarily mean duplicate authoritative storage?','["Yes, every display must be unique", "No", "Only if the name is short", "Only when ordered"]'::jsonb,1,'A result can display one stored fact beside several associations.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-data-redundancy-application-6','cx-data-redundancy-application','What should an intentional cache specify?','["Only its table color", "That every copy is independently authoritative", "Owner, freshness, invalidation and failure policy", "No refresh behavior"]'::jsonb,2,'Deliberate duplication requires a defined consistency contract.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-data-redundancy-application-7','cx-data-redundancy-application','Can an event’s agreed price differ legitimately from the current catalog price?','["No, all prices must always match", "Only before a SELECT", "Only without foreign keys", "Yes"]'::jsonb,3,'Historical agreements and current catalog facts have different meanings.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-data-redundancy-application-8','cx-data-redundancy-application','What inputs does AgeAtEnrollment normally need?','["DateOfBirth and the relevant EnrollmentDate", "Only the current date", "Only InstructorOffice", "Only CourseName"]'::jsonb,0,'An event-specific derived age depends on the event date, not merely birth date.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-data-redundancy-application-9','cx-data-redundancy-application','Why reconstruct by identifiers rather than display names?','["Names can never repeat", "Different entities can share names", "Identifiers are always shorter", "SQL forbids name equality"]'::jsonb,1,'A name-based join can mix distinct entities’ relationships.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-data-redundancy-application-10','cx-data-redundancy-application','What does normalization preserve while relocating shared descriptions?','["Only one row per visible string", "Only the newest enrollment", "Every legitimate association and its meaning", "Only the smallest table"]'::jsonb,2,'Removing repeated descriptions must not discard distinct relationship facts.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
