select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-11-dml-and-data-modification/data-validation' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'data-validation'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'data-validation'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('eb27f839820abfe29f4ebf265400b883','194a872fe0c26dda049374ca29430f8c')) then raise exception 'Notes changed since seed; review before applying: %', 'data-validation'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-11-data-validation' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'data-validation'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-11-data-validation' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'data-validation'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-11-data-validation','pt-dbms-sql-11-data-validation-application')) then raise exception 'Extra topic tests require manual integration: %', 'data-validation'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-11-data-validation-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'data-validation'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Required positive quantity and reference checks are separate", "description": "The diagnostic exercise gives quantity failure priority before missing equipment.", "columns": ["Code", "Quantity", "Reference known", "Outcome"], "rows": [["CAM", "2", "Yes", "accepted"], ["BAD", "0", "No", "invalid_quantity"], ["BAD", "2", "No", "unknown_equipment"], ["CAM", "NULL", "Yes", "invalid_quantity"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'data-validation'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Required positive quantity and reference checks are separate", "description": "The diagnostic exercise gives quantity failure priority before missing equipment.", "columns": ["Code", "Quantity", "Reference known", "Outcome"], "rows": [["CAM", "2", "Yes", "accepted"], ["BAD", "0", "No", "invalid_quantity"], ["BAD", "2", "No", "unknown_equipment"], ["CAM", "NULL", "Yes", "invalid_quantity"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Required positive quantity and reference checks are separate", "description": "The diagnostic exercise gives quantity failure priority before missing equipment.", "columns": ["Code", "Quantity", "Reference known", "Outcome"], "rows": [["CAM", "2", "Yes", "accepted"], ["BAD", "0", "No", "invalid_quantity"], ["BAD", "2", "No", "unknown_equipment"], ["CAM", "NULL", "Yes", "invalid_quantity"]]}]'::jsonb;
