if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-validation-1' and (question_text,options,correct_index,explanation) is distinct from ('What is the strongest layer of data validation, enforced regardless of which application writes the data?','["Application-level form validation", "Database-level constraints (NOT NULL, CHECK, FOREIGN KEY, UNIQUE)", "Post-modification verification queries", "Code comments describing the expected data shape"]'::jsonb,1,'Database constraints are enforced by the engine itself, regardless of which script or app writes to the table.') and (question_text,options,correct_index,explanation) is distinct from ('Which mechanism can enforce a stored invariant across different ordinary writers?','["A placeholder in one form", "An appropriate enforced database constraint", "A comment in application code", "A spreadsheet instruction"]'::jsonb,1,'Writers bypassing the original interface still meet table enforcement.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-data-validation-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-validation-2' and test_id<>'pt-dbms-sql-11-data-validation') then raise exception 'Question ID collision: %', 'tq-dbms-sql-11-data-validation-2'; end if;
