if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-validation-2' and (question_text,options,correct_index,explanation) is distinct from ('Why is relying only on application-level validation, with no database constraints, risky?','["It''s not risky at all", "Any future script, migration, or admin tool that writes directly to the database bypasses application logic entirely, leaving no protection", "Application validation is always slower than database constraints", "Database constraints are deprecated in modern SQL"]'::jsonb,1,'Only database-level enforcement protects against writes that don''t go through the application layer.') and (question_text,options,correct_index,explanation) is distinct from ('Why is client-only validation insufficient?','["Browsers cannot display numbers", "Other clients can bypass that interface", "SQL constraints are always slower", "Every client is trusted equally"]'::jsonb,1,'Essential acceptance rules need a trusted boundary.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-data-validation-2'; end if;
