if not exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-validation-3' and test_id='pt-dbms-sql-11-data-validation') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-11-data-validation-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-validation-3' and (question_text,options,correct_index,explanation) is distinct from ('Why might relying only on database constraints, without any application-level validation, hurt user experience?','["It never affects user experience", "A raw constraint-violation error is often less helpful to an end user than a clear, specific validation message shown before submission", "Database constraints are always instant, unlike application checks", "Constraints cannot produce any error message at all"]'::jsonb,1,'Application-level validation can give friendlier, more specific feedback before ever reaching the database.') and (question_text,options,correct_index,explanation) is distinct from ('What benefit does early form validation provide?','["Authority over all direct database writers", "Clear, timely feedback before submission", "Guaranteed stock reservation", "A replacement for access checks"]'::jsonb,1,'Good interaction complements trusted enforcement.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-data-validation-3'; end if;
