if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-validation-4' and (question_text,options,correct_index,explanation) is distinct from ('What is a post-modification verification query useful for?','["Replacing the need for any database constraints", "Confirming, after a bulk change, that the expected number of rows were affected and no unexpected bad values appeared", "Making an UPDATE statement run faster", "Automatically fixing bad data"]'::jsonb,1,'A sanity-check query after a large change catches problems that might have slipped past other validation layers.') and (question_text,options,correct_index,explanation) is distinct from ('What can a post-write verification query establish?','["That every future concurrent write is valid", "Whether observed results match the expected contract", "That no invalid state ever existed", "That constraints are unnecessary"]'::jsonb,1,'Verification observes outcomes rather than replacing enforcement.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-data-validation-4'; end if;
