if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-validation-5' and (question_text,options,correct_index,explanation) is distinct from ('Why does bulk-loaded or migrated data especially benefit from explicit post-load verification queries?','["Bulk-loaded data is always perfectly clean by definition", "Bulk-load paths can validate less strictly by default (for performance), making it more likely that bad data slips through unnoticed", "Verification queries are required by SQL syntax for bulk loads", "Migrated data cannot be queried at all"]'::jsonb,1,'Since bulk-load mechanisms may trade off some validation for speed, explicit follow-up checks matter more.') and (question_text,options,correct_index,explanation) is distinct from ('Why review import warning and conversion policies?','["Bulk input always skips all constraints", "Accepted stored values may differ from malformed original input", "Every loader has identical strictness", "Warnings always mean no data changed"]'::jsonb,1,'Interpretation rules depend on the actual path and settings.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-data-validation-5'; end if;
