if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-validation-6' and (question_text,options,correct_index,explanation) is distinct from ('Which validation layer would catch a business rule spanning multiple unrelated tables that a single CHECK constraint can''t express?','["Only a PRIMARY KEY constraint", "Application-level validation logic, since some cross-table business rules exceed what a single-row CHECK can express", "Only a UNIQUE constraint", "This kind of rule can never be validated anywhere"]'::jsonb,1,'Complex, multi-table business logic often needs application-level (or trigger-based) enforcement beyond a simple CHECK.') and (question_text,options,correct_index,explanation) is distinct from ('Where should a changing cross-table stock rule be enforced?','["Only in a form read", "In a trusted operation with suitable transaction and concurrency controls", "In a single arbitrary CHECK subquery", "In an unprotected cached count"]'::jsonb,1,'The decision must remain valid under concurrent writers.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-data-validation-6'; end if;
