if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-validation-7' and (question_text,options,correct_index,explanation) is distinct from ('What is the recommended overall approach to data validation, according to this topic?','["Pick exactly one layer and rely on it exclusively", "A layered combination: strong database constraints, application-level checks for good UX, and post-modification verification for what slips through", "Validation is unnecessary if the schema was designed correctly once", "Only validate data once, at initial table creation"]'::jsonb,1,'The layered approach captures the strengths of each validation mechanism.') and (question_text,options,correct_index,explanation) is distinct from ('Which overall design is appropriate?','["Only interface checks", "Helpful interface checks, trusted validation, constraints and result verification", "Only after-the-fact cleanup", "No checks after initial table creation"]'::jsonb,1,'Each boundary addresses different failure modes.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-data-validation-7'; end if;
