if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-data-validation-8' and (question_text,options,correct_index,explanation) is distinct from ('Does having database constraints eliminate the value of application-level validation entirely?','["Yes, constraints alone are always sufficient", "No \u2014 application-level validation still improves user experience and can express rules constraints can''t, even though constraints are the stronger safety net", "Application-level validation is illegal once constraints exist", "Constraints replace the need for any testing"]'::jsonb,1,'The two layers serve complementary purposes rather than being redundant with each other.') and (question_text,options,correct_index,explanation) is distinct from ('Do constraints eliminate the need for input validation?','["Yes, all business logic is a key", "No, parsing, feedback and other business rules still matter", "Yes, including authorization", "Only for numeric forms"]'::jsonb,1,'Constraints protect the rules they actually express.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-data-validation-8'; end if;
