insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-data-validation-1','pt-dbms-sql-11-data-validation','Which mechanism can enforce a stored invariant across different ordinary writers?','["A placeholder in one form", "An appropriate enforced database constraint", "A comment in application code", "A spreadsheet instruction"]'::jsonb,1,'Writers bypassing the original interface still meet table enforcement.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-data-validation-2','pt-dbms-sql-11-data-validation','Why is client-only validation insufficient?','["Browsers cannot display numbers", "Other clients can bypass that interface", "SQL constraints are always slower", "Every client is trusted equally"]'::jsonb,1,'Essential acceptance rules need a trusted boundary.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-data-validation-3','pt-dbms-sql-11-data-validation','What benefit does early form validation provide?','["Authority over all direct database writers", "Clear, timely feedback before submission", "Guaranteed stock reservation", "A replacement for access checks"]'::jsonb,1,'Good interaction complements trusted enforcement.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-data-validation-4','pt-dbms-sql-11-data-validation','What can a post-write verification query establish?','["That every future concurrent write is valid", "Whether observed results match the expected contract", "That no invalid state ever existed", "That constraints are unnecessary"]'::jsonb,1,'Verification observes outcomes rather than replacing enforcement.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
