insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-database-reasoning-interview-lab-fundamentals-1','cx-database-reasoning-interview-lab-fundamentals','What should be clarified before counting applications per event?','["The result grain and whether empty events remain", "Only the preferred indentation", "Only the interviewer’s editor", "Only the number of SQL keywords"]'::jsonb,0,'The requirement determines join direction and grouping.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-database-reasoning-interview-lab-fundamentals-2','cx-database-reasoning-interview-lab-fundamentals','Which count yields zero for a missing left-joined application?','["COUNT(*)", "COUNT(a.application_id)", "COUNT(e.event_id)", "COUNT(1)"]'::jsonb,1,'COUNT of the nullable matched key excludes the placeholder.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-database-reasoning-interview-lab-fundamentals-3','cx-database-reasoning-interview-lab-fundamentals','Why group by event identity as well as its displayed name?','["Names can never be stored", "Identifiers cannot be selected", "Different events can share a name", "Every group must have two columns"]'::jsonb,2,'Stable identity prevents collapsing distinct events with equal labels.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-database-reasoning-interview-lab-fundamentals-4','cx-database-reasoning-interview-lab-fundamentals','What can NULL in a NOT IN subquery cause?','["Guaranteed true comparisons", "Automatic removal of NULL rows before comparison", "An automatic foreign key violation", "Unknown comparisons that fail WHERE"]'::jsonb,3,'SQL three valued logic affects NOT IN semantics.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-database-reasoning-interview-lab-fundamentals-5','cx-database-reasoning-interview-lab-fundamentals','What does NOT EXISTS naturally express?','["Absence of a matching related row", "Automatic sorting", "A universal performance guarantee", "A nonnull replacement value"]'::jsonb,0,'It checks whether the correlated subquery has any matching row.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
