if exists(select 1 from public.test_questions where id='tq-dbms-sql-14-date-functions-5' and (question_text,options,correct_index,explanation) is distinct from ('In MySQL, what does DATEDIFF(''2024-01-05'', ''2024-01-01'') return?','["4", "-4", "0", "1"]'::jsonb,0,'MySQL''s DATEDIFF(date1, date2) computes date1 - date2 in days: 2024-01-05 minus 2024-01-01 is 4 days.') and (question_text,options,correct_index,explanation) is distinct from ('In MySQL, what does DATEDIFF(''2024-01-05'', ''2024-01-01'') return?','["4", "-4", "0", "1"]'::jsonb,0,'MySQL''s DATEDIFF(date1, date2) computes date1 - date2 in days: 2024-01-05 minus 2024-01-01 is 4 days.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-14-date-functions-5'; end if;
