insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-denormalization-1','pt-dbms-sql-21-denormalization','What is denormalization, precisely?','["Forgetting to normalize a schema during initial design", "The deliberate reintroduction of controlled redundancy into an already-normalized schema, to optimize a specific known read-heavy access pattern", "A synonym for reaching 1NF", "Removing all foreign keys from a schema"]'::jsonb,1,'Denormalization is a conscious, informed trade-off made after understanding the fully normalized design — not an accident or a shortcut taken instead of normalizing.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
