if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-dirty-read-1' and (question_text,options,correct_index,explanation) is distinct from ('What is the defining condition of a dirty read?','["A transaction reads a value that was written by another transaction which has not yet committed", "A transaction reads the same value twice and gets different results", "A transaction reads a row that doesn''t exist yet", "A transaction fails to read any data at all"]'::jsonb,0,'A dirty read is specifically about reading uncommitted (possibly-to-be-rolled-back) data from another in-progress transaction.') and (question_text,options,correct_index,explanation) is distinct from ('What is the defining condition of a dirty read?','["A transaction reads a value that was written by another transaction which has not yet committed", "A transaction reads the same value twice and gets different results", "A transaction reads a row that doesn''t exist yet", "A transaction fails to read any data at all"]'::jsonb,0,'A dirty read is specifically about reading uncommitted (possibly-to-be-rolled-back) data from another in-progress transaction.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-dirty-read-1'; end if;
