if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-dirty-read-4' and (question_text,options,correct_index,explanation) is distinct from ('Which schedule property, if enforced, directly rules out dirty reads?','["Seriality", "Cascadelessness \u2014 requiring a transaction to only read data after its writer has already committed", "View serializability", "Conflict serializability alone, with no other property needed"]'::jsonb,1,'Cascadelessness (23.8) is defined precisely to forbid reading data from an uncommitted writer, which is exactly what prevents dirty reads.') and (question_text,options,correct_index,explanation) is distinct from ('Which schedule property, if enforced, directly rules out dirty reads?','["Recoverability alone", "Cascadelessness \u2014 requiring a transaction to only read data after its writer has already committed", "View serializability", "Conflict serializability alone, with no other property needed"]'::jsonb,1,'Cascadelessness (23.8) is defined precisely to forbid reading data from an uncommitted writer, which is exactly what prevents dirty reads.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-dirty-read-4'; end if;
