insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-dirty-read-1','pt-dbms-sql-23-dirty-read','What is the defining condition of a dirty read?','["A transaction reads a value that was written by another transaction which has not yet committed", "A transaction reads the same value twice and gets different results", "A transaction reads a row that doesn''t exist yet", "A transaction fails to read any data at all"]'::jsonb,0,'A dirty read is specifically about reading uncommitted (possibly-to-be-rolled-back) data from another in-progress transaction.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-dirty-read-2','pt-dbms-sql-23-dirty-read','In W1(A=900), R2(A=900), A1, why is T2 reading900 problematic?','["Because 900 is a negative number", "Because T1 had not yet committed its write of 900 at that point, and T1 later aborts, meaning A never actually settled at 900 in the database''s committed history", "Because T2 read the value twice", "Because T2''s transaction ID is higher than T1''s"]'::jsonb,1,'T1''s write was still uncommitted when T2 read it; T1''s subsequent abort means the value T2 based its logic on never became a real, permanent database fact.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-dirty-read-3','pt-dbms-sql-23-dirty-read','What business risk can a dirty read introduce?','["It always causes the database server to crash", "A workflow may make an external decision from a value whose writer later aborts.", "It is impossible to prevent", "It only affects read-only transactions"]'::jsonb,1,'Anomaly severity depends on the application; there is no universal ranking against lost updates.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-dirty-read-4','pt-dbms-sql-23-dirty-read','Which schedule property, if enforced, directly rules out dirty reads?','["Recoverability alone", "Cascadelessness — requiring a transaction to only read data after its writer has already committed", "View serializability", "Conflict serializability alone, with no other property needed"]'::jsonb,1,'Cascadelessness (23.8) is defined precisely to forbid reading data from an uncommitted writer, which is exactly what prevents dirty reads.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-dirty-read-5','pt-dbms-sql-23-dirty-read','If T1 aborts BEFORE T2 ever attempts to read A, does a dirty read occur?','["Yes, aborts always cause dirty reads", "No — T2 would simply see the restored pre-T1 value (or block, depending on locking); there is no dirty read since T2 never read the uncommitted value", "Only if T2 also aborts", "Only under READ UNCOMMITTED isolation"]'::jsonb,1,'A dirty read requires the reader to actually observe an uncommitted value; if the writer aborts before that read occurs, there''s nothing dirty for the reader to see.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-dirty-read-6','pt-dbms-sql-23-dirty-read','How does a dirty read differ from a lost update?','["They are identical phenomena", "A dirty read observes another transaction before its outcome is committed; a lost update erases an intended concurrent effect.", "A dirty read only happens with DELETE statements", "A lost update always involves three or more transactions"]'::jsonb,1,'A dirty read is already dirty before the writer outcome is known; the writer may later commit or abort.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-dirty-read-7','pt-dbms-sql-23-dirty-read','How is strict two-phase locking able to prevent dirty reads automatically?','["It disallows all read operations", "T1 holds its exclusive write lock on A until it commits or aborts, so T2''s read request on A is blocked until that lock is released, ensuring T2 never sees the uncommitted value", "It uses timestamps instead of locks", "It only applies to write operations, not reads"]'::jsonb,1,'Because the writer''s exclusive lock isn''t released until commit/abort, any reader requesting access to that same item is forced to wait, so it can never observe the dirty (uncommitted) value.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
