insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-distinct-1','pt-dbms-sql-12-distinct','What does SELECT DISTINCT remove?','["Rows from the stored source table", "Repeated complete rows in the selected result", "Only repeated first-column values", "All NULL values automatically"]'::jsonb,1,'Deduplication applies to the selected tuple.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
