if exists(select 1 from public.test_questions where id='tq-dbms-sql-18-duplicate-handling-1' and (question_text,options,correct_index,explanation) is distinct from ('What is the default duplicate-handling behavior of UNION, INTERSECT, and EXCEPT?','["All three keep every duplicate by default", "All three remove duplicates by default (set semantics)", "UNION keeps duplicates, but INTERSECT and EXCEPT remove them", "Duplicate handling is undefined and varies randomly"]'::jsonb,1,'Every one of these three operations deduplicates by default.') and (question_text,options,correct_index,explanation) is distinct from ('What is the default duplicate-handling behavior of UNION, INTERSECT, and EXCEPT?','["All three keep every duplicate by default", "All three remove duplicates by default (set semantics)", "UNION keeps duplicates, but INTERSECT and EXCEPT remove them", "Duplicate handling is undefined and varies randomly"]'::jsonb,1,'Every one of these three operations deduplicates by default.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-18-duplicate-handling-1'; end if;
