if exists(select 1 from public.test_questions where id='tq-dbms-sql-18-duplicate-handling-2' and (question_text,options,correct_index,explanation) is distinct from ('Which set operation has a universally-available ''ALL'' variant to keep duplicates?','["INTERSECT ALL", "EXCEPT ALL", "UNION ALL", "None of them support an ALL variant"]'::jsonb,2,'UNION ALL is the widely-supported, commonly-used bag-semantics variant.') and (question_text,options,correct_index,explanation) is distinct from ('Which MySQL 8.4 operation concatenates both inputs while retaining their combined copies?','["INTERSECT ALL", "EXCEPT ALL", "UNION ALL", "UNION DISTINCT"]'::jsonb,2,'UNION ALL adds the multiplicities from both branches without distinct elimination.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-18-duplicate-handling-2'; end if;
