if exists(select 1 from public.test_questions where id='tq-dbms-sql-18-duplicate-handling-3' and (question_text,options,correct_index,explanation) is distinct from ('Are INTERSECT ALL and EXCEPT ALL as widely supported as UNION ALL?','["Yes, identically supported everywhere", "No \u2014 they exist in some dialects (like PostgreSQL) but are far less commonly available or needed", "No dialect supports INTERSECT ALL or EXCEPT ALL", "They are more widely supported than UNION ALL"]'::jsonb,1,'UNION ALL is the dominant, most broadly available bag-semantics variant among the three operations.') and (question_text,options,correct_index,explanation) is distinct from ('For one tuple appearing m times on the left and n times on the right, how do MySQL 8.4 INTERSECT ALL and EXCEPT ALL differ?','["Both always return m+n copies", "INTERSECT ALL returns min(m,n); EXCEPT ALL returns max(m-n,0)", "Both return exactly one copy", "Neither syntax is supported in MySQL 8.4"]'::jsonb,1,'ALL preserves multiset semantics according to the operation; it is not synonymous with concatenation for every set operator.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-18-duplicate-handling-3'; end if;
