update public.learning_topics set short_description='Choose SQL duplicate policies deliberately with DISTINCT, UNION and UNION ALL, preserving fact identity, provenance, null behavior and meaningful event multiplicity.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Choose SQL duplicate policies deliberately with DISTINCT, UNION and UNION ALL, preserving fact identity, provenance, null behavior and meaningful event multiplicity.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Duplicate Handling.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-18-duplicate-handling' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-test-duplicate-handling-2','MCQ Test 2',category,10,10,'Application and scenarios for Duplicate Handling.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-18-duplicate-handling' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-duplicate-handling-1','pt-dbms-sql-18-duplicate-handling','What is the default duplicate-handling behavior of UNION, INTERSECT, and EXCEPT?','["All three keep every duplicate by default", "All three remove duplicates by default (set semantics)", "UNION keeps duplicates, but INTERSECT and EXCEPT remove them", "Duplicate handling is undefined and varies randomly"]'::jsonb,1,'Every one of these three operations deduplicates by default.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-duplicate-handling-2','pt-dbms-sql-18-duplicate-handling','Which MySQL 8.4 operation concatenates both inputs while retaining their combined copies?','["INTERSECT ALL", "EXCEPT ALL", "UNION ALL", "UNION DISTINCT"]'::jsonb,2,'UNION ALL adds the multiplicities from both branches without distinct elimination.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-duplicate-handling-3','pt-dbms-sql-18-duplicate-handling','For one tuple appearing m times on the left and n times on the right, how do MySQL 8.4 INTERSECT ALL and EXCEPT ALL differ?','["Both always return m+n copies", "INTERSECT ALL returns min(m,n); EXCEPT ALL returns max(m-n,0)", "Both return exactly one copy", "Neither syntax is supported in MySQL 8.4"]'::jsonb,1,'ALL preserves multiset semantics according to the operation; it is not synonymous with concatenation for every set operator.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-duplicate-handling-4','pt-dbms-sql-18-duplicate-handling','Do you ever need to explicitly opt OUT of deduplication to get the default deduplicating behavior?','["Yes, deduplication must always be explicitly requested", "No — deduplication IS the default; you explicitly opt INTO keeping duplicates instead (e.g. via ALL)", "Deduplication cannot be controlled at all", "This varies unpredictably by query"]'::jsonb,1,'Plain set forms eliminate duplicate tuples. ALL selects multiset rules: UNION ALL adds copies, INTERSECT ALL keeps the minimum count, and EXCEPT ALL subtracts counts without going below zero.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-duplicate-handling-5','pt-dbms-sql-18-duplicate-handling','Why does duplicate handling matter for a downstream COUNT(*) on a combined result?','["COUNT(*) is unaffected by whether duplicates were removed", "Whether duplicates were removed directly changes how many rows COUNT(*) sees", "COUNT(*) automatically ignores duplicates regardless of the set operation used", "This only matters for INTERSECT, never UNION"]'::jsonb,1,'The actual row count of the combined result depends directly on whether deduplication happened.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-duplicate-handling-6','pt-dbms-sql-18-duplicate-handling','What practical question should precede choosing between a plain set operation and its ALL variant?','["Whether the tables have the same name", "Whether duplicates actually need to be removed for this specific use case", "Whether ORDER BY will be used", "Whether the query involves more than one table"]'::jsonb,1,'This is the core cost/correctness trade-off to consider before defaulting to the deduplicating form.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-duplicate-handling-7','pt-dbms-sql-18-duplicate-handling','What is a careful performance statement about duplicate elimination?','["It never costs work", "It can require comparison or other processing, though a provably redundant step may be optimized away", "It only matters for INTERSECT", "Every plan must use the same sorting method"]'::jsonb,1,'Physical work depends on the selected plan and proven properties. Do not assert a mandatory algorithm or unavoidable cost when redundancy is provable.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-duplicate-handling-8','pt-dbms-sql-18-duplicate-handling','When do UNION and UNION ALL return the same bag of selected tuples from two branches?','["Whenever there is no cross-branch overlap, even if a branch repeats tuples", "When each branch has unique selected tuples and their tuple sets are disjoint", "Whenever both branches have the same row count", "Whenever ORDER BY is omitted"]'::jsonb,1,'Both within-branch uniqueness and cross-branch disjointness are required. Equal results do not by themselves establish a universal performance difference.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-duplicate-handling-9','pt-dbms-sql-18-duplicate-handling','What does SELECT DISTINCT compare?','["The entire selected tuple", "Only the first column", "Only the primary key even if absent", "Only numeric values"]'::jsonb,0,'All selected expressions define result equality.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-duplicate-handling-10','pt-dbms-sql-18-duplicate-handling','Does DISTINCT modify stored rows?','["Yes, it deletes copies", "No", "Yes, it creates a unique index", "Only for NULL values"]'::jsonb,1,'It changes the returned result only.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-duplicate-handling-11','cx-test-duplicate-handling-2','What does UNION ALL preserve?','["Only one copy per tuple", "Only unmatched rows", "Result multiplicity", "Only nonnull values"]'::jsonb,2,'All branch rows remain.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-duplicate-handling-12','cx-test-duplicate-handling-2','Can UNION remove repeats from within one branch?','["No, only cross-branch copies", "Only if a key is declared", "Only for empty input", "Yes"]'::jsonb,3,'Duplicate removal covers the combined output.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
