insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-duplicate-rows-1','pt-dbms-sql-16-duplicate-rows','One Engineering department row matches exactly two different employee rows by the intended department key. Is repeating Engineering in those two joined pairs necessarily a bug?','["Yes, always a bug requiring DISTINCT", "No — it''s the expected consequence of Engineering having two employees, an intended result of one-to-many cardinality", "Yes, because department names should never repeat", "This can only be determined by running EXPLAIN"]'::jsonb,1,'Repeated values reflecting a genuine one-to-many relationship are correct, not duplicated data.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
