if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-durability-3' and (question_text,options,correct_index,explanation) is distinct from ('What mechanism typically helps provide durability?','["An in-memory cache with no disk involvement", "A write-ahead log (Chapter 26) that records changes durably before/alongside the commit", "Deleting old data to save space", "Running the database in read-only mode"]'::jsonb,1,'Write-ahead logging is the standard mechanism for achieving durable commits, covered further in Chapter 26.') and (question_text,options,correct_index,explanation) is distinct from ('What mechanism typically helps provide durability?','["An in-memory cache with no disk involvement", "A write-ahead log (Chapter 26) that records changes durably before/alongside the commit", "Deleting old data to save space", "Running the database in read-only mode"]'::jsonb,1,'Write-ahead logging is the standard mechanism for achieving durable commits, covered further in Chapter 26.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-durability-3'; end if;
