if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-durability-5' and (question_text,options,correct_index,explanation) is distinct from ('Can durability be violated even if the database software behaves correctly?','["No, durability is guaranteed purely by database software logic", "Yes \u2014 a genuinely faulty disk or a storage layer that lies about a write succeeding can violate durability despite correct database behavior", "Only a database bug can violate durability", "Durability is guaranteed regardless of the physical storage medium"]'::jsonb,1,'Durability ultimately depends on the physical storage actually behaving as promised, which is outside the database''s own control.') and (question_text,options,correct_index,explanation) is distinct from ('Can durability be violated even if the database software behaves correctly?','["No, durability is guaranteed purely by database software logic", "Yes \u2014 a genuinely faulty disk or a storage layer that lies about a write succeeding can violate durability despite correct database behavior", "Only a database bug can violate durability", "Durability is guaranteed regardless of the physical storage medium"]'::jsonb,1,'Durability ultimately depends on the physical storage actually behaving as promised, which is outside the database''s own control.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-durability-5'; end if;
