if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-durability-6' and (question_text,options,correct_index,explanation) is distinct from ('Why do some real systems add replication or checksums beyond a single disk''s guarantees?','["These have nothing to do with durability", "As extra safeguards against physical storage failures that could otherwise violate durability", "To make transactions commit faster", "To reduce the need for isolation"]'::jsonb,1,'Extra redundancy compensates for the risk that a single storage medium''s own guarantee might not hold.') and (question_text,options,correct_index,explanation) is distinct from ('Why do some real systems add replication or checksums beyond a single disk''s guarantees?','["These have nothing to do with durability", "As extra safeguards against physical storage failures that could otherwise violate durability", "To make transactions commit faster", "To reduce the need for isolation"]'::jsonb,1,'Extra redundancy compensates for the risk that a single storage medium''s own guarantee might not hold.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-durability-6'; end if;
