update public.learning_topics set short_description='Follow committed data through logging, crashes, and recovery, and distinguish InnoDB durability settings from replication and backup guarantees.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Follow committed data through logging, crashes, and recovery, and distinguish InnoDB durability settings from replication and backup guarantees.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Durability.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-22-durability' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-durability-application','MCQ Test 2',category,10,10,'Application and scenarios for Durability.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-22-durability' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-durability-1','pt-dbms-sql-22-durability','What does durability promise after a successful commit under the documented configuration and storage assumptions?','["Fast transaction commits", "Committed changes survive the failures covered by that documented guarantee", "Transactions never fail", "Data is always encrypted at rest"]'::jsonb,1,'Durability is scoped to a failure model and persistence assumptions; it does not promise survival after every possible disaster.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-durability-2','pt-dbms-sql-22-durability','Does durability require an unfinished transaction to survive as committed business work after a pre-commit crash?','["Yes, its partial changes are preserved", "No; unfinished physical changes may need undo or exclusion during atomic recovery", "It guarantees the transaction will automatically retry", "Durability guarantees the crash never happened"]'::jsonb,1,'Durability protects committed outcomes. Unfinished work can already have physical effects, but recovery must not present it as a completed business transaction.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-durability-3','pt-dbms-sql-22-durability','What mechanism typically helps provide durability?','["An in-memory cache with no disk involvement", "A write-ahead log (Chapter 26) that records changes durably before/alongside the commit", "Deleting old data to save space", "Running the database in read-only mode"]'::jsonb,1,'Write-ahead logging is the standard mechanism for achieving durable commits, covered further in Chapter 26.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-durability-4','pt-dbms-sql-22-durability','Can a database be configured to trade away some durability for higher write performance?','["No, durability is always absolute with no configuration", "Yes — some systems offer weaker durability modes as an explicit performance trade-off, a genuine configuration risk when enabled", "This would violate the SQL standard and is never possible", "Durability can only be strengthened, never weakened"]'::jsonb,1,'Configurable durability trade-offs exist in some real systems, worth understanding as an explicit choice.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-durability-5','pt-dbms-sql-22-durability','Can durability be violated even if the database software behaves correctly?','["No, durability is guaranteed purely by database software logic", "Yes — a genuinely faulty disk or a storage layer that lies about a write succeeding can violate durability despite correct database behavior", "Only a database bug can violate durability", "Durability is guaranteed regardless of the physical storage medium"]'::jsonb,1,'Durability ultimately depends on the physical storage actually behaving as promised, which is outside the database''s own control.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-durability-6','pt-dbms-sql-22-durability','Why do some real systems add replication or checksums beyond a single disk''s guarantees?','["These have nothing to do with durability", "As extra safeguards against physical storage failures that could otherwise violate durability", "To make transactions commit faster", "To reduce the need for isolation"]'::jsonb,1,'Extra redundancy compensates for the risk that a single storage medium''s own guarantee might not hold.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-durability-7','pt-dbms-sql-22-durability','What supports relying on an acknowledged successful COMMIT within the system’s documented failure model?','["Nothing — commits can be silently undone at any time", "Durability, provided the configured persistence policy and storage assumptions satisfy that model", "Atomicity alone, without needing Durability", "The absence of any storage medium involvement"]'::jsonb,1,'The promise concerns covered failures and the actual durability configuration, rather than unconditional permanence under every failure.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-durability-8','pt-dbms-sql-22-durability','Is durability a guarantee about IN-PROGRESS (uncommitted) transaction state?','["Yes, all in-progress state is durable", "No — durability specifically concerns state AFTER a successful commit, not in-progress uncommitted work", "Durability applies equally to both committed and uncommitted state", "In-progress state is irrelevant to any ACID property"]'::jsonb,1,'Durability''s guarantee is scoped strictly to the post-commit state.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
