CREATE TABLE equipment (item_id INT PRIMARY KEY, category_id INT NOT NULL);
CREATE TABLE equipment_loan (loan_id INT PRIMARY KEY, item_id INT NOT NULL, borrower_id INT NOT NULL, checked_out_on DATE NOT NULL, due_on DATE NOT NULL, returned_on DATE NULL);
INSERT INTO borrower VALUES (1,''Mira''),(2,''Noah'');
INSERT INTO category VALUES (1,''Camera''),(2,''Audio''),(3,''Lighting'');
INSERT INTO equipment VALUES (10,1),(11,1),(20,2);
INSERT INTO equipment_loan VALUES (100,10,1,''2026-10-01'',''2026-10-20'',NULL),(101,11,2,''2026-10-01'',''2026-10-10'',''2026-10-09''),(102,20,2,''2026-10-01'',''2026-10-29'',NULL);
```

