insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-exists-1','pt-dbms-sql-17-exists','When is EXISTS true?','["When a selected number is positive only", "When its subquery returns at least one row", "Only for exactly one row", "Only for nonnull selected labels"]'::jsonb,1,'Existence concerns the presence of rows rather than the values projected from them.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
