if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-full-functional-dependency-2' and (question_text,options,correct_index,explanation) is distinct from ('In the sample data, C1 (Database Systems) has three different EnrollmentDate values (2026-01-10, 2026-01-11, 2026-01-12) across S1, S2, and S3. What does this prove?','["That CourseID alone determines EnrollmentDate", "That CourseID alone does NOT determine EnrollmentDate, ruling out CourseID as a sufficient determinant by itself", "That EnrollmentDate is not a valid attribute", "That StudentID alone determines EnrollmentDate"]'::jsonb,1,'If the same CourseID value corresponds to different EnrollmentDate values across rows, CourseID alone cannot be a determinant of EnrollmentDate — confirming the dependency needs the full composite key.') and (question_text,options,correct_index,explanation) is distinct from ('Two allowed rows have the same Assessment but different Mark values. What does this refute?','["The pair necessarily determines Mark", "Assessment alone determines Mark", "Student alone determines Mark", "Every possible dependency in the relation"]'::jsonb,1,'It refutes that singleton dependency only. Establishing fullness also requires the pair dependency and the other subset check.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-full-functional-dependency-2'; end if;
