if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-full-functional-dependency-3' and (question_text,options,correct_index,explanation) is distinct from ('For a full functional dependency to exist on a composite key X = {A, B}, what must be true?','["Both A -> Y and B -> Y must hold individually", "X -> Y must hold, AND neither A alone nor B alone may determine Y", "Y must be part of the key itself", "A and B must both be foreign keys"]'::jsonb,1,'Full functional dependency requires the whole composite determinant, with no proper subset (here, A alone or B alone) sufficient to determine Y on its own.') and (question_text,options,correct_index,explanation) is distinct from ('For a full functional dependency to exist on a composite key X = {A, B}, what must be true?','["Both A -> Y and B -> Y must hold individually", "X -> Y must hold, AND neither A alone nor B alone may determine Y", "Y must be part of the key itself", "A and B must both be foreign keys"]'::jsonb,1,'Full functional dependency requires the whole composite determinant, with no proper subset (here, A alone or B alone) sufficient to determine Y on its own.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-full-functional-dependency-3'; end if;
