if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-full-functional-dependency-5' and (question_text,options,correct_index,explanation) is distinct from ('Which attribute in the running example is NOT fully dependent on {StudentID, CourseID} (i.e., is only partially dependent)?','["EnrollmentDate", "CourseName, since CourseID alone already determines it", "There are no partially dependent attributes in this table", "StudentID itself"]'::jsonb,1,'CourseName depends on CourseID alone, a proper subset of the composite key — that''s a partial dependency (21.7), the opposite of full functional dependency.') and (question_text,options,correct_index,explanation) is distinct from ('Under the campus rules, which dependency from Student,Assessment is partial?','["The dependency to Mark when neither singleton determines it", "The dependency to AssessmentTitle, because Assessment alone suffices", "Every dependency from any pair", "Only dependencies to numeric columns"]'::jsonb,1,'The student component is unnecessary for the assessment title.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-full-functional-dependency-5'; end if;
