if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-full-functional-dependency-6' and (question_text,options,correct_index,explanation) is distinct from ('A table has key {OrderID, ProductID} and an attribute ShipDate that is the same for every ProductID within a given OrderID (the whole order ships together). Is ShipDate fully dependent on {OrderID, ProductID}?','["Yes, because it depends on the composite key", "No \u2014 since ShipDate is determined by OrderID alone (a proper subset), it is only partially dependent, not fully dependent, on the composite key", "Yes, because ShipDate is a date type", "No, because ShipDate cannot be functionally dependent on anything"]'::jsonb,1,'If OrderID alone already fixes ShipDate, the composite key is not fully necessary — this is a partial dependency, structurally identical to the CourseName situation in the running example.') and (question_text,options,correct_index,explanation) is distinct from ('A table has key {OrderID, ProductID} and an attribute ShipDate that is the same for every ProductID within a given OrderID (the whole order ships together). Is ShipDate fully dependent on {OrderID, ProductID}?','["Yes, because it depends on the composite key", "No \u2014 since ShipDate is determined by OrderID alone (a proper subset), it is only partially dependent, not fully dependent, on the composite key", "Yes, because ShipDate is a date type", "No, because ShipDate cannot be functionally dependent on anything"]'::jsonb,1,'OrderID alone fixes ShipDate, so ProductID is unnecessary in that determinant. This is analogous to an assessment title determined by Assessment alone.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-full-functional-dependency-6'; end if;
