insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-full-functional-dependency-1','pt-dbms-sql-21-full-functional-dependency','Under the stated campus rules, why is Student,Assessment determines Mark full?','["The pair is printed first", "The pair determines Mark, and neither single identity does", "Mark is numeric", "The sample contains exactly one row"]'::jsonb,1,'Both determinant components are necessary under the specified permitted-state rules.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-full-functional-dependency-2','pt-dbms-sql-21-full-functional-dependency','Two allowed rows have the same Assessment but different Mark values. What does this refute?','["The pair necessarily determines Mark", "Assessment alone determines Mark", "Student alone determines Mark", "Every possible dependency in the relation"]'::jsonb,1,'It refutes that singleton dependency only. Establishing fullness also requires the pair dependency and the other subset check.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-full-functional-dependency-3','pt-dbms-sql-21-full-functional-dependency','For a full functional dependency to exist on a composite key X = {A, B}, what must be true?','["Both A -> Y and B -> Y must hold individually", "X -> Y must hold, AND neither A alone nor B alone may determine Y", "Y must be part of the key itself", "A and B must both be foreign keys"]'::jsonb,1,'Full functional dependency requires the whole composite determinant, with no proper subset (here, A alone or B alone) sufficient to determine Y on its own.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-full-functional-dependency-4','pt-dbms-sql-21-full-functional-dependency','Why must a careful fullness definition consider the empty set even for a singleton determinant?','["The empty set contains all key attributes", "A dependent fixed by the domain can be determined by the empty set", "Every singleton determinant is necessarily composite", "Constants can never appear in relations"]'::jsonb,1,'Fullness rules out every proper determining subset. The familiar singleton shortcut assumes no empty-set dependency on the dependent.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
