insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-full-functional-dependency-6','pt-dbms-sql-21-full-functional-dependency','A table has key {OrderID, ProductID} and an attribute ShipDate that is the same for every ProductID within a given OrderID (the whole order ships together). Is ShipDate fully dependent on {OrderID, ProductID}?','["Yes, because it depends on the composite key", "No — since ShipDate is determined by OrderID alone (a proper subset), it is only partially dependent, not fully dependent, on the composite key", "Yes, because ShipDate is a date type", "No, because ShipDate cannot be functionally dependent on anything"]'::jsonb,1,'OrderID alone fixes ShipDate, so ProductID is unnecessary in that determinant. This is analogous to an assessment title determined by Assessment alone.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
