insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-full-functional-dependency-20','cx-test-full-functional-dependency-2','What must a proposed decomposition preserve?','["Only the original column order", "Only the original row count in one sample", "Every repeated name", "A lossless relationship and relevant dependency guarantees"]'::jsonb,3,'Smaller tables alone do not establish design correctness.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
