select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-16-joins/full-outer-join' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'full-outer-join'; end if;
