if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-16-full-outer-join' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'full-outer-join'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-16-full-outer-join' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'full-outer-join'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-16-full-outer-join','pt-dbms-sql-16-full-outer-join-application')) then raise exception 'Extra topic tests require manual integration: %', 'full-outer-join'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-16-full-outer-join-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'full-outer-join'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Three reconciliation categories", "description": "Both sources retain their unmatched identities while one matching pair combines the shared code20.", "columns": ["Registered code", "Scanned code", "Category"], "rows": [["10", "No scan", "Registered only"], ["20", "20", "Matched"], ["No register row", "30", "Scanned only"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'full-outer-join'; end if;
