if exists(select 1 from public.test_questions where id='tq-dbms-sql-16-full-outer-join-1' and (question_text,options,correct_index,explanation) is distinct from ('What does FULL OUTER JOIN preserve?','["Only matched rows from both tables", "Every row from BOTH tables, filling NULL where a match is missing on either side", "Only the left table''s rows", "Only the right table''s rows"]'::jsonb,1,'FULL OUTER JOIN is the union of what LEFT and RIGHT JOIN each individually preserve.') and (question_text,options,correct_index,explanation) is distinct from ('What does FULL OUTER JOIN preserve?','["Only matched rows from both tables", "Every row from BOTH tables, filling NULL where a match is missing on either side", "Only the left table''s rows", "Only the right table''s rows"]'::jsonb,1,'FULL OUTER JOIN is the union of what LEFT and RIGHT JOIN each individually preserve.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-16-full-outer-join-1'; end if;
