if exists(select 1 from public.test_questions where id='tq-dbms-sql-16-full-outer-join-2' and (question_text,options,correct_index,explanation) is distinct from ('In the running example, does FULL OUTER JOIN include both Vikram (no department) and Marketing (no employees)?','["No, only one of them", "Yes \u2014 both unmatched rows are preserved, one from each side", "Neither is included", "This depends on which table is listed first"]'::jsonb,1,'FULL OUTER JOIN keeps unmatched rows from both sides simultaneously.') and (question_text,options,correct_index,explanation) is distinct from ('In a full reconciliation with registered asset10 absent from scans and scan code30 absent from registered assets, which missing populations must remain?','["No, only one of them", "Both the registered-only asset10 and the scan-only code30, withNULLs for their missing counterparts", "Neither is included", "This depends on which table is listed first"]'::jsonb,1,'Full reconciliation preserves unmatched rows from both populations, not only the rows on one chosen side.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-16-full-outer-join-2'; end if;
