if exists(select 1 from public.test_questions where id='tq-dbms-sql-16-full-outer-join-3' and (question_text,options,correct_index,explanation) is distinct from ('Does MySQL natively support FULL OUTER JOIN in the same way PostgreSQL and SQL Server do?','["Yes, identically", "No \u2014 MySQL historically lacks native FULL OUTER JOIN and requires simulating it with LEFT JOIN UNION RIGHT JOIN", "MySQL only supports FULL OUTER JOIN for two tables, never more", "No database supports FULL OUTER JOIN"]'::jsonb,1,'This is a real, practically important dialect limitation.') and (question_text,options,correct_index,explanation) is distinct from ('Does MySQL natively support FULL OUTER JOIN in the same way PostgreSQL and SQL Server do?','["Yes, identically", "No; emulate it with a left-join branch and the opposite unmatched-only branch combined with UNION ALL", "MySQL only supports FULL OUTER JOIN for two tables, never more", "No database supports FULL OUTER JOIN"]'::jsonb,1,'Use disjoint branches and a reliable nonnull left marker for the anti-match filter. Plain UNION can erase legitimate duplicate projections.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-16-full-outer-join-3'; end if;
