if exists(select 1 from public.test_questions where id='tq-dbms-sql-16-full-outer-join-4' and (question_text,options,correct_index,explanation) is distinct from ('When simulating FULL OUTER JOIN with (A LEFT JOIN B) UNION (A RIGHT JOIN B), why must UNION (not UNION ALL) be used?','["UNION ALL is not valid syntax here", "UNION ALL would double-count every matched row, since it would appear once from each side''s join; UNION deduplicates it back to one row", "UNION is faster in every case", "There''s no difference between UNION and UNION ALL here"]'::jsonb,1,'Matched rows appear in both the LEFT and RIGHT JOIN halves, so deduplication via UNION prevents double-counting.') and (question_text,options,correct_index,explanation) is distinct from ('Which MySQL emulation preserves full-join bag multiplicity without double-counting matched pairs?','["UNION ALL is not valid syntax here", "A LEFT JOIN branch UNION ALL an opposite-side anti-match branch", "UNION is faster in every case", "There''s no difference between UNION and UNION ALL here"]'::jsonb,1,'The branches are disjoint; plain UNION can erase legitimate projected duplicates.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-16-full-outer-join-4'; end if;
