if exists(select 1 from public.test_questions where id='tq-dbms-sql-16-full-outer-join-5' and (question_text,options,correct_index,explanation) is distinct from ('What does FULL OUTER JOIN combined with `WHERE a.id IS NULL OR b.id IS NULL` accomplish?','["Finds only fully matched rows", "Finds every unmatched row from EITHER side \u2014 a two-way reconciliation/anti-join between the two tables", "Causes a syntax error", "Returns the same result as INNER JOIN"]'::jsonb,1,'This combines FULL OUTER JOIN''s completeness with an anti-join-style filter, checking both sides at once.') and (question_text,options,correct_index,explanation) is distinct from ('When a.id and b.id are guaranteed nonnull identities, what does WHERE a.id IS NULL OR b.id IS NULL select after a full-join reconciliation?','["Finds only fully matched rows", "Finds every unmatched row from EITHER side \u2014 a two-way reconciliation/anti-join between the two tables", "Causes a syntax error", "Returns the same result as INNER JOIN"]'::jsonb,1,'This combines FULL OUTER JOIN''s completeness with an anti-join-style filter, checking both sides at once.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-16-full-outer-join-5'; end if;
