if exists(select 1 from public.test_questions where id='tq-dbms-sql-16-full-outer-join-6' and (question_text,options,correct_index,explanation) is distinct from ('Is FULL OUTER JOIN''s use of the OUTER keyword optional, like with LEFT/RIGHT JOIN?','["No, OUTER is mandatory for FULL JOIN", "Yes \u2014 FULL JOIN and FULL OUTER JOIN mean the same thing", "FULL JOIN and FULL OUTER JOIN are different operations entirely", "OUTER changes FULL JOIN into an INNER JOIN"]'::jsonb,1,'Consistent with LEFT/RIGHT, OUTER is optional and FULL JOIN behaves identically to FULL OUTER JOIN.') and (question_text,options,correct_index,explanation) is distinct from ('Is FULL OUTER JOIN''s use of the OUTER keyword optional, like with LEFT/RIGHT JOIN?','["No, OUTER is mandatory for FULL JOIN", "Yes \u2014 FULL JOIN and FULL OUTER JOIN mean the same thing", "FULL JOIN and FULL OUTER JOIN are different operations entirely", "OUTER changes FULL JOIN into an INNER JOIN"]'::jsonb,1,'Consistent with LEFT/RIGHT, OUTER is optional and FULL JOIN behaves identically to FULL OUTER JOIN.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-16-full-outer-join-6'; end if;
