insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-16-full-outer-join-application','MCQ Test 2',category,10,10,'Application and scenarios for FULL OUTER JOIN.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-16-full-outer-join' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-full-outer-join-1','pt-dbms-sql-16-full-outer-join','What does FULL OUTER JOIN preserve?','["Only matched rows from both tables", "Every row from BOTH tables, filling NULL where a match is missing on either side", "Only the left table''s rows", "Only the right table''s rows"]'::jsonb,1,'FULL OUTER JOIN is the union of what LEFT and RIGHT JOIN each individually preserve.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-full-outer-join-2','pt-dbms-sql-16-full-outer-join','In a full reconciliation with registered asset10 absent from scans and scan code30 absent from registered assets, which missing populations must remain?','["No, only one of them", "Both the registered-only asset10 and the scan-only code30, withNULLs for their missing counterparts", "Neither is included", "This depends on which table is listed first"]'::jsonb,1,'Full reconciliation preserves unmatched rows from both populations, not only the rows on one chosen side.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-full-outer-join-3','pt-dbms-sql-16-full-outer-join','Does MySQL natively support FULL OUTER JOIN in the same way PostgreSQL and SQL Server do?','["Yes, identically", "No; emulate it with a left-join branch and the opposite unmatched-only branch combined with UNION ALL", "MySQL only supports FULL OUTER JOIN for two tables, never more", "No database supports FULL OUTER JOIN"]'::jsonb,1,'Use disjoint branches and a reliable nonnull left marker for the anti-match filter. Plain UNION can erase legitimate duplicate projections.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-full-outer-join-4','pt-dbms-sql-16-full-outer-join','Which MySQL emulation preserves full-join bag multiplicity without double-counting matched pairs?','["UNION ALL is not valid syntax here", "A LEFT JOIN branch UNION ALL an opposite-side anti-match branch", "UNION is faster in every case", "There''s no difference between UNION and UNION ALL here"]'::jsonb,1,'The branches are disjoint; plain UNION can erase legitimate projected duplicates.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-full-outer-join-5','pt-dbms-sql-16-full-outer-join','When a.id and b.id are guaranteed nonnull identities, what does WHERE a.id IS NULL OR b.id IS NULL select after a full-join reconciliation?','["Finds only fully matched rows", "Finds every unmatched row from EITHER side — a two-way reconciliation/anti-join between the two tables", "Causes a syntax error", "Returns the same result as INNER JOIN"]'::jsonb,1,'This combines FULL OUTER JOIN''s completeness with an anti-join-style filter, checking both sides at once.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-full-outer-join-6','pt-dbms-sql-16-full-outer-join','Is FULL OUTER JOIN''s use of the OUTER keyword optional, like with LEFT/RIGHT JOIN?','["No, OUTER is mandatory for FULL JOIN", "Yes — FULL JOIN and FULL OUTER JOIN mean the same thing", "FULL JOIN and FULL OUTER JOIN are different operations entirely", "OUTER changes FULL JOIN into an INNER JOIN"]'::jsonb,1,'Consistent with LEFT/RIGHT, OUTER is optional and FULL JOIN behaves identically to FULL OUTER JOIN.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-full-outer-join-7','pt-dbms-sql-16-full-outer-join','Unique register keys10, 20 and scan keys20, 30 have one matched pair and one unmatched row per side. How many full result rows?','["Three rows: one matched pair plus two unmatched rows.", "Always exactly 4 rows", "Exactly two rows because unmatched inputs vanish", "Always exactly 12 rows (a full cartesian product)"]'::jsonb,0,'M+L+R gives1+1+1=3.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
