- Repeated matching values when keys permit them.','[{"input": "INSERT INTO register_assets VALUES(10),(20); INSERT INTO scans VALUES(1,20),(2,30);", "output": "registered_id\tscan_id\tscanned_code\n10\tNULL\tNULL\n20\t1\t20\nNULL\t2\t30", "explanation": "Disjoint branches preserve matching observation identities and unmatched rows exactly once."}]'::jsonb,'[{"seed_sql": "INSERT INTO register_assets VALUES(10);", "expected": "registered_id\tscan_id\tscanned_code\n10\tNULL\tNULL", "hidden": true}, {"seed_sql": "INSERT INTO register_assets VALUES(20); INSERT INTO scans VALUES(1,20),(2,20);", "expected": "registered_id\tscan_id\tscanned_code\n20\t1\t20\n20\t2\t20", "hidden": true}]'::jsonb,'[]'::jsonb,'["Disjoint branches preserve matching observation identities and unmatched rows exactly once."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'Disjoint branches preserve matching observation identities and unmatched rows exactly once.','{"sql": "SELECT * FROM (SELECT r.asset_id AS registered_id,s.scan_id,s.asset_id AS scanned_code FROM register_assets r LEFT JOIN scans s ON s.asset_id=r.asset_id UNION ALL SELECT r.asset_id,s.scan_id,s.asset_id FROM scans s LEFT JOIN register_assets r ON r.asset_id=s.asset_id WHERE r.asset_id IS NULL) x ORDER BY COALESCE(registered_id,scanned_code),scan_id;"}'::jsonb,'Disjoint branches preserve matching observation identities and unmatched rows exactly once.',array['sql'],'CREATE TABLE register_assets(asset_id INT PRIMARY KEY); CREATE TABLE scans(scan_id INT PRIMARY KEY,asset_id INT NULL);','INSERT INTO register_assets VALUES(10),(20); INSERT INTO scans VALUES(1,20),(2,30);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-16-full-outer-join' on conflict(id) do nothing;
