if exists(select 1 from public.test_questions where id='cx-function-based-index-concept-application-9' and (question_text,options,correct_index,explanation) is distinct from ('Is every legal SELECT function automatically allowed in an index expression?','["Yes always", "No, engine restrictions apply", "Only if its name is uppercase", "Only if the table has two rows"]'::jsonb,1,'Index expressions have eligibility restrictions.') and (question_text,options,correct_index,explanation) is distinct from ('Is every legal SELECT function automatically allowed in an index expression?','["Yes always", "No, engine restrictions apply", "Only if its name is uppercase", "Only if the table has two rows"]'::jsonb,1,'Index expressions have eligibility restrictions.')) then raise exception 'Edited question requires review: %', 'cx-function-based-index-concept-application-9'; end if;
