update public.learning_topics set short_description='Learn expression indexing with MySQL functional keys, lowercase email semantics, generated columns, NULL collisions, and practical EXPLAIN design labs.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Learn expression indexing with MySQL functional keys, lowercase email semantics, generated columns, NULL collisions, and practical EXPLAIN design labs.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Function Based Index Concept.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-20-function-based-index-concept' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-function-based-index-concept-application','MCQ Test 2',category,10,10,'Application and scenarios for Function Based Index Concept.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-20-function-based-index-concept' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-function-based-index-concept-1','pt-dbms-sql-20-function-based-index-concept','What does a function-based (expression) index actually index?','["The raw, unmodified column value only", "The result of applying a function or expression to a column", "A randomly selected sample of rows", "The table''s row count"]'::jsonb,1,'A function-based index stores entries sorted by the computed result of an expression, not the raw underlying column value.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-function-based-index-concept-2','pt-dbms-sql-20-function-based-index-concept','Why can a regular index on raw email fail to provide a direct expression-key lookup for LOWER(email)=''x''?','["Because LOWER() is not valid SQL", "Because the regular index is sorted by raw email values, which don''t align with the lowercased comparison the query is making", "Because email columns cannot be indexed at all", "Because LOWER() always returns NULL"]'::jsonb,1,'The indexed raw-key order need not align with the expression comparison. A full or covering index scan can still be possible; the point is absence of a guaranteed direct expression-key lookup.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-function-based-index-concept-3','pt-dbms-sql-20-function-based-index-concept','What is the correct way to make `WHERE LOWER(email) = ''x''` use an index?','["Create a regular index on the raw email column", "Create a function-based index on LOWER(email)", "Remove the email column from the table", "Convert the table to use a hash index automatically"]'::jsonb,1,'A function-based index built directly on LOWER(email) aligns the index''s stored values with what the query is comparing, enabling index use.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-function-based-index-concept-4','pt-dbms-sql-20-function-based-index-concept','If a function-based index is built on LOWER(email), can a query filtering on UPPER(email) use it?','["Yes, LOWER and UPPER are treated as equivalent by all engines", "Generally no, since UPPER(email) is a different expression than LOWER(email)", "Yes, but only for numeric columns", "It depends solely on the table''s primary key"]'::jsonb,1,'The query''s expression must match (or be recognized as equivalent to) the indexed expression; UPPER and LOWER are different functions.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-function-based-index-concept-5','pt-dbms-sql-20-function-based-index-concept','Which predicate is a candidate for a compatible supported expression index, subject to selectivity and measured plan costs?','["WHERE id = 5", "WHERE YEAR(created_at) = 2024", "WHERE gpa BETWEEN 3.0 AND 4.0", "WHERE department = ''CS''"]'::jsonb,1,'A supported YEAR expression index can provide an eligible access path. A raw created_at range rewrite may also help, and actual benefit depends on selectivity, plan and maintenance cost.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-function-based-index-concept-6','pt-dbms-sql-20-function-based-index-concept','Before MySQL native functional key parts introduced in 8.0.13, what supported generated-column pattern was available from 5.7 for suitable expressions?','["They didn''t support any workaround at all", "Using a generated/virtual column storing the expression''s result, plus a regular index on that generated column", "By disabling all WHERE clauses", "By converting all tables to NoSQL"]'::jsonb,1,'Suitable generated columns could be indexed from MySQL5.7. Native functional key parts arrived in8.0.13; expression and engine restrictions still apply.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-function-based-index-concept-7','pt-dbms-sql-20-function-based-index-concept','What is a cost specific to function-based indexes beyond the usual index write overhead?','["None; they have zero additional cost", "The function must be computed on every relevant write, which can add computational cost if the function is expensive", "They can never be dropped once created", "They automatically disable all other indexes on the table"]'::jsonb,1,'Because the index tracks a computed expression, the function must be re-evaluated on every write that touches the underlying column(s), adding compute cost beyond typical index maintenance.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-function-based-index-concept-8','pt-dbms-sql-20-function-based-index-concept','Does PostgreSQL support indexes on permitted immutable expressions?','["No, expression indexes do not exist", "Yes, subject to immutability and documented index-expression restrictions", "Only date expressions are allowed", "Only in a special NoSQL mode"]'::jsonb,1,'PostgreSQL expression indexes are supported, but arbitrary volatile or otherwise disallowed expressions are not automatically eligible.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-function-based-index-concept-fundamentals-9','pt-dbms-sql-20-function-based-index-concept','What does an expression index organize for searching?','["Computed expression values", "Only SQL comments", "Only original query strings", "A cached full report automatically"]'::jsonb,0,'The indexed keys represent a derived expression.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
