insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-function-based-index-concept-application-4','cx-function-based-index-concept-application','Can two different spellings share one nonunique expression key?','["Yes", "No, expression indexes are always unique", "Only if both IDs match", "Only in empty tables"]'::jsonb,0,'A nonunique key permits collisions in computed values.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
