if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-21-functional-dependency' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'functional-dependency'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-21-functional-dependency' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'functional-dependency'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-21-functional-dependency','pt-dbms-sql-21-functional-dependency-application')) then raise exception 'Extra topic tests require manual integration: %', 'functional-dependency'; end if;
