update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Agreement on a determinant must preserve its dependent value", "description": "Repeated consistent observations are allowed; conflicting values violate the stated rule.", "columns": ["Code", "Observed titles", "Code→title holds in sample?"], "rows": [["DB", "Databases,Databases", "Yes"], ["SQL", "SQL Basics,Querying", "No"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Agreement on a determinant must preserve its dependent value", "description": "Repeated consistent observations are allowed; conflicting values violate the stated rule.", "columns": ["Code", "Observed titles", "Code→title holds in sample?"], "rows": [["DB", "Databases,Databases", "Yes"], ["SQL", "SQL Basics,Querying", "No"]]}]'::jsonb;
