if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-1' and (question_text,options,correct_index,explanation) is distinct from ('Which of the following correctly states what the functional dependency InstructorID -> InstructorOffice means?','["Every office has exactly one instructor assigned to it", "For any given InstructorID value, the InstructorOffice value is always the same, in every valid instance of the table", "InstructorOffice values must be unique across all instructors", "InstructorID can be derived from InstructorOffice"]'::jsonb,1,'X -> Y means X determines Y: knowing InstructorID always tells you the same InstructorOffice value. It says nothing about the reverse direction.') and (question_text,options,correct_index,explanation) is distinct from ('What does X determines Y require?','["Every X value occurs only once", "Rows agreeing on X agree on Y", "Y always determines X", "X is physically indexed"]'::jsonb,1,'The dependency constrains value consistency across rows sharing the determinant.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-functional-dependency-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-2' and test_id<>'pt-dbms-sql-21-functional-dependency') then raise exception 'Question ID collision: %', 'tq-dbms-sql-21-functional-dependency-2'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-2' and test_id='pt-dbms-sql-21-functional-dependency') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-21-functional-dependency-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-2' and (question_text,options,correct_index,explanation) is distinct from ('In the sample data, why does CourseID -> InstructorID hold?','["Because every course has a unique CourseName", "Because, under the simplified ''one instructor of record per course'' rule, a given CourseID always maps to the same InstructorID (e.g., C1 always means I1)", "Because InstructorID values are alphabetically ordered", "Because EnrollmentDate depends on CourseID"]'::jsonb,1,'The FD holds because the business rule fixes exactly one instructor per course; every row with CourseID=''C1'' has InstructorID=''I1''.') and (question_text,options,correct_index,explanation) is distinct from ('What is X called?','["The projection order", "The determinant", "The clustered leaf", "The nullable placeholder"]'::jsonb,1,'X supplies the attributes whose agreement forces agreement on Y.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-functional-dependency-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-3' and test_id<>'pt-dbms-sql-21-functional-dependency') then raise exception 'Question ID collision: %', 'tq-dbms-sql-21-functional-dependency-3'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-3' and test_id='pt-dbms-sql-21-functional-dependency') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-21-functional-dependency-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-3' and (question_text,options,correct_index,explanation) is distinct from ('Why does StudentName -> StudentID NOT hold as a functional dependency, even though today''s sample data shows unique names (Asha, Ravi, Kiran)?','["Because StudentName is a numeric column", "Because an FD must hold for every valid instance of the data, and two different students could share the same name in the future, breaking the determination", "Because functional dependencies only apply to primary keys", "Because StudentName is a derived attribute"]'::jsonb,1,'A functional dependency is a permanent schema-level rule, not an accident of the current snapshot; name uniqueness today doesn''t guarantee it always holds, so the FD is invalid.') and (question_text,options,correct_index,explanation) is distinct from ('Does a dependency''s converse automatically hold?','["Yes", "No", "Only for text", "Only if sorted"]'::jsonb,1,'Several determinant values may share one determined value.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-functional-dependency-3'; end if;
