if not exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-4' and test_id='pt-dbms-sql-21-functional-dependency') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-21-functional-dependency-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-4' and (question_text,options,correct_index,explanation) is distinct from ('Which of the following is a trivial functional dependency?','["CourseID -> CourseName", "{StudentID, CourseID} -> StudentID", "InstructorID -> InstructorName", "StudentID -> StudentName"]'::jsonb,1,'{StudentID, CourseID} -> StudentID is trivial because StudentID is already part of the left-hand side (Y is a subset of X) — it holds automatically and adds no new information.') and (question_text,options,correct_index,explanation) is distinct from ('Can repeated identical course-code/title observations obey the dependency?','["No", "Yes", "Only with DISTINCT storage", "Only in an empty table"]'::jsonb,1,'Repeated determinant values are permitted when their determined values agree.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-functional-dependency-4'; end if;
