if not exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-5' and test_id='pt-dbms-sql-21-functional-dependency') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-21-functional-dependency-5'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-5' and (question_text,options,correct_index,explanation) is distinct from ('What is the determinant in the functional dependency {StudentID, CourseID} -> EnrollmentDate?','["EnrollmentDate", "StudentID alone", "{StudentID, CourseID} together, as a composite", "CourseID alone"]'::jsonb,2,'The determinant (the X side) is the whole composite {StudentID, CourseID} — the FD notation treats a multi-attribute left-hand side as a single determinant.') and (question_text,options,correct_index,explanation) is distinct from ('Does a sample without violations prove a future domain rule?','["Yes", "Only with ten rows", "No", "Only if alphabetized"]'::jsonb,2,'A sample can refute a rule but cannot establish every permitted future state.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-functional-dependency-5'; end if;
