if not exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-6' and test_id='pt-dbms-sql-21-functional-dependency') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-21-functional-dependency-6'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-6' and (question_text,options,correct_index,explanation) is distinct from ('Can a functional dependency ever be established just by inspecting three sample rows and finding no contradiction?','["Yes, three rows with no contradiction always prove the FD holds", "No \u2014 sample rows can disprove an FD (by showing a counter-example) but can never fully prove one holds for all future valid instances; that requires understanding the real-world business rule", "Yes, but only if the rows are sorted", "No, functional dependencies can never be verified by data at all"]'::jsonb,1,'FDs are asserted based on business rules that must hold universally; a finite sample can only ever falsify an FD, never conclusively prove it holds forever.') and (question_text,options,correct_index,explanation) is distinct from ('What can change a current-title dependency in a history relation?','["A shorter alias", "Multiple versions per code", "An extra caption", "Output ordering"]'::jsonb,1,'Historical versions can give one code different valid titles at different times.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-functional-dependency-6'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-7' and test_id<>'pt-dbms-sql-21-functional-dependency') then raise exception 'Question ID collision: %', 'tq-dbms-sql-21-functional-dependency-7'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-7' and test_id='pt-dbms-sql-21-functional-dependency') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-21-functional-dependency-7'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-7' and (question_text,options,correct_index,explanation) is distinct from ('If a university later allowed courses to be co-taught by multiple instructors of record, which FD from the running example would break?','["StudentID -> StudentName", "CourseID -> InstructorID (a single CourseID could now map to more than one InstructorID)", "InstructorID -> InstructorOffice", "{StudentID, CourseID} -> EnrollmentDate"]'::jsonb,1,'If a course could have multiple instructors, CourseID would no longer determine a single InstructorID value, invalidating that specific FD and requiring a schema redesign.') and (question_text,options,correct_index,explanation) is distinct from ('When is X determines Y trivial?','["When X has one character", "When Y is contained in X", "When Y is null", "When the relation is indexed"]'::jsonb,1,'Agreement on X already entails agreement on its own subset.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-functional-dependency-7'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-8' and test_id<>'pt-dbms-sql-21-functional-dependency') then raise exception 'Question ID collision: %', 'tq-dbms-sql-21-functional-dependency-8'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-8' and test_id='pt-dbms-sql-21-functional-dependency') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-21-functional-dependency-8'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-functional-dependency-8' and (question_text,options,correct_index,explanation) is distinct from ('Which statement best distinguishes a functional dependency from the redundancy discussed in 21.1?','["They are the same thing under two different names", "A functional dependency is the underlying business rule (X determines Y); redundancy is the physical symptom of storing Y''s value multiple times when that rule is combined with an unrelated composite key", "Functional dependencies only exist in normalized tables", "Redundancy causes functional dependencies, not the other way around"]'::jsonb,1,'The FD is the abstract rule; redundancy is what happens when a table''s key doesn''t match that rule''s determinant, forcing dependent values to be physically duplicated.') and (question_text,options,correct_index,explanation) is distinct from ('What does augmentation do?','["Reverse every dependency", "Add the same attributes to both sides", "Delete all determinants", "Choose a physical index"]'::jsonb,1,'The added agreement preserves the original dependency implication.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-functional-dependency-8'; end if;
