update public.learning_topics set short_description='Build correct SQL group summaries by choosing result grain, WHERE and HAVING populations, NULL measures, empty-group behavior and safe join inputs.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Build correct SQL group summaries by choosing result grain, WHERE and HAVING populations, NULL measures, empty-group behavior and safe join inputs.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for GROUP BY.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-15-group-by' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-15-group-by-application','MCQ Test 2',category,10,10,'Application and scenarios for GROUP BY.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-15-group-by' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-group-by-1','pt-dbms-sql-15-group-by','What does `GROUP BY` do to a result set before aggregates are applied?','["It sorts rows alphabetically", "It partitions rows into buckets sharing the same grouping-column value(s)", "It removes duplicate rows entirely", "It filters rows based on a condition"]'::jsonb,1,'GROUP BY partitions the rows into groups by the specified column(s); aggregate functions then compute one value per group.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-group-by-2','pt-dbms-sql-15-group-by','Given the `orders` table (East: 310, West: 550, North: 200 total amount), what does `SELECT region, SUM(amount) FROM orders GROUP BY region ORDER BY region; ` return?','["A single row with 1060", "Three rows: East 310, North 200, West 550", "Six rows, one per order", "An error because SUM needs HAVING"]'::jsonb,1,'GROUP BY region collapses the six current fixture rows into three groups, with East310, North200 and West550. The projection returns one aggregate row per represented region.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-group-by-3','pt-dbms-sql-15-group-by','Why does `SELECT region, product, SUM(amount) FROM orders GROUP BY region; ` raise an error in PostgreSQL?','["SUM cannot be used with GROUP BY", "product is neither in GROUP BY nor wrapped in an aggregate function", "region must be aggregated too", "GROUP BY requires at least two columns"]'::jsonb,1,'In this grouping, region does not determine product and product is not aggregated, so PostgreSQL cannot choose one product value per region. PostgreSQL has supported functional-dependency exceptions such as grouping by a table’s primary key; the unqualified every-column slogan is too broad.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-group-by-4','pt-dbms-sql-15-group-by','How are NULL values in a grouping column treated by GROUP BY?','["Each NULL forms its own separate group", "All NULLs are excluded from the result", "All NULLs are grouped together into one group", "NULLs cause a runtime error"]'::jsonb,2,'For grouping purposes, all NULL values in a column are treated as equal to each other and collapsed into a single group.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-group-by-5','pt-dbms-sql-15-group-by','What does `SELECT COUNT(*) FROM orders GROUP BY region; ` return if the `orders` table has zero rows?','["One row with COUNT(*) = 0", "Zero rows", "An error", "One row with COUNT(*) = NULL"]'::jsonb,1,'With GROUP BY, an empty table produces zero groups and therefore zero output rows — unlike a plain COUNT(*) with no GROUP BY, which returns one row of 0.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-group-by-6','pt-dbms-sql-15-group-by','In MySQL prior to enabling `ONLY_FULL_GROUP_BY` (its default is now ON since 5.7), what happened if you selected an ungrouped, non-aggregated column?','["An immediate syntax error", "The query ran but returned an arbitrary, unpredictable value for that column per group", "The column was automatically added to GROUP BY", "MySQL never allowed this, ever"]'::jsonb,1,'Older/relaxed MySQL modes permitted this and silently picked one arbitrary row''s value per group, which is why relying on it is dangerous.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-group-by-7','pt-dbms-sql-15-group-by','Which clause conceptually executes GROUP BY relative to WHERE and HAVING?','["GROUP BY runs before WHERE", "GROUP BY runs after WHERE and before HAVING", "GROUP BY and WHERE run simultaneously", "GROUP BY runs after HAVING"]'::jsonb,1,'Logical query processing order is FROM/JOIN -> WHERE -> GROUP BY -> HAVING -> SELECT -> ORDER BY -> LIMIT.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-group-by-8','pt-dbms-sql-15-group-by','If you `GROUP BY id` where `id` is the orders table''s primary key, how many rows end up in each group?','["Exactly one row per group, since id is unique", "All 8 rows in one group", "Zero rows", "It depends on the region"]'::jsonb,0,'Since id is unique per row, grouping by it puts exactly one row in each group — legal, but aggregates become trivial.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-15-group-by-c-new-1','pt-dbms-sql-15-group-by','What is the grain of GROUP BY region?','["One row per represented region", "One row per order", "One row per product always", "One row per SQL token"]'::jsonb,0,'The grouping key defines which source rows combine.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
