insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cp-dbms-sql-total-revenue-by-region',null::text,'Total Revenue by Region','Easy','total-revenue-by-region','Return region, total as SUM(amount) for every represented region, ordered by region. Preserve all original order rows; do not deduplicate equal amounts.

**MySQL dialect.**

```sql
CREATE TABLE orders (
  id INTEGER PRIMARY KEY,
  region TEXT NOT NULL,
  product TEXT NOT NULL,
  amount INTEGER NOT NULL
);
INSERT INTO orders (id, region, product, amount) VALUES
(1, ''North'', ''Widget'', 200),
(2, ''North'', ''Gadget'', 150),
(3, ''South'', ''Widget'', 100),
(4, ''South'', ''Gadget'', 50),
(5, ''North'', ''Widget'', 300),
(6, ''East'', ''Widget'', 400);
```

**Required ordering:** Order by region.

**Edge cases:**
- Equal amounts are separate rows.
- Empty input gives no groups.
- Single region.','[{"input": "INSERT INTO orders (id, region, product, amount) VALUES\n(1, ''North'', ''Widget'', 200),\n(2, ''North'', ''Gadget'', 150),\n(3, ''South'', ''Widget'', 100),\n(4, ''South'', ''Gadget'', 50),\n(5, ''North'', ''Widget'', 300),\n(6, ''East'', ''Widget'', 400);", "output": "region\ttotal\nEast\t400\nNorth\t650\nSouth\t150", "explanation": "Each represented region contributes one group. SUM counts every contributing amount, including equal-valued rows.", "check_sql": ""}]'::jsonb,'[{"seed_sql": "INSERT INTO orders (id, region, product, amount) VALUES\n(1, ''West'', ''Widget'', 500),\n(2, ''West'', ''Gadget'', 200),\n(3, ''East'', ''Widget'', 100),\n(4, ''East'', ''Gadget'', 300);", "expected": "region\ttotal\nEast\t400\nWest\t700", "hidden": true}, {"seed_sql": "", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO orders VALUES(1,''East'',''Widget'',10),(2,''East'',''Widget'',10);", "expected": "region\ttotal\nEast\t20", "hidden": true}]'::jsonb,'[]'::jsonb,'["Group by region and sum every amount."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'Each represented region contributes one group. SUM counts every contributing amount, including equal-valued rows.','{"sql": "SELECT region,SUM(amount) AS total FROM orders GROUP BY region ORDER BY region;"}'::jsonb,'Each represented region contributes one group. SUM counts every contributing amount, including equal-valued rows.',array['sql'],'CREATE TABLE orders (
  id INTEGER PRIMARY KEY,
  region TEXT NOT NULL,
  product TEXT NOT NULL,
  amount INTEGER NOT NULL
);','INSERT INTO orders (id, region, product, amount) VALUES
(1, ''North'', ''Widget'', 200),
(2, ''North'', ''Gadget'', 150),
(3, ''South'', ''Widget'', 100),
(4, ''South'', ''Gadget'', 50),
(5, ''North'', ''Widget'', 300),
(6, ''East'', ''Widget'', 400);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-15-group-by' on conflict(id) do update set description=excluded.description,examples=excluded.examples,test_cases=excluded.test_cases,constraints=excluded.constraints,hints=excluded.hints,editorial=excluded.editorial,solution_code=excluded.solution_code,solution_approach=excluded.solution_approach,updated_at=now() where (dsa_problems.description,dsa_problems.examples,dsa_problems.test_cases,dsa_problems.constraints,dsa_problems.hints,dsa_problems.editorial,dsa_problems.solution_code,dsa_problems.solution_approach) is distinct from (excluded.description,excluded.examples,excluded.test_cases,excluded.constraints,excluded.hints,excluded.editorial,excluded.solution_code,excluded.solution_approach);
