insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-grouping-sets-concept-1','pt-dbms-sql-15-grouping-sets-concept','What does `GROUP BY GROUPING SETS ((region), (product), ())` compute?','["Only a per-region total", "Per-region totals, per-product totals, and a grand total, all in one query", "A per-(region, product) breakdown only", "An error, since GROUPING SETS requires ROLLUP"]'::jsonb,1,'Each set in the list defines one grouping level: (region), (product), and the empty set () for the grand total — all computed together.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-grouping-sets-concept-2','pt-dbms-sql-15-grouping-sets-concept','In the GROUPING SETS result, what does a row with region = NULL and product = ''Widget'' represent?','["An order whose region field is genuinely unknown", "The subtotal for all Widget orders across every region (530)", "A grand total row", "An error row"]'::jsonb,1,'That row comes from the (product) grouping set, which aggregates across all regions for each product — region shows NULL because it wasn''t part of that grouping level, and the Widget total is 530.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-grouping-sets-concept-3','pt-dbms-sql-15-grouping-sets-concept','What does the empty grouping set `()` represent in GROUPING SETS?','["No output at all", "The grand total across all rows, with every grouping column shown as NULL", "A syntax error", "The same as GROUP BY with no columns, which is disallowed"]'::jsonb,1,'() is a valid grouping set representing zero grouping columns — i.e., one row aggregating the entire table, the grand total (1060 here).',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
