if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-hash-index-6' and (question_text,options,correct_index,explanation) is distinct from ('What must a hash index''s implementation handle when two different values hash to the same bucket?','["Nothing; this situation is impossible by design", "Hash collisions, typically via chaining within a bucket", "The database automatically drops one of the values", "The table becomes locked permanently"]'::jsonb,1,'Collisions are a normal part of hashing and are handled internally (e.g., via chained entries within a bucket).') and (question_text,options,correct_index,explanation) is distinct from ('What must a hash index''s implementation handle when two different values hash to the same bucket?','["Nothing; this situation is impossible by design", "Hash collisions, typically via chaining within a bucket", "The database automatically drops one of the values", "The table becomes locked permanently"]'::jsonb,1,'Collisions are a normal part of hashing and are handled internally (e.g., via chained entries within a bucket).')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-hash-index-6'; end if;
