insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-hash-index-4','pt-dbms-sql-20-hash-index','Why can''t a hash index support `ORDER BY` on the indexed column?','["ORDER BY is not valid SQL syntax", "The hash function scrambles values so that similar values do not end up stored near each other", "Hash indexes do not allow duplicate values", "Hash indexes are always slower than B+ Trees"]'::jsonb,1,'Since hashing intentionally destroys any relationship between nearby values, there''s no way to derive sorted order from bucket positions.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
