insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-having-1','pt-dbms-sql-15-having','What does HAVING filter?','["Individual rows before grouping", "Groups, after aggregation has been computed", "Columns in the SELECT list", "Tables in a JOIN"]'::jsonb,1,'HAVING filters the aggregated groups produced by GROUP BY, evaluated after aggregate values are computed.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-having-2','pt-dbms-sql-15-having','Given per-region totals East=310, North=200, West=550, what does `... GROUP BY region HAVING SUM(amount) > 400` return?','["All three regions", "Only West", "Only East and West", "No rows"]'::jsonb,1,'Only West''s total (550) exceeds 400; East (310) and North (200) do not.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-having-3','pt-dbms-sql-15-having','Why can HAVING reference `SUM(amount)` directly while WHERE cannot?','["HAVING is just a synonym for WHERE", "HAVING runs after aggregation, when per-group aggregate values already exist; WHERE runs before grouping, when they don''t yet exist", "SUM() is disallowed in WHERE due to a syntax restriction with no logical reason", "WHERE can actually reference SUM() too"]'::jsonb,1,'At the point WHERE executes, rows haven''t been grouped or aggregated yet, so aggregate values don''t exist; HAVING executes after aggregation.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-having-4','pt-dbms-sql-15-having','East has count 3 and average 103.33; North has count 2 and average 100; West has count 3 and average 183.33. Which region fails HAVING COUNT(*) > 2 AND AVG(amount) > 100?','["East only", "West only", "North only", "All three fail"]'::jsonb,2,'North has COUNT(*) = 2, which fails the COUNT(*) > 2 condition, so it''s excluded even though its AVG (100.00) is not > 100 either.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-having-5','pt-dbms-sql-15-having','What does `SELECT SUM(amount) FROM orders HAVING SUM(amount) > 5000;` return, given the total of all orders is 1060?','["A row showing 1060", "Zero rows", "An error, since GROUP BY is missing", "A row showing 5000"]'::jsonb,1,'Without GROUP BY, HAVING treats the entire table as one implicit group. Since 1060 is not greater than 5000, that single group is filtered out, leaving zero rows.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-having-6','pt-dbms-sql-15-having','Is `SELECT region, product, SUM(amount) FROM orders GROUP BY region HAVING product = ''Widget''` valid in PostgreSQL?','["Yes, HAVING can reference any column freely", "No — product is neither grouped nor aggregated, so it can''t appear in SELECT or HAVING", "Yes, because HAVING implicitly aggregates it", "No, because HAVING cannot use equality comparisons"]'::jsonb,1,'The same GROUP BY column rule applies inside HAVING: an ungrouped, non-aggregated column like product cannot be referenced.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-having-7','pt-dbms-sql-15-having','For a valid query grouped by region, which predicates may appear in HAVING?','["SUM(amount) > 100 only", "region = ''West'' only", "Both SUM(amount) > 100 and a grouped-key condition region = West", "Neither condition"]'::jsonb,2,'Both the aggregate predicate and grouped-key predicate can be legal. A key-only condition can often be expressed in WHERE, and an optimizer may push a safe condition down; no measured performance claim follows merely from clause placement.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-having-8','pt-dbms-sql-15-having','In MySQL 8.4, can HAVING total_amount > 400 refer to SELECT SUM(amount) AS total_amount?','["Never — aliases are always rejected in HAVING", "Yes, MySQL permits this alias reference; PostgreSQL does not permit the same SELECT alias in HAVING", "Only in HAVING, never in WHERE, for any database", "Only if the alias is quoted"]'::jsonb,1,'MySQL allows SELECT-list aliases in HAVING. PostgreSQL requires repeating the aggregate expression or using an outer query. Preserve dialect distinctions instead of assuming the same alias rule.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
