update public.learning_topics set short_description='Interpret index cardinality as an estimated distinct-key count, distinguish it from selectivity and result size, and reason about skew, composite prefixes and statistics.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Interpret index cardinality as an estimated distinct-key count, distinguish it from selectivity and result size, and reason about skew, composite prefixes and statistics.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Cardinality.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-20-index-cardinality' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-20-index-cardinality-application','MCQ Test 2',category,10,10,'Application and scenarios for Cardinality.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-20-index-cardinality' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-index-cardinality-1','pt-dbms-sql-20-index-cardinality','What does an index-cardinality statistic describe in this discussion?','["The total number of rows in the table", "An estimated distinct-key count for the relevant indexed column or composite prefix", "The shape of a relationship (1:1, 1:N, M:N) between two entities", "The estimated row count produced by a join"]'::jsonb,1,'Associate the count with the indexed key prefix and distinguish metadata estimates from exact counts.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-index-cardinality-2','pt-dbms-sql-20-index-cardinality','How does table row cardinality differ from index distinct-key cardinality?','["They are exactly the same concept with different names", "Table cardinality counts rows; index cardinality describes distinct values of the relevant key or prefix", "Index cardinality only applies to primary keys", "Table row count can only describe a clustered primary index"]'::jsonb,1,'These are genuinely different measurements that happen to share the word ''cardinality'' — row count vs. distinct-value count.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-index-cardinality-3','pt-dbms-sql-20-index-cardinality','Define a distinctness ratio as distinct key count divided by table row count. Which formula computes that explicitly defined ratio?','["Distinctness ratio = index cardinality / total row count", "Index cardinality = selectivity / total number of rows", "They are unrelated and computed independently", "Selectivity = index cardinality squared"]'::jsonb,0,'This D/N distinctness ratio is not the qualifying-row fraction of a particular predicate. Predicate selectivity also depends on the value distribution and condition.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-index-cardinality-4','pt-dbms-sql-20-index-cardinality','A million-row non-NULL boolean column contains both TRUE and FALSE. How many distinct values are observed?','["1,000,000", "500,000", "2", "0"]'::jsonb,2,'Under the stated fixture both boolean values occur,so the exact distinct count is two. A boolean column need not contain both values in every dataset.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-index-cardinality-5','pt-dbms-sql-20-index-cardinality','For roughly uniform equality lookups, why can a high distinct-key count relative to row count be useful?','["Because high cardinality guarantees fast writes", "It suggests relatively few matches per key on average,which can make a key-directed lookup useful", "Because high cardinality columns can never contain NULLs", "Because it means the column is the primary key automatically"]'::jsonb,1,'This is an average under the stated distribution assumption. Skew,broad ranges and other workload costs can change the conclusion.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-index-cardinality-6','pt-dbms-sql-20-index-cardinality','A distinctness ratio is defined as D/N. D remains1000 while N grows from1000 to one billion. What happens to that defined ratio?','["Selectivity stays 1.0 regardless of table size", "It drops from1 to0.000001", "Selectivity becomes undefined", "Cardinality and selectivity are unrelated so nothing changes about selectivity"]'::jsonb,1,'The D/N ratio decreases as row count grows with fixed distinct count. This does not alone determine a particular predicate''s match fraction.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-index-cardinality-7','pt-dbms-sql-20-index-cardinality','Why does the query optimizer need to know a column''s cardinality?','["To decide the table''s column order in CREATE TABLE", "To estimate how many rows a filter on that column will likely return, informing whether using an index is worthwhile", "To determine the table''s clustered index automatically without any configuration", "Cardinality is purely academic and optimizers never use it"]'::jsonb,1,'Distinct-key counts contribute to average equality-match estimates; value frequencies, skew, predicates and other statistics refine the estimate. Cardinality alone does not determine every predicate selectivity.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-index-cardinality-8','pt-dbms-sql-20-index-cardinality','Why can stale cardinality statistics cause problems for the query optimizer?','["Stale statistics have no effect on optimizer decisions", "If cardinality has drifted since statistics were last computed (e.g., via ANALYZE), the optimizer may make poor indexing/scan decisions based on outdated information", "Stale statistics automatically trigger a full table rebuild", "The database refuses to run any queries until statistics are refreshed"]'::jsonb,1,'Cardinality can drift as data changes; if the optimizer''s stored statistics aren''t refreshed (e.g., via ANALYZE), its cost-based decisions can become inaccurate.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-20-index-cardinality-new-9','pt-dbms-sql-20-index-cardinality','Why can case-sensitive and case-insensitive text comparisons produce different exact distinct-label counts?','["Index names change every value", "The comparison collation can treat differently cased labels as different or equal", "COUNT always ignores text", "Case changes table row count"]'::jsonb,1,'Distinctness follows the expression''s comparison rules,including collation; document them when case differences matter.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-20-index-cardinality-new-10','pt-dbms-sql-20-index-cardinality','One million rows uniformly distributed over1000 IDs imply what average equality-match count?','["One always", "One million always", "About1000", "Zero"]'::jsonb,2,'The estimate divides rows by distinct IDs under an explicit uniformity assumption.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-20-index-cardinality-application-new-1','pt-dbms-sql-20-index-cardinality-application','Can the same distinct count hide very different value distributions?','["No", "Only for empty tables", "Only when no index exists", "Yes"]'::jsonb,3,'A global diversity count does not describe frequency skew.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-20-index-cardinality-application-new-2','pt-dbms-sql-20-index-cardinality-application','Does a high-cardinality date column guarantee every date-range predicate is selective?','["No", "Yes", "Only when nullable", "Only for yearly reports"]'::jsonb,0,'A broad range can match most rows despite many distinct dates.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-20-index-cardinality-application-new-3','pt-dbms-sql-20-index-cardinality-application','Can one rare value on a low-cardinality status column be selective?','["No", "Yes", "Only if every status is unique", "Only without WHERE"]'::jsonb,1,'The matching fraction depends on the selected value distribution.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-20-index-cardinality-application-new-4','pt-dbms-sql-20-index-cardinality-application','What should accompany a reported selectivity number?','["Only an alias", "Only a page title", "Its convention and qualifying population", "Only the index name"]'::jsonb,2,'Terminology can use different conventions,so state what the fraction means.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-20-index-cardinality-application-new-5','pt-dbms-sql-20-index-cardinality-application','For a composite index, what can a later key-part Cardinality estimate describe?','["Only the standalone final column always", "The total number of all indexes", "The number of source tables", "Distinct values of the corresponding leading key prefix"]'::jsonb,3,'Read key sequence and column metadata together.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-20-index-cardinality-application-new-6','pt-dbms-sql-20-index-cardinality-application','Is the observed distinct campus-learner pair count necessarily the product of separate counts?','["No", "Yes,always", "Only when both are integers", "Only with aliases"]'::jsonb,0,'Observed dependencies and missing combinations matter.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
