insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-20-index-cardinality-application-new-10','pt-dbms-sql-20-index-cardinality-application','Which comparison exposes skew while preserving the same distinct count?','["Uniform and highly uneven frequency populations using the same labels", "Two different alias names", "Only empty tables", "Two Markdown titles"]'::jsonb,0,'The label count stays fixed while per-value match counts change.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
-- index-maintenance
select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-20-indexes-and-access-paths/index-maintenance' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'index-maintenance'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'index-maintenance'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('9e2038521bd6ea92c0bc2a4e911e2b2d','7eb6fb11067efdaf0e70accd8f061b3c')) then raise exception 'Notes changed since seed; review before applying: %', 'index-maintenance'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-20-index-maintenance' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'index-maintenance'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-20-index-maintenance' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'index-maintenance'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-20-index-maintenance','pt-dbms-sql-20-index-maintenance-application')) then raise exception 'Extra topic tests require manual integration: %', 'index-maintenance'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-20-index-maintenance-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'index-maintenance'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Match maintenance actions to observed problems", "description": "Different symptoms call for different investigations rather than a universal rebuild.", "columns": ["Observation", "Investigate first", "Do not assume"], "rows": [["Poor estimated cardinality", "Statistics and data skew", "Every index is fragmented"], ["Slow monthly report", "Query population and plan", "A rebuild is automatically the remedy"], ["Zero observed usage", "Window instrumentation constraints", "Safe deletion"], ["Large allocated file", "Reuse and measured storage need", "Immediate harmful fragmentation"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'index-maintenance'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Match maintenance actions to observed problems", "description": "Different symptoms call for different investigations rather than a universal rebuild.", "columns": ["Observation", "Investigate first", "Do not assume"], "rows": [["Poor estimated cardinality", "Statistics and data skew", "Every index is fragmented"], ["Slow monthly report", "Query population and plan", "A rebuild is automatically the remedy"], ["Zero observed usage", "Window instrumentation constraints", "Safe deletion"], ["Large allocated file", "Reuse and measured storage need", "Immediate harmful fragmentation"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Match maintenance actions to observed problems", "description": "Different symptoms call for different investigations rather than a universal rebuild.", "columns": ["Observation", "Investigate first", "Do not assume"], "rows": [["Poor estimated cardinality", "Statistics and data skew", "Every index is fragmented"], ["Slow monthly report", "Query population and plan", "A rebuild is automatically the remedy"], ["Zero observed usage", "Window instrumentation constraints", "Safe deletion"], ["Large allocated file", "Reuse and measured storage need", "Immediate harmful fragmentation"]]}]'::jsonb;
if exists(select 1 from public.test_questions where test_id='pt-dbms-sql-20-index-maintenance' and id not in ('tq-dbms-sql-20-index-maintenance-1','tq-dbms-sql-20-index-maintenance-2','tq-dbms-sql-20-index-maintenance-3','tq-dbms-sql-20-index-maintenance-4','tq-dbms-sql-20-index-maintenance-5','tq-dbms-sql-20-index-maintenance-6','tq-dbms-sql-20-index-maintenance-7','tq-dbms-sql-20-index-maintenance-8','pt-dbms-sql-20-index-maintenance-new-9','pt-dbms-sql-20-index-maintenance-new-10')) then raise exception 'Unexpected questions require review: %', 'pt-dbms-sql-20-index-maintenance'; end if;
if exists(select 1 from public.test_questions where test_id='pt-dbms-sql-20-index-maintenance' and marks<>1) then raise exception 'Custom question marks require review: %', 'pt-dbms-sql-20-index-maintenance'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-index-maintenance-1' and test_id<>'pt-dbms-sql-20-index-maintenance') then raise exception 'Question ID collision: %', 'tq-dbms-sql-20-index-maintenance-1'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-20-index-maintenance-1' and test_id='pt-dbms-sql-20-index-maintenance') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-20-index-maintenance-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-index-maintenance-1' and (question_text,options,correct_index,explanation) is distinct from ('When a row is inserted into a table with 3 non-clustered indexes plus a clustered index, how many structures typically need updating?','["Just the table itself, no indexes", "Only 1 structure, whichever is queried most", "All 4 structures \u2014 the clustered index/table plus each of the 3 non-clustered indexes", "Exactly 2, chosen at random"]'::jsonb,2,'Every relevant index (plus the clustered index/table itself) must reflect the new row, so all 4 structures need updating.') and (question_text,options,correct_index,explanation) is distinct from ('What should drive index maintenance?','["A universal daily rebuild rule", "Only index age", "Observed workload needs", "Only its name"]'::jsonb,2,'Maintenance should address a measured symptom and verified dependencies.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-index-maintenance-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-index-maintenance-2' and test_id<>'pt-dbms-sql-20-index-maintenance') then raise exception 'Question ID collision: %', 'tq-dbms-sql-20-index-maintenance-2'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-20-index-maintenance-2' and test_id='pt-dbms-sql-20-index-maintenance') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-20-index-maintenance-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-index-maintenance-2' and (question_text,options,correct_index,explanation) is distinct from ('Why does adding more indexes to a table increase the cost of writes?','["It doesn''t; indexes have zero write cost", "Because each additional index is a separate structure that must also be updated on every relevant INSERT/UPDATE/DELETE", "Because more indexes reduce the table''s storage capacity to zero", "Because indexes convert all writes into reads"]'::jsonb,1,'Every index the write touches must be kept in sync, so more indexes directly means more work per write.') and (question_text,options,correct_index,explanation) is distinct from ('What can an index do besides speed SELECT?','["Authenticate every user", "Enforce uniqueness", "Replace all table constraints", "Guarantee no locking"]'::jsonb,1,'Constraint responsibility can remain important even without observed read usage.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-index-maintenance-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-index-maintenance-3' and test_id<>'pt-dbms-sql-20-index-maintenance') then raise exception 'Question ID collision: %', 'tq-dbms-sql-20-index-maintenance-3'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-20-index-maintenance-3' and test_id='pt-dbms-sql-20-index-maintenance') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-20-index-maintenance-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-index-maintenance-3' and (question_text,options,correct_index,explanation) is distinct from ('What is index fragmentation?','["A security vulnerability unique to hash indexes", "The gradual degradation of an index''s physical layout efficiency due to ongoing inserts, updates, and deletes", "A type of index that only covers half the columns", "An error that occurs when a query has no WHERE clause"]'::jsonb,1,'Fragmentation refers to the index''s physical storage becoming less optimally organized over time as data changes accumulate.') and (question_text,options,correct_index,explanation) is distinct from ('What does SHOW INDEX provide?','["Complete caller behavior", "Existing index metadata", "A production benchmark", "Every future query"]'::jsonb,1,'Definitions are useful evidence but must be combined with workload and constraint tracing.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-index-maintenance-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-index-maintenance-4' and test_id<>'pt-dbms-sql-20-index-maintenance') then raise exception 'Question ID collision: %', 'tq-dbms-sql-20-index-maintenance-4'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-20-index-maintenance-4' and test_id='pt-dbms-sql-20-index-maintenance') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-20-index-maintenance-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-index-maintenance-4' and (question_text,options,correct_index,explanation) is distinct from ('What operation do database administrators run to fix a fragmented index?','["DROP TABLE", "A rebuild/reorganize operation (e.g., REINDEX or ALTER INDEX REBUILD)", "SELECT * FROM the table", "Disabling all foreign keys"]'::jsonb,1,'Rebuild/reorganize commands restore an index''s efficient physical layout after it has become fragmented.') and (question_text,options,correct_index,explanation) is distinct from ('What increases ongoing write work?','["Only renaming aliases", "Maintaining relevant index entries", "Only reading comments", "Only changing page titles"]'::jsonb,1,'Writes must update indexed representations affected by the changed values.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-index-maintenance-4'; end if;
