insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-intersect-1','pt-dbms-sql-18-intersect','What does INTERSECT return?','["Rows in either query", "Rows present in BOTH queries", "Rows in the first query only", "All rows from both queries including duplicates"]'::jsonb,1,'INTERSECT returns exactly the overlap between two result sets.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-intersect-2','pt-dbms-sql-18-intersect','In the running example, what does INTERSECT return?','["1, 4", "2, 3", "1, 2, 3, 4, 5", "5 only"]'::jsonb,1,'Students 2 and 3 are the only ones enrolled in both 2025 and 2026.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-intersect-3','pt-dbms-sql-18-intersect','Since which MySQL version has native INTERSECT support been available?','["MySQL has never supported INTERSECT natively", "MySQL 8.0.31 (2022)", "MySQL 5.7", "MySQL 4.0"]'::jsonb,1,'Native INTERSECT/EXCEPT support was added to MySQL relatively recently, in 8.0.31.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-intersect-4','pt-dbms-sql-18-intersect','On older MySQL versions lacking native INTERSECT, which approach can implement distinct nonnull single-column intersection with appropriate output deduplication?','["There is no workaround; it''s simply impossible", "SELECT DISTINCT from one source with a matching IN subquery, under the stated nonnull identity contract", "Using UNION instead, which behaves identically", "Using CROSS JOIN"]'::jsonb,1,'IN can supply membership, but DISTINCT is needed for set multiplicity and nullable inputs need a deliberate null-matching policy to reproduce full set semantics.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-intersect-5','pt-dbms-sql-18-intersect','Does INTERSECT remove duplicate rows from its result by default?','["No, it preserves all duplicates", "Yes — like UNION, INTERSECT deduplicates by default, following set semantics", "Only if ORDER BY is used", "INTERSECT cannot produce duplicates in any case"]'::jsonb,1,'Default set semantics apply consistently across UNION, INTERSECT, and EXCEPT.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-intersect-6','pt-dbms-sql-18-intersect','What requirement do the two queries combined with INTERSECT share with UNION?','["They must be union-compatible: same column count, compatible types", "They must both include a WHERE clause", "They must query the same table", "There is no shared requirement"]'::jsonb,0,'Union-compatibility applies uniformly across all the set operations in this chapter.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-intersect-7','pt-dbms-sql-18-intersect','Why might explicit parentheses matter when chaining INTERSECT with UNION/EXCEPT in one statement?','["Parentheses have no effect on set operation queries", "Without them, precedence/grouping ambiguity can make it unclear which operations combine first", "INTERSECT cannot be combined with other set operations under any circumstances", "Parentheses are required syntax and their absence always causes an error"]'::jsonb,1,'Clarifying grouping with parentheses avoids ambiguity when multiple set operations are chained together.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-intersect-8','pt-dbms-sql-18-intersect','Which relational-algebra operation corresponds to distinct rows common to both compatible inputs?','["Projection alone", "Intersection", "Cartesian product", "Difference"]'::jsonb,1,'Intersection keeps the compatible rows present in both inputs. SQL duplicate and NULL comparison rules must still be interpreted explicitly.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-intersect-fundamentals-9','pt-dbms-sql-18-intersect','The first input contains 2 three times and the second contains 2 twice. How many 2 rows does plain INTERSECT return?','["1", "2", "3", "6"]'::jsonb,0,'Plain INTERSECT removes duplicate shared rows.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-intersect-fundamentals-10','pt-dbms-sql-18-intersect','For the same inputs, how many 2 rows does INTERSECT ALL return?','["1", "2", "3", "6"]'::jsonb,1,'ALL retains the smaller occurrence count.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
