insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-is-null-4','pt-dbms-sql-12-is-null','How can LEFT JOIN identify no qualifying right-side match?','["Test any optional right note", "Test a guaranteed-present matched right identifier for NULL", "Require a right status in WHERE without considering unmatched rows", "Test only the left key"]'::jsonb,1,'A reliable marker distinguishes real and NULL-extended rows.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
