insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-fundamentals-1','cx-isolation-level-lab-fundamentals','What does a SQL isolation level help define?','["Permitted interactions and observations between concurrent transactions", "Whether all queries use one physical connection", "Whether application inputs are authorized", "The spelling of table names"]'::jsonb,0,'Isolation constrains concurrent behavior, while other correctness boundaries remain separate.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-fundamentals-2','cx-isolation-level-lab-fundamentals','Which lab setup is necessary for an interleaving experiment?','["Two aliases in one SELECT only", "Two independently controlled connections", "Two comments in one connection", "Two identical backups"]'::jsonb,1,'Separate connections allow one transaction to remain open while another acts.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-fundamentals-3','cx-isolation-level-lab-fundamentals','When should the lab choose the next transaction isolation level?','["After its final COMMIT only", "Inside an unrelated result caption", "Before starting that transaction", "Only after dropping the table"]'::jsonb,2,'The transaction context must have the intended setting when it begins.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
