insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-fundamentals-5','cx-isolation-level-lab-fundamentals','B commits a change between A reads under READ COMMITTED. What can occur?','["A non-repeatable read", "A dirty read by definition", "Automatic distributed commit", "A missing primary key by definition"]'::jsonb,0,'The new observation is committed but differs from A’s earlier observation.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-fundamentals-6','cx-isolation-level-lab-fundamentals','What usually establishes an InnoDB REPEATABLE READ consistent-read snapshot?','["The name of the transaction variable", "The first ordinary consistent read in the transaction", "Any client comment", "Every COMMIT on another connection"]'::jsonb,1,'With ordinary transaction start semantics, first consistent-read timing matters.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-fundamentals-7','cx-isolation-level-lab-fundamentals','Can a REPEATABLE READ transaction observe its own writes?','["No, never", "Only after its connection closes", "Yes", "Only through a replica"]'::jsonb,2,'Own changes are visible even though other consistent reads use a snapshot.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-fundamentals-8','cx-isolation-level-lab-fundamentals','What distinguishes a locking read from an ordinary snapshot read?','["It always reads a backup", "It cannot wait", "It always ignores own writes", "It requests relevant locks and uses current-read behavior"]'::jsonb,3,'The two operations need separate visibility and blocking reasoning.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-fundamentals-9','cx-isolation-level-lab-fundamentals','What is a phantom observation about?','["Changes to rows satisfying a predicate across observations", "Any changed column alias", "A database file disappearing", "Only a lost connection"]'::jsonb,0,'Predicate membership is the relevant observation, rather than only one row value.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-fundamentals-10','cx-isolation-level-lab-fundamentals','Does a stable snapshot prove that the SELECT locked every matching gap?','["Yes, always", "No", "Only when the result is empty", "Only for text columns"]'::jsonb,1,'Version visibility can preserve results without the locking behavior of a range locking read.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-application-1','cx-isolation-level-lab-application','What makes a dirty read dirty?','["It later rolled back in every case", "The observed change was uncommitted at observation time", "The value was a negative integer", "It came from a large table"]'::jsonb,1,'A later commit does not retroactively make the earlier uncommitted observation clean.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-application-2','cx-isolation-level-lab-application','Does READ UNCOMMITTED eliminate all write locking?','["Yes, for every engine", "Only when a primary key exists", "No", "Only for updates after midnight"]'::jsonb,2,'Relaxed read visibility is not freedom from write conflicts or deadlocks.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-application-3','cx-isolation-level-lab-application','Two on-call workers each leave after observing the other. What rule is endangered?','["Every row must have a different alias", "The database must contain exactly two indexes", "Every read must have LIMIT", "At least one worker must remain on call"]'::jsonb,3,'The cross-row invariant can fail even when the transactions write different rows.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-application-4','cx-isolation-level-lab-application','What makes a guard-row solution work?','["Every relevant decision path locks the same guard before checking the invariant", "Only one path knows the guard exists", "The guard is read after commit", "The guard has a decorative name"]'::jsonb,0,'Coordination requires universal participation by paths enforcing the shared rule.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-application-5','cx-isolation-level-lab-application','What does serializable execution aim to provide?','["Guaranteed absence of waiting", "Results equivalent to some serial execution within its supported model", "Correct external payments automatically", "Unlimited retry success"]'::jsonb,1,'Serial equivalence describes transaction results, not every application reliability concern.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-application-6','cx-isolation-level-lab-application','What must be considered when an engine reports a retryable serialization failure?','["Repeat only an external notification", "Assume the operation already committed", "Repeat the complete logical transaction under a bounded policy", "Ignore all earlier decisions"]'::jsonb,2,'Earlier observations and writes may no longer form a valid attempt.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-application-7','cx-isolation-level-lab-application','Why can session-level isolation changes matter to pooled connections?','["They rename every pooled table", "They automatically clear all locks forever", "They disable prepared statements by definition", "Later borrowers may inherit changed session state"]'::jsonb,3,'Session defaults persist beyond one application request unless deliberately managed.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-level-lab-application-8','cx-isolation-level-lab-application','B rolls back an update before A reads at READ COMMITTED. Which value should A avoid?','["B’s uncommitted replacement", "The prior committed value", "A’s own valid write", "Every value from the primary key"]'::jsonb,0,'The stronger-level read does not expose B’s uncommitted version.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
