if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-isolation-1' and (question_text,options,correct_index,explanation) is distinct from ('What does Isolation guarantee?','["Data is permanently stored", "Concurrent transactions don''t see each other''s uncommitted, intermediate state", "Every transaction runs faster", "All constraints are automatically enforced"]'::jsonb,1,'Isolation controls what one transaction can observe of another''s in-progress work.') and (question_text,options,correct_index,explanation) is distinct from ('What does the transaction isolation contract specify?','["Every query physically runs alone", "Which concurrent interactions and observations are permitted under the chosen level and engine", "Every application input is correct", "All copies immediately have identical values"]'::jsonb,1,'Weaker levels can permit anomalies, including dirty reads at READ UNCOMMITTED. Do not make an unqualified no-intermediate-state promise.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-isolation-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-isolation-2' and test_id<>'pt-dbms-sql-22-isolation') then raise exception 'Question ID collision: %', 'tq-dbms-sql-22-isolation-2'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-22-isolation-2' and test_id='pt-dbms-sql-22-isolation') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-22-isolation-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-isolation-2' and (question_text,options,correct_index,explanation) is distinct from ('Without isolation, what problem could occur if T2 reads while T1 is mid-update?','["T2 would always see a clean, fully consistent snapshot", "T2 could see a confusing mix of some already-updated and some not-yet-updated rows, a state that never really existed", "T2 would be blocked from reading entirely", "T1 would automatically pause until T2 finishes"]'::jsonb,1,'This inconsistent mixed view is exactly what isolation is designed to prevent.') and (question_text,options,correct_index,explanation) is distinct from ('Without isolation, what problem could occur if T2 reads while T1 is mid-update?','["T2 would always see a clean, fully consistent snapshot", "T2 could see a confusing mix of some already-updated and some not-yet-updated rows, a state that never really existed", "T2 would be blocked from reading entirely", "T1 would automatically pause until T2 finishes"]'::jsonb,1,'An insufficient observation contract can expose a mix that never existed as one committed state; precise behavior depends on the engine, read type and level.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-isolation-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-isolation-3' and test_id<>'pt-dbms-sql-22-isolation') then raise exception 'Question ID collision: %', 'tq-dbms-sql-22-isolation-3'; end if;
