if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-isolation-5' and (question_text,options,correct_index,explanation) is distinct from ('Is Isolation the same concern as Atomicity?','["Yes, they are synonyms", "No \u2014 Atomicity is about one transaction''s own all-or-nothing completion; Isolation is about transactions not observing each other''s in-progress state", "Isolation only applies to single-statement transactions", "Atomicity is a stricter version of Isolation"]'::jsonb,1,'These are related but distinct ACID properties addressing different concerns.') and (question_text,options,correct_index,explanation) is distinct from ('Is Isolation the same concern as Atomicity?','["Yes, they are synonyms", "Atomicity concerns supported all-or-nothing completion; isolation specifies permitted concurrent observations under the chosen level and engine.", "Isolation only applies to single-statement transactions", "Atomicity is a stricter version of Isolation"]'::jsonb,1,'Atomicity concerns one supported transaction outcome; isolation concerns concurrent interactions and observations under the selected contract.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-isolation-5'; end if;
