if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-isolation-6' and (question_text,options,correct_index,explanation) is distinct from ('What kinds of anomalies does Isolation (at varying strength) aim to prevent?','["Syntax errors", "Concurrency anomalies like dirty reads, non-repeatable reads, and phantom reads (Chapter 23)", "Disk space exhaustion", "Slow query performance"]'::jsonb,1,'Isolation levels are specifically calibrated against these named concurrency anomalies.') and (question_text,options,correct_index,explanation) is distinct from ('What kinds of anomalies does Isolation (at varying strength) aim to prevent?','["Syntax errors", "Concurrency anomalies like dirty reads, non-repeatable reads, and phantom reads (Chapter 23)", "Disk space exhaustion", "Slow query performance"]'::jsonb,1,'Isolation levels are specifically calibrated against these named concurrency anomalies.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-isolation-6'; end if;
