if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-isolation-7' and (question_text,options,correct_index,explanation) is distinct from ('Does ''isolation'' in ACID refer to operating-system process isolation?','["Yes, they are the same concept", "No \u2014 ACID Isolation is specifically about transaction visibility rules within the database, unrelated to OS/container isolation", "ACID Isolation is implemented using OS process isolation exclusively", "This is an interchangeable term across all contexts"]'::jsonb,1,'Despite the shared word, these are unrelated concepts in different domains.') and (question_text,options,correct_index,explanation) is distinct from ('Does ''isolation'' in ACID refer to operating-system process isolation?','["Yes, they are the same concept", "No \u2014 ACID Isolation is specifically about transaction visibility rules within the database, unrelated to OS/container isolation", "ACID Isolation is implemented using OS process isolation exclusively", "This is an interchangeable term across all contexts"]'::jsonb,1,'Despite the shared word, these are unrelated concepts in different domains.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-isolation-7'; end if;
