if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-isolation-8' and (question_text,options,correct_index,explanation) is distinct from ('From a single transaction''s own point of view under proper isolation, how does concurrent execution appear?','["As if many other transactions are visibly interleaved with it", "As if it were running alone, even though other transactions may be executing concurrently", "As a series of random errors", "Isolation provides no particular appearance guarantee"]'::jsonb,1,'This ''as if alone'' illusion is exactly what isolation aims to provide to each transaction.') and (question_text,options,correct_index,explanation) is distinct from ('At a documented serializable contract, how should supported concurrent results relate to a serial reference?','["All levels allow every dirty read", "They should be equivalent to some permitted serial execution under the engine model", "Every transaction must start at the same instant", "The result must maximize every balance"]'::jsonb,1,'This is a serializable-level statement, not a promise that every weaker isolation level looks as though no other transaction exists.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-isolation-8'; end if;
