insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-isolation-application','MCQ Test 2',category,10,10,'Application and scenarios for Isolation.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-22-isolation' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-isolation-1','pt-dbms-sql-22-isolation','What does the transaction isolation contract specify?','["Every query physically runs alone", "Which concurrent interactions and observations are permitted under the chosen level and engine", "Every application input is correct", "All copies immediately have identical values"]'::jsonb,1,'Weaker levels can permit anomalies, including dirty reads at READ UNCOMMITTED. Do not make an unqualified no-intermediate-state promise.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-isolation-2','pt-dbms-sql-22-isolation','Without isolation, what problem could occur if T2 reads while T1 is mid-update?','["T2 would always see a clean, fully consistent snapshot", "T2 could see a confusing mix of some already-updated and some not-yet-updated rows, a state that never really existed", "T2 would be blocked from reading entirely", "T1 would automatically pause until T2 finishes"]'::jsonb,1,'An insufficient observation contract can expose a mix that never existed as one committed state; precise behavior depends on the engine, read type and level.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-isolation-3','pt-dbms-sql-22-isolation','Does serializable behavior require literally executing every whole transaction one at a time?','["Yes, all independent work must always wait", "No; eligible work can interleave while preserving required serial equivalence, though coordination has workload-dependent costs", "Only on a single table", "Only for read-only queries"]'::jsonb,1,'Serial and serializable are distinct. Stronger guarantees can require blocking or retries without global physical serialization.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-isolation-4','pt-dbms-sql-22-isolation','How do real database systems typically balance isolation strength against performance?','["They always use perfect (fully serial) isolation", "They offer configurable isolation levels (Chapter 25) that trade some isolation strength for better throughput", "They disable isolation entirely by default", "Isolation cannot be configured in any real system"]'::jsonb,1,'Levels provide different contracts. Performance effects depend on workload, plans, contention and implementation, rather than a universal weaker-is-faster guarantee.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-isolation-5','pt-dbms-sql-22-isolation','Is Isolation the same concern as Atomicity?','["Yes, they are synonyms", "Atomicity concerns supported all-or-nothing completion; isolation specifies permitted concurrent observations under the chosen level and engine.", "Isolation only applies to single-statement transactions", "Atomicity is a stricter version of Isolation"]'::jsonb,1,'Atomicity concerns one supported transaction outcome; isolation concerns concurrent interactions and observations under the selected contract.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-isolation-6','pt-dbms-sql-22-isolation','What kinds of anomalies does Isolation (at varying strength) aim to prevent?','["Syntax errors", "Concurrency anomalies like dirty reads, non-repeatable reads, and phantom reads (Chapter 23)", "Disk space exhaustion", "Slow query performance"]'::jsonb,1,'Isolation levels are specifically calibrated against these named concurrency anomalies.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-isolation-7','pt-dbms-sql-22-isolation','Does ''isolation'' in ACID refer to operating-system process isolation?','["Yes, they are the same concept", "No — ACID Isolation is specifically about transaction visibility rules within the database, unrelated to OS/container isolation", "ACID Isolation is implemented using OS process isolation exclusively", "This is an interchangeable term across all contexts"]'::jsonb,1,'Despite the shared word, these are unrelated concepts in different domains.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-isolation-8','pt-dbms-sql-22-isolation','At a documented serializable contract, how should supported concurrent results relate to a serial reference?','["All levels allow every dirty read", "They should be equivalent to some permitted serial execution under the engine model", "Every transaction must start at the same instant", "The result must maximize every balance"]'::jsonb,1,'This is a serializable-level statement, not a promise that every weaker isolation level looks as though no other transaction exists.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-fundamentals-9','pt-dbms-sql-22-isolation','Does transactional support alone prove serializable execution for every query?','["No", "Yes, every level is serializable", "Only with a primary key", "Only for text tables"]'::jsonb,0,'The actual isolation level and statement semantics determine the contract.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-fundamentals-10','pt-dbms-sql-22-isolation','Does an older committed snapshot value necessarily constitute a dirty read?','["Yes, all old data is dirty", "No", "Only if numeric", "Only after an UPDATE"]'::jsonb,1,'Dirty reads concern an uncommitted source, not age alone.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-application-1','cx-isolation-application','Can serializable work physically interleave?','["No, one transaction must always occupy the whole server", "Yes, if required serial equivalence is preserved", "Only if all work aborts", "Only if no rows exist"]'::jsonb,1,'Serializability is an equivalence guarantee, not literal no-overlap scheduling.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-application-2','cx-isolation-application','What does ordinary InnoDB READ COMMITTED generally provide per statement?','["One permanent database-wide snapshot", "Every uncommitted writer value", "A fresh committed snapshot", "Only replica values"]'::jsonb,2,'Later statements can observe newly committed changes.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-application-3','cx-isolation-application','What generally establishes the ordinary REPEATABLE READ snapshot in this context?','["A comment before BEGIN", "Any other connection’s query", "The table filename", "The first consistent read"]'::jsonb,3,'First-read timing matters for snapshot contents.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-application-4','cx-isolation-application','Does a stable snapshot automatically enforce a cross-row on-call invariant?','["No", "Yes, any snapshot is sufficient", "Only if names are unique", "Only if both rows are integers"]'::jsonb,0,'Decision coordination must protect the actual shared rule.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-application-5','cx-isolation-application','What must a reservation inspect after a conditional decrement?','["Only whether SQL parsed", "Whether the required row effect occurred", "Only its output color", "Only the number of comments"]'::jsonb,1,'An unmet predicate can return no changed row without an SQL exception.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-application-6','cx-isolation-application','Do locking reads and ordinary consistent reads necessarily share one visibility context?','["Yes, for every statement", "Only with SELECT star", "No", "Only if sorted"]'::jsonb,2,'InnoDB current locking reads differ from ordinary historical snapshot reads.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-isolation-application-7','cx-isolation-application','What should a retryable aborted operation normally recompute?','["Only a stale replacement value", "Only an external email", "The old snapshot identity", "Its complete logical decision with fresh state"]'::jsonb,3,'Earlier observations may no longer be valid for the new attempt.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
