insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-join-predicate-1','pt-dbms-sql-16-join-predicate','What is a join predicate?','["The list of columns selected", "The condition (after ON) that determines whether two rows count as a match", "A synonym for ORDER BY", "The name given to a joined table"]'::jsonb,1,'The predicate is the actual matching condition driving the join.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-join-predicate-2','pt-dbms-sql-16-join-predicate','Are join predicates limited to equality comparisons?','["Yes, only = is allowed in ON clauses", "No — any boolean condition is valid, including ranges and inequalities, matching the Theta Join concept", "Only BETWEEN and = are allowed", "Join predicates cannot reference more than one column"]'::jsonb,1,'ON conditions support the full generality of Theta Join, not just equality.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-join-predicate-3','pt-dbms-sql-16-join-predicate','For an OUTER join, does putting an extra condition in ON versus WHERE make a difference?','["No difference at all", "Yes — an ON-clause condition filters before NULL-filling the non-preserved side, while a WHERE-clause condition filters after, potentially discarding preserved NULL rows", "WHERE can never be used with outer joins", "ON conditions are always evaluated after WHERE conditions"]'::jsonb,1,'This ON-vs-WHERE timing difference is exactly the subtlety already flagged for LEFT JOIN filtering in earlier chapters.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-join-predicate-4','pt-dbms-sql-16-join-predicate','Can an ON clause reference a later table alias that is not available in its relevant join expression or applicable query scope?','["Yes, always", "No; references must be available in the relevant join expression and applicable query scope", "Only in subqueries", "Only for LEFT JOIN"]'::jsonb,1,'Explicit join binding and query scope determine alias availability; do not assume every later FROM alias is visible.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-join-predicate-5','pt-dbms-sql-16-join-predicate','For an INNER JOIN, what does a nonselective predicate such as ON 1=1 produce?','["The join fails with an error", "It technically works but effectively produces a Cartesian Product, since every row ''matches''", "It automatically becomes a CROSS JOIN keyword", "SQL rejects this as invalid syntax"]'::jsonb,1,'Every pair qualifies for an inner join. Outer joins with an empty opposite input still have their separate preservation semantics.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-join-predicate-6','pt-dbms-sql-16-join-predicate','Can a join predicate combine multiple conditions with AND/OR?','["No, only one condition is allowed", "Yes — exactly like a WHERE clause, multiple conditions can be combined", "Only AND is allowed, never OR", "Combining conditions requires a subquery instead"]'::jsonb,1,'ON clauses support the same compound-condition logic as WHERE.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
