if exists(select 1 from public.test_questions where id='tq-dbms-sql-13-keyset-pagination-2' and (question_text,options,correct_index,explanation) is distinct from ('What does a keyset pagination query use instead of OFFSET to find the next page?','["A random sample of rows", "A WHERE condition comparing the sort column to the last-seen row''s value", "A subquery that counts all prior rows", "A second LIMIT clause"]'::jsonb,1,'Keyset pagination remembers the last row''s sort-key value and filters with WHERE sort_col > last_seen_value to fetch the next page.') and (question_text,options,correct_index,explanation) is distinct from ('What determines the next page in keyset pagination?','["An arbitrary physical row address", "A comparison against the last displayed ordering tuple", "The number of table columns", "An implicit random seed"]'::jsonb,1,'The boundary follows the declared result order.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-13-keyset-pagination-2'; end if;
