if exists(select 1 from public.test_questions where id='tq-dbms-sql-13-keyset-pagination-3' and (question_text,options,correct_index,explanation) is distinct from ('Why can keyset pagination be significantly faster than OFFSET-based pagination on large tables and deep pages?','["It avoids sorting the data entirely", "It can use an index seek to jump directly past already-seen rows instead of scanning and discarding them", "It caches all pages in memory automatically", "It replaces LIMIT with a faster keyword"]'::jsonb,1,'The WHERE-based seek lets the engine use an index to jump straight to the right position, whereas OFFSET must scan and discard every skipped row.') and (question_text,options,correct_index,explanation) is distinct from ('Why can a suitable keyset query improve deep-page performance?','["Every such query skips all sorting automatically", "Its boundary can support indexed range access", "It caches all future pages automatically", "It removes the need for filtering"]'::jsonb,1,'An indexed range can avoid repeated positional-prefix work; the actual plan still requires measurement.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-13-keyset-pagination-3'; end if;
