update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Keyset Pagination.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-13-keyset-pagination' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
