insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-keyset-pagination-1','pt-dbms-sql-13-keyset-pagination','Which name also describes keyset pagination?','["The seek method", "Random sampling", "Whole-table counting", "Implicit grouping"]'::jsonb,0,'Continuation seeks past a remembered ordering boundary.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-keyset-pagination-2','pt-dbms-sql-13-keyset-pagination','What determines the next page in keyset pagination?','["An arbitrary physical row address", "A comparison against the last displayed ordering tuple", "The number of table columns", "An implicit random seed"]'::jsonb,1,'The boundary follows the declared result order.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-keyset-pagination-3','pt-dbms-sql-13-keyset-pagination','Why can a suitable keyset query improve deep-page performance?','["Every such query skips all sorting automatically", "Its boundary can support indexed range access", "It caches all future pages automatically", "It removes the need for filtering"]'::jsonb,1,'An indexed range can avoid repeated positional-prefix work; the actual plan still requires measurement.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-keyset-pagination-4','pt-dbms-sql-13-keyset-pagination','What does a cursor alone fail to provide for arbitrary page-number jumps?','["Any bounded result", "An independently known boundary for the requested page", "A way to use WHERE", "A way to order rows"]'::jsonb,1,'Sequential continuation starts from known values rather than an arbitrary numeric position.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-keyset-pagination-5','pt-dbms-sql-13-keyset-pagination','How should an ascending nonunique price order be completed?','["Ignore equal-price rows", "Add a unique result-grain key to both ordering and continuation", "Apply DISTINCT to price only", "Always restart from the first price"]'::jsonb,1,'A complete ordering tuple distinguishes identities within a tie.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-keyset-pagination-6','pt-dbms-sql-13-keyset-pagination','What usually supports the seek method''s intended access benefit?','["Disabling all indexes", "An appropriate index aligned with relevant filters and order", "Allowing NULL in every key", "Returning every column necessarily"]'::jsonb,1,'Index design provides an access opportunity, not a universal plan guarantee.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
