insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-keyset-pagination-8','pt-dbms-sql-13-keyset-pagination','Which interaction often fits forward keyset navigation?','["Mandatory direct access to every page number", "Sequential load-more browsing", "Random selection without ordering", "Editing table definitions"]'::jsonb,1,'The interaction naturally supplies a prior boundary; actual performance still depends on the plan.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-keyset-pagination-new-9','pt-dbms-sql-13-keyset-pagination','Why does id >= cursor_id usually repeat a row?','["It includes the boundary identity", "It reverses every order", "It ignores the WHERE clause", "It changes the primary key"]'::jsonb,0,'Continuation normally excludes the last displayed tuple.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
