insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-keyset-pagination-application-new-1','pt-dbms-sql-13-keyset-pagination-application','For score DESC, id ASC after (80,4), which predicate continues correctly?','["score > 80 OR id > 4", "score < 80 OR (score = 80 AND id > 4)", "score < 80 AND id > 4", "score = 80 AND id < 4"]'::jsonb,1,'Later scores are lower; within the boundary score later identifiers are greater.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-keyset-pagination-application-new-2','pt-dbms-sql-13-keyset-pagination-application','Why enclose the OR continuation branches when adding status=''active''?','["Parentheses make indexes unnecessary", "To reverse the score order", "To apply eligibility to both continuation routes", "To force every score to equal the cursor"]'::jsonb,2,'AND has higher precedence than OR, so grouping preserves the requested population.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
