insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cp-dbms-sql-every-employee-department-or-not',null::text,'Every Employee, Department or Not','Easy','every-employee-department-or-not','Write a query returning `id`, `name` (employee), and `department` for EVERY employee, showing `NULL` for employees with no department, ordered by employee `id`.

**MySQL dialect.**

```sql
CREATE TABLE departments (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL
);
CREATE TABLE employees (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  department_id INTEGER,
  manager_id INTEGER,
  salary INTEGER NOT NULL
);
INSERT INTO departments (id, name) VALUES (1, ''Engineering''), (2, ''Sales''), (3, ''Marketing'');
INSERT INTO employees (id, name, department_id, manager_id, salary) VALUES
(1, ''Asha'', 1, NULL, 90000),
(2, ''Rohan'', 1, 1, 70000),
(3, ''Neha'', 2, 1, 65000),
(4, ''Vikram'', NULL, 1, 50000);
```

**Required ordering:** Use the explicit ORDER BY required by the task.

**Edge cases:**
- Empty input.
- Different valid fixture.
- Repeated contributing values.','[{"input": "INSERT INTO departments (id, name) VALUES (1, ''Engineering''), (2, ''Sales''), (3, ''Marketing'');\nINSERT INTO employees (id, name, department_id, manager_id, salary) VALUES\n(1, ''Asha'', 1, NULL, 90000),\n(2, ''Rohan'', 1, 1, 70000),\n(3, ''Neha'', 2, 1, 65000),\n(4, ''Vikram'', NULL, 1, 50000);", "output": "id\tname\tdepartment\n1\tAsha\tEngineering\n2\tRohan\tEngineering\n3\tNeha\tSales\n4\tVikram\tNULL", "explanation": "The query preserves the required source identities and evaluates the requested operation on all eligible fixture rows.", "check_sql": ""}]'::jsonb,'[{"seed_sql": "INSERT INTO departments (id, name) VALUES (10, ''Finance''), (20, ''Legal''), (30, ''HR'');\nINSERT INTO employees (id, name, department_id, manager_id, salary) VALUES\n(1, ''Zara'', 10, NULL, 95000),\n(2, ''Omar'', 10, 1, 60000),\n(3, ''Leo'', NULL, 1, 40000);", "expected": "id\tname\tdepartment\n1\tZara\tFinance\n2\tOmar\tFinance\n3\tLeo\tNULL", "hidden": true}, {"seed_sql": "", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO employees VALUES(9,''Mira'',NULL,NULL,50000);", "expected": "id\tname\tdepartment\n9\tMira\tNULL", "hidden": true}]'::jsonb,'[]'::jsonb,'["Preserve the requested result grain and aliases."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The query preserves the required source identities and evaluates the requested operation on all eligible fixture rows.','{"sql": "SELECT e.id,e.name,d.name AS department FROM employees e LEFT JOIN departments d ON e.department_id=d.id ORDER BY e.id;"}'::jsonb,'The query preserves the required source identities and evaluates the requested operation on all eligible fixture rows.',array['sql'],'CREATE TABLE departments (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL
);
CREATE TABLE employees (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  department_id INTEGER,
  manager_id INTEGER,
  salary INTEGER NOT NULL
);','INSERT INTO departments (id, name) VALUES (1, ''Engineering''), (2, ''Sales''), (3, ''Marketing'');
INSERT INTO employees (id, name, department_id, manager_id, salary) VALUES
(1, ''Asha'', 1, NULL, 90000),
(2, ''Rohan'', 1, 1, 70000),
(3, ''Neha'', 2, 1, 65000),
(4, ''Vikram'', NULL, 1, 50000);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-16-left-join' on conflict(id) do update set description=excluded.description,examples=excluded.examples,test_cases=excluded.test_cases,constraints=excluded.constraints,hints=excluded.hints,editorial=excluded.editorial,solution_code=excluded.solution_code,solution_approach=excluded.solution_approach,updated_at=now() where (dsa_problems.description,dsa_problems.examples,dsa_problems.test_cases,dsa_problems.constraints,dsa_problems.hints,dsa_problems.editorial,dsa_problems.solution_code,dsa_problems.solution_approach) is distinct from (excluded.description,excluded.examples,excluded.test_cases,excluded.constraints,excluded.hints,excluded.editorial,excluded.solution_code,excluded.solution_approach);
