insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-limit-1','pt-dbms-sql-13-limit','What does LIMIT specify in a MySQL SELECT?','["A required exact row count", "A maximum number of returned rows", "A sort direction", "A row authorization rule"]'::jsonb,1,'It bounds output without defining eligibility or ranking.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-limit-2','pt-dbms-sql-13-limit','Without ORDER BY, does LIMIT 3 guarantee the same three identities in the same sequence?','["Yes, always by primary key", "Yes, always newest first", "No", "Only if the table is small"]'::jsonb,2,'An arbitrary observed access order is not a ranking contract.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-limit-3','pt-dbms-sql-13-limit','Can an unordered LIMIT be useful when any small subset is acceptable?','["No, it is always meaningless", "Only if it returns zero", "Yes", "Only for sorted timestamps"]'::jsonb,2,'It is insufficient for a specific ordered-selection requirement, not universally useless.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-limit-4','pt-dbms-sql-13-limit','Eight rows qualify and LIMIT 1000 is requested. What is returned?','["One thousand padded rows", "The eight qualifying rows", "A row-count error", "No rows"]'::jsonb,1,'The cap is an upper bound.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-limit-5','pt-dbms-sql-13-limit','What is missing from a query intended to show newest requests using only LIMIT 10?','["A second LIMIT", "An explicit appropriate time order and tie policy", "A larger primary key value", "A requirement to return all statuses"]'::jsonb,1,'The cap does not infer newest.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-limit-6','pt-dbms-sql-13-limit','What does LIMIT 0 return?','["Every row", "One row", "Zero result rows", "Always a syntax error"]'::jsonb,2,'Application-specific zero conventions must not be confused with SQL.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-limit-7','pt-dbms-sql-13-limit','Which form selects the cheapest five under a complete known-price order?','["LIMIT 5 alone", "ORDER BY price ASC,id ASC LIMIT 5", "WHERE price>0 LIMIT 5 without order", "ORDER BY id DESC LIMIT 5"]'::jsonb,1,'Ranking and identity ties define the selected prefix.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-limit-8','pt-dbms-sql-13-limit','What should be verified before moving a LIMIT query to another SQL engine?','["That engine’s supported bounded-result syntax and semantics", "Only keyword capitalization", "That every engine uses identical syntax", "That the table has no keys"]'::jsonb,0,'The package uses MySQL forms.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-limit-new-9','pt-dbms-sql-13-limit','Does ordinary LIMIT 3 include all rows tied at the third price?','["No, not automatically", "Yes, always", "Only when price is indexed", "Only if four rows tie"]'::jsonb,0,'An all-rank-ties contract needs different explicit logic.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-limit-new-10','pt-dbms-sql-13-limit','Why is an id not automatically the same as event recency?','["Ids can never be sorted", "Generation or import policy can differ from event time", "Every id is random", "Only timestamps can be indexed"]'::jsonb,1,'Use the authoritative recency property.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
