insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-locking-protocol-lab-application-9','cx-locking-protocol-lab-application','What does the rollback variant of the one-place lab predict?','["The decrement becomes durable", "The original place remains available after A rolls back", "B must always see zero", "Both clients automatically reserve successfully"]'::jsonb,1,'Transactional rollback reverses A’s supported change before B acts on the released resource.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-locking-protocol-lab-application-10','cx-locking-protocol-lab-application','Does a SQLite query fixture prove the InnoDB lab behavior?','["Yes, all SQL engines share locks", "Only when rows are sorted", "No, it does not reproduce InnoDB locking semantics", "Only with integer identifiers"]'::jsonb,2,'Engine-specific concurrency needs independent connections on the intended engine.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
