insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-logical-operators-1','pt-dbms-sql-12-logical-operators','What do AND, OR and NOT operate on in a WHERE condition?','["Only table names", "Predicates and their logical results", "Only sort directions", "Only integer primary keys"]'::jsonb,1,'They combine or negate conditions.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-logical-operators-2','pt-dbms-sql-12-logical-operators','How does a OR b AND c group with keyword precedence?','["(a OR b) AND c", "a OR (b AND c)", "(a OR b) OR c", "It is always invalid SQL"]'::jsonb,1,'AND binds more tightly than OR.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
