insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-logical-operators-4','pt-dbms-sql-12-logical-operators','What is TRUE OR UNKNOWN?','["UNKNOWN", "TRUE", "FALSE", "NULL converted to zero"]'::jsonb,1,'One known true alternative is sufficient.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-logical-operators-5','pt-dbms-sql-12-logical-operators','What is NOT UNKNOWN?','["TRUE", "UNKNOWN", "FALSE", "An empty string"]'::jsonb,1,'Negation does not create knowledge of a missing fact.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-logical-operators-6','pt-dbms-sql-12-logical-operators','How can repeated category equality alternatives be shortened?','["Use BETWEEN for arbitrary names", "Use category IN a list of allowed values", "Use one random category", "Use ORDER BY category"]'::jsonb,1,'Membership expresses repeated equality alternatives on the same operand.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
