if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-lost-update-2' and (question_text,options,correct_index,explanation) is distinct from ('In the interleaved schedule shown, why does T1''s withdrawal end up ''lost''?','["T1 never actually committed", "T2 read A''s stale value (1000) before T1''s write landed, so T2 computed 1500 from the stale value and its write overwrote T1''s 900", "T1''s write caused a constraint violation", "The database automatically reverted T1''s change"]'::jsonb,1,'T2''s read at step 2 happened before T1''s write at step 4, so T2''s subsequent write is based on outdated data and blindly overwrites T1''s already-applied change.') and (question_text,options,correct_index,explanation) is distinct from ('In the interleaved schedule shown, why does T1''s withdrawal end up ''lost''?','["T1 never actually committed", "T2 read A''s stale value (1000) before T1''s write landed, so T2 computed 1500 from the stale value and its write overwrote T1''s 900", "T1''s write caused a constraint violation", "The database automatically reverted T1''s change"]'::jsonb,1,'T2 computed its replacement from the earlier committed1000, then assigned1500 after T1 assigned900. The later stale replacement omits the withdrawal.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-lost-update-2'; end if;
