if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-lost-update-3' and (question_text,options,correct_index,explanation) is distinct from ('Does a lost update raise any error or exception in the database?','["Yes, it always triggers a constraint violation", "No \u2014 both transactions complete and commit successfully; the database ends up with a silently wrong final value with no error raised", "Yes, it always causes a deadlock", "Only if the isolation level is set to SERIALIZABLE"]'::jsonb,1,'This is what makes lost update dangerous — nothing fails visibly; the anomaly is purely in the silently incorrect final data value.') and (question_text,options,correct_index,explanation) is distinct from ('In the illustrated admitted stale-assignment history, can both writes complete without a database error while one effect is lost?','["Yes, it always triggers a constraint violation", "Yes; this history can complete successfully with the wrong final business value", "Yes, it always causes a deadlock", "Only if the isolation level is set to SERIALIZABLE"]'::jsonb,1,'The illustrated history can be silent; other engines or isolation configurations may block or reject a competing attempt.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-lost-update-3'; end if;
