insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-lost-update-application-new-1','pt-dbms-sql-23-lost-update-application','Which update avoids computing a decrement from an old application copy?','["SET quantity = 9 after an old read", "SET quantity = old_client_value", "SET quantity = quantity - 1", "SET quantity = 10 regardless of state"]'::jsonb,2,'Relative arithmetic uses the row state at the update.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-lost-update-application-new-2','pt-dbms-sql-23-lost-update-application','A stock decrement includes quantity >= requested. What must the caller inspect?','["Only whether SQL was uppercase", "Only the table alias", "Only the result column count", "Whether the required row was actually changed"]'::jsonb,3,'An unmet predicate can affect zero rows without an SQL exception.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-lost-update-application-new-3','pt-dbms-sql-23-lost-update-application','When should SELECT FOR UPDATE obtain protection for a read-compute-write decision?','["Before making the decision from the protected row", "After the stale final write", "On an unrelated connection", "Only after COMMIT"]'::jsonb,0,'Protection must cover the relevant read and subsequent action.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-lost-update-application-new-4','pt-dbms-sql-23-lost-update-application','A row version changed from 4 to 5. What should an update requiring version 4 do?','["Silently overwrite version 5", "Match no row in the controlled fixture", "Reset every row version", "Delete the row"]'::jsonb,1,'The stale predicate rejects replacement.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-lost-update-application-new-5','pt-dbms-sql-23-lost-update-application','What is required for an optimistic version protocol to work?','["Only the interface displays a number", "Only one test uses the version", "All relevant writers follow the version contract", "The version never changes"]'::jsonb,2,'Bypassing writers can defeat stale detection.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-lost-update-application-new-6','pt-dbms-sql-23-lost-update-application','Can lost update occur without a dirty read?','["No, the labels are identical", "Only on text columns", "Only after an abort", "Yes, both clients may read the same committed value"]'::jsonb,3,'Overwriting stale computations differs from reading uncommitted data.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-lost-update-application-new-7','pt-dbms-sql-23-lost-update-application','Do two blind writes prove a lost business effect without knowing the contract?','["No, intended replacement semantics must be established", "Yes, all replacements are forbidden", "Only if their SQL is lowercase", "Only if no row exists"]'::jsonb,0,'Last writer semantics can be intentional.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-lost-update-application-new-8','pt-dbms-sql-23-lost-update-application','After detecting a stale computed update, what retry is useful?','["Repeat the same stale assignment forever", "Recompute the complete decision with fresh state when permitted", "Ignore the affected row result", "Commit an unrelated row"]'::jsonb,1,'Fresh state and bounded retry are necessary.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-lost-update-application-new-9','pt-dbms-sql-23-lost-update-application','What does one protected counter fail to prove?','["That the counter has a value", "That UPDATE is valid SQL", "Safety of every cross-row business invariant", "That two arithmetic operations exist"]'::jsonb,2,'Write skew and predicate invariants can need a broader design.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-lost-update-application-new-10','pt-dbms-sql-23-lost-update-application','What evidence is needed to claim the shown interleaving was admitted by an engine?','["Only a final screenshot", "Only the database product name", "Only the application function name", "Controlled sessions, read types, isolation settings and outcomes"]'::jsonb,3,'A theoretical history and observed execution are distinct.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
