select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-19-views/materialized-views' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'materialized-views'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'materialized-views'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('3e51afc0a3628c8341c82a538433fc37','a58fcedaa948696ac17c61622df75389')) then raise exception 'Notes changed since seed; review before applying: %', 'materialized-views'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-19-materialized-views' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'materialized-views'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-19-materialized-views' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'materialized-views'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-19-materialized-views','cx-materialized-views-application')) then raise exception 'Extra topic tests require manual integration: %', 'materialized-views'; end if;
if exists(select 1 from public.practice_tests where id='cx-materialized-views-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'materialized-views'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "A stored result can lag a committed source change", "description": "A100-unit source summary stays 100 after a new 50-unit source order until the supported refresh incorporates it. Freshness describes source coverage, not the time the browser loaded.", "columns": ["Event", "Live eligible total", "Stored total"], "rows": [["Initial build", "100", "100"], ["New approved 50 commits", "150", "100"], ["Refresh succeeds", "150", "150"], ["Refresh fails after another change", "New source value", "Last successful build; timestamp must remain honest"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'materialized-views'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "A stored result can lag a committed source change", "description": "A100-unit source summary stays 100 after a new 50-unit source order until the supported refresh incorporates it. Freshness describes source coverage, not the time the browser loaded.", "columns": ["Event", "Live eligible total", "Stored total"], "rows": [["Initial build", "100", "100"], ["New approved 50 commits", "150", "100"], ["Refresh succeeds", "150", "150"], ["Refresh fails after another change", "New source value", "Last successful build; timestamp must remain honest"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "A stored result can lag a committed source change", "description": "A100-unit source summary stays 100 after a new 50-unit source order until the supported refresh incorporates it. Freshness describes source coverage, not the time the browser loaded.", "columns": ["Event", "Live eligible total", "Stored total"], "rows": [["Initial build", "100", "100"], ["New approved 50 commits", "150", "100"], ["Refresh succeeds", "150", "150"], ["Refresh fails after another change", "New source value", "Last successful build; timestamp must remain honest"]]}]'::jsonb;
