if exists(select 1 from public.test_questions where id='tq-dbms-sql-19-materialized-views-1' and test_id<>'pt-dbms-sql-19-materialized-views') then raise exception 'Question ID collision: %', 'tq-dbms-sql-19-materialized-views-1'; end if;
