if exists(select 1 from public.test_questions where id='tq-dbms-sql-19-materialized-views-1' and (question_text,options,correct_index,explanation) is distinct from ('What is the fundamental difference between a regular view and a materialized view?','["Materialized views cannot use joins", "A regular view re-runs its query live on each access; a materialized view stores the computed result physically and needs an explicit refresh", "Regular views are always faster", "Materialized views are only for single-table queries"]'::jsonb,1,'This is the defining trade-off: plain views compute on demand with no storage, while materialized views trade freshness for storage and read speed, requiring REFRESH to stay current.') and (question_text,options,correct_index,explanation) is distinct from ('What is the fundamental difference between a regular view and a materialized view?','["They are identical", "A regular view stores a definition; a materialized view stores computed rows with an engine-specific maintenance/freshness contract", "Regular views always store independent rows", "Materialized views cannot be queried"]'::jsonb,1,'Do not claim all engines require exactly the same explicit refresh mechanism; maintenance features vary.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-19-materialized-views-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-19-materialized-views-2' and test_id<>'pt-dbms-sql-19-materialized-views') then raise exception 'Question ID collision: %', 'tq-dbms-sql-19-materialized-views-2'; end if;
