if exists(select 1 from public.test_questions where id='tq-dbms-sql-19-materialized-views-2' and (question_text,options,correct_index,explanation) is distinct from ('Does MySQL support CREATE MATERIALIZED VIEW natively?','["Yes, identically to PostgreSQL", "No \u2014 MySQL has no native materialized view feature and it must be simulated with a real table plus a scheduled refresh job", "Yes, but only in MySQL 8 Enterprise", "No, and MySQL has no workaround at all"]'::jsonb,1,'MySQL lacks native materialized view support; the common workaround is a regular table populated by a scheduled job (e.g., an EVENT) that periodically re-runs the defining query.') and (question_text,options,correct_index,explanation) is distinct from ('Does MySQL support CREATE MATERIALIZED VIEW natively?','["Yes, identically to PostgreSQL", "No \u2014 MySQL has no native materialized view feature and it must be simulated with a real table plus a scheduled refresh job", "Yes, but only in MySQL 8 Enterprise", "No, and MySQL has no workaround at all"]'::jsonb,1,'MySQL 8.4 has no equivalent native materialized-view object. A reviewed summary-table workflow is a related application-managed pattern, not automatically a scheduled deployment feature.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-19-materialized-views-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-19-materialized-views-3' and test_id<>'pt-dbms-sql-19-materialized-views') then raise exception 'Question ID collision: %', 'tq-dbms-sql-19-materialized-views-3'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-19-materialized-views-3' and test_id='pt-dbms-sql-19-materialized-views') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-19-materialized-views-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-19-materialized-views-3' and (question_text,options,correct_index,explanation) is distinct from ('After data changes in the base tables, when does a materialized view''s data reflect those changes?','["Immediately and automatically, just like a regular view", "Only after an explicit REFRESH MATERIALIZED VIEW (or engine-equivalent) is run", "Never \u2014 materialized views are permanently frozen at creation time", "Only if the base table is dropped and recreated"]'::jsonb,1,'A materialized view''s stored data goes stale after base-table changes and only updates when explicitly refreshed (or on an automatic schedule/trigger configured by the DBA).') and (question_text,options,correct_index,explanation) is distinct from ('For the explicitly refreshed PostgreSQL materialized-view pattern, when do source changes enter the stored result?','["Immediately and automatically, just like a regular view", "Only after an explicit REFRESH MATERIALIZED VIEW (or engine-equivalent) is run", "Never \u2014 materialized views are permanently frozen at creation time", "Only if the base table is dropped and recreated"]'::jsonb,1,'Under this pattern a successful refresh recomputes the stored result. Other engines can offer different maintenance modes, so avoid a universal explicit-refresh-only claim.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-19-materialized-views-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-19-materialized-views-4' and test_id<>'pt-dbms-sql-19-materialized-views') then raise exception 'Question ID collision: %', 'tq-dbms-sql-19-materialized-views-4'; end if;
