if exists(select 1 from public.test_questions where id='tq-dbms-sql-19-materialized-views-5' and (question_text,options,correct_index,explanation) is distinct from ('Which scenario is the best candidate for a materialized view rather than a regular view?','["A cheap single-row lookup queried once a day", "An expensive multi-join aggregation queried frequently by a dashboard, where slight staleness is acceptable", "A view that must always reflect the absolute latest data with zero staleness", "A view with no aggregation at all"]'::jsonb,1,'Materialized views shine when an expensive query is read often relative to how often the underlying data changes, and some staleness is tolerable — classic dashboard/reporting use case.') and (question_text,options,correct_index,explanation) is distinct from ('Which scenario is the best candidate for a materialized view rather than a regular view?','["A cheap single-row lookup queried once a day", "An expensive multi-join aggregation queried frequently by a dashboard, where slight staleness is acceptable", "A view that must always reflect the absolute latest data with zero staleness", "A view with no aggregation at all"]'::jsonb,1,'Materialized views shine when an expensive query is read often relative to how often the underlying data changes, and some staleness is tolerable — classic dashboard/reporting use case.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-19-materialized-views-5'; end if;
