if exists(select 1 from public.test_questions where id='tq-dbms-sql-19-materialized-views-8' and (question_text,options,correct_index,explanation) is distinct from ('What risk does a nightly-refreshed materialized view introduce for reporting?','["It always corrupts the base tables", "Users may see numbers that don''t match a live query against the base tables, since the materialized data can be stale until the next refresh", "It prevents any further writes to the base tables", "It removes the need for any GRANT permissions"]'::jsonb,1,'Because materialized views are only as fresh as their last refresh, reports built on them can diverge from the live base-table state — a trade-off that must be communicated to consumers.') and (question_text,options,correct_index,explanation) is distinct from ('What risk does a nightly-refreshed materialized view introduce for reporting?','["It always corrupts the base tables", "Users may see numbers that don''t match a live query against the base tables, since the materialized data can be stale until the next refresh", "It prevents any further writes to the base tables", "It removes the need for any GRANT permissions"]'::jsonb,1,'Because materialized views are only as fresh as their last refresh, reports built on them can diverge from the live base-table state — a trade-off that must be communicated to consumers.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-19-materialized-views-8'; end if;
