update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Materialized Views.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-19-materialized-views' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-materialized-views-application','MCQ Test 2',category,10,10,'Application and scenarios for Materialized Views.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-19-materialized-views' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-materialized-views-1','pt-dbms-sql-19-materialized-views','What is the fundamental difference between a regular view and a materialized view?','["They are identical", "A regular view stores a definition; a materialized view stores computed rows with an engine-specific maintenance/freshness contract", "Regular views always store independent rows", "Materialized views cannot be queried"]'::jsonb,1,'Do not claim all engines require exactly the same explicit refresh mechanism; maintenance features vary.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-materialized-views-2','pt-dbms-sql-19-materialized-views','Does MySQL support CREATE MATERIALIZED VIEW natively?','["Yes, identically to PostgreSQL", "No — MySQL has no native materialized view feature and it must be simulated with a real table plus a scheduled refresh job", "Yes, but only in MySQL 8 Enterprise", "No, and MySQL has no workaround at all"]'::jsonb,1,'MySQL 8.4 has no equivalent native materialized-view object. A reviewed summary-table workflow is a related application-managed pattern, not automatically a scheduled deployment feature.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-materialized-views-3','pt-dbms-sql-19-materialized-views','For the explicitly refreshed PostgreSQL materialized-view pattern, when do source changes enter the stored result?','["Immediately and automatically, just like a regular view", "Only after an explicit REFRESH MATERIALIZED VIEW (or engine-equivalent) is run", "Never — materialized views are permanently frozen at creation time", "Only if the base table is dropped and recreated"]'::jsonb,1,'Under this pattern a successful refresh recomputes the stored result. Other engines can offer different maintenance modes, so avoid a universal explicit-refresh-only claim.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-materialized-views-4','pt-dbms-sql-19-materialized-views','What does `REFRESH MATERIALIZED VIEW CONCURRENTLY` require in PostgreSQL?','["Any index, including partial expressions", "An already populated view and a suitable UNIQUE index over column names covering all rows, with other documented prerequisites", "Only an ORDER BY", "No index can be present"]'::jsonb,1,'A mere unique-index label is insufficient; CONCURRENTLY excludes partial/expression qualifying indexes and WITH NO DATA.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-materialized-views-5','pt-dbms-sql-19-materialized-views','Which scenario is the best candidate for a materialized view rather than a regular view?','["A cheap single-row lookup queried once a day", "An expensive multi-join aggregation queried frequently by a dashboard, where slight staleness is acceptable", "A view that must always reflect the absolute latest data with zero staleness", "A view with no aggregation at all"]'::jsonb,1,'Materialized views shine when an expensive query is read often relative to how often the underlying data changes, and some staleness is tolerable — classic dashboard/reporting use case.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-materialized-views-6','pt-dbms-sql-19-materialized-views','Can a materialized view be indexed?','["No, indexing is impossible on any kind of view", "Yes — because it physically stores data like a table, it can be indexed directly, unlike a regular (non-materialized) view", "Only in MySQL", "Only if it has no aggregate columns"]'::jsonb,1,'PostgreSQL materialized views can have indexes. A materialized result and a normal view have different storage; other engines can offer specialized indexed-view features, so avoid universal cross-engine claims.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-materialized-views-7','pt-dbms-sql-19-materialized-views','In MySQL''s simulated materialized-view pattern, what commonly triggers the periodic refresh?','["A UNIQUE constraint violation", "A scheduled MySQL EVENT (or external cron job) that re-runs the aggregation and repopulates the snapshot table", "The MySQL query optimizer automatically", "A foreign key cascade"]'::jsonb,1,'A reviewed scheduler or worker can recompute and publish a summary under an explicit coherent boundary. TRUNCATE has implicit-commit behavior in MySQL and is not a generally reversible transactional replacement; the refresh design must preserve reader and failure requirements.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-materialized-views-8','pt-dbms-sql-19-materialized-views','What risk does a nightly-refreshed materialized view introduce for reporting?','["It always corrupts the base tables", "Users may see numbers that don''t match a live query against the base tables, since the materialized data can be stale until the next refresh", "It prevents any further writes to the base tables", "It removes the need for any GRANT permissions"]'::jsonb,1,'Because materialized views are only as fresh as their last refresh, reports built on them can diverge from the live base-table state — a trade-off that must be communicated to consumers.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-materialized-views-fundamentals-9','pt-dbms-sql-19-materialized-views','What does the materialized result store?','["Computed query rows", "Only a query name with no data", "Every future source change automatically in all engines", "Only a client screenshot"]'::jsonb,0,'Stored computation requires a defined maintenance contract.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-materialized-views-fundamentals-10','pt-dbms-sql-19-materialized-views','A new approved 50 order follows a stored 100 total. Before refresh, what can the summary show?','["Always 150 automatically", "100 while a current live query shows 150", "Zero by definition", "An automatic authorization grant"]'::jsonb,1,'Staleness follows the last maintenance boundary.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-materialized-views-application-1','cx-materialized-views-application','Does loading the dashboard page necessarily refresh the stored database result?','["Yes, all materialized views refresh per request", "No", "Only if the page is blue", "Only after ORDER BY"]'::jsonb,1,'Refresh must be an actual supported operation, not an assumed UI effect.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-materialized-views-application-2','cx-materialized-views-application','What must incremental maintenance handle when an order changes regions?','["Only add to the new region", "Only rename the report column", "Remove its old-group contribution and add its new-group contribution", "Ignore every update"]'::jsonb,2,'Update and deletion semantics matter beyond inserts.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-materialized-views-application-3','cx-materialized-views-application','Does a unique partial index satisfy the stated PostgreSQL concurrent-refresh requirement?','["Yes, any index suffices", "Only if named refresh", "Only if it is nonunique", "No, the required index covers all rows and uses column names"]'::jsonb,3,'The documented prerequisite excludes partial and expression indexes.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-materialized-views-application-4','cx-materialized-views-application','Can PostgreSQL CONCURRENTLY refresh combine with WITH NO DATA?','["No", "Yes, always", "Only if the view is empty", "Only with two readers"]'::jsonb,0,'The options are incompatible under the documented contract.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-materialized-views-application-5','cx-materialized-views-application','Does MySQL 8.4 accept PostgreSQL CREATE MATERIALIZED VIEW unchanged?','["Yes, universally", "No", "Only for one column", "Only when an EVENT exists"]'::jsonb,1,'A manually maintained summary table is a different implementation.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-materialized-views-application-6','cx-materialized-views-application','Why can separate autocommitted DELETE and INSERT be a refresh defect?','["They always preserve one atomic replacement", "They automatically create a snapshot", "Readers can observe an empty or partial publication interval", "They validate every source invariant"]'::jsonb,2,'Publication needs an explicit coherent boundary.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-materialized-views-application-7','cx-materialized-views-application','Why should a failed refresh not advance its success timestamp?','["It makes the table shorter", "It disables every index", "It changes the query alias", "It would falsely imply source coverage was incorporated"]'::jsonb,3,'Freshness indicators must reflect actual successful data coverage.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-materialized-views-application-8','cx-materialized-views-application','Does storing a report fix an incorrect source join?','["No, it can persist the same mistake", "Yes, materialization repairs cardinality", "Only with a unique index", "Only after a schedule"]'::jsonb,0,'Correctness of the defining computation remains essential.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-materialized-views-application-9','cx-materialized-views-application','What is an appropriate source-of-truth correction path?','["Edit totals arbitrarily to hide disagreement", "Correct authoritative source facts and recompute through reviewed maintenance", "Disable access controls", "Drop the report without review"]'::jsonb,1,'Direct cosmetic summary edits can conceal and later lose the real correction.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-materialized-views-application-10','cx-materialized-views-application','What belongs in a performance comparison?','["Only the number of SELECT characters", "Only a warm one-row test", "Read latency, refresh cost, storage and freshness requirements", "Only the object name"]'::jsonb,2,'Stored computation moves work and adds operational obligations.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
