select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-14-sql-functions/max' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'max'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'max'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('2dd7fa872a8ff933442a22f748fe6790','bdc7f8b750d3cb4e6bb6c7b80ac4aeab')) then raise exception 'Notes changed since seed; review before applying: %', 'max'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-14-max' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'max'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-14-max' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'max'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-14-max','pt-dbms-sql-14-max-application')) then raise exception 'Extra topic tests require manual integration: %', 'max'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-14-max-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'max'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Latest accepted times preserve all matching details", "description": "Each laboratory''s accepted inspection times establish its latest known boundary; later rejected times are excluded.", "columns": ["Laboratory", "Latest known accepted time", "Matching accepted identities", "Excluded evidence"], "rows": [["BIO", "2026-01-12 09:00:00", "2 and 3", "Later rejected inspection 4"], ["CHEM", "2026-01-11 08:00:00", "5", "Rejected tie 7 and missing time 6"], ["EMPTY", "NULL", "None", "Only an unknown accepted time"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'max'; end if;
