INSERT INTO lab_inspections VALUES (1,''BIO'',''2026-01-10 10:00:00'',1),(2,''BIO'',''2026-01-12 09:00:00'',1),(3,''BIO'',''2026-01-12 09:00:00'',1),(4,''BIO'',''2026-01-20 10:00:00'',0),(5,''CHEM'',''2026-01-11 08:00:00'',1),(6,''CHEM'',NULL,1),(7,''CHEM'',''2026-01-11 08:00:00'',0),(8,''EMPTY'',NULL,1);
