insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-min-1','pt-dbms-sql-14-min','For values 12, NULL, -4, and 8, what is MIN(value)?','["-4", "0", "NULL", "12"]'::jsonb,0,'Missing values are ignored; negative four is the smallest known candidate.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-min-2','pt-dbms-sql-14-min','What does MIN(inspection_date) identify among known dates?','["The insertion date of the newest row", "The earliest date", "The latest date", "The current session date"]'::jsonb,1,'Chronologically earlier date values compare smaller.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-min-3','pt-dbms-sql-14-min','Can MIN compare a supported VARCHAR expression in MySQL?','["No, it accepts integers only", "Yes, using its applicable string comparison rules", "Yes, but only after every value becomes zero", "Only when the query has no WHERE"]'::jsonb,1,'A text minimum follows the applicable collation rather than a universal alphabet.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-min-4','pt-dbms-sql-14-min','Under an ordinary collation ordering Amber before Copper and Zinc, what is MIN(name) for Copper, Amber, Zinc, Amber?','["Copper", "Zinc", "Amber", "NULL"]'::jsonb,2,'Repeating Amber does not alter the smallest candidate.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-min-5','pt-dbms-sql-14-min','What value does an ungrouped MIN(price) return when WHERE admits no rows?','["0", "NULL", "An automatic default price", "An exception because no minimum row exists"]'::jsonb,1,'The ungrouped query still produces a summary row, whose minimum is missing.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-min-6','pt-dbms-sql-14-min','How does MIN(DISTINCT price) compare with MIN(price) over the same ordinary values?','["It always halves the minimum", "It counts minimum-price rows", "It produces the same minimum", "It is invalid MySQL aggregate syntax"]'::jsonb,2,'Removing repeated candidates cannot move the minimum boundary.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-min-7','pt-dbms-sql-14-min','Why does MIN(price) alone not answer which supplier offered the cheapest price?','["It always selects the highest supplier id", "It returns the value without choosing an owning detail row", "It cannot process a WHERE filter", "Every supplier must offer a different price"]'::jsonb,1,'Ties and sibling properties need an explicit detail-selection contract.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-min-8','pt-dbms-sql-14-min','What is a useful reason to choose MIN rather than an ordered detail query when only a summary value is needed?','["It guarantees zero table reads", "It directly expresses an aggregate boundary and composes with grouping", "It automatically returns supplier details", "It always outruns every indexed ordered query"]'::jsonb,1,'The semantic fit is clear, while performance still depends on the plan.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
