if exists(select 1 from public.dsa_problems where id='cx-min-approved-item-quotes' and description is distinct from 'Return quote_id,item_code,price for every approved quotation tied at the lowest known approved price within its item_code. approval=1 means approved. Exclude unknown prices and rejected quotations, including rejected quotations tied at an approved boundary. Order by item_code ascending then quote_id ascending.

**MySQL dialect.**

```sql
CREATE TABLE item_quotes(quote_id INT PRIMARY KEY,item_code VARCHAR(12) NOT NULL,price INT,approval INT NOT NULL);
INSERT INTO item_quotes VALUES (1,''CAM'',80,1),(2,''CAM'',60,1),(3,''CAM'',60,1),(4,''CAM'',10,0),(5,''MIC'',20,1),(6,''MIC'',NULL,1),(7,''MIC'',20,0),(8,''UNK'',NULL,1);
```

**Required ordering:** item_code ASC, then quote_id ASC.

**Edge cases:**
- Rejected values must not establish the minimum.
- Rejected rows sharing a boundary remain excluded.
- An all-missing item has no qualifying detail row.') then raise exception 'New coding ID already has other content: %', 'cx-min-approved-item-quotes'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-min-approved-item-quotes',null::text,'Return every lowest approved quotation by item','Medium','min-approved-item-quotes','Return quote_id,item_code,price for every approved quotation tied at the lowest known approved price within its item_code. approval=1 means approved. Exclude unknown prices and rejected quotations, including rejected quotations tied at an approved boundary. Order by item_code ascending then quote_id ascending.

**MySQL dialect.**

```sql
CREATE TABLE item_quotes(quote_id INT PRIMARY KEY,item_code VARCHAR(12) NOT NULL,price INT,approval INT NOT NULL);
INSERT INTO item_quotes VALUES (1,''CAM'',80,1),(2,''CAM'',60,1),(3,''CAM'',60,1),(4,''CAM'',10,0),(5,''MIC'',20,1),(6,''MIC'',NULL,1),(7,''MIC'',20,0),(8,''UNK'',NULL,1);
```

**Required ordering:** item_code ASC, then quote_id ASC.

**Edge cases:**
- Rejected values must not establish the minimum.
- Rejected rows sharing a boundary remain excluded.
- An all-missing item has no qualifying detail row.','[{"input": "INSERT INTO item_quotes VALUES (1,''CAM'',80,1),(2,''CAM'',60,1),(3,''CAM'',60,1),(4,''CAM'',10,0),(5,''MIC'',20,1),(6,''MIC'',NULL,1),(7,''MIC'',20,0),(8,''UNK'',NULL,1);", "output": "quote_id\titem_code\tprice\n2\tCAM\t60\n3\tCAM\t60\n5\tMIC\t20", "explanation": "Approval is applied before the item partition minimum is computed. Equality retains every known price tied at that item''s boundary. Rejected quotations never appear in the window input, and NULL comparisons do not qualify."}]'::jsonb,'[{"seed_sql": "INSERT INTO item_quotes VALUES (1,''A'',NULL,1),(2,''A'',-9,0),(3,''B'',5,0);", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO item_quotes VALUES (8,''A'',0,1),(2,''A'',-2,1),(6,''A'',-2,1),(7,''B'',3,1),(9,''A'',-2,0);", "expected": "quote_id\titem_code\tprice\n2\tA\t-2\n6\tA\t-2\n7\tB\t3", "hidden": true}, {"seed_sql": "", "expected": "", "hidden": true}]'::jsonb,'["Use the supplied MySQL 8.4-compatible schema.", "Return all qualifying ties without updating source rows."]'::jsonb,'["Filter approval before computing each item''s boundary.", "A windowed MIN preserves details for a surrounding filter."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'Approval is applied before the item partition minimum is computed. Equality retains every known price tied at that item''s boundary. Rejected quotations never appear in the window input, and NULL comparisons do not qualify.','{"sql": "SELECT quote_id,item_code,price FROM (SELECT quote_id,item_code,price,MIN(price) OVER (PARTITION BY item_code) AS lowest_price FROM item_quotes WHERE approval=1) AS ranked WHERE price=lowest_price ORDER BY item_code ASC,quote_id ASC;"}'::jsonb,'Approval is applied before the item partition minimum is computed. Equality retains every known price tied at that item''s boundary. Rejected quotations never appear in the window input, and NULL comparisons do not qualify.',array['sql'],'CREATE TABLE item_quotes(quote_id INT PRIMARY KEY,item_code VARCHAR(12) NOT NULL,price INT,approval INT NOT NULL);','INSERT INTO item_quotes VALUES (1,''CAM'',80,1),(2,''CAM'',60,1),(3,''CAM'',60,1),(4,''CAM'',10,0),(5,''MIC'',20,1),(6,''MIC'',NULL,1),(7,''MIC'',20,0),(8,''UNK'',NULL,1);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-14-min' on conflict(id) do nothing;
