if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'minimal-cover'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'minimal-cover'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('490419ea9f8c95f101e3a9358d63fe45','0926f9d6d197978226fb74eb9f0c63f3')) then raise exception 'Notes changed since seed; review before applying: %', 'minimal-cover'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-21-minimal-cover' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'minimal-cover'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-21-minimal-cover' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'minimal-cover'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-21-minimal-cover','pt-dbms-sql-21-minimal-cover-application')) then raise exception 'Extra topic tests require manual integration: %', 'minimal-cover'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-21-minimal-cover-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'minimal-cover'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Simplify rules while preserving their closure", "description": "The worked ABCD example removes an extraneous determinant attribute and a redundant consequence.", "columns": ["Stage", "Dependency set", "Reason"], "rows": [["Initial", "A→B;AB→C;C→D;A→D", "Given rules"], ["Reduce left side", "A→B;A→C;C→D;A→D", "A already derives B"], ["Remove redundant rule", "A→B;A→C;C→D", "A derives D through C"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'minimal-cover'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Simplify rules while preserving their closure", "description": "The worked ABCD example removes an extraneous determinant attribute and a redundant consequence.", "columns": ["Stage", "Dependency set", "Reason"], "rows": [["Initial", "A→B;AB→C;C→D;A→D", "Given rules"], ["Reduce left side", "A→B;A→C;C→D;A→D", "A already derives B"], ["Remove redundant rule", "A→B;A→C;C→D", "A derives D through C"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Simplify rules while preserving their closure", "description": "The worked ABCD example removes an extraneous determinant attribute and a redundant consequence.", "columns": ["Stage", "Dependency set", "Reason"], "rows": [["Initial", "A→B;AB→C;C→D;A→D", "Given rules"], ["Reduce left side", "A→B;A→C;C→D;A→D", "A already derives B"], ["Remove redundant rule", "A→B;A→C;C→D", "A derives D through C"]]}]'::jsonb;
