if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-minimal-cover-1' and (question_text,options,correct_index,explanation) is distinct from ('Why is CourseID -> InstructorName dropped when reducing the naive FD set G to its minimal cover?','["Because InstructorName is not a real attribute", "Because it is already implied transitively: CourseID -> InstructorID (G3) and InstructorID -> InstructorName (G4) together already establish it", "Because CourseID cannot determine text attributes", "Because it has more than one attribute on the right-hand side"]'::jsonb,1,'A minimal cover excludes any FD derivable from the rest of the set; since the two-step chain already implies it, keeping G6 as a separate FD is redundant.') and (question_text,options,correct_index,explanation) is distinct from ('What must a minimal cover preserve?','["Only current row counts", "The original dependency implications", "Only attribute names", "Only physical indexes"]'::jsonb,1,'Equivalent covers describe the same logical constraints on permitted states.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-minimal-cover-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-minimal-cover-2' and test_id<>'pt-dbms-sql-21-minimal-cover') then raise exception 'Question ID collision: %', 'tq-dbms-sql-21-minimal-cover-2'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-21-minimal-cover-2' and test_id='pt-dbms-sql-21-minimal-cover') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-21-minimal-cover-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-minimal-cover-2' and (question_text,options,correct_index,explanation) is distinct from ('Why does {StudentID, CourseID} -> StudentName (G9) get reduced/removed during minimal cover derivation?','["Because StudentName is never functionally dependent on anything", "Because CourseID is an extraneous attribute on the left-hand side \u2014 StudentID alone already determines StudentName, making G9 a duplicate of G1 once reduced", "Because composite left-hand sides are always invalid", "Because StudentName must be on the left-hand side, not the right"]'::jsonb,1,'Testing for extraneous LHS attributes shows CourseID contributes nothing here since StudentID alone suffices; after removing the extraneous attribute, G9 collapses into the already-present G1.') and (question_text,options,correct_index,explanation) is distinct from ('Which right-side convention is used here?','["Exactly two attributes always", "One attribute per dependency", "No right sides", "Only candidate keys"]'::jsonb,1,'Singleton right sides make individual consequence tests explicit.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-minimal-cover-2'; end if;
