if not exists(select 1 from public.test_questions where id='tq-dbms-sql-21-minimal-cover-3' and test_id='pt-dbms-sql-21-minimal-cover') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-21-minimal-cover-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-minimal-cover-3' and (question_text,options,correct_index,explanation) is distinct from ('Which of the three formal properties must every FD in a minimal cover satisfy regarding its right-hand side?','["It must reference at least two attributes", "It must consist of exactly a single attribute", "It must always be a foreign key", "It must match the primary key exactly"]'::jsonb,1,'One of minimal cover''s defining conditions is that every FD''s right-hand side contains a single attribute — composite right-hand sides must be split into separate single-attribute FDs first.') and (question_text,options,correct_index,explanation) is distinct from ('How expand A→BC?','["Only A\u2192B", "A\u2192B and A\u2192C", "B\u2192A and C\u2192A", "AB\u2192C only"]'::jsonb,1,'Both determined attributes must remain represented.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-minimal-cover-3'; end if;
