if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-minimal-cover-5' and (question_text,options,correct_index,explanation) is distinct from ('After fully reducing the naive 9-FD set G, how many FDs remain in the minimal cover for the running example?','["9, all of them are necessary", "6 \u2014 the same clean FD set (F1-F6) used throughout this chapter", "3, only the single-attribute-key FDs", "0, the relation has no functional dependencies"]'::jsonb,1,'After dropping G6, G7 (redundant/transitively implied) and G9 (extraneous-LHS duplicate of G1), exactly 6 necessary FDs remain — matching F1-F6 from 21.5.') and (question_text,options,correct_index,explanation) is distinct from ('Under A→B and AB→C what does A''s closure gain?','["Only B forever", "B then C", "Only D", "Nothing"]'::jsonb,1,'A first derives B, making the AB determinant available.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-minimal-cover-5'; end if;
