if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-minimal-cover-7' and (question_text,options,correct_index,explanation) is distinct from ('Why do schema-design algorithms (like 3NF synthesis) require a minimal cover as input rather than an arbitrary FD set?','["Because arbitrary FD sets are always syntactically invalid", "Because redundant or extraneous FDs can cause the algorithm to produce unnecessary extra tables or miss the true underlying dependency structure", "Because minimal covers are required by SQL syntax", "Because algorithms cannot process composite left-hand sides at all"]'::jsonb,1,'Feeding redundant/extraneous FDs into a synthesis algorithm can distort its output; a minimal cover ensures the algorithm reasons only about genuinely necessary dependencies.') and (question_text,options,correct_index,explanation) is distinct from ('What must be removed during a whole-rule redundancy test?','["Every attribute on the right", "The candidate dependency", "The relation schema", "Every other dependency"]'::jsonb,1,'Otherwise the candidate can trivially prove itself.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-minimal-cover-7'; end if;
