if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-multiple-grouping-columns-2' and (question_text,options,correct_index,explanation) is distinct from ('How many rows does `SELECT region, product, SUM(amount) FROM orders GROUP BY region, product;` return for the 8-row orders table?','["3, one per region", "8, one per raw row", "6, one per distinct (region, product) pair present", "9, one per theoretical region x product combination"]'::jsonb,2,'There are exactly 6 distinct (region, product) pairs in the data (East/Gadget, East/Widget, North/Gadget, North/Widget, West/Gadget, West/Widget) since East and West each only have Widget+Gadget, not a 9th combination.') and (question_text,options,correct_index,explanation) is distinct from ('What happens to two North Widget orders?','["They create separate groups because order IDs differ", "One is removed automatically", "They contribute to the same pair", "They become a South group"]'::jsonb,2,'The grouping expressions agree for both orders.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-multiple-grouping-columns-2'; end if;
