update public.learning_topics set short_description='Order SQL rows by multiple columns with separate ASC and DESC directions; trace left-to-right priorities and use a final key to resolve ties.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Order SQL rows by multiple columns with separate ASC and DESC directions; trace left-to-right priorities and use a final key to resolve ties.';
