insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-multiple-sort-keys-1','pt-dbms-sql-13-multiple-sort-keys','In ORDER BY category,price, what is price used for?','["Sorting every row globally before category", "Filtering expensive rows", "Breaking ties on the earlier category key", "Removing duplicate categories"]'::jsonb,2,'Keys have left-to-right priority.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-multiple-sort-keys-2','pt-dbms-sql-13-multiple-sort-keys','Does swapping category and price generally preserve sequence?','["Yes, ordering keys are commutative", "No, it changes the primary ranking priority", "Only if both are numbers", "Always if there are two keys"]'::jsonb,1,'Some samples may coincide, but the contracts differ.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-multiple-sort-keys-3','pt-dbms-sql-13-multiple-sort-keys','Can one key ascend while the next descends?','["No, one direction applies to the entire list", "Yes", "Only for the final key", "Only in a stored procedure"]'::jsonb,1,'Each term owns its direction.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
