if exists(select 1 from public.test_questions where id='cx-q-natural-join-sql-19' and (question_text,options,correct_index,explanation) is distinct from ('Does NATURAL JOIN guarantee unique result rows?','["Yes always", "Only for strings", "No", "Only without ORDER BY"]'::jsonb,2,'Uniqueness requires a justified source or projection policy.') and (question_text,options,correct_index,explanation) is distinct from ('Does NATURAL JOIN guarantee unique result rows?','["Yes always", "Only for strings", "No", "Only without ORDER BY"]'::jsonb,2,'Uniqueness requires a justified source or projection policy.')) then raise exception 'Edited question requires review: %', 'cx-q-natural-join-sql-19'; end if;
