update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Natural Join.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-16-natural-join-sql' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-test-natural-join-sql-2','MCQ Test 2',category,10,10,'Application and scenarios for Natural Join.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-16-natural-join-sql' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-natural-join-sql-1','pt-dbms-sql-16-natural-join-sql','How does NATURAL JOIN decide what to match on?','["You must specify columns explicitly", "Automatically, based on every identically-named column shared by both tables", "It always matches on the primary key only", "It requires a CROSS JOIN first"]'::jsonb,1,'NATURAL JOIN infers its match condition purely from shared column names.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-natural-join-sql-2','pt-dbms-sql-16-natural-join-sql','Inputs employees(employee_id, department_id) and departments(id, department_name) have no shared column names. What does their NATURAL JOIN pair?','["Only declared foreign-key matches", "Every employee with every department", "Only equal first-column values", "No rows, even when both inputs are nonempty"]'::jsonb,1,'There are no common names in these explicit schemas, so no implicit equality restricts the Cartesian pairing.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-natural-join-sql-3','pt-dbms-sql-16-natural-join-sql','Why is NATURAL JOIN considered risky if two tables happen to share an unrelated column name?','["It isn''t risky in that case", "NATURAL JOIN would silently require that unrelated column to also match, potentially breaking the intended relationship", "Shared unrelated column names cause a guaranteed syntax error", "NATURAL JOIN ignores all but the first shared column name"]'::jsonb,1,'Every shared name becomes part of the automatic match condition, intended or not.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-natural-join-sql-4','pt-dbms-sql-16-natural-join-sql','Why do many real-world style guides prefer explicit JOIN ... ON over NATURAL JOIN?','["JOIN ... ON is always faster to execute", "Explicit conditions don''t silently depend on incidental column-naming choices that could change later", "NATURAL JOIN is not valid SQL syntax", "JOIN ... ON requires fewer keystrokes"]'::jsonb,1,'Robustness to schema evolution is the main argument for explicit join conditions.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-natural-join-sql-5','pt-dbms-sql-16-natural-join-sql','Does NATURAL JOIN require writing an ON or USING clause?','["Yes, always", "No — that''s the defining feature of NATURAL JOIN; the match is inferred automatically", "Only USING is required, never ON", "Only for more than two tables"]'::jsonb,1,'The absence of an explicit condition is exactly what makes it a ''natural'' join.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-natural-join-sql-6','pt-dbms-sql-16-natural-join-sql','How does a natural join differ from renaming an input column?','["A natural join combines matching rows; a rename changes a name used to describe an input", "Both operations always combine rows", "Renaming alone checks foreign keys", "A natural join only changes a display label"]'::jsonb,0,'Joining and renaming are different operations. A rename can change which names are shared, but does not itself combine the input relations.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-natural-join-sql-7','pt-dbms-sql-16-natural-join-sql','What real consequence follows from NATURAL JOIN degenerating into a CROSS JOIN when no shared column names exist?','["The query simply returns zero rows safely", "A likely unintended, potentially very large row-count explosion, with no error to flag the problem", "SQL automatically raises a warning in this exact case", "The query is automatically converted to an INNER JOIN instead"]'::jsonb,1,'The lack of an error, combined with the Cartesian-Product row-count risk from 16.5, makes this a genuinely dangerous silent failure mode.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-16-natural-join-sql-8','pt-dbms-sql-16-natural-join-sql','Only department_id is shared by employees(department_id, employee_name) and departments(department_id, department_name). Which query matches SELECT department_id,employee_name,department_name FROM employees NATURAL JOIN departments?','["SELECT e.department_id,e.employee_name,d.department_name FROM employees e CROSS JOIN departments d", "SELECT e.department_id,e.employee_name,d.department_name FROM employees e JOIN departments d ON e.department_id=d.department_id", "SELECT e.department_id,e.employee_name,d.department_name FROM employees e LEFT JOIN departments d ON 1=1", "SELECT e.department_id,e.employee_name,d.department_name FROM employees e JOIN departments d ON e.department_id<>d.department_id"]'::jsonb,1,'The one shared name supplies the equality, and explicit projection preserves the requested output shape rather than comparing different SELECT * schemas.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-natural-join-sql-9','pt-dbms-sql-16-natural-join-sql','Which newly shared column can silently alter a natural join?','["status", "A column present only on the left", "A column present only on the right", "An output alias not in either input"]'::jsonb,0,'Every same-named input column participates.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-natural-join-sql-10','pt-dbms-sql-16-natural-join-sql','For the shown natural INNER JOIN, what happens when registrations is empty and members is nonempty?','["Every member gets a placeholder registration", "The result is empty", "One NULL row is returned", "Every member appears once"]'::jsonb,1,'An inner join requires a qualifying pair, so an empty input produces no pairs.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-natural-join-sql-11','cx-test-natural-join-sql-2','Does NATURAL JOIN infer foreign keys?','["Always", "Only for NULL keys", "No", "Only after ORDER BY"]'::jsonb,2,'It relies on names rather than declared relationships.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-natural-join-sql-12','cx-test-natural-join-sql-2','Does a natural inner join match NULL to NULL?','["Always", "Only for integer keys", "Only for text keys", "No under ordinary equality"]'::jsonb,3,'Unknown equality does not form a match.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
