if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-nested-transaction-concepts-1' and (question_text,options,correct_index,explanation) is distinct from ('Do most SQL databases support true nested transactions?','["Yes, universally and identically", "No \u2014 most don''t; SAVEPOINT provides the practical substitute for the most common use case", "Only NoSQL databases support this", "Nested transactions are part of the core SQL standard, always supported"]'::jsonb,1,'True independent nested transactions are not commonly supported — SAVEPOINT covers the practical need instead.') and (question_text,options,correct_index,explanation) is distinct from ('In MySQL, does issuing START TRANSACTION inside an active transaction create an independently nested child transaction?','["Yes, with independent child durability", "No; it can end the current transaction, so use an explicitly designed savepoint contract for scoped recovery", "Only if the child has one statement", "Every SQL engine guarantees this behavior"]'::jsonb,1,'Scope the claim to MySQL rather than an unsupported count of most SQL databases.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-nested-transaction-concepts-1'; end if;
