if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-nested-transaction-concepts-2' and (question_text,options,correct_index,explanation) is distinct from ('What commonly happens if you issue START TRANSACTION while a transaction is already open?','["It always creates a fully independent nested transaction", "Dialect-specific behavior \u2014 commonly an implicit commit of the current transaction, a warning/error, or a no-op continuing the existing transaction", "It always raises a fatal, unrecoverable error", "It automatically converts to a SAVEPOINT"]'::jsonb,1,'This behavior varies by database and is not genuine nesting in any case.') and (question_text,options,correct_index,explanation) is distinct from ('What commonly happens if you issue START TRANSACTION while a transaction is already open?','["It always creates a fully independent nested transaction", "Dialect-specific behavior \u2014 commonly an implicit commit of the current transaction, a warning/error, or a no-op continuing the existing transaction", "It always raises a fatal, unrecoverable error", "It automatically converts to a SAVEPOINT"]'::jsonb,1,'This behavior varies by database and is not genuine nesting in any case.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-nested-transaction-concepts-2'; end if;
