if exists(select 1 from public.test_questions where id='tq-dbms-sql-22-nested-transaction-concepts-3' and (question_text,options,correct_index,explanation) is distinct from ('How do ORMs/frameworks typically implement a ''nested transaction'' API?','["Using genuine database-level independent nested transactions", "Usually via SAVEPOINT under the hood, not true database-level nesting", "By opening a separate database connection for each nested call", "Nested transaction APIs don''t exist in any framework"]'::jsonb,1,'Framework ''nested transactions'' are typically SAVEPOINT-based wrappers, which explains their actual (non-independent) behavior.') and (question_text,options,correct_index,explanation) is distinct from ('What should be verified before relying on a framework nested-transaction API?','["Only its method name", "Its documented savepoint, bookkeeping or rollback-only behavior and actual connection statements", "Only the table row count", "Only its UI label"]'::jsonb,1,'Frameworks differ; a nested scope is not proof of an independent inner commit.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-22-nested-transaction-concepts-3'; end if;
