insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-nested-transaction-concepts-1','pt-dbms-sql-22-nested-transaction-concepts','In MySQL, does issuing START TRANSACTION inside an active transaction create an independently nested child transaction?','["Yes, with independent child durability", "No; it can end the current transaction, so use an explicitly designed savepoint contract for scoped recovery", "Only if the child has one statement", "Every SQL engine guarantees this behavior"]'::jsonb,1,'Scope the claim to MySQL rather than an unsupported count of most SQL databases.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-nested-transaction-concepts-2','pt-dbms-sql-22-nested-transaction-concepts','What commonly happens if you issue START TRANSACTION while a transaction is already open?','["It always creates a fully independent nested transaction", "Dialect-specific behavior — commonly an implicit commit of the current transaction, a warning/error, or a no-op continuing the existing transaction", "It always raises a fatal, unrecoverable error", "It automatically converts to a SAVEPOINT"]'::jsonb,1,'This behavior varies by database and is not genuine nesting in any case.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-nested-transaction-concepts-3','pt-dbms-sql-22-nested-transaction-concepts','What should be verified before relying on a framework nested-transaction API?','["Only its method name", "Its documented savepoint, bookkeeping or rollback-only behavior and actual connection statements", "Only the table row count", "Only its UI label"]'::jsonb,1,'Frameworks differ; a nested scope is not proof of an independent inner commit.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-nested-transaction-concepts-4','pt-dbms-sql-22-nested-transaction-concepts','What is the real correctness trap with issuing a second START TRANSACTION while one is open?','["There is no trap — it''s always safe", "Some databases implicitly commit the outer transaction first, silently committing work the caller thought was still pending", "It always throws a compile-time error", "It permanently locks the database"]'::jsonb,1,'Silent implicit-commit behavior on a second START TRANSACTION is a genuine, dialect-specific correctness hazard.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-nested-transaction-concepts-5','pt-dbms-sql-22-nested-transaction-concepts','What practical benefit does SAVEPOINT provide as a substitute for true nested transactions?','["Fully independent commit of an inner unit without affecting the outer transaction", "The ability to isolate and undo just a portion of a larger transaction, without discarding the whole thing", "Automatic conflict resolution between concurrent transactions", "Encryption of transaction data"]'::jsonb,1,'SAVEPOINT covers the most common real use case for ''nesting'' — partial rollback — without requiring true nested transaction support.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
