update public.learning_topics set short_description='Understand InnoDB secondary lookups, primary-key locators, composite prefixes, covering queries, and the measured tradeoffs of extra indexes.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Understand InnoDB secondary lookups, primary-key locators, composite prefixes, covering queries, and the measured tradeoffs of extra indexes.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Non Clustered Index.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-20-non-clustered-index' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-non-clustered-index-application','MCQ Test 2',category,10,10,'Application and scenarios for Non Clustered Index.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-20-non-clustered-index' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-non-clustered-index-1','pt-dbms-sql-20-non-clustered-index','What does a non-clustered index''s leaf entry actually contain?','["The complete row data for every column", "The indexed value plus a pointer/reference back to the actual row stored elsewhere", "Nothing; it is an empty placeholder", "A duplicate of the clustered index"]'::jsonb,1,'Unlike a clustered index, a non-clustered index''s leaves hold the indexed value and a pointer back to where the full row actually lives.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-non-clustered-index-2','pt-dbms-sql-20-non-clustered-index','How many non-clustered indexes can a single table have?','["At most one, same as a clustered index", "Zero only", "Many — there is no ''one per table'' restriction like there is for clustered indexes", "Exactly the same number as columns in the table, no more no less"]'::jsonb,2,'Because non-clustered indexes are separate structures that don''t dictate physical row order, a table can have many of them.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-non-clustered-index-3','pt-dbms-sql-20-non-clustered-index','Why does looking up a row via a non-clustered index typically require an extra step compared to a clustered index?','["It doesn''t; both are equally direct", "Because the non-clustered index only gives a pointer, requiring a second lookup to fetch the actual row from wherever it''s stored", "Because non-clustered indexes are always unsorted", "Because non-clustered indexes cannot use B+ Trees"]'::jsonb,1,'The non-clustered index search yields a pointer, and a second ''bookmark lookup'' step is needed to retrieve the actual row.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-non-clustered-index-4','pt-dbms-sql-20-non-clustered-index','What is this extra step (finding the pointer, then fetching the actual row) commonly called?','["A hash collision", "A bookmark lookup (or key lookup)", "A table scan", "A page split"]'::jsonb,1,'This two-step access pattern is commonly referred to as a bookmark or key lookup.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-non-clustered-index-5','pt-dbms-sql-20-non-clustered-index','If `students` is clustered on `id` and has a non-clustered index on `department`, what does the non-clustered index''s pointer typically reference?','["Nothing; it stores full rows directly", "The clustered key value (e.g., the id), used to then find the full row via the clustered index", "A random row in the table", "Another non-clustered index"]'::jsonb,1,'On a clustered table, non-clustered index entries typically point via the clustered key, which is then used to locate the actual row.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-non-clustered-index-6','pt-dbms-sql-20-non-clustered-index','Why might a table have non-clustered indexes on department, gpa, AND email simultaneously?','["Because only one index total is allowed per table", "Because each non-clustered index optimizes a different query pattern without affecting the single physical row order", "Because non-clustered indexes replace the need for a table entirely", "Because SQL requires every column to be indexed"]'::jsonb,1,'Multiple non-clustered indexes let different queries each get fast lookups on their respective filter columns, all independent of physical storage order.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-non-clustered-index-7','pt-dbms-sql-20-non-clustered-index','What is a real cost of adding many non-clustered indexes to a table?','["The table can no longer be read from", "Inserts, deletes and updates to relevant indexed keys or stored locators can add maintenance work and write overhead", "Non-clustered indexes make the clustered index disappear", "Reads become slower with more non-clustered indexes"]'::jsonb,1,'Inserts, deletes and changes to indexed keys or stored row locators can require secondary-index maintenance. Updating an unrelated nonindexed column need not rewrite every secondary entry.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-non-clustered-index-8','pt-dbms-sql-20-non-clustered-index','How can the extra ''bookmark lookup'' hop of a non-clustered index be avoided for a specific query?','["It cannot ever be avoided", "By using a covering index that includes all columns the query needs, directly in the index itself", "By deleting the clustered index", "By converting the non-clustered index into a hash index"]'::jsonb,1,'A covering index can avoid a clustered lookup for missing row values. InnoDB can still require clustered access forMVCCvisibility under some conditions, so do not promise it never consults the clustered record.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-non-clustered-index-fundamentals-9','pt-dbms-sql-20-non-clustered-index','What does an InnoDB secondary index entry use to locate the full row?','["The clustered key", "A universal raw memory address", "The table name only", "The SELECT alias"]'::jsonb,0,'Secondary entries include the clustered key values.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
