if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-repeatable-read-1' and (question_text,options,correct_index,explanation) is distinct from ('What is the defining condition of a non-repeatable read?','["A transaction reads uncommitted data from another transaction", "A transaction reads the same data item twice within its own lifetime and gets two different values, because another transaction committed a change to that item in between", "A transaction inserts a duplicate row", "A transaction reads a row that was deleted"]'::jsonb,1,'Non-repeatable read specifically requires two reads of the SAME item within one transaction returning different values due to an intervening committed change from another transaction.') and (question_text,options,correct_index,explanation) is distinct from ('What is the defining condition of a non-repeatable read?','["A transaction reads uncommitted data from another transaction", "A transaction reads the same data item twice within its own lifetime and gets two different values, because another transaction committed a change to that item in between", "A transaction inserts a duplicate row", "A transaction reads a row that was deleted"]'::jsonb,1,'Non-repeatable read specifically requires two reads of the SAME item within one transaction returning different values due to an intervening committed change from another transaction.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-non-repeatable-read-1'; end if;
