if not exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-repeatable-read-2' and test_id='pt-dbms-sql-23-non-repeatable-read') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-23-non-repeatable-read-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-repeatable-read-2' and (question_text,options,correct_index,explanation) is distinct from ('In the worked example, what two values does T1 read for A across its two reads, and why do they differ?','["1000 both times, because T2 didn''t affect T1", "1000 then 1500, because T2 deposited 500 and COMMITTED in between T1''s two reads", "1500 then 1000, because T1''s own write reduced the balance", "0 then 1000, because T1''s first read failed"]'::jsonb,1,'T1 first reads 1000, then T2 deposits 500 and commits, and T1''s second read sees the new, committed value 1500 — two different values for the same item within one transaction.') and (question_text,options,correct_index,explanation) is distinct from ('In the worked example, what two values does T1 read for A across its two reads, and why do they differ?','["1000 both times, because T2 didn''t affect T1", "1000 then 1500, because T2 deposited 500 and COMMITTED in between T1''s two reads", "1500 then 1000, because T1''s own write reduced the balance", "0 then 1000, because T1''s first read failed"]'::jsonb,1,'T1 first reads 1000, then T2 deposits 500 and commits, and T1''s second read sees the new, committed value 1500 — two different values for the same item within one transaction.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-non-repeatable-read-2'; end if;
