if not exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-repeatable-read-3' and test_id='pt-dbms-sql-23-non-repeatable-read') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-23-non-repeatable-read-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-repeatable-read-3' and (question_text,options,correct_index,explanation) is distinct from ('Why is the example in this topic NOT classified as a dirty read?','["Because T1 never actually commits", "Because T2''s write to A was fully committed BEFORE T1''s second read \u2014 T1 never observed an uncommitted (dirty) value at any point", "Because dirty reads only apply to DELETE statements", "Because T1 only read A once"]'::jsonb,1,'The key distinguishing fact is that T2 committed cleanly before T1''s second read; T1 never saw data that might later be rolled back, which is what would make it a dirty read.') and (question_text,options,correct_index,explanation) is distinct from ('Why is the example in this topic NOT classified as a dirty read?','["Because T1 never actually commits", "Because T2''s write to A was fully committed BEFORE T1''s second read \u2014 T1 never observed an uncommitted (dirty) value at any point", "Because dirty reads only apply to DELETE statements", "Because T1 only read A once"]'::jsonb,1,'The key distinguishing fact is that T2 committed cleanly before T1''s second read; T1 never saw data that might later be rolled back, which is what would make it a dirty read.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-non-repeatable-read-3'; end if;
