if not exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-repeatable-read-4' and test_id='pt-dbms-sql-23-non-repeatable-read') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-23-non-repeatable-read-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-repeatable-read-4' and (question_text,options,correct_index,explanation) is distinct from ('Can a non-repeatable read occur if a transaction reads a given data item only ONCE during its lifetime?','["Yes, a single read is enough to trigger it", "No \u2014 by definition, non-repeatable read requires the SAME transaction to read the same item at least twice, with the values differing between reads", "Yes, if the item was inserted after the transaction started", "Only if the transaction is read-only"]'::jsonb,1,'The anomaly is inherently about disagreement BETWEEN two reads of the same item in one transaction; with only one read, there is nothing to compare, so it cannot occur.') and (question_text,options,correct_index,explanation) is distinct from ('Can a non-repeatable read occur if a transaction reads a given data item only ONCE during its lifetime?','["Yes, a single read is enough to trigger it", "No \u2014 by definition, non-repeatable read requires the SAME transaction to read the same item at least twice, with the values differing between reads", "Yes, if the item was inserted after the transaction started", "Only if the transaction is read-only"]'::jsonb,1,'The anomaly is inherently about disagreement BETWEEN two reads of the same item in one transaction; with only one read, there is nothing to compare, so it cannot occur.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-non-repeatable-read-4'; end if;
