if not exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-repeatable-read-5' and test_id='pt-dbms-sql-23-non-repeatable-read') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-23-non-repeatable-read-5'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-repeatable-read-5' and (question_text,options,correct_index,explanation) is distinct from ('What isolation-level mechanism prevents non-repeatable reads?','["Disallowing all write operations globally", "Holding read locks on a data item for the ENTIRE duration of the reading transaction, so no other transaction can commit a change to it until the reader finishes", "Allowing dirty reads to compensate", "Running every transaction serially with no exceptions"]'::jsonb,1,'By holding the read lock beyond the individual read statement and through the whole transaction, other transactions are blocked from writing/committing changes to that item until the reader is done — this is the REPEATABLE READ guarantee.') and (question_text,options,correct_index,explanation) is distinct from ('Which mechanisms can prevent the stated nonrepeatable ordinary read, depending on the engine?','["Only a full database shutdown", "A suitable repeatable committed snapshot or an appropriate held read-lock protocol", "Disabling every transaction", "Removing all primary keys"]'::jsonb,1,'InnoDB ordinary REPEATABLE READ commonly uses version visibility. Lock retention is another mechanism; not every committed reader must block every writer.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-non-repeatable-read-5'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-repeatable-read-6' and test_id<>'pt-dbms-sql-23-non-repeatable-read') then raise exception 'Question ID collision: %', 'tq-dbms-sql-23-non-repeatable-read-6'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-repeatable-read-6' and test_id='pt-dbms-sql-23-non-repeatable-read') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-23-non-repeatable-read-6'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-repeatable-read-6' and (question_text,options,correct_index,explanation) is distinct from ('How does non-repeatable read differ from a lost update?','["They are the same anomaly under different names", "A lost update involves TWO transactions both writing based on stale reads, with one write silently erasing the other; non-repeatable read involves ONE transaction reading the same item twice and observing a legitimately committed change made by another transaction", "Non-repeatable read only occurs with INSERT statements", "A lost update requires at least three transactions"]'::jsonb,1,'These are distinct mechanisms: lost update is about a write being clobbered; non-repeatable read is about a reading transaction''s own view of a value shifting between two of its own reads.') and (question_text,options,correct_index,explanation) is distinct from ('How does non-repeatable read differ from a lost update?','["They are the same anomaly under different names", "A lost update involves TWO transactions both writing based on stale reads, with one write silently erasing the other; non-repeatable read involves ONE transaction reading the same item twice and observing a legitimately committed change made by another transaction", "Non-repeatable read only occurs with INSERT statements", "A lost update requires at least three transactions"]'::jsonb,1,'A lost update concerns an overwritten intended effect. The nonrepeatable-read example requires only repeated committed observations and need not include any write by the reader.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-non-repeatable-read-6'; end if;
