if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-serial-schedule-1' and (question_text,options,correct_index,explanation) is distinct from ('What makes a schedule ''non-serial''?','["It involves more than 5 transactions", "At least one operation of one transaction is interleaved between operations of another transaction \u2014 no transaction fully completes before the next begins", "It always ends in an abort", "It never involves a COMMIT"]'::jsonb,1,'Non-serial simply means the operations of the transactions overlap in time, unlike a serial schedule where one transaction fully finishes before the next starts.') and (question_text,options,correct_index,explanation) is distinct from ('What makes a schedule ''non-serial''?','["It involves more than 5 transactions", "Operations from different transactions interleave rather than forming one uninterrupted block per transaction", "It always ends in an abort", "It never involves a COMMIT"]'::jsonb,1,'Some transactions may finish before others start; the presence of interleaving elsewhere is enough for a nonserial history.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-non-serial-schedule-1'; end if;
