if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-serial-schedule-2' and (question_text,options,correct_index,explanation) is distinct from ('In worked schedule S1 in this topic, is the final state (A=990, B=2310) the same as some serial schedule''s result?','["No, it is a completely unique result impossible under any serial order", "Yes \u2014 it matches the result of the serial schedule <T1, T2>, even though the operations were interleaved", "It cannot be determined without running the schedule twice", "Yes, it matches <T2, T1>"]'::jsonb,1,'Tracing S1 shows the final balances exactly match the serial schedule <T1, T2>, because T2''s reads always land after T1 has already updated the relevant item.') and (question_text,options,correct_index,explanation) is distinct from ('In the stated A=1000,B=2000 example,T1 transfers100 andT2 applies10% afterT1 on each item. Which serial order has final A=990,B=2310?','["No, it is a completely unique result impossible under any serial order", "Yes \u2014 it matches the result of the serial schedule <T1, T2>, even though the operations were interleaved", "It cannot be determined without running the schedule twice", "Yes, it matches <T2, T1>"]'::jsonb,1,'T1 thenT2 gives900×1.1=990 and2100×1.1=2310. Recovery and engine permissibility remain separate.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-non-serial-schedule-2'; end if;
