if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-non-serial-schedule-3' and (question_text,options,correct_index,explanation) is distinct from ('What is the key open question a non-serial schedule raises that a serial schedule never does?','["Whether the transactions will ever commit", "Whether the interleaved result is equivalent to some serial execution, or whether it produces a state no serial order could ever produce", "Whether the schedule uses SQL correctly", "Whether the transactions touch the same table"]'::jsonb,1,'A serial schedule is correct by definition; a non-serial schedule''s correctness must be checked via serializability, since interleaving may or may not preserve the same effective result as some serial order.') and (question_text,options,correct_index,explanation) is distinct from ('What is the key open question a non-serial schedule raises that a serial schedule never does?','["Whether the transactions will ever commit", "Whether the interleaved result is equivalent to some serial execution, or whether it produces a state no serial order could ever produce", "Whether the schedule uses SQL correctly", "Whether the transactions touch the same table"]'::jsonb,1,'Serializability tests serial-equivalence of the interaction; business correctness still depends on the transactions and invariants supplied.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-non-serial-schedule-3'; end if;
