update public.learning_topics set short_description='Trace interleaved transaction schedules, distinguish serializability from matching final values, construct conflict graphs and separate recovery properties from business correctness.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Trace interleaved transaction schedules, distinguish serializability from matching final values, construct conflict graphs and separate recovery properties from business correctness.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Non Serial Schedule.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-23-non-serial-schedule' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-23-non-serial-schedule-application','MCQ Test 2',category,10,10,'Application and scenarios for Non Serial Schedule.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-23-non-serial-schedule' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-non-serial-schedule-1','pt-dbms-sql-23-non-serial-schedule','What makes a schedule ''non-serial''?','["It involves more than 5 transactions", "Operations from different transactions interleave rather than forming one uninterrupted block per transaction", "It always ends in an abort", "It never involves a COMMIT"]'::jsonb,1,'Some transactions may finish before others start; the presence of interleaving elsewhere is enough for a nonserial history.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-non-serial-schedule-2','pt-dbms-sql-23-non-serial-schedule','In the stated A=1000,B=2000 example,T1 transfers100 andT2 applies10% afterT1 on each item. Which serial order has final A=990,B=2310?','["No, it is a completely unique result impossible under any serial order", "Yes — it matches the result of the serial schedule <T1, T2>, even though the operations were interleaved", "It cannot be determined without running the schedule twice", "Yes, it matches <T2, T1>"]'::jsonb,1,'T1 thenT2 gives900×1.1=990 and2100×1.1=2310. Recovery and engine permissibility remain separate.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-non-serial-schedule-3','pt-dbms-sql-23-non-serial-schedule','What is the key open question a non-serial schedule raises that a serial schedule never does?','["Whether the transactions will ever commit", "Whether the interleaved result is equivalent to some serial execution, or whether it produces a state no serial order could ever produce", "Whether the schedule uses SQL correctly", "Whether the transactions touch the same table"]'::jsonb,1,'Serializability tests serial-equivalence of the interaction; business correctness still depends on the transactions and invariants supplied.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-non-serial-schedule-4','pt-dbms-sql-23-non-serial-schedule','Which theoretical tools determine whether a given non-serial schedule is ''safe'' (serializable)?','["Only the DBMS''s query optimizer", "Conflict serializability and view serializability", "The number of tables involved", "The transaction isolation level configured by the DBA"]'::jsonb,1,'Conflict serializability (practical, used by real concurrency control protocols) and view serializability (a broader, more theoretical notion) are exactly the tools used to judge non-serial schedule correctness.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-non-serial-schedule-5','pt-dbms-sql-23-non-serial-schedule','What is the goal of a concurrency protocol configured to enforce serializable execution?','["To prevent any non-serial schedule from ever occurring", "To ensure that only serializable non-serial schedules are allowed to execute, combining interleaving''s speed with serial execution''s correctness guarantee", "To force every schedule to become serial", "To speed up disk I/O directly"]'::jsonb,1,'The scope is explicitly serializable execution. Weaker supported isolation modes need not reject every nonserializable history.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-non-serial-schedule-6','pt-dbms-sql-23-non-serial-schedule','In the stated formal read/write model, does conflict-serializability analysis require understanding the business meaning of each arithmetic operation?','["Yes, semantic understanding is required", "No — serializability analysis only needs to know which data items are read/written and their relative order, regardless of what the operations ''mean''", "Only for financial applications", "Only if the transaction spans multiple tables"]'::jsonb,1,'Conflict analysis uses transaction owners, items, access types and order. Application validity and richer predicate/version models need additional reasoning.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-non-serial-schedule-7','pt-dbms-sql-23-non-serial-schedule','Is it possible for more than two transactions to interleave in a single non-serial schedule?','["No, non-serial schedules are limited to exactly two transactions", "Yes — the same serializability analysis techniques generalize to any number of concurrently interleaved transactions", "Only if all transactions are read-only", "Only in distributed databases"]'::jsonb,1,'Non-serial schedules and the tools to analyze them (precedence graphs, etc.) work for any number of transactions, not just two.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-non-serial-schedule-8','pt-dbms-sql-23-non-serial-schedule','Which statement correctly summarizes the relationship between ''non-serial'' and ''incorrect''?','["Non-serial and incorrect mean the same thing", "Nonserial only describes interleaving; serializability,recovery and application invariants require their own checks", "All non-serial schedules are incorrect by definition", "Only serial schedules can ever be interleaved"]'::jsonb,1,'Interleaving alone neither proves nor disproves any complete application correctness claim.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-non-serial-schedule-new-9','pt-dbms-sql-23-non-serial-schedule','Which pair conflicts in the single-version item model?','["r1(A) and r2(A)", "r1(A) and w2(A)", "r1(A) and w2(B)", "Two reads byT1 alone"]'::jsonb,1,'Different owners, same item and a write establish conflict.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
