insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-null-functions-5','pt-dbms-sql-14-null-functions','What is the correct way to test whether a column''s value is NULL in a WHERE clause, across all SQL dialects?','["WHERE amount = NULL", "WHERE ISNULL(amount)", "WHERE amount IS NULL", "WHERE amount == NULL"]'::jsonb,2,'IS NULL (with a space) is the universal operator for testing NULL; = NULL never works because NULL = NULL evaluates to NULL, not TRUE.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
