update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for NULL Ordering.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-13-null-ordering' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-13-null-ordering-application','MCQ Test 2',category,10,10,'Application and scenarios for NULL Ordering.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-13-null-ordering' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-null-ordering-1','pt-dbms-sql-13-null-ordering','Where does PostgreSQL 18 ordinarily place NULL for an ascending term?','["First", "Last", "It removes NULL rows", "It raises an error"]'::jsonb,1,'Its default differs from MySQL’s ascending placement.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-null-ordering-2','pt-dbms-sql-13-null-ordering','Where does MySQL 8.4 ordinarily place NULL for an ascending term?','["Last", "First", "It replaces NULL with zero", "It always filters NULL"]'::jsonb,1,'This is an ordering convention, not ordinary numeric comparison.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-null-ordering-3','pt-dbms-sql-13-null-ordering','What native syntax can PostgreSQL attach to an ordering term?','["NULLS FIRST or NULLS LAST", "SKIP UNKNOWN", "GROUP NULLS", "NULLS EQUAL ZERO"]'::jsonb,0,'Use the target engine’s supported form.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-null-ordering-4','pt-dbms-sql-13-null-ordering','Why can the same short ascending query differ between MySQL and PostgreSQL?','["Their SELECT lists always reverse", "Their default missing-value placements differ", "MySQL cannot sort numbers", "PostgreSQL always removes unknowns"]'::jsonb,1,'Explicit policies make migration differences visible.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-null-ordering-5','pt-dbms-sql-13-null-ordering','Why state NULL placement explicitly in a report contract?','["It always makes the query faster", "Every ORDER BY otherwise fails", "Defaults can differ across engines and feature expectations", "It automatically validates missing data"]'::jsonb,2,'The contract should not depend on an accidental target default.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-null-ordering-6','pt-dbms-sql-13-null-ordering','Where does PostgreSQL 18 ordinarily place NULL for a descending term?','["Last", "First", "Nowhere", "Always between equal known values"]'::jsonb,1,'That is its default missingness placement.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-null-ordering-7','pt-dbms-sql-13-null-ordering','Which MySQL ordering form puts known ascending values before NULL?','["ORDER BY value IS NULL ASC,value ASC", "WHERE value IS NOT NULL only", "ORDER BY value ASC only", "GROUP BY value IS NULL"]'::jsonb,0,'The known group has missingness flag zero.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-null-ordering-8','pt-dbms-sql-13-null-ordering','Which statement about ordering defaults is accurate?','["All engines put NULL last ascending", "They can differ by engine, so verify the intended placement", "NULL cannot be sorted", "NULLS FIRST and LAST are equivalent"]'::jsonb,1,'Dialect differences are observable behaviour.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-null-ordering-new-9','pt-dbms-sql-13-null-ordering','Does MySQL NULL-first ascending mean NULL < 0 is TRUE?','["No, ordinary comparison still yields UNKNOWN", "Yes, NULL is numeric negative infinity", "Only if zero is indexed", "Only in WHERE"]'::jsonb,0,'Sort placement and predicate semantics differ.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
