if exists(select 1 from public.dsa_problems where (id='cx-numeric-exact-rounding' or slug='numeric-exact-rounding') and (id<>'cx-numeric-exact-rounding' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cx-numeric-exact-rounding'; end if;
if exists(select 1 from public.dsa_problems where id='cx-numeric-exact-rounding' and description is distinct from 'Return adjustment_id,rounded_value,truncated_value from adjustments ordered by adjustment_id. Round exact amount to two decimal places with ROUND and truncate to two places with TRUNCATE. Retain NULL outputs for missing amounts and preserve source data.

**MySQL dialect.**

```sql
CREATE TABLE adjustments(adjustment_id INT PRIMARY KEY,amount DECIMAL(8,3));
INSERT INTO adjustments VALUES (1,12.345),(2,-12.345),(3,0.009),(4,NULL);
```

**Required ordering:** adjustment_id ASC.

**Edge cases:**
- Negative exact halves round away from zero.
- Truncation discards digits instead of selecting the nearest value.
- NULL remains NULL.') then raise exception 'New coding ID already has other content: %', 'cx-numeric-exact-rounding'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-numeric-exact-rounding',null::text,'Compare rounding with decimal truncation','Easy','numeric-exact-rounding','Return adjustment_id,rounded_value,truncated_value from adjustments ordered by adjustment_id. Round exact amount to two decimal places with ROUND and truncate to two places with TRUNCATE. Retain NULL outputs for missing amounts and preserve source data.

**MySQL dialect.**

```sql
CREATE TABLE adjustments(adjustment_id INT PRIMARY KEY,amount DECIMAL(8,3));
INSERT INTO adjustments VALUES (1,12.345),(2,-12.345),(3,0.009),(4,NULL);
```

**Required ordering:** adjustment_id ASC.

**Edge cases:**
- Negative exact halves round away from zero.
- Truncation discards digits instead of selecting the nearest value.
- NULL remains NULL.','[{"input": "INSERT INTO adjustments VALUES (1,12.345),(2,-12.345),(3,0.009),(4,NULL);", "output": "adjustment_id\trounded_value\ttruncated_value\n1\t12.35\t12.34\n2\t-12.35\t-12.34\n3\t0.01\t0.00\n4\tNULL\tNULL", "explanation": "The exact decimal halfway values round away from zero, while truncation discards the third decimal digit toward zero. Both expressions preserve NULL rather than introduce a numerical default."}]'::jsonb,'[{"seed_sql": "INSERT INTO adjustments VALUES (8,-0.004),(2,9.999),(5,4.000);", "expected": "adjustment_id\trounded_value\ttruncated_value\n2\t10.00\t9.99\n5\t4.00\t4.00\n8\t0.00\t0.00", "hidden": true}, {"seed_sql": "INSERT INTO adjustments VALUES (1,NULL);", "expected": "adjustment_id\trounded_value\ttruncated_value\n1\tNULL\tNULL", "hidden": true}, {"seed_sql": "", "expected": "", "hidden": true}]'::jsonb,'["Use the supplied exact DECIMAL expression.", "Preserve signed values and missingness."]'::jsonb,'["Both functions accept the requested precision as their second argument.", "Do not replace TRUNCATE with FLOOR."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The exact decimal halfway values round away from zero, while truncation discards the third decimal digit toward zero. Both expressions preserve NULL rather than introduce a numerical default.','{"sql": "SELECT adjustment_id,ROUND(amount,2) AS rounded_value,TRUNCATE(amount,2) AS truncated_value FROM adjustments ORDER BY adjustment_id;"}'::jsonb,'The exact decimal halfway values round away from zero, while truncation discards the third decimal digit toward zero. Both expressions preserve NULL rather than introduce a numerical default.',array['sql'],'CREATE TABLE adjustments(adjustment_id INT PRIMARY KEY,amount DECIMAL(8,3));','INSERT INTO adjustments VALUES (1,12.345),(2,-12.345),(3,0.009),(4,NULL);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-14-numeric-functions' on conflict(id) do nothing;
if exists(select 1 from public.dsa_problems where (id='cx-numeric-packaging-metrics' or slug='numeric-packaging-metrics') and (id<>'cx-numeric-packaging-metrics' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cx-numeric-packaging-metrics'; end if;
if exists(select 1 from public.dsa_problems where id='cx-numeric-packaging-metrics' and description is distinct from 'Return shipment_id,complete_boxes,loose_units,boxes_needed for every shipments row ordered by shipment_id. For quantity>=0 and capacity>0, compute the integer quotient, remainder, and number of whole boxes needed including one for a nonzero remainder. For every invalid row, including NULL capacity, return NULL in all three metrics. Preserve input data.

**MySQL dialect.**

```sql
CREATE TABLE shipments(shipment_id INT PRIMARY KEY,quantity INT NOT NULL,capacity INT);
INSERT INTO shipments VALUES (1,10,4),(2,8,4),(3,0,5),(4,5,0),(5,-1,4),(6,4,NULL);
```

**Required ordering:** shipment_id ASC.

**Edge cases:**
- Exact multiples need no extra box.
- Zero units need zero boxes.
- Negative or missing capacity must not generate an instruction.') then raise exception 'New coding ID already has other content: %', 'cx-numeric-packaging-metrics'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-numeric-packaging-metrics',null::text,'Calculate containers with an explicit validity rule','Medium','numeric-packaging-metrics','Return shipment_id,complete_boxes,loose_units,boxes_needed for every shipments row ordered by shipment_id. For quantity>=0 and capacity>0, compute the integer quotient, remainder, and number of whole boxes needed including one for a nonzero remainder. For every invalid row, including NULL capacity, return NULL in all three metrics. Preserve input data.

**MySQL dialect.**

```sql
CREATE TABLE shipments(shipment_id INT PRIMARY KEY,quantity INT NOT NULL,capacity INT);
INSERT INTO shipments VALUES (1,10,4),(2,8,4),(3,0,5),(4,5,0),(5,-1,4),(6,4,NULL);
```

**Required ordering:** shipment_id ASC.

**Edge cases:**
- Exact multiples need no extra box.
- Zero units need zero boxes.
- Negative or missing capacity must not generate an instruction.','[{"input": "INSERT INTO shipments VALUES (1,10,4),(2,8,4),(3,0,5),(4,5,0),(5,-1,4),(6,4,NULL);", "output": "shipment_id\tcomplete_boxes\tloose_units\tboxes_needed\n1\t2\t2\t3\n2\t2\t0\t2\n3\t0\t0\t0\n4\tNULL\tNULL\tNULL\n5\tNULL\tNULL\tNULL\n6\tNULL\tNULL\tNULL", "explanation": "The validity condition separates calculations from rejected denominator or quantity states. DIV counts complete boxes and MOD identifies loose units. Adding one when the remainder is positive counts a partial box without rounding a fractional quotient first. Invalid rows remain visible with NULL metrics."}]'::jsonb,'[{"seed_sql": "INSERT INTO shipments VALUES (9,1,3),(2,0,0),(6,7,-2),(3,12,3);", "expected": "shipment_id\tcomplete_boxes\tloose_units\tboxes_needed\n2\tNULL\tNULL\tNULL\n3\t4\t0\t4\n6\tNULL\tNULL\tNULL\n9\t0\t1\t1", "hidden": true}, {"seed_sql": "INSERT INTO shipments VALUES (1,0,NULL);", "expected": "shipment_id\tcomplete_boxes\tloose_units\tboxes_needed\n1\tNULL\tNULL\tNULL", "hidden": true}, {"seed_sql": "", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO shipments VALUES (1,100001,100000),(2,1,100000);", "expected": "shipment_id\tcomplete_boxes\tloose_units\tboxes_needed\n1\t1\t1\t2\n2\t0\t1\t1", "hidden": true}]'::jsonb,'["Valid quantity is nonnegative and valid capacity is positive.", "Keep invalid rows visible with uncomputed metrics.", "Do not treat zero capacity as one."]'::jsonb,'["Use CASE to enforce the domain for each computed result.", "Use DIV for the integer quotient and MOD for the remainder; add one to the quotient when a positive remainder needs a final box."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The validity condition separates calculations from rejected denominator or quantity states. DIV counts complete boxes and MOD identifies loose units. Adding one when the remainder is positive counts a partial box without rounding a fractional quotient first. Invalid rows remain visible with NULL metrics.','{"sql": "SELECT shipment_id,CASE WHEN quantity>=0 AND capacity>0 THEN quantity DIV NULLIF(capacity,0) END AS complete_boxes,CASE WHEN quantity>=0 AND capacity>0 THEN MOD(quantity,NULLIF(capacity,0)) END AS loose_units,CASE WHEN quantity>=0 AND capacity>0 THEN (quantity DIV NULLIF(capacity,0))+(MOD(quantity,NULLIF(capacity,0))>0) END AS boxes_needed FROM shipments ORDER BY shipment_id;"}'::jsonb,'The validity condition separates calculations from rejected denominator or quantity states. DIV counts complete boxes and MOD identifies loose units. Adding one when the remainder is positive counts a partial box without rounding a fractional quotient first. Invalid rows remain visible with NULL metrics.',array['sql'],'CREATE TABLE shipments(shipment_id INT PRIMARY KEY,quantity INT NOT NULL,capacity INT);','INSERT INTO shipments VALUES (1,10,4),(2,8,4),(3,0,5),(4,5,0),(5,-1,4),(6,4,NULL);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-14-numeric-functions' on conflict(id) do nothing;
