insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-offset-1','pt-dbms-sql-13-offset','What does OFFSET count?','["A minimum identifier value", "Rows skipped in the qualifying result sequence", "The number of table columns", "The number of returned rows"]'::jsonb,1,'Positions depend on eligibility and ordering.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-offset-2','pt-dbms-sql-13-offset','LIMIT 10 OFFSET 20 admits which positions if enough rows qualify?','["Positions 1 through 10", "Positions 21 through 30", "Positions 1 through 20", "Always the last ten"]'::jsonb,1,'The first twenty result rows are skipped.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-offset-3','pt-dbms-sql-13-offset','Why can deep offsets be costly despite small returned pages?','["Offsets above one hundred always fail", "The engine can need substantial work accounting for the skipped prefix", "OFFSET locks the whole table necessarily", "The result must contain one million rows"]'::jsonb,1,'Measure actual plans rather than assert a fixed physical count.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-offset-4','pt-dbms-sql-13-offset','What happens when the offset exceeds the qualifying row count?','["The offset is ignored", "The result is empty", "The table is deleted", "A required exception is raised"]'::jsonb,1,'No rows remain after the skipped prefix.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-offset-5','pt-dbms-sql-13-offset','Should identical page sizes imply identical work at shallow and deep offsets?','["Yes, output size fully determines work", "No, depth and plan can materially affect cost", "Only if rows have integers", "Only if the limit is twenty"]'::jsonb,1,'Returned size and preceding work are distinct.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-offset-6','pt-dbms-sql-13-offset','What does OFFSET without a defined order fail to provide for page navigation?','["Any valid SQL result", "A specified sequence of identities to skip", "A numeric row limit", "The ability to return no rows"]'::jsonb,1,'An arbitrary slice is insufficient for a defined page contract.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-offset-7','pt-dbms-sql-13-offset','Which continuation method can avoid counting a deep positional prefix?','["Removing all ordering", "Keyset pagination using the actual ordering tuple", "Increasing offset every time without a bound", "Using any convenient id regardless of order"]'::jsonb,1,'The key comparisons must match the ranking contract.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-offset-8','pt-dbms-sql-13-offset','Seven rows qualify, LIMIT 5 OFFSET 5. How many rows return?','["Five", "Two", "Zero", "Seven"]'::jsonb,1,'The cap admits only the remaining rows.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-offset-new-9','pt-dbms-sql-13-offset','Does skipping two rows mean equipment_id>2?','["No", "Yes, identifiers always equal positions", "Only in every sorted query", "Only if the id has an index"]'::jsonb,0,'Identifiers can have gaps and the result may use another order.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-offset-new-10','pt-dbms-sql-13-offset','For one-based page p with size s, what is the usual offset?','["p*s always", "(p-1)*s", "p+s", "s-p"]'::jsonb,1,'Page one skips zero earlier pages.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-offset-application-new-1','pt-dbms-sql-13-offset-application','What can a zero-based versus one-based mismatch cause?','["Automatic schema correction", "Repeated or missing page slices", "An invalid primary key", "A guaranteed SQL syntax error"]'::jsonb,1,'The arithmetic can be valid while the navigation contract is wrong.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-offset-application-new-2','pt-dbms-sql-13-offset-application','Should closed requests consume positions in an active-only page?','["Yes, every table row counts", "Only if they have high scores", "No, eligibility defines the sequence first", "Only if ids are consecutive"]'::jsonb,2,'Filter scope must match the requested page population.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-offset-application-new-3','pt-dbms-sql-13-offset-application','Why add a unique final key around offset boundaries?','["To freeze every future update", "To remove the skipped prefix permanently", "To guarantee a constant-time plan", "To specify equal-ranking row order for a fixed visible dataset"]'::jsonb,3,'Incomplete ties can change slice membership.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-offset-application-new-4','pt-dbms-sql-13-offset-application','What can an insertion before the second-page boundary cause?','["An identity can repeat or shift relative to the earlier page", "The first page becomes a transaction lock", "Every offset remains tied to the original snapshot", "The database always rejects the next request"]'::jsonb,0,'Separate requests can observe different positions.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-offset-application-new-5','pt-dbms-sql-13-offset-application','Does a complete order guarantee stable cross-request membership?','["Yes, for every live dataset", "No, visibility and continuation policy are separate", "Only if all terms ascend", "Only if every id is numeric"]'::jsonb,1,'Determinism applies to the observed result.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-offset-application-new-6','pt-dbms-sql-13-offset-application','Why inspect result grain before offsetting joined rows?','["Joins cannot be sorted", "Every join has unique equipment ids", "Several joined rows can belong to one intended displayed item", "OFFSET automatically groups whole items"]'::jsonb,2,'A positional slice counts result rows, not implied entities.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-offset-application-new-7','pt-dbms-sql-13-offset-application','What should happen to unsupported negative paging input?','["Silently broaden the request", "Concatenate it directly into SQL", "Treat it as all pages", "Reject or handle it through the explicit trusted validation contract"]'::jsonb,3,'Malformed input should not remove limits or scope.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-offset-application-new-8','pt-dbms-sql-13-offset-application','How does MySQL’s comma LIMIT form order its two arguments?','["Offset first, row count second", "Row count first, offset second", "Both are sort keys", "Both are filter thresholds"]'::jsonb,0,'The keyword form can make their roles clearer.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-offset-application-new-9','pt-dbms-sql-13-offset-application','Is OFFSET always the wrong design?','["Yes, even for tiny static tables", "No, choose according to scale, navigation needs and measured costs", "Only if an index exists", "Only if the UI uses page numbers"]'::jsonb,1,'Offset and keyset offer different tradeoffs.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-13-offset-application-new-10','pt-dbms-sql-13-offset-application','How can a small fixture be checked manually?','["Filter id by the offset value", "Ignore inactive rows only after slicing", "List the qualified complete sequence, skip the prefix, take up to the limit", "Count table rows without ordering"]'::jsonb,2,'This directly models the query contract.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
