if exists(select 1 from public.dsa_problems where id='cx-offset-price-slice' and description is distinct from 'Return equipment_id,price after skipping the first two rows ordered by price ascending then equipment_id ascending, taking at most three more. All prices are known. Preserve source data.

**MySQL dialect.**

```sql
CREATE TABLE equipment_prices(equipment_id INT PRIMARY KEY,price INT NOT NULL);
INSERT INTO equipment_prices VALUES (90,1),(10,2),(70,3),(30,3),(50,4),(20,5);
```

**Required ordering:** As explicitly ordered in the result query.

**Edge cases:**
- Nonconsecutive ids are positions only after sorting.
- Skipping the entire population yields an empty result.') then raise exception 'New coding ID already has other content: %', 'cx-offset-price-slice'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-offset-price-slice',null::text,'Skip two price-ranked rows','Easy','offset-price-slice','Return equipment_id,price after skipping the first two rows ordered by price ascending then equipment_id ascending, taking at most three more. All prices are known. Preserve source data.

**MySQL dialect.**

```sql
CREATE TABLE equipment_prices(equipment_id INT PRIMARY KEY,price INT NOT NULL);
INSERT INTO equipment_prices VALUES (90,1),(10,2),(70,3),(30,3),(50,4),(20,5);
```

**Required ordering:** As explicitly ordered in the result query.

**Edge cases:**
- Nonconsecutive ids are positions only after sorting.
- Skipping the entire population yields an empty result.','[{"input": "INSERT INTO equipment_prices VALUES (90,1),(10,2),(70,3),(30,3),(50,4),(20,5);", "output": "equipment_id\tprice\n30\t3\n70\t3\n50\t4", "explanation": "The first two positions are identities 90 and 10. The slice then admits the two equal-price rows in identity order followed by the next price."}]'::jsonb,'[{"seed_sql": "INSERT INTO equipment_prices VALUES (100,1),(200,2);", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO equipment_prices VALUES (8,5),(2,5),(7,5),(1,5);", "expected": "equipment_id\tprice\n7\t5\n8\t5", "hidden": true}]'::jsonb,'["Use only the supplied synthetic tables and requested transition.", "Preserve unrelated rows."]'::jsonb,'["Calculate positions after the complete order.", "Do not replace offset with an id threshold."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The first two positions are identities 90 and 10. The slice then admits the two equal-price rows in identity order followed by the next price.','{"sql": "SELECT equipment_id,price FROM equipment_prices ORDER BY price ASC,equipment_id ASC LIMIT 3 OFFSET 2;"}'::jsonb,'The first two positions are identities 90 and 10. The slice then admits the two equal-price rows in identity order followed by the next price.',array['sql'],'CREATE TABLE equipment_prices(equipment_id INT PRIMARY KEY,price INT NOT NULL);','INSERT INTO equipment_prices VALUES (90,1),(10,2),(70,3),(30,3),(50,4),(20,5);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-13-offset' on conflict(id) do nothing;
if exists(select 1 from public.dsa_problems where (id='cx-offset-active-ranked-page' or slug='offset-active-ranked-page') and (id<>'cx-offset-active-ranked-page' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cx-offset-active-ranked-page'; end if;
if exists(select 1 from public.dsa_problems where id='cx-offset-active-ranked-page' and description is distinct from 'Return request_id,score for active requests ordered by score descending then request_id ascending, skipping one qualifying row and returning at most two more. Inactive rows must not consume positions. Scores are known.

**MySQL dialect.**

```sql
CREATE TABLE requests(request_id INT PRIMARY KEY,status VARCHAR(20) NOT NULL,score INT NOT NULL);
INSERT INTO requests VALUES (8,''closed'',100),(9,''active'',90),(2,''active'',90),(7,''active'',80),(1,''active'',70);
```

**Required ordering:** As explicitly ordered in the result query.

**Edge cases:**
- One active row is entirely skipped.
- An inactive top score does not move the active page boundary.') then raise exception 'New coding ID already has other content: %', 'cx-offset-active-ranked-page'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-offset-active-ranked-page',null::text,'Page only the active ranked population','Medium','offset-active-ranked-page','Return request_id,score for active requests ordered by score descending then request_id ascending, skipping one qualifying row and returning at most two more. Inactive rows must not consume positions. Scores are known.

**MySQL dialect.**

```sql
CREATE TABLE requests(request_id INT PRIMARY KEY,status VARCHAR(20) NOT NULL,score INT NOT NULL);
INSERT INTO requests VALUES (8,''closed'',100),(9,''active'',90),(2,''active'',90),(7,''active'',80),(1,''active'',70);
```

**Required ordering:** As explicitly ordered in the result query.

**Edge cases:**
- One active row is entirely skipped.
- An inactive top score does not move the active page boundary.','[{"input": "INSERT INTO requests VALUES (8,''closed'',100),(9,''active'',90),(2,''active'',90),(7,''active'',80),(1,''active'',70);", "output": "request_id\tscore\n9\t90\n7\t80", "explanation": "Filtering creates the active-only sequence 2,9,7,1. Skipping identity 2 admits 9 and 7; closed identity 8 never consumes a position."}]'::jsonb,'[{"seed_sql": "INSERT INTO requests VALUES (1,''closed'',99),(8,''active'',20);", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO requests VALUES (7,''active'',5),(2,''active'',5),(9,''active'',5);", "expected": "request_id\tscore\n7\t5\n9\t5", "hidden": true}]'::jsonb,'["Use only the supplied synthetic tables and requested transition.", "Preserve unrelated rows."]'::jsonb,'["Put the status rule in the qualifying query.", "Use identity to complete score ties before skipping."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'Filtering creates the active-only sequence 2,9,7,1. Skipping identity 2 admits 9 and 7; closed identity 8 never consumes a position.','{"sql": "SELECT request_id,score FROM requests WHERE status=''active'' ORDER BY score DESC,request_id ASC LIMIT 2 OFFSET 1;"}'::jsonb,'Filtering creates the active-only sequence 2,9,7,1. Skipping identity 2 admits 9 and 7; closed identity 8 never consumes a position.',array['sql'],'CREATE TABLE requests(request_id INT PRIMARY KEY,status VARCHAR(20) NOT NULL,score INT NOT NULL);','INSERT INTO requests VALUES (8,''closed'',100),(9,''active'',90),(2,''active'',90),(7,''active'',80),(1,''active'',70);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-13-offset' on conflict(id) do nothing;
