if exists(select 1 from public.test_questions where id='tq-dbms-sql-12-operator-precedence-3' and (question_text,options,correct_index,explanation) is distinct from ('How does `WHERE category = ''Books'' OR category = ''Stationery'' AND price < 100` actually get evaluated?','["As (category = ''Books'' OR category = ''Stationery'') AND price < 100", "As category = ''Books'' OR (category = ''Stationery'' AND price < 100)", "Left to right with no precedence applied", "This is a syntax error"]'::jsonb,1,'AND binding tighter than OR means the AND clause groups first.') and (question_text,options,correct_index,explanation) is distinct from ('How does Books OR Stationery AND cheap group?','["(Books OR Stationery) AND cheap", "Books OR (Stationery AND cheap)", "Books AND (Stationery OR cheap)", "It is always invalid syntax"]'::jsonb,1,'A Books row can qualify without the cheap condition.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-12-operator-precedence-3'; end if;
