insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-order-by-1','pt-dbms-sql-13-order-by','What does ORDER BY specify?','["Which rows qualify by a predicate", "The returned row sequence by named keys or expressions", "A uniqueness constraint", "The number of inserted rows"]'::jsonb,1,'It arranges the result rather than filtering it.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-order-by-2','pt-dbms-sql-13-order-by','What direction is used when an ordinary ordering term omits ASC or DESC?','["DESC", "ASC", "No defined direction", "Always text order regardless of type"]'::jsonb,1,'Name the direction explicitly when clarity helps.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
