insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-order-by-4','pt-dbms-sql-13-order-by','Why are ordinals fragile in maintained queries?','["They are always unsupported", "They always force descending order", "Changing the SELECT-list layout can silently change the sort target", "They always scan twice"]'::jsonb,2,'Use descriptive properties or aliases for clarity.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-order-by-5','pt-dbms-sql-13-order-by','Can a valid computed value be an ordering expression?','["No, only primary keys", "Yes, in appropriate query shapes", "Only after storing a new column", "Only in a procedure"]'::jsonb,1,'Expressions can represent the actual ranking quantity.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-order-by-6','pt-dbms-sql-13-order-by','What row-order guarantee exists without ORDER BY?','["Insertion order always", "Primary-key order always", "No general presentation-sequence guarantee", "First selected column always ascending"]'::jsonb,2,'Observed access order is not a stable result contract.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-order-by-7','pt-dbms-sql-13-order-by','How is reverse name ordering requested?','["ORDER BY name ASC", "SORT name REVERSE", "ORDER BY name DESC", "WHERE name DESC"]'::jsonb,2,'DESC specifies the direction of that term.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
