if exists(select 1 from public.test_questions where id='tq-dbms-sql-13-pagination-performance-2' and (question_text,options,correct_index,explanation) is distinct from ('Why does keyset pagination avoid the slowdown that OFFSET experiences at deep pages?','["It disables ORDER BY entirely", "It uses a WHERE condition on an indexed sort key, allowing an index seek directly to the right position instead of scanning and discarding rows", "It caches all previous pages permanently in the database", "It limits tables to a maximum of 1000 rows"]'::jsonb,1,'Keyset pagination''s WHERE-based seek can jump directly to the target position via an index, unlike OFFSET which must traverse every preceding row.') and (question_text,options,correct_index,explanation) is distinct from ('What opportunity does a suitable indexed keyset boundary provide?','["Automatic caching of every page", "Range access starting near the continuation boundary", "Elimination of every join", "An authorization bypass"]'::jsonb,1,'The engine may enter a useful range rather than account for a long positional prefix.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-13-pagination-performance-2'; end if;
