if exists(select 1 from public.test_questions where id='tq-dbms-sql-13-pagination-performance-5' and (question_text,options,correct_index,explanation) is distinct from ('Roughly how does LIMIT/OFFSET query cost scale as the offset (m) grows, assuming the sort column is indexed?','["Constant time, O(1)", "Roughly linear, O(m)", "Roughly logarithmic, O(log m)", "It decreases as m increases"]'::jsonb,1,'The engine must still traverse and discard on the order of m rows/index entries before returning the requested page, giving roughly linear cost in m.') and (question_text,options,correct_index,explanation) is distinct from ('In a simple ordered index scan, what tends to grow as the skipped prefix grows?','["The requested output column count", "The work traversing preceding entries", "The guaranteed rows returned beyond LIMIT", "The number of primary keys per row"]'::jsonb,1,'This access-pattern model explains deep-offset cost without asserting universal timing complexity.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-13-pagination-performance-5'; end if;
