update public.learning_topics set short_description='Prove partial versus full functional dependency using key subsets, closures and enrollment examples, including alternative candidate keys and surrogate-key pitfalls.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Prove partial versus full functional dependency using key subsets, closures and enrollment examples, including alternative candidate keys and surrogate-key pitfalls.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Partial Dependency.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-21-partial-dependency' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-partial-dependency-application','MCQ Test 2',category,10,10,'Application and scenarios for Partial Dependency.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-21-partial-dependency' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-partial-dependency-1','pt-dbms-sql-21-partial-dependency','Why is CourseName considered partially dependent on the key {StudentID, CourseID}?','["Because CourseName is a text field", "Because CourseID alone (a proper subset of the key) already determines CourseName, making StudentID unnecessary for that determination", "Because CourseName changes over time", "Because StudentID alone determines CourseName"]'::jsonb,1,'Partial dependency means the attribute only needs part of the composite key. CourseID alone fixes CourseName; StudentID contributes nothing to that determination.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-partial-dependency-2','pt-dbms-sql-21-partial-dependency','Which attribute in the running example is the ONLY one that is fully (not partially) dependent on {StudentID, CourseID}?','["StudentName", "CourseName", "EnrollmentDate", "InstructorOffice"]'::jsonb,2,'EnrollmentDate genuinely requires both StudentID and CourseID together; every other non-key attribute (StudentName, CourseName, InstructorID/Name/Office) is determined by just one part of the key.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-partial-dependency-3','pt-dbms-sql-21-partial-dependency','If every candidate key is a single attribute and there are no nontrivial empty-determinant dependencies, why is ordinary partial-key dependency absent?','["Surrogate keys are always unique", "There is no proper nonempty subset of any candidate key to determine a nonprime attribute", "Surrogate keys are never referenced", "Single keys are always nonnumeric"]'::jsonb,1,'A single-column PRIMARY KEY alone is insufficient when a composite alternative candidate key exists; the stated all-key and empty-determinant assumptions are necessary.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-partial-dependency-4','pt-dbms-sql-21-partial-dependency','What is the direct consequence of CourseName being partially dependent on the key, as seen in the sample data?','["CourseName cannot be queried", "''Database Systems'' is physically repeated once per student enrolled in C1, instead of being stored once per course — the redundancy from topic 21.1", "CourseName becomes a foreign key", "The table automatically splits into two tables"]'::jsonb,1,'Because CourseName only needs CourseID but is stored in a table keyed by the bigger composite key, its value is duplicated across every row sharing that CourseID.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-partial-dependency-5','pt-dbms-sql-21-partial-dependency','Which of these statements about partial dependency is TRUE?','["It is unrelated to normal forms", "2NF requires 1NF and full dependency of every nonprime attribute on every candidate key", "Partial dependency means a SQL NULL", "Partial dependency concerns only primary-key names"]'::jsonb,1,'The normal-form restriction concerns nonprime attributes against every candidate key, not all dependencies on arbitrary superkeys.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-partial-dependency-6','pt-dbms-sql-21-partial-dependency','If StudentCourse had TWO candidate keys instead of one, how should partial dependency be checked?','["Only against the chosen primary key", "Against every candidate key, since an attribute could be partially dependent on one candidate key even if fully dependent on another", "Partial dependency does not apply when there are multiple candidate keys", "Only against the candidate key with the fewest attributes"]'::jsonb,1,'2NF requires checking full/partial dependency against every candidate key of the relation, not just whichever one was designated primary.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-partial-dependency-7','pt-dbms-sql-21-partial-dependency','In the 2NF fix previewed for this table, which relation does CourseName end up in?','["Enrollment(StudentID, CourseID, EnrollmentDate)", "Course(CourseID, CourseName, InstructorID, InstructorName, InstructorOffice)", "Student(StudentID, StudentName)", "It remains in the original composite-keyed table"]'::jsonb,1,'Since CourseName''s true determinant is CourseID alone, it is relocated to a Course relation keyed by CourseID, removing the partial dependency.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-partial-dependency-8','pt-dbms-sql-21-partial-dependency','Which pair of attributes both exhibit partial dependency on {StudentID, CourseID} in the running example?','["EnrollmentDate and CourseName", "StudentName and CourseName", "StudentID and CourseID themselves", "EnrollmentDate and InstructorOffice"]'::jsonb,1,'StudentName depends on StudentID alone and CourseName depends on CourseID alone — both are determined by only part of the composite key, making both partial dependencies.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-partial-dependency-fundamentals-9','pt-dbms-sql-21-partial-dependency','What does partial dependency describe?','["A proper subset already determines the dependent attribute", "A missing SQL value", "A half-written row", "An incomplete backup"]'::jsonb,0,'The property concerns dependency implication, not NULL or storage completion.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-partial-dependency-fundamentals-10','pt-dbms-sql-21-partial-dependency','Does a surrogate primary key erase a composite alternative candidate key?','["Yes, always", "No", "Only with integer columns", "Only when a name repeats"]'::jsonb,1,'All candidate keys remain relevant to normalization.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-partial-dependency-application-1','cx-partial-dependency-application','Why can InstructorOffice be partially dependent on the enrollment key?','["Office is always a key", "CourseID determines it through InstructorID", "Every office string is unique", "EnrollmentDate determines it"]'::jsonb,1,'Implied transitive paths also establish dependencies from key subsets.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-partial-dependency-application-2','cx-partial-dependency-application','Which concept must be established before checking 2NF?','["Only the table display name", "Only current row count", "Candidate keys and nonprime attributes", "Only the primary-key sort order"]'::jsonb,2,'The normal-form condition is defined relative to all candidate keys.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-partial-dependency-application-3','cx-partial-dependency-application','What is the empty determinant relevant to?','["A deleted primary key", "An SQL NULL value", "A database without tables", "Constant attributes implied by the domain"]'::jsonb,3,'The empty set is a proper subset even of a singleton key.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
