if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-partial-index-concept-1' and (question_text,options,correct_index,explanation) is distinct from ('What is a partial index?','["An index that only stores half of each row''s data", "An index that covers only a subset of a table''s rows matching a specified condition", "An index that is deleted automatically after a week", "An index that can only be built on numeric columns"]'::jsonb,1,'A partial (filtered) index restricts its entries to rows that satisfy a WHERE condition, rather than covering the entire table.') and (question_text,options,correct_index,explanation) is distinct from ('What is a partial index?','["An index that only stores half of each row''s data", "An index that covers only a subset of a table''s rows matching a specified condition", "An index that is deleted automatically after a week", "An index that can only be built on numeric columns"]'::jsonb,1,'A partial (filtered) index restricts its entries to rows that satisfy a WHERE condition, rather than covering the entire table.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-partial-index-concept-1'; end if;
