if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-partial-index-concept-2' and (question_text,options,correct_index,explanation) is distinct from ('Which SQL dialect has NO native support for partial/filtered indexes?','["PostgreSQL", "SQL Server", "MySQL", "All of the above lack support"]'::jsonb,2,'MySQL has no native partial/filtered index feature, unlike PostgreSQL (WHERE clause on CREATE INDEX) and SQL Server (filtered indexes).') and (question_text,options,correct_index,explanation) is distinct from ('Which SQL dialect has NO native support for partial/filtered indexes?','["PostgreSQL", "SQL Server", "MySQL", "All of the above lack support"]'::jsonb,2,'MySQL has no native partial/filtered index feature, unlike PostgreSQL (WHERE clause on CREATE INDEX) and SQL Server (filtered indexes).')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-partial-index-concept-2'; end if;
