if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-partial-index-concept-4' and (question_text,options,correct_index,explanation) is distinct from ('A partial index is built with `WHERE status = ''pending''`. Can it help a query filtering `WHERE status = ''completed''`?','["Yes, partial indexes cover all possible values regardless of condition", "No, since ''completed'' rows were never included in this partial index", "Yes, but only for status values starting with ''p''", "It depends only on the table''s clustered index"]'::jsonb,1,'A partial index only contains entries for rows matching its defining condition; rows outside that condition simply aren''t indexed at all.') and (question_text,options,correct_index,explanation) is distinct from ('A partial index is built with `WHERE status = ''pending''`. Can it help a query filtering `WHERE status = ''completed''`?','["Yes, partial indexes cover all possible values regardless of condition", "No, since ''completed'' rows were never included in this partial index", "Yes, but only for status values starting with ''p''", "It depends only on the table''s clustered index"]'::jsonb,1,'A partial index only contains entries for rows matching its defining condition; rows outside that condition simply aren''t indexed at all.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-partial-index-concept-4'; end if;
