if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-partial-index-concept-5' and (question_text,options,correct_index,explanation) is distinct from ('What is a common real-world use case for combining a partial index with a uniqueness rule?','["Enforcing global uniqueness across every row in the table, always", "Enforcing uniqueness only among ''active'' (non-soft-deleted) rows, e.g., UNIQUE(email) WHERE deleted_at IS NULL", "Preventing any INSERT statements from ever running", "Making every column in the table NOT NULL"]'::jsonb,1,'A very common pattern is a partial unique index that enforces uniqueness only among active rows, allowing reused values among soft-deleted rows.') and (question_text,options,correct_index,explanation) is distinct from ('What is a common real-world use case for combining a partial index with a uniqueness rule?','["Enforcing global uniqueness across every row in the table, always", "Enforcing uniqueness only among ''active'' (non-soft-deleted) rows, e.g., UNIQUE(email) WHERE deleted_at IS NULL", "Preventing any INSERT statements from ever running", "Making every column in the table NOT NULL"]'::jsonb,1,'A very common pattern is a partial unique index that enforces uniqueness only among active rows, allowing reused values among soft-deleted rows.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-partial-index-concept-5'; end if;
