if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-partial-index-concept-6' and (question_text,options,correct_index,explanation) is distinct from ('Why does a partial index reduce write overhead compared to a full index on the same column?','["It doesn''t; write overhead is identical to a full index", "Writes to rows that don''t match the partial index''s condition never touch that index at all", "Partial indexes disable all writes to the table", "Partial indexes are read-only and cannot be written to"]'::jsonb,1,'Only rows satisfying the partial condition are tracked by the index, so non-matching row writes skip updating it entirely.') and (question_text,options,correct_index,explanation) is distinct from ('Why does a partial index reduce write overhead compared to a full index on the same column?','["Every write becomes free", "Rows remaining excluded can avoid member-entry maintenance, but predicate-changing updates can enter or leave the index", "It disables transaction logging", "Only SELECT statements remain legal"]'::jsonb,1,'A previously nonmatching row can become a member. Predicate evaluation and exact engine maintenance still matter.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-partial-index-concept-6'; end if;
