insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-partial-index-concept-1','pt-dbms-sql-20-partial-index-concept','What is a partial index?','["An index that only stores half of each row''s data", "An index that covers only a subset of a table''s rows matching a specified condition", "An index that is deleted automatically after a week", "An index that can only be built on numeric columns"]'::jsonb,1,'A partial (filtered) index restricts its entries to rows that satisfy a WHERE condition, rather than covering the entire table.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-partial-index-concept-2','pt-dbms-sql-20-partial-index-concept','Which SQL dialect has NO native support for partial/filtered indexes?','["PostgreSQL", "SQL Server", "MySQL", "All of the above lack support"]'::jsonb,2,'MySQL has no native partial/filtered index feature, unlike PostgreSQL (WHERE clause on CREATE INDEX) and SQL Server (filtered indexes).',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-partial-index-concept-3','pt-dbms-sql-20-partial-index-concept','What is the main benefit of a partial index over a full index on the same column?','["It stores every row twice", "It can be smaller and reduce eligible access or maintenance work, but benefits depend on subset, queries and transitions", "It always eliminates all writes", "It is guaranteed faster for every workload"]'::jsonb,1,'The subset can reduce work, but no universal speed or maintenance guarantee follows.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-partial-index-concept-4','pt-dbms-sql-20-partial-index-concept','A partial index is built with `WHERE status = ''pending''`. Can it help a query filtering `WHERE status = ''completed''`?','["Yes, partial indexes cover all possible values regardless of condition", "No, since ''completed'' rows were never included in this partial index", "Yes, but only for status values starting with ''p''", "It depends only on the table''s clustered index"]'::jsonb,1,'A partial index only contains entries for rows matching its defining condition; rows outside that condition simply aren''t indexed at all.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-partial-index-concept-5','pt-dbms-sql-20-partial-index-concept','What is a common real-world use case for combining a partial index with a uniqueness rule?','["Enforcing global uniqueness across every row in the table, always", "Enforcing uniqueness only among ''active'' (non-soft-deleted) rows, e.g., UNIQUE(email) WHERE deleted_at IS NULL", "Preventing any INSERT statements from ever running", "Making every column in the table NOT NULL"]'::jsonb,1,'A very common pattern is a partial unique index that enforces uniqueness only among active rows, allowing reused values among soft-deleted rows.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-partial-index-concept-6','pt-dbms-sql-20-partial-index-concept','Why does a partial index reduce write overhead compared to a full index on the same column?','["Every write becomes free", "Rows remaining excluded can avoid member-entry maintenance, but predicate-changing updates can enter or leave the index", "It disables transaction logging", "Only SELECT statements remain legal"]'::jsonb,1,'A previously nonmatching row can become a member. Predicate evaluation and exact engine maintenance still matter.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-partial-index-concept-7','pt-dbms-sql-20-partial-index-concept','What happens if application query patterns shift so that the partial index''s condition no longer matches common queries?','["The database throws a fatal error", "The partial index quietly stops being useful/chosen by the optimizer, without any error", "The partial index automatically updates its own condition", "All queries against the table stop working"]'::jsonb,1,'A partial index simply becomes irrelevant to new query patterns silently; there''s no automatic detection or alert for this.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
