if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-1' and test_id<>'pt-dbms-sql-23-phantom-read') then raise exception 'Question ID collision: %', 'tq-dbms-sql-23-phantom-read-1'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-1' and test_id='pt-dbms-sql-23-phantom-read') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-23-phantom-read-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-1' and (question_text,options,correct_index,explanation) is distinct from ('What is the defining condition of a phantom read?','["An existing row''s value changes between two reads within the same transaction", "The set of rows returned by the same query/condition, run twice within one transaction, differs because another transaction inserted or deleted a matching row in between", "A transaction reads uncommitted data", "A transaction''s write is silently overwritten by another transaction"]'::jsonb,1,'Phantom read is specifically about the ROW SET matching a repeated query changing due to another transaction''s committed insert/delete — not any existing row''s value being updated.') and (question_text,options,correct_index,explanation) is distinct from ('What observation defines a phantom in the repeated-predicate example?','["An existing row''s value changes between two reads within the same transaction", "The qualifying row set changes within one transaction because another transaction commits an insertion, deletion, or update crossing the predicate", "A transaction reads uncommitted data", "A transaction''s write is silently overwritten by another transaction"]'::jsonb,1,'An update can move an existing row into or out of the predicate, so phantoms are not limited to INSERT or DELETE statements.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-phantom-read-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-2' and test_id<>'pt-dbms-sql-23-phantom-read') then raise exception 'Question ID collision: %', 'tq-dbms-sql-23-phantom-read-2'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-2' and test_id='pt-dbms-sql-23-phantom-read') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-23-phantom-read-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-2' and (question_text,options,correct_index,explanation) is distinct from ('In the worked example, why does T1''s second query return Carol''s row when the first query didn''t?','["Because Bob''s balance changed", "Because T2 inserted a new row for Carol with balance 1500 and committed it in between T1''s two identical query executions", "Because T1''s query had a syntax error the first time", "Because Alice''s row was updated to match the condition"]'::jsonb,1,'Carol''s row didn''t exist at the time of T1''s first query; T2''s committed insert created it in between, so it appears — as a ''phantom'' — only in the second execution of the identical query.') and (question_text,options,correct_index,explanation) is distinct from ('T1 first lists Tuesday booking IDs 1 and 2. T2 inserts Tuesday booking 3 and commits. Under the stated READ COMMITTED ordinary-read lab, why can T1 next return ID 3?','["Because Bob''s balance changed", "Its second statement uses a fresh committed snapshot containing T2\u2019s inserted matching row", "Because T1''s query had a syntax error the first time", "Because Alice''s row was updated to match the condition"]'::jsonb,1,'Both reads belong to T1, but READ COMMITTED obtains a new consistent snapshot for each ordinary statement.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-phantom-read-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-3' and test_id<>'pt-dbms-sql-23-phantom-read') then raise exception 'Question ID collision: %', 'tq-dbms-sql-23-phantom-read-3'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-3' and test_id='pt-dbms-sql-23-phantom-read') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-23-phantom-read-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-3' and (question_text,options,correct_index,explanation) is distinct from ('What is the precise distinction between a non-repeatable read and a phantom read?','["They are the same anomaly with different names", "Non-repeatable read: an EXISTING row''s value changes between two reads. Phantom read: the SET of rows matching a condition changes because a new row was inserted (or an old one deleted), not because an existing row''s value changed", "Non-repeatable read only applies to numeric columns; phantom read applies to text columns", "Phantom read requires three or more transactions; non-repeatable read requires only two"]'::jsonb,1,'This is the core distinguishing fact examiners test: non-repeatable read = same row, different value; phantom read = different set of rows entirely, via insert/delete.') and (question_text,options,correct_index,explanation) is distinct from ('Which distinction best describes the worked nonrepeatable-read and phantom examples?','["They are the same anomaly with different names", "The first isolates a changed value for one identified row; the second isolates changed membership of a predicate\u2019s result set", "Non-repeatable read only applies to numeric columns; phantom read applies to text columns", "Phantom read requires three or more transactions; non-repeatable read requires only two"]'::jsonb,1,'A predicate’s membership can change through insertion, deletion, or an update crossing its boundary. Some update observations can overlap labels, so state the exact query property.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-phantom-read-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-4' and test_id<>'pt-dbms-sql-23-phantom-read') then raise exception 'Question ID collision: %', 'tq-dbms-sql-23-phantom-read-4'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-4' and test_id='pt-dbms-sql-23-phantom-read') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-23-phantom-read-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-4' and (question_text,options,correct_index,explanation) is distinct from ('Why doesn''t ordinary row-level locking (locking every row returned by a query) prevent phantom reads?','["Row-level locking is too slow to matter", "The phantom row does not exist yet at the time of the first query, so there is no row available to lock \u2014 preventing this requires locking the query''s condition/range itself, not just already-returned rows", "Row-level locking only works for UPDATE statements", "Phantom reads never involve row locks of any kind"]'::jsonb,1,'Since the inserted row is brand new, no lock could have been placed on it before it existed; only a range/predicate lock on the condition itself can block new matching inserts.') and (question_text,options,correct_index,explanation) is distinct from ('Why does locking only the existing rows returned by a query not by itself block every new matching insertion?','["Row-level locking is too slow to matter", "A future matching row may be inserted into a gap not protected by those existing-row locks", "Row-level locking only works for UPDATE statements", "Phantom reads never involve row locks of any kind"]'::jsonb,1,'Protecting against such insertion can require suitable range or predicate coordination. Stable snapshot visibility can separately keep a repeated result unchanged without blocking the insertion.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-phantom-read-4'; end if;
