if not exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-5' and test_id='pt-dbms-sql-23-phantom-read') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-23-phantom-read-5'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-5' and (question_text,options,correct_index,explanation) is distinct from ('Which of the following is a ''reverse phantom'' scenario?','["T1''s first query returns 3 rows; T2 deletes one of those matching rows and commits; T1''s second identical query now returns only 2 rows", "T1 reads the same row''s balance twice and gets different values", "T1 reads a value written by T2 before T2 commits", "T1''s write is overwritten by T2''s write"]'::jsonb,0,'A phantom can occur via deletion just as easily as insertion — the matching row SET shrinks instead of growing, but it''s the same underlying anomaly (set of matching rows changed due to a committed operation from another transaction).') and (question_text,options,correct_index,explanation) is distinct from ('Which of the following is a ''reverse phantom'' scenario?','["T1''s first query returns 3 rows; T2 deletes one of those matching rows and commits; T1''s second identical query now returns only 2 rows", "T1 reads the same row''s balance twice and gets different values", "T1 reads a value written by T2 before T2 commits", "T1''s write is overwritten by T2''s write"]'::jsonb,0,'A phantom can occur via deletion just as easily as insertion — the matching row SET shrinks instead of growing, but it''s the same underlying anomaly (set of matching rows changed due to a committed operation from another transaction).')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-phantom-read-5'; end if;
