if not exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-6' and test_id='pt-dbms-sql-23-phantom-read') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-23-phantom-read-6'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-6' and (question_text,options,correct_index,explanation) is distinct from ('Which isolation level is typically required to fully prevent phantom reads?','["READ UNCOMMITTED", "READ COMMITTED", "SERIALIZABLE (the strictest level, using range/predicate locking)", "Phantom reads cannot be prevented by any isolation level"]'::jsonb,2,'Because preventing phantoms requires locking the query''s predicate/range (not just existing rows), this guarantee is associated with the strongest, SERIALIZABLE isolation level.') and (question_text,options,correct_index,explanation) is distinct from ('Among the standard named isolation levels, which level specifies phantom prevention as a minimum requirement rather than relying on stronger engine-specific REPEATABLE READ behavior?','["READ UNCOMMITTED", "READ COMMITTED", "SERIALIZABLE", "Phantom reads cannot be prevented by any isolation level"]'::jsonb,2,'The standard minimum at REPEATABLE READ can permit phantoms, while engines such as PostgreSQL and ordinary InnoDB snapshot reads can provide stronger repeatability. Prevention does not universally require one particular locking implementation.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-phantom-read-6'; end if;
