if not exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-8' and test_id='pt-dbms-sql-23-phantom-read') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-23-phantom-read-8'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-phantom-read-8' and (question_text,options,correct_index,explanation) is distinct from ('How can a phantom read manifest through an aggregate query rather than a row list?','["It cannot \u2014 phantom reads only ever affect SELECT * queries", "A repeated COUNT(*) WHERE balance > 1000 could return 1 the first time and 2 the second time, reflecting the same underlying row-set change even though no individual row list was compared", "Aggregate queries are immune to all concurrency anomalies", "Only SUM() queries can exhibit phantom reads"]'::jsonb,1,'The same root cause (a new matching row committed in between two query executions) can be observed through a changing aggregate count/sum just as easily as through a changing row list.') and (question_text,options,correct_index,explanation) is distinct from ('How can a phantom read manifest through an aggregate query rather than a row list?','["It cannot \u2014 phantom reads only ever affect SELECT * queries", "A repeated COUNT(*) WHERE balance > 1000 could return 1 the first time and 2 the second time, reflecting the same underlying row-set change even though no individual row list was compared", "Aggregate queries are immune to all concurrency anomalies", "Only SUM() queries can exhibit phantom reads"]'::jsonb,1,'The same root cause (a new matching row committed in between two query executions) can be observed through a changing aggregate count/sum just as easily as through a changing row list.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-phantom-read-8'; end if;
