if exists(select 1 from public.test_questions where id='cx-phantom-read-fundamentals-9' and (question_text,options,correct_index,explanation) is distinct from ('What is the defining observation in a phantom read?','["A repeated predicate query sees changed qualifying membership", "A password becomes visible", "An index is rebuilt", "A primary key is renamed"]'::jsonb,0,'Phantoms concern the set of rows satisfying a predicate.') and (question_text,options,correct_index,explanation) is distinct from ('What is the defining observation in a phantom read?','["A repeated predicate query sees changed qualifying membership", "A password becomes visible", "An index is rebuilt", "A primary key is renamed"]'::jsonb,0,'Phantoms concern the set of rows satisfying a predicate.')) then raise exception 'Edited question requires review: %', 'cx-phantom-read-fundamentals-9'; end if;
