insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-precedence-graph-1','pt-dbms-sql-23-precedence-graph','How is an edge added to a precedence graph?','["One edge per transaction, regardless of conflicts", "A directed edge Ti → Tj is added whenever Ti has an operation that conflicts with, and precedes, an operation of Tj on the same data item", "An edge is added for every pair of transactions, whether or not they conflict", "Edges are added only for COMMIT operations"]'::jsonb,1,'Edges represent conflict-based ordering requirements: Ti→Tj means some conflicting operation of Ti had to happen before Tj''s corresponding operation.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-precedence-graph-2','pt-dbms-sql-23-precedence-graph','What is the precedence graph theorem for conflict serializability?','["A schedule is conflict-serializable if and only if its precedence graph has no cycles", "A schedule is conflict-serializable if and only if its precedence graph has at least one cycle", "A schedule is always conflict-serializable regardless of the graph''s shape", "The precedence graph determines view serializability, not conflict serializability"]'::jsonb,0,'This is the fundamental theorem: acyclic precedence graph implies conflict-serializable (with a topological sort giving the equivalent serial order); any cycle implies it is not.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-precedence-graph-3','pt-dbms-sql-23-precedence-graph','In Worked Example 1 (schedule S1), why did every single conflicting pair produce an edge in the same direction (T1→T2)?','["Because T1 and T2 never actually conflict", "Because in S1, all of T1''s operations on both A and B happen to occur before the corresponding conflicting operations of T2 that touch the same items", "Because the graph algorithm forces all edges to point the same way", "Because T1 committed before T2 started"]'::jsonb,1,'Tracing S1''s timeline shows T1''s reads/writes on A and B consistently precede T2''s conflicting operations on those same items, so every conflict contributes a T1→T2 edge, never the reverse.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-precedence-graph-4','pt-dbms-sql-23-precedence-graph','In Worked Example 2 (schedule S2), what specifically causes the precedence graph to contain a cycle?','["R2(B) precedes W1(B) (giving T2→T1) while R1(A) precedes W2(A) (giving T1→T2), producing edges in both directions between the same two nodes", "S2 has more than two transactions", "Neither transaction ever writes any data", "The schedule includes a blind write"]'::jsonb,0,'The two conflicts impose contradictory ordering requirements (T2 before T1 on B, T1 before T2 on A), which manifests as a 2-node cycle in the graph.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-precedence-graph-5','pt-dbms-sql-23-precedence-graph','If a precedence graph is acyclic (a DAG) with multiple valid topological sorts, what does that mean?','["The schedule is not conflict-serializable", "More than one serial schedule is equivalent to the given schedule — any of the valid topological orders works", "The schedule must be re-executed", "Only the alphabetically-first order is valid"]'::jsonb,1,'A DAG can admit multiple topological sorts when it isn''t a total order; each one represents an equally valid equivalent serial schedule.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-precedence-graph-6','pt-dbms-sql-23-precedence-graph','What happens to a precedence graph when two transactions share no conflicting operations at all?','["The graph is undefined", "No edge is drawn between them; if this holds for all pairs, the graph is trivially acyclic and every interleaving is conflict-serializable", "An edge is drawn in both directions by default", "The schedule is automatically non-serializable"]'::jsonb,1,'With zero conflicts, there is no ordering constraint between the transactions, so the graph has no edges connecting them and remains (or stays) acyclic.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-precedence-graph-7','pt-dbms-sql-23-precedence-graph','Why does the precedence graph test conflict serializability specifically, rather than view serializability?','["It preserves all ordered conflicts, including blind write-write order; view equivalence can permit some changes to that order while preserving reads and final writers", "It encodes only elapsed time", "Blind writes never conflict", "It requires all transactions to be read-only"]'::jsonb,0,'Blind writes to the same item do conflict. The distinction is that view equivalence preserves a different, sometimes weaker set of relationships, not that the conflict graph ignores write-write pairs.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-precedence-graph-8','pt-dbms-sql-23-precedence-graph','Why is the precedence-graph approach preferred over manually searching for a valid sequence of swaps to test conflict serializability?','["It always gives a different answer than the swap method", "Cycle detection in a directed graph is an efficient, well-known algorithm, making it far more practical than exhaustively searching for a swap sequence", "Swaps are mathematically undefined", "It requires fewer transactions"]'::jsonb,1,'Both methods are provably equivalent in their verdict, but cycle detection is computationally efficient and systematic, unlike manually trying every possible reordering.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-precedence-graph-fundamentals-9','pt-dbms-sql-23-precedence-graph','What does a precedence-graph vertex represent?','["A transaction", "A table column only", "A client window", "A backup file"]'::jsonb,0,'The graph orders transactions through conflicts among their operations.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
