if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-recoverable-schedule-4' and (question_text,options,correct_index,explanation) is distinct from ('In the ''Recoverable'' worked example, T2 read T1''s uncommitted write at step 4, yet the schedule is still recoverable. Why?','["Because T2 never actually committed", "Because T1 committed at step 5, BEFORE T2 committed at step 6 \u2014 satisfying the requirement that Ti commits before Tj commits", "Because T2''s read happened after T1''s commit", "Because recoverability doesn''t care about reads at all"]'::jsonb,1,'Recoverability only requires the correct ORDER OF COMMITS (Ti before Tj), regardless of when the read itself happened relative to Ti''s commit.') and (question_text,options,correct_index,explanation) is distinct from ('For w1(X), r2(X), c1, c2 with r2 reading w1, why is the schedule recoverable despite the dirty read?','["Because T2 never actually committed", "The source T1 commits before its dependent reader T2 commits", "Because T2''s read happened after T1''s commit", "Because recoverability doesn''t care about reads at all"]'::jsonb,1,'Recoverability constrains dependent commit order; it does not require c1 to precede r2.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-recoverable-schedule-4'; end if;
