if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-recoverable-schedule-7' and (question_text,options,correct_index,explanation) is distinct from ('Is it possible for a schedule to be conflict-serializable but irrecoverable?','["No, serializability guarantees recoverability", "Yes \u2014 serializability and recoverability are independent properties; a schedule can satisfy one without the other", "No, they are the exact same concept", "Only view-serializable schedules can be irrecoverable"]'::jsonb,1,'Serializability is about the equivalence of the schedule''s result to a serial order; recoverability is about safe handling of commits/aborts. A schedule can pass one test and fail the other.') and (question_text,options,correct_index,explanation) is distinct from ('Is it possible for a schedule to be conflict-serializable but irrecoverable?','["No, serializability guarantees recoverability", "Yes \u2014 serializability and recoverability are independent properties; a schedule can satisfy one without the other", "No, they are the exact same concept", "Only view-serializable schedules can be irrecoverable"]'::jsonb,1,'Serializability is about the equivalence of the schedule''s result to a serial order; recoverability is about safe handling of commits/aborts. A schedule can pass one test and fail the other.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-recoverable-schedule-7'; end if;
