update public.learning_topics set short_description='Classify recoverable schedules using reads-from dependencies, commit order, cascading rollback examples, and comparisons with strictness and serializability.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Classify recoverable schedules using reads-from dependencies, commit order, cascading rollback examples, and comparisons with strictness and serializability.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Recoverable Schedule.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-23-recoverable-schedule' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-recoverable-schedule-application','MCQ Test 2',category,10,10,'Application and scenarios for Recoverable Schedule.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-23-recoverable-schedule' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-recoverable-schedule-1','pt-dbms-sql-23-recoverable-schedule','What is the defining condition for a schedule to be ''recoverable''?','["No transaction is ever allowed to abort", "If Tj reads a data item written by Ti, then Ti must commit before Tj commits", "All transactions must commit at the same instant", "Tj must never read any data written by Ti"]'::jsonb,1,'Recoverability requires that a transaction''s commit never depends on the outcome of another transaction that hasn''t yet committed — Ti must commit first.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-recoverable-schedule-2','pt-dbms-sql-23-recoverable-schedule','In the ''NOT Recoverable'' worked example, what specifically makes the schedule irrecoverable?','["T2 read a value from T1 before T1 committed, and then T2 committed before T1''s eventual abort — leaving T2''s commit based on data that was rolled back", "T1 never wrote any data", "T2 aborted before T1", "Both transactions committed at the same time"]'::jsonb,0,'T2 committed (step 3) based on T1''s uncommitted write, and T1 then aborted (step 4); since T2 already committed, it cannot be undone, even though the data it relied on turned out to be rolled back.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-recoverable-schedule-3','pt-dbms-sql-23-recoverable-schedule','Why is w1(X), r2(X), c2, a1 unsafe when r2 reads w1?','["It uses too much disk space", "T2 has committed a result based on an aborted source, which ordinary rollback cannot simply retract", "It always causes a deadlock", "It is slower than a recoverable schedule"]'::jsonb,1,'A separate compensating business action may be possible, but ordinary abort recovery cannot treat an already committed dependent transaction as though it never committed.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-recoverable-schedule-4','pt-dbms-sql-23-recoverable-schedule','For w1(X), r2(X), c1, c2 with r2 reading w1, why is the schedule recoverable despite the dirty read?','["Because T2 never actually committed", "The source T1 commits before its dependent reader T2 commits", "Because T2''s read happened after T1''s commit", "Because recoverability doesn''t care about reads at all"]'::jsonb,1,'Recoverability constrains dependent commit order; it does not require c1 to precede r2.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-recoverable-schedule-5','pt-dbms-sql-23-recoverable-schedule','Does recoverability restrict WHEN Tj is allowed to read data written by an uncommitted Ti?','["Yes, Tj can never read uncommitted data under a recoverable schedule", "No — recoverability only constrains the relative order of COMMITS (Ti before Tj), not when the read itself occurs", "Yes, Tj must always wait for Ti to abort", "Recoverability only applies to write operations, never reads"]'::jsonb,1,'Recoverability is a commit-ordering constraint; it permits Tj to read Ti''s uncommitted (dirty) data, as long as Ti commits before Tj does. This is what separates it from the stricter cascadeless property.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-recoverable-schedule-6','pt-dbms-sql-23-recoverable-schedule','A completed schedule contains only Ti and Tj, and neither reads the other’s writes. Does Ti aborting alone make it unrecoverable?','["No, any abort automatically makes a schedule irrecoverable", "No, there is no intertransaction read dependency imposing a source-before-reader commit requirement", "Only if Tj also aborts", "Only if Ti aborts before Tj starts"]'::jsonb,1,'With no cross-transaction reads in this two-transaction history, the recoverability condition is satisfied vacuously, though other properties still require analysis.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-recoverable-schedule-7','pt-dbms-sql-23-recoverable-schedule','Is it possible for a schedule to be conflict-serializable but irrecoverable?','["No, serializability guarantees recoverability", "Yes — serializability and recoverability are independent properties; a schedule can satisfy one without the other", "No, they are the exact same concept", "Only view-serializable schedules can be irrecoverable"]'::jsonb,1,'Serializability is about the equivalence of the schedule''s result to a serial order; recoverability is about safe handling of commits/aborts. A schedule can pass one test and fail the other.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-recoverable-schedule-8','pt-dbms-sql-23-recoverable-schedule','Which mechanism can produce recoverable histories without allowing readers to consume pending writes?','["They forbid all transactions from ever reading data another transaction wrote", "Locking that withholds uncommitted values or MVCC that supplies suitable committed versions", "They only run one transaction at a time", "They disable rollback entirely"]'::jsonb,1,'Preventing dirty read dependencies is a stronger route to recoverability. The definition also permits dirty reads if dependent commits wait for their source commits, but that is not every engine’s typical implementation.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-recoverable-schedule-fundamentals-9','pt-dbms-sql-23-recoverable-schedule','Which ordering is required when T2 reads T1’s write and T2 commits?','["T1 commits before T2", "T2 must commit first", "The reads must have identical timestamps", "T1 must always abort"]'::jsonb,0,'Recoverability requires source commit before dependent commit.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-recoverable-schedule-fundamentals-10','pt-dbms-sql-23-recoverable-schedule','For w1(X), r2(X), c1, c2, where T2 reads T1, which classification holds?','["Unrecoverable and strict", "Recoverable but not cascadeless", "Cascadeless but unrecoverable", "Strict and dirty read free"]'::jsonb,1,'The read is dirty but the commit dependency is respected.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-recoverable-schedule-application-1','cx-recoverable-schedule-application','Why is w1(X), r2(X), c2, c1 unrecoverable?','["Both transactions eventually commit", "The dependent reader commits before its source", "There is only one item", "T1 wrote before T2 read"]'::jsonb,1,'A later source commit does not satisfy the required earlier commit order.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-recoverable-schedule-application-2','cx-recoverable-schedule-application','If T2 reads T1 and T3 reads T2, what direct dependency edges apply?','["Only T3 to T1", "Only T1 to T3", "T1 to T2 and T2 to T3", "No edges because values differ"]'::jsonb,2,'Read dependencies form a chain through the producing transactions.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-recoverable-schedule-application-3','cx-recoverable-schedule-application','Does recoverability forbid dirty reads?','["Yes, all reads must be serial", "Only for primary keys", "Only for two transactions", "No, it constrains dependent commit order"]'::jsonb,3,'A recoverable schedule can require cascading aborts after dirty reads.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
