if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-16-right-join','pt-dbms-sql-16-right-join-application')) then raise exception 'Extra topic tests require manual integration: %', 'right-join'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-16-right-join-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'right-join'; end if;
