update public.learning_topics set short_description='Use ROLLBACK to discard pending transactional changes, distinguish statement and transaction failures, and recognize implicit commits, savepoint and external-effect limits.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Use ROLLBACK to discard pending transactional changes, distinguish statement and transaction failures, and recognize implicit commits, savepoint and external-effect limits.';
