insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-22-rollback-application','MCQ Test 2',category,10,10,'Application and scenarios for ROLLBACK.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-22-rollback' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-rollback-1','pt-dbms-sql-22-rollback','What does ROLLBACK do?','["Makes changes permanent", "Discards supported uncommitted changes in the current transaction and ends it", "Speeds up the transaction", "Deletes the entire table"]'::jsonb,1,'The statement does not undo previous commits, unrelated sessions or nontransactional/external effects.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-rollback-2','pt-dbms-sql-22-rollback','In an isolated InnoDB row-update fixture without implicit commits, what remains after full ROLLBACK?','["The transaction’s own pending row changes are removed, preserving the original committed fixture", "Partially updated", "Deleted", "Locked permanently"]'::jsonb,0,'The isolated fixture returns its baseline data; real systems can retain logs, allocation gaps and independent concurrent commits.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-rollback-3','pt-dbms-sql-22-rollback','Can ROLLBACK happen automatically, without an explicit ROLLBACK statement?','["No, only an explicit statement triggers it", "Yes, some conditions can roll back a transaction; other errors roll back only a statement", "Only COMMIT can be automatic, never ROLLBACK", "Automatic rollback only exists in theory, never in real systems"]'::jsonb,1,'Failure scope is engine- and error-specific, so the caller must close unsuccessful work deliberately.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-rollback-4','pt-dbms-sql-22-rollback','What happens to writes on a MyISAM table when a MySQL transaction is rolled back?','["It works identically to InnoDB", "They are not reversed as transactional InnoDB writes would be; incomplete rollback can produce diagnostics", "It raises a syntax error", "It deletes the table"]'::jsonb,1,'This follows MyISAM nontransactional behavior; no actual provider default or empirical run is asserted.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-rollback-5','pt-dbms-sql-22-rollback','What is a common real-world mistake related to ROLLBACK/COMMIT?','["Using ROLLBACK too often", "Forgetting to explicitly ROLLBACK or COMMIT an open transaction, leaving it hanging and potentially holding locks", "Using COMMIT instead of ROLLBACK by mistake is impossible", "ROLLBACK cannot be misused"]'::jsonb,1,'Relying on driver auto-rollback-on-disconnect rather than explicitly closing transactions is fragile, real-world practice.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-rollback-6','pt-dbms-sql-22-rollback','Which ACID property is illustrated by discarding an incomplete transaction’s supported row changes?','["Durability", "Atomicity", "Isolation only", "None of them"]'::jsonb,1,'Atomicity concerns the all-or-nothing committed data effect, not literal absence of every diagnostic trace.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-rollback-7','pt-dbms-sql-22-rollback','Accounts1 and2 start at1000 and500; an isolated InnoDB transaction subtracts300 from1, adds300 to2, then rolls back. What is account1 after rollback?','["300 less than before", "Exactly what it was before the transaction started", "300 more than before", "Zero"]'::jsonb,1,'Its own pending debit is undone, returning account1 to1000 in this isolated fixture.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-rollback-8','pt-dbms-sql-22-rollback','Should application code assume a transaction rollback never needs explicit error handling?','["Yes, rollback never needs handling", "No, handle the documented failure scope, close the transaction and reconcile uncertain outcomes", "Only network errors need handling", "Rollback errors are impossible to detect"]'::jsonb,1,'Some errors leave earlier work pending; connection loss can prevent outcome confirmation.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-rollback-new-9','pt-dbms-sql-22-rollback','A standalone UPDATE autocommits. What can a later ROLLBACK undo from that committed statement?','["The entire database history", "Nothing from that already committed update", "Only the first column", "Every other user change"]'::jsonb,1,'Rollback applies to pending supported work, not past committed transactions.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-rollback-new-10','pt-dbms-sql-22-rollback','What connection must run the boundary and its writes?','["Any unrelated pooled session", "Only a browser session", "The same database session", "A different connection per statement"]'::jsonb,2,'Transaction state belongs to the database connection.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-rollback-application-new-1','pt-dbms-sql-22-rollback-application','A failed statement leaves an earlier update pending. What is needed when the business operation failed?','["Assume every exception committed everything", "Continue dependent writes blindly", "Hide the error in the interface", "Explicitly close or discard that unsuccessful transaction appropriately"]'::jsonb,3,'Error scope does not always include the entire transaction.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-rollback-application-new-2','pt-dbms-sql-22-rollback-application','Does rollback erase another transaction’s later legitimate committed work?','["No", "Yes, all work after START is removed", "Only if IDs are equal", "Only when the table has an index"]'::jsonb,0,'It reverses its own supported uncommitted effects.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-rollback-application-new-3','pt-dbms-sql-22-rollback-application','An insert rolls back but an auto-increment value is skipped. Is a committed business row proved?','["Yes, every gap means a row survives", "No, allocation gaps can remain", "Only for strings", "Only with SELECT DISTINCT"]'::jsonb,1,'Allocation side effects and committed row existence differ.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
