insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-rollback-application-new-5','pt-dbms-sql-22-rollback-application','Can ROLLBACK unsend a previously delivered notification?','["Yes, automatically", "Only if the email has one recipient", "Only with InnoDB", "No"]'::jsonb,3,'External effects require their own coordination contract.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
