if exists(select 1 from public.dsa_problems where id='cp-dbms-sql-rollback-a-failed-transfer' and (md5(description) not in ('bedcdc27fb9c06a00524ede0d3fa48fb','95efefd7e7ee289c1f0fb4253246456b') or sql_schema_sql is distinct from 'CREATE TABLE accounts (
  id INTEGER PRIMARY KEY,
  balance INTEGER NOT NULL
) ENGINE=InnoDB;' or sql_seed_sql is distinct from 'INSERT INTO accounts (id, balance) VALUES (1, 1000), (2, 500);' or sql_check_sql is distinct from 'SELECT id, balance FROM accounts ORDER BY id;')) then raise exception 'Edited coding problem requires review: %', 'cp-dbms-sql-rollback-a-failed-transfer'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cp-dbms-sql-rollback-a-failed-transfer',null::text,'Rollback a Failed Transfer','Easy','rollback-a-failed-transfer','Write a transaction that attempts to transfer 300 from account id 1 to account id 2, but then rolls it back instead of committing. Debit account 1 by 300, credit account 2 by 300, then `ROLLBACK`.

**MySQL dialect.**

```sql
CREATE TABLE accounts (
  id INTEGER PRIMARY KEY,
  balance INTEGER NOT NULL
) ENGINE=InnoDB;
INSERT INTO accounts (id, balance) VALUES (1, 1000), (2, 500);
```

**Required ordering:** Retain the ordering stated in the original task.

**Edge cases:**
- Verify the alternative seeded fixture.','[{"input": "INSERT INTO accounts (id, balance) VALUES (1, 1000), (2, 500);", "output": "id\tbalance\n1\t1000\n2\t500", "explanation": "The requested debit and credit are pending InnoDB changes. Full rollback discards both, and the retained trailing checker reads the original balances. Final output alone cannot prove the writes were attempted.", "check_sql": "SELECT id, balance FROM accounts ORDER BY id;"}]'::jsonb,'[{"seed_sql": "INSERT INTO accounts (id, balance) VALUES (1, 5000), (2, 2000);", "expected": "id\tbalance\n1\t5000\n2\t2000", "hidden": true}]'::jsonb,'["Preserve the original fixture and requested output."]'::jsonb,'["Trace the required output grain and conditions."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The requested debit and credit are pending InnoDB changes. Full rollback discards both, and the retained trailing checker reads the original balances. Final output alone cannot prove the writes were attempted.','{"sql": "START TRANSACTION; UPDATE accounts SET balance = balance - 300 WHERE id = 1; UPDATE accounts SET balance = balance + 300 WHERE id = 2; ROLLBACK;"}'::jsonb,'The requested debit and credit are pending InnoDB changes. Full rollback discards both, and the retained trailing checker reads the original balances. Final output alone cannot prove the writes were attempted.',array['sql'],'CREATE TABLE accounts (
  id INTEGER PRIMARY KEY,
  balance INTEGER NOT NULL
) ENGINE=InnoDB;','INSERT INTO accounts (id, balance) VALUES (1, 1000), (2, 500);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-22-rollback' on conflict(id) do update set description=excluded.description,examples=excluded.examples,test_cases=excluded.test_cases,constraints=excluded.constraints,hints=excluded.hints,editorial=excluded.editorial,solution_code=excluded.solution_code,solution_approach=excluded.solution_approach,updated_at=now() where (dsa_problems.description,dsa_problems.examples,dsa_problems.test_cases,dsa_problems.constraints,dsa_problems.hints,dsa_problems.editorial,dsa_problems.solution_code,dsa_problems.solution_approach) is distinct from (excluded.description,excluded.examples,excluded.test_cases,excluded.constraints,excluded.hints,excluded.editorial,excluded.solution_code,excluded.solution_approach);
