if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-rollup-concept-5' and (question_text,options,correct_index,explanation) is distinct from ('Why does column order matter for ROLLUP but not for plain GROUP BY?','["It doesn''t actually matter for either", "ROLLUP''s column order defines which columns get ''peeled off'' first for subtotals, so ROLLUP(region, product) and ROLLUP(product, region) produce different subtotal rows; plain GROUP BY just groups by the same combination regardless of listed order", "GROUP BY column order changes which rows are grouped together", "ROLLUP requires columns in reverse alphabetical order"]'::jsonb,1,'ROLLUP(a, b) rolls up subtotals as (a,b) -> (a) -> (); reversing to ROLLUP(b, a) instead produces (b,a) -> (b) -> (), a materially different subtotal hierarchy — unlike plain GROUP BY, where grouping is set-based and order-independent.') and (question_text,options,correct_index,explanation) is distinct from ('Why does column order matter for ROLLUP but not for plain GROUP BY?','["It doesn''t actually matter for either", "ROLLUP''s column order defines which columns get ''peeled off'' first for subtotals, so ROLLUP(region, product) and ROLLUP(product, region) produce different subtotal rows; plain GROUP BY just groups by the same combination regardless of listed order", "GROUP BY column order changes which rows are grouped together", "ROLLUP requires columns in reverse alphabetical order"]'::jsonb,1,'ROLLUP(a, b) rolls up subtotals as (a, b) -> (a) -> (); reversing to ROLLUP(b, a) instead produces (b, a) -> (b) -> (), a materially different subtotal hierarchy — unlike plain GROUP BY, where grouping is set-based and order-independent.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-rollup-concept-5'; end if;
