update public.learning_topics set short_description='Build hierarchical SQL totals with MySQL WITH ROLLUP, grouping flags, NULL-safe labels, level filters and protection against subtotal double counting.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Build hierarchical SQL totals with MySQL WITH ROLLUP, grouping flags, NULL-safe labels, level filters and protection against subtotal double counting.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for ROLLUP Concept.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-15-rollup-concept' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-15-rollup-concept-application','MCQ Test 2',category,10,10,'Application and scenarios for ROLLUP Concept.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-15-rollup-concept' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-rollup-concept-1','pt-dbms-sql-15-rollup-concept','What grouping sets does `ROLLUP(region, product)` expand to?','["GROUPING SETS ((region), (product), ())", "GROUPING SETS ((region, product), (region), ())", "GROUPING SETS ((region, product), (product), ())", "GROUPING SETS ((region, product))"]'::jsonb,1,'ROLLUP peels off columns from the right, one at a time: full detail (region, product), then (region) alone, then the empty grand-total set — never a product-only set.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-rollup-concept-2','pt-dbms-sql-15-rollup-concept','For the stated six region-product combinations across three regions, how many rollup rows result?','["6", "7", "10", "12"]'::jsonb,2,'6 detail rows (per region/product) + 3 region subtotal rows + 1 grand total row = 10.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-rollup-concept-3','pt-dbms-sql-15-rollup-concept','What is the East region''s subtotal row''s total_amount in `GROUP BY ROLLUP(region, product)`?','["160", "150", "310", "1060"]'::jsonb,2,'The current East fixture has Camera90 and Tripod220, so its subtotal is90+220=310.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-rollup-concept-4','pt-dbms-sql-15-rollup-concept','Does `GROUP BY ROLLUP(region, product)` produce a row summarizing totals by product alone, ignoring region (e.g., region=NULL, product=''Widget'')?','["Yes, always", "No — ROLLUP only produces subtotals by dropping columns from the right (region-only, then grand total), never a product-only subtotal", "Only if CUBE is also specified", "Only in MySQL"]'::jsonb,1,'ROLLUP''s hierarchy strictly rolls up right-to-left; a product-only breakdown requires CUBE or an explicit GROUPING SETS entry.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-rollup-concept-5','pt-dbms-sql-15-rollup-concept','Why does column order matter for ROLLUP but not for plain GROUP BY?','["It doesn''t actually matter for either", "ROLLUP''s column order defines which columns get ''peeled off'' first for subtotals, so ROLLUP(region, product) and ROLLUP(product, region) produce different subtotal rows; plain GROUP BY just groups by the same combination regardless of listed order", "GROUP BY column order changes which rows are grouped together", "ROLLUP requires columns in reverse alphabetical order"]'::jsonb,1,'ROLLUP(a, b) rolls up subtotals as (a, b) -> (a) -> (); reversing to ROLLUP(b, a) instead produces (b, a) -> (b) -> (), a materially different subtotal hierarchy — unlike plain GROUP BY, where grouping is set-based and order-independent.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-rollup-concept-6','pt-dbms-sql-15-rollup-concept','Which databases support the standard `GROUP BY ROLLUP(region, product)` function syntax?','["Only MySQL", "PostgreSQL, SQL Server, and Oracle", "No mainstream database supports ROLLUP", "Only SQLite"]'::jsonb,1,'PostgreSQL, SQLServer and Oracle support the shown ROLLUP form. Current MySQL8.4 documentation also describes ROLLUP(...) alongside the established trailing WITH ROLLUP form; verify the deployed release rather than claim exclusivity.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-rollup-concept-7','pt-dbms-sql-15-rollup-concept','Which MySQL syntax expresses the same region-product rollup hierarchy used in this lesson?','["GROUP BY region, product WITH ROLLUP", "GROUP BY ROLLUP region, product", "GROUP BY GROUPING SETS(region, product)", "MySQL has no equivalent at all"]'::jsonb,0,'GROUP BY region, product WITH ROLLUP is the MySQL form used here. Current MySQL8.4 documentation also describes a ROLLUP grouping syntax alternative; do not infer exclusive syntax support from this example.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-rollup-concept-8','pt-dbms-sql-15-rollup-concept','If `HAVING SUM(amount) > 200` is applied to `GROUP BY ROLLUP(region, product)`, what happens to the North region''s subtotal row (total_amount = 200)?','["It is kept because 200 is close to 200", "It is dropped, since 200 is not strictly greater than 200", "HAVING cannot be combined with ROLLUP", "It is automatically replaced with the grand total"]'::jsonb,1,'HAVING filters every output row from the rollup, including subtotal rows; North''s subtotal of exactly 200 fails the strict > 200 condition and is excluded.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-15-rollup-concept-c-new-1','pt-dbms-sql-15-rollup-concept','What grouping levels does region, product WITH ROLLUP request?','["Region-product, region, grand total", "Product only and no grand total", "Every arbitrary dimension combination", "Only detail rows"]'::jsonb,0,'Rollup follows ordered prefixes, dropping suffix dimensions.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-15-rollup-concept-c-new-2','pt-dbms-sql-15-rollup-concept','Why are there ten rows in the stated six-combination fixture?','["Every rollup has ten rows", "Six details plus three regional subtotals plus one grand total", "There are ten source orders", "NULL removes four rows"]'::jsonb,1,'The count follows represented combinations and hierarchy levels.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-15-rollup-concept-c-new-3','pt-dbms-sql-15-rollup-concept-application','What distinguishes a real NULL product group from a generated product subtotal marker?','["Only product IS NULL", "The label Total", "GROUPING(product)", "The query filename"]'::jsonb,2,'The flag identifies whether the dimension was aggregated away.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
