if exists(select 1 from public.test_questions where id='tq-dbms-sql-11-safe-updates-4' and (question_text,options,correct_index,explanation) is distinct from ('What is a reliable technique for testing a risky UPDATE/DELETE against production data with zero risk?','["Running it directly with no safeguards", "Running it inside an explicit transaction, inspecting the result, then ROLLBACK instead of COMMIT if anything looks wrong", "Running it twice to double-check", "Disabling all constraints first"]'::jsonb,1,'A transaction that you inspect and then roll back lets you verify effects with no permanent risk.') and (question_text,options,correct_index,explanation) is distinct from ('Does UPDATE followed by ROLLBACK make a production rehearsal risk free?','["Yes, all possible effects are reversed", "No, locking and nontransactional or external effects can still matter", "Yes, even for implicitly committing DDL", "Only if no WHERE clause is used"]'::jsonb,1,'Transactional rollback does not erase every operational effect.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-11-safe-updates-4'; end if;
