update public.learning_topics set short_description='Use MySQL savepoints to recover optional transactional work while preserving clear commit ownership, valid recovery names and honest lock and resource boundaries.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Use MySQL savepoints to recover optional transactional work while preserving clear commit ownership, valid recovery names and honest lock and resource boundaries.';
