insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-savepoint-1','pt-dbms-sql-22-savepoint','What does a SAVEPOINT allow you to do?','["Commit part of a transaction early", "Roll back only the statements after a named point, without discarding the whole transaction", "Create a backup of the entire database", "Skip writing a WHERE clause"]'::jsonb,1,'SAVEPOINT enables fine-grained, partial rollback within an open transaction.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-savepoint-2','pt-dbms-sql-22-savepoint','After ROLLBACK TO a savepoint, is the transaction finished?','["Yes, it automatically commits", "No — the transaction is still open; you must still explicitly COMMIT or ROLLBACK afterward", "Yes, it automatically rolls back completely", "ROLLBACK TO always raises an error"]'::jsonb,1,'ROLLBACK TO only undoes statements after the savepoint — the transaction itself remains open.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-savepoint-3','pt-dbms-sql-22-savepoint','What happens to statements BEFORE the savepoint when you ROLLBACK TO it?','["They are also undone", "They remain part of the still-open, still-uncommitted transaction", "They are immediately committed", "They cause an error"]'::jsonb,1,'Only statements after the named savepoint are undone; earlier work in the transaction is preserved.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-savepoint-4','pt-dbms-sql-22-savepoint','What happens if you ROLLBACK TO a savepoint name that was never created?','["It silently does nothing", "It raises an explicit error (e.g. ''SAVEPOINT ... does not exist''), proving the database genuinely tracks savepoint state", "It rolls back the entire transaction instead", "It creates the savepoint retroactively"]'::jsonb,1,'MySQL documents an error for an unavailable savepoint. This package does not claim that the missing-name lab was executed.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-savepoint-5','pt-dbms-sql-22-savepoint','What participant condition is required for the InnoDB savepoint row-change lab in these notes?','["Nothing special — it always works", "The row changes must use participating transactional tables, such as the stated InnoDB tables", "SAVEPOINT never works on this platform", "Only SELECT statements need InnoDB"]'::jsonb,1,'The lesson specifies InnoDB rather than asserting a verified default engine for every course judge or provider.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-savepoint-6','pt-dbms-sql-22-savepoint','What does RELEASE SAVEPOINT do?','["Commits the entire transaction", "Removes a savepoint you no longer need to roll back to, without affecting the transaction''s data", "Rolls back to that savepoint immediately", "Deletes the underlying table"]'::jsonb,1,'RELEASE SAVEPOINT frees the bookkeeping for a savepoint without changing any data.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-savepoint-7','pt-dbms-sql-22-savepoint','Why does the badge example commit capacity 9 with no badge after rolling back to before_badge?','["It doesn''t match — SAVEPOINT changes the final outcome", "The earlier capacity decrement remains pending, the later badge insert is undone, and COMMIT preserves the surviving decrement", "Because SAVEPOINT ignores all UPDATE statements", "Because COMMIT overrides any prior UPDATE"]'::jsonb,1,'The savepoint separates the mandatory earlier reservation from the explicitly optional later badge attempt.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-savepoint-8','pt-dbms-sql-22-savepoint','Why is SAVEPOINT useful for multi-step transactions?','["It makes transactions run faster", "It allows correcting a mistake partway through a transaction without restarting the whole transaction from scratch", "It removes the need for COMMIT entirely", "It automatically validates all business rules"]'::jsonb,1,'Fine-grained error recovery within one transaction is SAVEPOINT''s core value.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-22-savepoint-new-9','pt-dbms-sql-22-savepoint','What survives ROLLBACK TO SAVEPOINT before_badge in the example?','["The earlier pending capacity update", "The later badge insert", "Nothing in the transaction", "Only an external email"]'::jsonb,0,'The target preserves supported work performed before its position.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
