update public.learning_topics set short_description='Understand one-value subquery shape, zero-row NULL and multirow errors, and preserve lookup, aggregate and correlation contracts when rewriting queries.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Understand one-value subquery shape, zero-row NULL and multirow errors, and preserve lookup, aggregate and correlation contracts when rewriting queries.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Scalar Subquery.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-17-scalar-subquery' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-scalar-subquery-application','MCQ Test 2',category,10,10,'Application and scenarios for Scalar Subquery.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-17-scalar-subquery' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-scalar-subquery-1','pt-dbms-sql-17-scalar-subquery','What must a scalar subquery return?','["One selected column and at most one result row; zero rows yield NULL in MySQL", "Any number of rows", "One row with unlimited columns", "Only a boolean value"]'::jsonb,0,'Exactly one row is not required: zero rows become NULL, while more than one row causes a MySQL cardinality error.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-scalar-subquery-2','pt-dbms-sql-17-scalar-subquery','Where can a scalar subquery legally be used?','["Only in WHERE", "Only in FROM", "Supported scalar-expression contexts such as a SELECT-list value or a suitable WHERE comparison", "Every syntactic position without exception"]'::jsonb,2,'Supported expression contexts depend on the engine and clause; avoid an unrestricted anywhere claim.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-scalar-subquery-3','pt-dbms-sql-17-scalar-subquery','What does `(SELECT salary FROM employees WHERE name=''Zack'')` evaluate to if no employee named Zack exists?','["An error", "0", "NULL", "An empty string"]'::jsonb,2,'Zero rows returned by a scalar subquery yields NULL, not an error.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-scalar-subquery-4','pt-dbms-sql-17-scalar-subquery','If known salaries average 71250.00, what does an uncorrelated AVG subquery logically display beside each outer employee row?','["A different value per row, matching that employee''s department", "The same value, 71250.00, repeated in every row", "NULL in every row", "It errors because a subquery cannot appear in SELECT"]'::jsonb,1,'The same global benchmark appears beside every outer row; this does not guarantee a particular physical execution count.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-scalar-subquery-5','pt-dbms-sql-17-scalar-subquery','Which of these would be safely usable as a scalar subquery expression?','["(SELECT name, salary FROM employees LIMIT 1)", "(SELECT department FROM employees) which can return 8 rows", "(SELECT MAX(salary) FROM employees)", "(SELECT * FROM employees WHERE id=1)"]'::jsonb,2,'MAX with no GROUP BY always collapses to one row, one column — a safe scalar shape. The others have multiple columns or an unbounded row count.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-scalar-subquery-6','pt-dbms-sql-17-scalar-subquery','Which SQL clause is a scalar subquery for a company-wide average salary most naturally used in?','["GROUP BY", "The SELECT list, as a computed column", "The FROM clause as a table", "A JOIN condition"]'::jsonb,1,'A common use of scalar subqueries is as a computed column alongside real columns.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-scalar-subquery-7','pt-dbms-sql-17-scalar-subquery','A scalar subquery must return at most:','["1 row, unlimited columns", "Unlimited rows, 1 column", "1 row and 1 column", "1 row per outer row group"]'::jsonb,2,'Both the row count and column count must be exactly one (or zero rows, which yields NULL).',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-scalar-subquery-8','pt-dbms-sql-17-scalar-subquery','Why do aggregate functions like AVG/COUNT/SUM make excellent scalar subqueries?','["They are always faster than joins", "They collapse to a single row automatically when there is no GROUP BY, guaranteeing the scalar shape", "They can only be used inside subqueries", "They automatically ignore rows with NULL department"]'::jsonb,1,'An ordinary ungrouped aggregate SELECT supplies one aggregate row. GROUP BY or other shape-changing clauses require a separate cardinality check.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-scalar-subquery-fundamentals-9','pt-dbms-sql-17-scalar-subquery','What does a zero-row scalar subquery yield in MySQL?','["NULL", "Zero automatically", "An empty relation column list", "Always a syntax error"]'::jsonb,0,'No scalar value row becomes a NULL expression.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-scalar-subquery-fundamentals-10','pt-dbms-sql-17-scalar-subquery','What happens when a scalar subquery returns two rows in MySQL?','["The first is always chosen", "An error", "Both become one string automatically", "A guaranteed average"]'::jsonb,1,'The scalar position requires at most one result row.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-scalar-subquery-application-1','cx-scalar-subquery-application','Does a current unique display name prove future scalar lookup uniqueness?','["Yes, one sample is a constraint", "No", "Only if uppercase", "Only if sorted"]'::jsonb,1,'A declared key or valid domain guarantee must establish cardinality.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-scalar-subquery-application-2','cx-scalar-subquery-application','Why can LIMIT 1 conceal a data-contract problem?','["It always returns NULL", "It proves the table is normalized", "It changes a uniqueness requirement into a selection rule", "It removes every duplicate from storage"]'::jsonb,2,'Choosing one candidate is not the same as proving at most one exists.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-scalar-subquery-application-3','cx-scalar-subquery-application','What does ungrouped COUNT return for no qualifying rows?','["NULL", "No aggregate row", "An arbitrary child identifier", "Zero"]'::jsonb,3,'COUNT produces its single aggregate row with zero.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-scalar-subquery-application-4','cx-scalar-subquery-application','What does ungrouped AVG normally return for no known values?','["NULL", "Zero automatically", "One", "An empty string"]'::jsonb,0,'No known values leave the average undefined under ordinary aggregate behavior.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
