insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-selectivity-1','pt-dbms-sql-20-selectivity','How is selectivity typically calculated?','["Total number of rows divided by number of distinct values", "Number of distinct values divided by total number of rows", "Number of indexes divided by number of tables", "Number of columns divided by number of rows"]'::jsonb,1,'Selectivity = distinct values / total rows — a ratio describing how much a value narrows down the search.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-selectivity-2','pt-dbms-sql-20-selectivity','Which column in the 1, 000, 000-row students table has the HIGHEST selectivity?','["is_active (boolean, 2 values)", "department (20 distinct values)", "email (nearly all unique values)", "A constant column with only 1 possible value"]'::jsonb,2,'email, being nearly unique per row, has selectivity close to 1.0 — the highest among these options.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-selectivity-3','pt-dbms-sql-20-selectivity','Why is a boolean column like is_active generally a poor index candidate?','["Booleans cannot be stored in indexes", "It has only 2 distinct values, so filtering on it still leaves a large fraction of rows matching, providing low selectivity", "Boolean indexes are always corrupted", "Booleans require a hash index specifically"]'::jsonb,1,'A roughly balanced boolean predicate often selects a large fraction, but a rare boolean value under skew can be highly selective. Evaluate the queried value’s distribution rather than distinct count alone.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-selectivity-4','pt-dbms-sql-20-selectivity','In a scenario where a WHERE clause on an indexed column still matches 70% of the table''s rows, what is the likely consequence?','["The index will always be dramatically faster than a full scan", "A full table scan may actually be cheaper, since the index-plus-lookups approach would still touch most of the table via scattered I/O", "The query will fail to execute", "The column''s data type is invalid for indexing"]'::jsonb,1,'When selectivity is low and most rows match, following many index pointers (random I/O) can be more expensive than a straightforward sequential full scan.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-selectivity-5','pt-dbms-sql-20-selectivity','What does it mean if a column has selectivity close to 1.0?','["Almost all rows have the same value", "Most values are unique or near-unique, so filtering on that column narrows results down sharply", "The column cannot be indexed", "The column has exactly one distinct value"]'::jsonb,1,'Selectivity near 1.0 indicates values are close to unique across rows, meaning filtering narrows the result set dramatically.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-selectivity-6','pt-dbms-sql-20-selectivity','Why can a single overall selectivity number for `department` be misleading if the data distribution is skewed?','["Selectivity is never misleading under any circumstances", "If one department has 80% of all rows and 19 others share the rest, filtering to the big department is low-value even though the average selectivity number looks reasonable", "Skewed data makes selectivity impossible to calculate at all", "Selectivity can only be computed for numeric columns"]'::jsonb,1,'A skewed distribution means the overall average selectivity doesn''t reflect the very different real selectivity of filtering to a huge group versus a tiny one — this is why optimizers use histograms for more nuance.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-selectivity-7','pt-dbms-sql-20-selectivity','What statistical tool do real query optimizers often use beyond a single selectivity ratio to handle skewed data distributions?','["Histograms of value frequency distribution", "A random number generator", "A separate hash index just for statistics", "They ignore skew entirely and always trust the average ratio"]'::jsonb,0,'Optimizers commonly maintain histograms capturing how values are distributed, which handles skew better than one single average ratio.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-selectivity-8','pt-dbms-sql-20-selectivity','How is selectivity mathematically related to cardinality (covered in 20.13)?','["They are unrelated concepts", "Selectivity = cardinality (distinct values) divided by total number of rows", "Cardinality = selectivity multiplied by the number of indexes", "Selectivity and cardinality are always equal to each other"]'::jsonb,1,'Selectivity is directly derived from cardinality: selectivity = cardinality / total rows, tying the two concepts together.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
