if exists(select 1 from public.test_questions where id='tq-dbms-sql-16-self-join-3' and (question_text,options,correct_index,explanation) is distinct from ('Why is LEFT JOIN (not INNER JOIN) used in the employee-manager self join example?','["LEFT JOIN is always required for self joins", "So employees with no manager (like Asha) still appear, with manager = NULL, instead of being dropped", "INNER JOIN cannot be used on the same table twice", "LEFT JOIN is faster for self joins specifically"]'::jsonb,1,'An INNER self join would drop any employee whose manager_id is NULL, which LEFT JOIN avoids.') and (question_text,options,correct_index,explanation) is distinct from ('Which join preserves employees with no matched manager?','["INNER JOIN only", "LEFT JOIN from the employee role", "CROSS JOIN", "A name comparison"]'::jsonb,1,'The employee is the preserved side, so a missing manager does not remove the employee.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-16-self-join-3'; end if;
