if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-serial-schedule-1' and (question_text,options,correct_index,explanation) is distinct from ('What defines a serial schedule of T1 and T2?','["T1 and T2 execute simultaneously on different CPU cores", "One transaction''s operations all complete before the other transaction''s first operation begins \u2014 no interleaving at all", "T1 and T2 both commit at exactly the same time", "T1 and T2 read the same initial values"]'::jsonb,1,'A serial schedule has zero overlap in time between transactions — one runs to completion (commit or abort) before the next starts.') and (question_text,options,correct_index,explanation) is distinct from ('What defines a serial schedule of T1 and T2?','["T1 and T2 execute simultaneously on different CPU cores", "One transaction''s operations all complete before the other transaction''s first operation begins \u2014 no interleaving at all", "T1 and T2 both commit at exactly the same time", "T1 and T2 read the same initial values"]'::jsonb,1,'A serial schedule has zero overlap in time between transactions — one runs to completion (commit or abort) before the next starts.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-serial-schedule-1'; end if;
