if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-serial-schedule-5' and (question_text,options,correct_index,explanation) is distinct from ('What is the main drawback of always using serial schedules in a production DBMS?','["They are mathematically impossible to construct", "They produce incorrect results", "They give up all the throughput/response-time benefits of interleaving, since every other transaction must wait idle even if it touches unrelated data", "They cannot be logged for recovery"]'::jsonb,2,'Forcing transactions to run strictly one-at-a-time means the system can never overlap one transaction''s I/O wait with another''s useful work, badly hurting throughput.') and (question_text,options,correct_index,explanation) is distinct from ('What is the main drawback of always using serial schedules in a production DBMS?','["They are mathematically impossible to construct", "They produce incorrect results", "They give up all the throughput/response-time benefits of interleaving, since every other transaction must wait idle even if it touches unrelated data", "They cannot be logged for recovery"]'::jsonb,2,'Forcing transactions to run strictly one-at-a-time means the system can never overlap one transaction''s I/O wait with another''s useful work, badly hurting throughput.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-serial-schedule-5'; end if;
