update public.learning_topics set short_description='Trace complete transaction orders, compare noncommuting results, count valid permutations, and distinguish serial execution from serializability and business correctness.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Trace complete transaction orders, compare noncommuting results, count valid permutations, and distinguish serial execution from serializability and business correctness.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Serial Schedule.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-23-serial-schedule' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-serial-schedule-application','MCQ Test 2',category,10,10,'Application and scenarios for Serial Schedule.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-23-serial-schedule' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-serial-schedule-1','pt-dbms-sql-23-serial-schedule','What defines a serial schedule of T1 and T2?','["T1 and T2 execute simultaneously on different CPU cores", "One transaction''s operations all complete before the other transaction''s first operation begins — no interleaving at all", "T1 and T2 both commit at exactly the same time", "T1 and T2 read the same initial values"]'::jsonb,1,'A serial schedule has zero overlap in time between transactions — one runs to completion (commit or abort) before the next starts.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-serial-schedule-2','pt-dbms-sql-23-serial-schedule','Using the running example (A=1000, B=2000), what is the final value of A after the serial schedule <T1, T2>?','["1000", "900", "990", "1100"]'::jsonb,2,'T1 first reduces A to 900 (1000-100) and commits; T2 then applies 10% interest to 900, giving 990.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-serial-schedule-3','pt-dbms-sql-23-serial-schedule','Why do the serial schedules <T1, T2> and <T2, T1> produce different final balances for A and B?','["One of the two schedules must be incorrect", "Because the order of operations changes what value each transaction''s calculation is based on — T2''s interest is computed on a different base depending on whether T1 already withdrew ₹100", "Serial schedules never actually change any values", "Because COMMIT changes the semantics of R and W"]'::jsonb,1,'Whichever transaction runs second operates on the value left behind by the first, so different orders legitimately yield different (but each individually correct) final states.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-serial-schedule-4','pt-dbms-sql-23-serial-schedule','Why is serial execution a correctness reference when each transaction is correct in isolation on an appropriate valid state?','["It always maximizes the final balance", "No transaction observes another transaction’s partial execution, so the assumed isolated correctness can be composed in the chosen order", "It always uses fewer CPU cycles", "It replaces every application precondition"]'::jsonb,1,'The conclusion assumes correct individual transactions and a domain-valid order; serial execution cannot repair faulty logic.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-serial-schedule-5','pt-dbms-sql-23-serial-schedule','What is the main drawback of always using serial schedules in a production DBMS?','["They are mathematically impossible to construct", "They produce incorrect results", "They give up all the throughput/response-time benefits of interleaving, since every other transaction must wait idle even if it touches unrelated data", "They cannot be logged for recovery"]'::jsonb,2,'Forcing transactions to run strictly one-at-a-time means the system can never overlap one transaction''s I/O wait with another''s useful work, badly hurting throughput.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-serial-schedule-6','pt-dbms-sql-23-serial-schedule','With 3 transactions T1, T2, T3, how many distinct serial schedules (orderings) are possible?','["3", "6", "9", "1"]'::jsonb,1,'The number of serial schedules of n transactions is n! — for 3 transactions, 3! = 6.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-serial-schedule-7','pt-dbms-sql-23-serial-schedule','Is a schedule where T1 and T2 touch completely disjoint data items, but interleave in time, considered a serial schedule?','["Yes, because there''s no risk of interference", "No — ''serial'' is defined purely by timing (no overlap), regardless of whether the data accessed overlaps", "Yes, because disjoint data always implies seriality", "It depends on which data items are involved"]'::jsonb,1,'Seriality is about time ordering, not data overlap — if operations interleave in time at all, the schedule is non-serial even if perfectly safe.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-serial-schedule-8','pt-dbms-sql-23-serial-schedule','In serializability theory, what role does a serial schedule play?','["It is irrelevant — only non-serial schedules matter", "It serves as the reference standard: a non-serial schedule is judged correct precisely when it is equivalent to some serial schedule", "It is used only for deadlock detection", "It replaces the need for a precedence graph"]'::jsonb,1,'The entire theory of serializability (conflict and view) is about comparing an interleaved schedule against the gold-standard of some serial ordering of the same transactions.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-serial-schedule-fundamentals-9','pt-dbms-sql-23-serial-schedule','Can two serial orders produce different final values?','["Yes, noncommuting operations can depend on order", "No, serial means identical results", "Only if a primary key is missing", "Only after an abort"]'::jsonb,0,'Serial execution prevents interleaving, not order dependence.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-serial-schedule-fundamentals-10','pt-dbms-sql-23-serial-schedule','If the fixed transfer is changed to 200 before the same 10% increase from A=1000, B=2000, what is the final pair?','["880 and 2420", "990 and 2310", "900 and 2400", "1000 and 2300"]'::jsonb,0,'The changed transfer first gives 800 and 2200; the increase then gives 880 and 2420.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-serial-schedule-application-1','cx-serial-schedule-application','What is the T2-then-T1 final pair?','["990 and 2310", "1000 and 2300", "900 and 2000", "1100 and 2300"]'::jsonb,1,'The increase creates 1100 and 2200 before subtracting and adding 100.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-serial-schedule-application-2','cx-serial-schedule-application','Does serial execution fix a wrong calculation inside one transaction?','["Yes, automatically", "Only for integer values", "No", "Only with two sessions"]'::jsonb,2,'Individual transaction correctness remains an assumption to establish.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-serial-schedule-application-3','cx-serial-schedule-application','What does serializable allow that serial excludes?','["Wrong ownership checks", "Unbounded duplicate effects", "Ignoring transaction program order", "Operation interleaving with the required serial equivalence"]'::jsonb,3,'Serializability concerns equivalence rather than literal adjacency of whole executions.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-serial-schedule-application-4','cx-serial-schedule-application','An A-only transaction interleaves with a B-only transaction. Is the list serial?','["No", "Yes, because values are unrelated", "Only if both commit", "Only when A is numeric"]'::jsonb,0,'The definition uses operation interleaving, independent of conflict absence.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-serial-schedule-application-5','cx-serial-schedule-application','For three distinct transactions with the requirement T1 before T2, how many serial orders satisfy that constraint?','["Six", "Three", "Two", "One"]'::jsonb,1,'The valid orders are T1, T2, T3; T1, T3, T2; and T3, T1, T2. The ordering requirement excludes the other three permutations.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-serial-schedule-application-6','cx-serial-schedule-application','What changes if T1 must precede T2?','["The dependency disappears under serial execution", "Every request must succeed", "Some otherwise possible permutations are inadmissible", "All histories become identical"]'::jsonb,2,'Domain prerequisites constrain permissible orders.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-serial-schedule-application-7','cx-serial-schedule-application','Does equal final total prove equal per-item results?','["Yes, for all transactions", "Only if there are two columns", "Only under autocommit", "No"]'::jsonb,3,'Different pairs can sum to the same total.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-serial-schedule-application-8','cx-serial-schedule-application','Does one connection imply one transaction for its entire lifetime?','["No", "Yes, always", "Only if it uses SELECT", "Only with a primary key"]'::jsonb,0,'A session can execute multiple independent transactions.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-serial-schedule-application-9','cx-serial-schedule-application','Why can global one-at-a-time execution waste capacity?','["It removes all indexes", "Unrelated work can wait while the active transaction performs I/O", "It makes arithmetic invalid", "It prevents every commit"]'::jsonb,1,'Concurrency can overlap eligible independent work.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-serial-schedule-application-10','cx-serial-schedule-application','Which assumption supports serial histories as a correctness reference?','["Every transaction has the same SQL text", "Every result contains the same total", "Each transaction preserves required invariants in appropriate valid states", "Every connection uses the same display name"]'::jsonb,2,'Seriality does not establish the correctness of transaction logic itself.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
-- set-compatibility
select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-18-set-operations/set-compatibility' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'set-compatibility'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'set-compatibility'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('0b9ec540fde26c7054cc36572f86c6d6','5ed65b4fb3ebb33351c03c7b41d40ebb')) then raise exception 'Notes changed since seed; review before applying: %', 'set-compatibility'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-18-set-compatibility' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'set-compatibility'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-18-set-compatibility' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'set-compatibility'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-18-set-compatibility','pt-dbms-sql-18-set-compatibility-application')) then raise exception 'Extra topic tests require manual integration: %', 'set-compatibility'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-18-set-compatibility-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'set-compatibility'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Compatibility includes identity and duplicate policy", "description": "The exact repeated identity-and-label row merges only under UNION.", "columns": ["Projected row", "Morning appearances", "Evening appearances", "UNION ALL / UNION"], "rows": [["1,Ari", "1", "1", "2 / 1"], ["2,Bo", "1", "0", "1 / 1"], ["3,Bo", "0", "1", "1 / 1"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'set-compatibility'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Compatibility includes identity and duplicate policy", "description": "The exact repeated identity-and-label row merges only under UNION.", "columns": ["Projected row", "Morning appearances", "Evening appearances", "UNION ALL / UNION"], "rows": [["1,Ari", "1", "1", "2 / 1"], ["2,Bo", "1", "0", "1 / 1"], ["3,Bo", "0", "1", "1 / 1"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Compatibility includes identity and duplicate policy", "description": "The exact repeated identity-and-label row merges only under UNION.", "columns": ["Projected row", "Morning appearances", "Evening appearances", "UNION ALL / UNION"], "rows": [["1,Ari", "1", "1", "2 / 1"], ["2,Bo", "1", "0", "1 / 1"], ["3,Bo", "0", "1", "1 / 1"]]}]'::jsonb;
if exists(select 1 from public.test_questions where test_id='pt-dbms-sql-18-set-compatibility' and id not in ('tq-dbms-sql-18-set-compatibility-1','tq-dbms-sql-18-set-compatibility-2','tq-dbms-sql-18-set-compatibility-3','tq-dbms-sql-18-set-compatibility-4','tq-dbms-sql-18-set-compatibility-5','tq-dbms-sql-18-set-compatibility-6','tq-dbms-sql-18-set-compatibility-7','tq-dbms-sql-18-set-compatibility-8','pt-dbms-sql-18-set-compatibility-new-9','pt-dbms-sql-18-set-compatibility-new-10')) then raise exception 'Unexpected questions require review: %', 'pt-dbms-sql-18-set-compatibility'; end if;
