if exists(select 1 from public.test_questions where id='tq-dbms-sql-18-set-compatibility-1' and test_id<>'pt-dbms-sql-18-set-compatibility') then raise exception 'Question ID collision: %', 'tq-dbms-sql-18-set-compatibility-1'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-18-set-compatibility-1' and test_id='pt-dbms-sql-18-set-compatibility') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-18-set-compatibility-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-18-set-compatibility-1' and (question_text,options,correct_index,explanation) is distinct from ('What does set (union) compatibility require of two queries combined with UNION/INTERSECT/EXCEPT?','["Identical column names", "The same number of columns, with compatible types in corresponding positions", "Both queries must reference the same table", "Both queries must return the same number of rows"]'::jsonb,1,'Column count and type compatibility are the structural requirements — not matching names.') and (question_text,options,correct_index,explanation) is distinct from ('How are columns aligned across set operands?','["By matching aliases", "By ordinal position", "By alphabetical name", "By primary-key declaration"]'::jsonb,1,'The first expression aligns with the first expression regardless of labels.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-18-set-compatibility-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-18-set-compatibility-2' and test_id<>'pt-dbms-sql-18-set-compatibility') then raise exception 'Question ID collision: %', 'tq-dbms-sql-18-set-compatibility-2'; end if;
