if exists(select 1 from public.test_questions where id='tq-dbms-sql-18-set-compatibility-2' and (question_text,options,correct_index,explanation) is distinct from ('Do the column names in the two queries combined by UNION need to match?','["Yes, they must be identical", "No \u2014 only column count and type compatibility matter; names don''t need to match", "Only the first column''s name must match", "Names must be different, never the same"]'::jsonb,1,'Structural compatibility is about count/type, not naming.') and (question_text,options,correct_index,explanation) is distinct from ('What arity must operands have?','["The same table size", "The same number of projected columns", "Exactly one column always", "Exactly two rows"]'::jsonb,1,'Set operators require corresponding positions across operand projections.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-18-set-compatibility-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-18-set-compatibility-3' and test_id<>'pt-dbms-sql-18-set-compatibility') then raise exception 'Question ID collision: %', 'tq-dbms-sql-18-set-compatibility-3'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-18-set-compatibility-3' and test_id='pt-dbms-sql-18-set-compatibility') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-18-set-compatibility-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-18-set-compatibility-3' and (question_text,options,correct_index,explanation) is distinct from ('Where do the final output column names in a UNION/INTERSECT/EXCEPT result come from?','["Always auto-generated as col1, col2, etc.", "The FIRST query''s column names/aliases", "The LAST query''s column names/aliases", "Alphabetically sorted across both queries"]'::jsonb,1,'The first query''s naming determines the combined result''s output names.') and (question_text,options,correct_index,explanation) is distinct from ('Why avoid SELECT* for a stable combined output?','["It always returns duplicates only", "Source changes can alter position and arity", "It disables indexes", "It grants access"]'::jsonb,1,'Explicit projections preserve the intended output schema.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-18-set-compatibility-3'; end if;
