if exists(select 1 from public.test_questions where id='tq-dbms-sql-18-set-compatibility-4' and (question_text,options,correct_index,explanation) is distinct from ('Is passing the set-compatibility check (right column count/types) a guarantee that the combination is semantically meaningful?','["Yes, structural compatibility guarantees semantic correctness", "No \u2014 the database only checks structure, not whether combining the data actually makes sense for the use case", "Semantic meaning is checked automatically by every SQL engine", "This distinction doesn''t apply to set operations"]'::jsonb,1,'Structural compatibility and semantic sensibility are separate concerns — SQL only enforces the former.') and (question_text,options,correct_index,explanation) is distinct from ('Does casting course codes and room codes to text establish a shared domain?','["Yes", "No", "Only with UNION ALL", "Only after sorting"]'::jsonb,1,'Representation compatibility does not establish business meaning.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-18-set-compatibility-4'; end if;
