if exists(select 1 from public.test_questions where id='tq-dbms-sql-18-set-compatibility-5' and (question_text,options,correct_index,explanation) is distinct from ('What happens if two queries combined with UNION have a different number of columns?','["Extra columns are silently dropped", "This is a hard error \u2014 column counts must match", "Missing columns are automatically filled with NULL", "The queries run separately and results are concatenated"]'::jsonb,1,'Mismatched column counts are a straightforward structural error, not silently resolved.') and (question_text,options,correct_index,explanation) is distinct from ('What does UNION ALL retain?','["Only unique identities automatically", "Every operand appearance", "Only nonnull values", "Only first-operand rows"]'::jsonb,1,'ALL preserves duplicate result appearances.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-18-set-compatibility-5'; end if;
