if exists(select 1 from public.test_questions where id='tq-dbms-sql-18-set-compatibility-6' and (question_text,options,correct_index,explanation) is distinct from ('Can an INT column and a DECIMAL column generally be combined via UNION?','["Never, this always causes an error", "Often yes, via implicit type conversion, though genuinely incompatible types (like numbers and non-numeric text) may error or convert unpredictably", "Only if both columns contain exactly the same values", "Only in NoSQL databases"]'::jsonb,1,'Reasonably compatible numeric types are often implicitly converted, unlike fundamentally mismatched types.') and (question_text,options,correct_index,explanation) is distinct from ('What does ordinary UNION remove?','["Every repeated name regardless of other columns", "Duplicate complete projected rows", "Only duplicate primary keys", "Only null rows"]'::jsonb,1,'Duplicate comparison concerns the full output row.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-18-set-compatibility-6'; end if;
