update public.learning_topics set short_description='Tune set queries by preserving duplicate and identity contracts, then measure branch access, deduplication, ordering and complete execution plans on representative data.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Tune set queries by preserving duplicate and identity contracts, then measure branch access, deduplication, ordering and complete execution plans on representative data.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Set Operation Performance.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-18-set-operation-performance' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-set-operation-performance-application','MCQ Test 2',category,10,10,'Application and scenarios for Set Operation Performance.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-18-set-operation-performance' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-set-operation-performance-1','pt-dbms-sql-18-set-operation-performance','What is the main performance cost specific to plain UNION (versus UNION ALL)?','["Sorting the final result", "The deduplication step, requiring rows to be compared against each other", "Checking union-compatibility", "Parsing the SQL syntax"]'::jsonb,1,'Comparing rows to remove duplicates is UNION''s distinctive extra cost over UNION ALL.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-set-operation-performance-2','pt-dbms-sql-18-set-operation-performance','When is replacing UNION with UNION ALL a valid candidate optimization?','["Whenever the query becomes shorter", "When retained multiplicity is required or the full projected input is proved duplicate-free at the required identity", "Whenever sources have different table names", "Whenever an index exists"]'::jsonb,1,'No universal most-impactful rule exists. Prove semantics, including within-source duplicates, before measuring.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-set-operation-performance-3','pt-dbms-sql-18-set-operation-performance','Is there a universal rule for whether a set operation or an equivalent join/subquery performs better?','["Yes, joins are always faster", "No — it depends on data size, indexes, and the specific engine''s optimizer; comparing actual execution plans is more reliable than a general rule", "Yes, set operations are always faster", "Set operations and joins always have identical performance"]'::jsonb,1,'Performance comparisons here are genuinely context-dependent, not governed by a universal rule.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-set-operation-performance-4','pt-dbms-sql-18-set-operation-performance','Can indexes help speed up a set operation''s deduplication/matching step?','["No, indexes only help WHERE clauses", "Yes — indexes on the relevant columns can speed up the comparison work, similar to their effect on JOIN or GROUP BY", "Indexes make set operations slower", "Only INTERSECT can benefit from indexes, not UNION or EXCEPT"]'::jsonb,1,'Indexes can help source access or eligible comparison strategies, but cannot guarantee a particular global combination plan or eliminate distinct work.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-set-operation-performance-5','pt-dbms-sql-18-set-operation-performance','What common, low-effort audit is worth doing on a slow query using plain UNION?','["Checking whether UNION could be replaced with UNION ALL if duplicates genuinely can''t occur or don''t matter", "Removing all WHERE clauses", "Adding more UNION statements", "Switching to a NoSQL database"]'::jsonb,0,'This is a frequently overlooked, easy performance check.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-set-operation-performance-6','pt-dbms-sql-18-set-operation-performance','Where should you look to make a reliable performance comparison between competing query formulations?','["General online rules of thumb only", "Actual execution plans for the realistic alternatives (Chapter 35)", "The query''s character count", "The number of tables referenced"]'::jsonb,1,'Inspect plans for realistic equivalent alternatives and use representative actual execution measurements. Estimates alone do not establish elapsed performance.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-set-operation-performance-7','pt-dbms-sql-18-set-operation-performance','Is deduplication''s cost purely theoretical, or does it matter in practice for large result sets?','["Purely theoretical, with no real practical impact", "It''s a genuine, significant cost for large result sets, not just a theoretical concern", "It only matters for INTERSECT, not UNION", "It only matters when ORDER BY is also used"]'::jsonb,1,'Distinct work can be material for large or wide populations, but its relative importance depends on the actual plan and workload.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-set-operation-performance-8','pt-dbms-sql-18-set-operation-performance','Can combining several large plain UNIONs in one analytics query create a hidden performance problem?','["No, UNION has no cumulative cost across multiple uses", "Yes — repeated deduplication passes across several large UNIONed queries can be a genuine, easy-to-overlook cost source", "This only happens with UNION ALL, never plain UNION", "Combining UNIONs always improves performance"]'::jsonb,1,'Several set boundaries can add work, but textual UNION count does not prove physical pass count; inspect grouping, semantics and optimizer plan.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-set-operation-performance-fundamentals-9','pt-dbms-sql-18-set-operation-performance','What must be proved before a performance rewrite is compared?','["That it preserves the required result contract", "That it has fewer characters", "That it uses a fashionable keyword", "That it removes all ORDER BY clauses"]'::jsonb,0,'A faster answer to a different question is not the same optimization.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-set-operation-performance-fundamentals-10','pt-dbms-sql-18-set-operation-performance','Do nonoverlapping source tables guarantee disjoint projected learner identifiers?','["Yes, always", "No", "Only if table names include years", "Only after a restart"]'::jsonb,1,'Different stored events can project the same learner identity.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-set-operation-performance-application-1','cx-set-operation-performance-application','Can within-source duplicates make UNION ALL wrong for a distinct report?','["No, only cross-source overlap matters", "Yes", "Only for strings", "Only if the second source is empty"]'::jsonb,1,'The final distinct population must account for duplicates from any input.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-set-operation-performance-application-2','cx-set-operation-performance-application','Does distinctness guarantee final sorted output?','["Yes, always", "Only for integer keys", "No", "Only with two branches"]'::jsonb,2,'Duplicate comparison and output ordering are separate requirements.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-set-operation-performance-application-3','cx-set-operation-performance-application','Why can removing a projected description change the result?','["It always increases storage", "It disables every index", "It convertsNULLtozero", "It can change which full rows compare equal"]'::jsonb,3,'Projection determines the compared identity.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-set-operation-performance-application-4','cx-set-operation-performance-application','What does an index on a branch key not prove?','["That the global combination needs no distinct work", "That the key exists", "That source rows can be compared", "That the index definition names a branch key"]'::jsonb,0,'The combination plan must be inspected independently.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-set-operation-performance-application-5','cx-set-operation-performance-application','Does EXPLAIN by itself provide actual execution timing?','["Yes, universally", "No", "Only with short aliases", "Only if output has one row"]'::jsonb,1,'Estimates and executed measurements are different evidence levels.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-set-operation-performance-application-6','cx-set-operation-performance-application','What can an outer ORDER BY add to UNION ALL?','["Automatic deduplication always", "A primary-key constraint", "Sorting work on the combined population", "A guaranteed zero-cost limit"]'::jsonb,2,'Retaining duplicates does not remove every later operator cost.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-set-operation-performance-application-7','cx-set-operation-performance-application','Does the number of textual UNION operators prove physical deduplication pass count?','["Yes, one pass per keyword always", "Only for three sources", "Only when cached", "No"]'::jsonb,3,'Optimizer transformations can change the physical plan.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-set-operation-performance-application-8','cx-set-operation-performance-application','Can a raw join rewrite multiply rows where a distinct set result would not?','["Yes", "No, all rowsets have identical multiplicity", "Only without a column alias", "Only after sorting"]'::jsonb,0,'Every matching pair can contribute a joined row.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-set-operation-performance-application-9','cx-set-operation-performance-application','What should a fair benchmark record?','["Only a screenshot", "Engine, schema, indexes, distribution, parameters and matching results", "Only elapsed time from one tiny input", "Only query length"]'::jsonb,1,'The conditions are needed to interpret and reproduce measurements.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-set-operation-performance-application-10','cx-set-operation-performance-application','Can a later ALL recover multiplicity removed by an earlier distinct boundary?','["Yes, always", "Only if the row reappears nowhere", "No", "Only on a replica"]'::jsonb,2,'Discarded duplicates are no longer present to be restored by that operator.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
