if exists(select 1 from public.test_questions where id='tq-dbms-sql-19-simple-views-1' and (question_text,options,correct_index,explanation) is distinct from ('What defines a ''simple view'' as opposed to a ''complex view''?','["It uses fewer than 100 rows", "It is based on a single table with no joins, aggregation, GROUP BY, or DISTINCT", "It is read-only", "It has no WHERE clause"]'::jsonb,1,'A simple view draws from one base table and performs no joins, aggregation, GROUP BY, or DISTINCT — essentially a filtered/projected view of one table.') and (question_text,options,correct_index,explanation) is distinct from ('What defines a ''simple view'' as opposed to a ''complex view''?','["It uses fewer than 100 rows", "It is based on a single table with no joins, aggregation, GROUP BY, or DISTINCT", "It is read-only", "It has no WHERE clause"]'::jsonb,1,'A simple view draws from one base table and performs no joins, aggregation, GROUP BY, or DISTINCT — essentially a filtered/projected view of one table.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-19-simple-views-1'; end if;
