if exists(select 1 from public.test_questions where id='tq-dbms-sql-19-simple-views-2' and (question_text,options,correct_index,explanation) is distinct from ('When you run `SELECT * FROM high_earners`, where does the data actually come from?','["A cached copy stored inside the view", "The underlying employees table, queried fresh at that moment", "A snapshot taken when the view was created", "The database''s system catalog"]'::jsonb,1,'A plain (non-materialized) view has no storage of its own; it re-runs its defining query against the base table each time it is queried.') and (question_text,options,correct_index,explanation) is distinct from ('When you run `SELECT * FROM high_earners`, where does the data actually come from?','["A cached copy stored inside the view", "The underlying employees table, queried fresh at that moment", "A snapshot taken when the view was created", "The database''s system catalog"]'::jsonb,1,'A plain (non-materialized) view has no storage of its own; it re-runs its defining query against the base table each time it is queried.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-19-simple-views-2'; end if;
