if exists(select 1 from public.test_questions where id='tq-dbms-sql-19-simple-views-3' and (question_text,options,correct_index,explanation) is distinct from ('Given `CREATE VIEW high_earners AS SELECT id, name, salary FROM employees WHERE salary > 80000;`, what happens if an employee''s salary is updated through the view from 85000 down to 70000?','["The update is rejected outright", "The row disappears from subsequent queries on the view because it no longer matches the WHERE clause", "The view definition is automatically changed", "The underlying table is unaffected"]'::jsonb,1,'Since the row no longer satisfies salary > 80000, it will no longer appear when the view is queried again — unless WITH CHECK OPTION is used to prevent such updates.') and (question_text,options,correct_index,explanation) is distinct from ('Given `CREATE VIEW high_earners AS SELECT id, name, salary FROM employees WHERE salary > 80000; `, what happens if an employee''s salary is updated through the view from 85000 down to 70000?','["The update is rejected outright", "The row disappears from subsequent queries on the view because it no longer matches the WHERE clause", "The view definition is automatically changed", "The underlying table is unaffected"]'::jsonb,1,'Since the row no longer satisfies salary > 80000, it will no longer appear when the view is queried again — unless WITH CHECK OPTION is used to prevent such updates.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-19-simple-views-3'; end if;
