insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-simple-views-1','pt-dbms-sql-19-simple-views','What defines a ''simple view'' as opposed to a ''complex view''?','["It uses fewer than 100 rows", "It is based on a single table with no joins, aggregation, GROUP BY, or DISTINCT", "It is read-only", "It has no WHERE clause"]'::jsonb,1,'A simple view draws from one base table and performs no joins, aggregation, GROUP BY, or DISTINCT — essentially a filtered/projected view of one table.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
