insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-simple-views-4','pt-dbms-sql-19-simple-views','Which of the following is a valid simple view definition?','["CREATE VIEW v AS SELECT department, AVG(salary) FROM employees GROUP BY department;", "CREATE VIEW v AS SELECT e.name, d.name FROM employees e JOIN departments d ON e.department = d.id;", "CREATE VIEW v AS SELECT id, name, department FROM employees;", "CREATE VIEW v AS SELECT DISTINCT department FROM employees;"]'::jsonb,2,'This is a single-table projection with no joins, aggregation, GROUP BY, or DISTINCT — the hallmark of a simple view. The others involve GROUP BY, a JOIN, or DISTINCT, making them complex views.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
