insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-single-row-subquery-1','pt-dbms-sql-17-single-row-subquery','A single-row subquery is intended to be used with which operators?','["IN only", "=, <, >, and similar comparison operators", "EXISTS only", "UNION"]'::jsonb,1,'Single-row subqueries pair with plain comparison operators because exactly one value is expected.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-single-row-subquery-2','pt-dbms-sql-17-single-row-subquery','What happens at runtime if a subquery used with `=` unexpectedly returns 3 rows?','["The database picks the first row automatically", "The database raises a runtime error", "The comparison silently becomes FALSE", "The query returns NULL for all rows"]'::jsonb,1,'Comparison operators like `=` require at most one row; more than one row is a runtime error, not a silent fallback.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-single-row-subquery-3','pt-dbms-sql-17-single-row-subquery','What happens if a single-row subquery used with `>` returns ZERO rows?','["A runtime error", "The comparison evaluates to UNKNOWN, excluding the row", "The comparison evaluates to TRUE", "A syntax error"]'::jsonb,1,'Zero rows makes the subquery NULL, and any comparison against NULL is UNKNOWN, so the row is excluded — no error.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-single-row-subquery-4','pt-dbms-sql-17-single-row-subquery','Given `WHERE department = (SELECT department FROM employees WHERE manager_id = 5)`, where manager_id=5 matches both Dave and Frank, what is the outcome?','["It returns rows for whichever department appears first", "Runtime error: subquery returns more than one row", "It silently returns zero rows", "It automatically converts to IN"]'::jsonb,1,'Two rows come back from the subquery, which `=` cannot handle, so the engine raises the more-than-one-row error.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-single-row-subquery-5','pt-dbms-sql-17-single-row-subquery','In the one-column comparison form used here, how does single-row comparison relate to a scalar subquery?','["Completely unrelated concepts", "Both use an at-most-one-row, one-column scalar operand here; general row subqueries can instead compare multiple columns", "Single-row subqueries can return multiple columns", "Scalar subqueries can never be used in WHERE"]'::jsonb,1,'The lesson focuses scalar comparisons without claiming that every possible single-row subquery must have one column.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-single-row-subquery-6','pt-dbms-sql-17-single-row-subquery','If a subquery returns two rows with the identical value (e.g., both ''Sales''), and it''s compared with `=`, what happens in engines like PostgreSQL?','["It succeeds because the values are identical", "It still raises \"more than one row\" — the check is on row count, not distinct values", "It automatically deduplicates first", "It returns ''Sales'' twice as the result"]'::jsonb,1,'The engine checks how many rows came back, not whether their values happen to match — two rows is still an error.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-single-row-subquery-7','pt-dbms-sql-17-single-row-subquery','When the requirement asks for the maximum, which shape provides one aggregate row even if several source rows qualify?','["Adding DISTINCT only", "An ungrouped MAX expression without HAVING that removes the aggregate row", "Using SELECT *", "Adding ORDER BY"]'::jsonb,1,'GROUP BY can create several rows and HAVING can remove the aggregate row; selecting MAX must also match the intended business question.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-single-row-subquery-8','pt-dbms-sql-17-single-row-subquery','Why is "subquery returns more than one row" considered a good failure mode compared to many SQL bugs?','["Because it silently returns wrong data", "Because the database fails loudly instead of guessing which row to use", "Because it prevents the query from ever running again", "Because it converts the query to a join automatically"]'::jsonb,1,'Rather than arbitrarily picking one of several rows and risking a wrong answer, the engine refuses to guess and errors instead.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-17-single-row-subquery-new-9','pt-dbms-sql-17-single-row-subquery','A subquery produces one scalar threshold. Can the outer query return several matching rows?','["Yes", "No, scalar means one final row", "Only after a rollback", "Only if IDs repeat"]'::jsonb,0,'The operand shape does not limit the outer match count.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
