if exists(select 1 from public.test_questions where id='tq-dbms-sql-13-stable-sorting-1' and (question_text,options,correct_index,explanation) is distinct from ('What does it mean for a sort to be ''stable''?','["It always sorts in ascending order", "Rows with equal sort-key values keep a consistent, repeatable relative order across runs", "It never includes NULL values", "It executes in constant time regardless of table size"]'::jsonb,1,'Stability specifically concerns tie-breaking: whether rows tied on the sort key(s) retain the same relative order every time the sort runs.') and (question_text,options,correct_index,explanation) is distinct from ('What does ORDER BY category alone specify for repeated categories?','["A mandatory primary-key tie order", "Category order but not relative identity order within a category", "Insertion order for every tie", "A guaranteed random sample"]'::jsonb,1,'All listed terms can tie.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-13-stable-sorting-1'; end if;
