if exists(select 1 from public.test_questions where id='tq-dbms-sql-13-stable-sorting-2' and (question_text,options,correct_index,explanation) is distinct from ('Does plain `ORDER BY category` guarantee the same relative order for two rows that share the same category value, across repeated executions?','["Yes, SQL guarantees ties always resolve identically", "No \u2014 the relative order of tied rows is not guaranteed and can differ between runs", "Yes, but only in PostgreSQL", "No, because ORDER BY cannot be used on non-unique columns"]'::jsonb,1,'When rows tie on all specified ORDER BY columns, SQL does not guarantee any particular relative order among them, and it can vary between executions.') and (question_text,options,correct_index,explanation) is distinct from ('What commonly completes a base-table category order?','["Removing ORDER BY", "A final unique identity with an explicit direction", "Increasing the limit only", "An unrelated comment"]'::jsonb,1,'The complete tuple distinguishes rows.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-13-stable-sorting-2'; end if;
