if exists(select 1 from public.test_questions where id='tq-dbms-sql-13-stable-sorting-3' and (question_text,options,correct_index,explanation) is distinct from ('What is the standard fix to make an ORDER BY clause fully deterministic?','["Add LIMIT to the query", "Append a guaranteed-unique column, such as the primary key, as the final sort key", "Use SELECT DISTINCT instead of ORDER BY", "Remove all WHERE conditions"]'::jsonb,1,'Adding a unique column as the last ORDER BY key eliminates any remaining ties, making the sort order fully deterministic.') and (question_text,options,correct_index,explanation) is distinct from ('Does repeatedly observing the same tied order make it guaranteed?','["Yes, after two executions", "No", "Only if the UI is desktop", "Only if categories are text"]'::jsonb,1,'Observed behavior is weaker than a query contract.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-13-stable-sorting-3'; end if;
