update public.learning_topics set short_description='Make SQL result order reproducible with unique result-grain tiebreakers, explicit null policies and correct outer ordering across paging and joins.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Make SQL result order reproducible with unique result-grain tiebreakers, explicit null policies and correct outer ordering across paging and joins.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Stable Sorting.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-13-stable-sorting' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-13-stable-sorting-application','MCQ Test 2',category,10,10,'Application and scenarios for Stable Sorting.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-13-stable-sorting' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-stable-sorting-1','pt-dbms-sql-13-stable-sorting','What does ORDER BY category alone specify for repeated categories?','["A mandatory primary-key tie order", "Category order but not relative identity order within a category", "Insertion order for every tie", "A guaranteed random sample"]'::jsonb,1,'All listed terms can tie.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-stable-sorting-2','pt-dbms-sql-13-stable-sorting','What commonly completes a base-table category order?','["Removing ORDER BY", "A final unique identity with an explicit direction", "Increasing the limit only", "An unrelated comment"]'::jsonb,1,'The complete tuple distinguishes rows.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-stable-sorting-3','pt-dbms-sql-13-stable-sorting','Does repeatedly observing the same tied order make it guaranteed?','["Yes, after two executions", "No", "Only if the UI is desktop", "Only if categories are text"]'::jsonb,1,'Observed behavior is weaker than a query contract.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-stable-sorting-4','pt-dbms-sql-13-stable-sorting','Can a complete order specify identities selected by a LIMIT boundary?','["Only for tables with one column", "Yes, for the same visible data and query", "No, identity never matters", "Only without filters"]'::jsonb,1,'Every competing row has a defined place.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-stable-sorting-5','pt-dbms-sql-13-stable-sorting','Does deterministic ordering freeze future data changes?','["Yes, primary keys freeze every row", "Only for ascending lists", "No", "Only for numeric measures"]'::jsonb,2,'Visibility over time is a separate requirement.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-stable-sorting-6','pt-dbms-sql-13-stable-sorting','For equal priority, due_day, which term can distinguish ticket rows?','["A constant literal", "Unique ticket_id", "The same repeated priority", "A hidden insertion sequence assumption"]'::jsonb,1,'A genuine final unique value resolves remaining ties.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-stable-sorting-7','pt-dbms-sql-13-stable-sorting','Why can equipment_id stop being unique after a join?','["Joins delete every identity", "Several inspection rows can belong to one item", "All join columns become NULL", "SQL prohibits ordered joins"]'::jsonb,1,'Uniqueness must hold at result grain.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-13-stable-sorting-8','pt-dbms-sql-13-stable-sorting','What does a stable sorting algorithm preserve?','["All table insertion positions as a SQL guarantee", "The relative input order of equal-key elements", "A cross-request database snapshot", "A fixed execution plan forever"]'::jsonb,1,'SQL does not supply an implicit ordered input table.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
