if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-strict-schedule-1' and (question_text,options,correct_index,explanation) is distinct from ('What is the defining rule of a strict schedule?','["No transaction may ever write the same item twice", "A transaction may not read OR write a data item written by another transaction until that other transaction has committed or aborted", "All transactions must be read-only", "Every schedule must be serial"]'::jsonb,1,'Strictness extends cascadelessness''s read restriction to also cover writes: nobody may touch an item another uncommitted transaction wrote, until that transaction resolves (commits or aborts).') and (question_text,options,correct_index,explanation) is distinct from ('What is the defining rule of a strict schedule?','["No transaction may ever write the same item twice", "A transaction may not read OR write a data item written by another transaction until that other transaction has committed or aborted", "All transactions must be read-only", "Every schedule must be serial"]'::jsonb,1,'Strictness extends cascadelessness''s read restriction to also cover writes: nobody may touch an item another uncommitted transaction wrote, until that transaction resolves (commits or aborts).')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-strict-schedule-1'; end if;
