if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-strict-schedule-2' and (question_text,options,correct_index,explanation) is distinct from ('In the ''Cascadeless but NOT Strict'' worked example, why is that schedule considered cascadeless despite T2 writing A before T1 commits?','["Because T2 never actually writes A", "Because T2''s operation is a blind write (no read), so there is no dirty READ for another transaction to depend on \u2014 cascadelessness only restricts reads, not writes", "Because T1 commits immediately after", "Because cascadelessness doesn''t apply to numeric data"]'::jsonb,1,'Cascadelessness is purely about preventing dirty reads; since T2 never reads A, there''s no read-based dependency chain, so the schedule passes the cascadeless test even though it fails the stricter write-based test.') and (question_text,options,correct_index,explanation) is distinct from ('In history w1(A),w2(A),c1,c2 with no reads,why can cascadelessness hold while strictness fails?','["Because T2 never actually writes A", "Because T2''s operation is a blind write (no read), so there is no dirty READ for another transaction to depend on \u2014 cascadelessness only restricts reads, not writes", "Because T1 commits immediately after", "Because cascadelessness doesn''t apply to numeric data"]'::jsonb,1,'Cascadelessness is purely about preventing dirty reads; since T2 never reads A, there''s no read-based dependency chain, so the schedule passes the cascadeless test even though it fails the stricter write-based test.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-strict-schedule-2'; end if;
