if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-strict-schedule-4' and (question_text,options,correct_index,explanation) is distinct from ('What is the correct ordering of strictness among the three properties in this mini-hierarchy?','["Recoverable is strictest, then cascadeless, then strict", "Strict implies cascadeless, and cascadeless implies recoverable (strict is the strongest guarantee, recoverable the weakest)", "All three properties are exactly equivalent", "Cascadeless is strictest, then strict, then recoverable"]'::jsonb,1,'The hierarchy is Strict ⊂ Cascadeless ⊂ Recoverable — every strict schedule is cascadeless, and every cascadeless schedule is recoverable, but not vice versa.') and (question_text,options,correct_index,explanation) is distinct from ('What is the correct ordering of strictness among the three properties in this mini-hierarchy?','["Recoverable is strictest, then cascadeless, then strict", "Strict implies cascadeless, and cascadeless implies recoverable (strict is the strongest guarantee, recoverable the weakest)", "All three properties are exactly equivalent", "Cascadeless is strictest, then strict, then recoverable"]'::jsonb,1,'The hierarchy is Strict ⊂ Cascadeless ⊂ Recoverable — every strict schedule is cascadeless, and every cascadeless schedule is recoverable, but not vice versa.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-strict-schedule-4'; end if;
