if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-strict-schedule-5' and (question_text,options,correct_index,explanation) is distinct from ('Which real-world locking technique naturally produces strict schedules?','["Shared locks released immediately after a read", "Exclusive locks on written items held until the transaction commits or aborts (as in strict two-phase locking)", "No locking at all", "Locks that expire after a fixed timer, regardless of commit status"]'::jsonb,1,'Holding an exclusive lock on a written item until commit/abort ensures no other transaction can read or write that item in the meantime, which is exactly the strict schedule guarantee.') and (question_text,options,correct_index,explanation) is distinct from ('Which real-world locking technique naturally produces strict schedules?','["Shared locks released immediately after a read", "Exclusive locks on written items held until the transaction commits or aborts (as in strict two-phase locking)", "No locking at all", "Locks that expire after a fixed timer, regardless of commit status"]'::jsonb,1,'In the classical single-version compatible-lock model,retained exclusive locks prevent access to the unresolved written value. Multiversion reads of older committed values need separate interpretation.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-strict-schedule-5'; end if;
