if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-strict-schedule-7' and (question_text,options,correct_index,explanation) is distinct from ('Is strictness related to whether a schedule is conflict-serializable?','["Strictness guarantees conflict serializability automatically", "They are orthogonal/independent properties \u2014 a schedule can be strict but not conflict-serializable, or conflict-serializable but not strict; real systems aim to guarantee both", "Conflict serializability guarantees strictness automatically", "They are the exact same property under different names"]'::jsonb,1,'Serializability concerns the equivalence of results to a serial order; strictness concerns safe handling of commits/aborts for recovery — the two are independent axes a schedule can satisfy or fail separately.') and (question_text,options,correct_index,explanation) is distinct from ('Is strictness related to whether a schedule is conflict-serializable?','["Strictness guarantees conflict serializability automatically", "They are orthogonal/independent properties \u2014 a schedule can be strict but not conflict-serializable, or conflict-serializable but not strict; real systems aim to guarantee both", "Conflict serializability guarantees strictness automatically", "They are the exact same property under different names"]'::jsonb,1,'Serializability concerns the equivalence of results to a serial order; strictness concerns safe handling of commits/aborts for recovery — the two are independent axes a schedule can satisfy or fail separately.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-strict-schedule-7'; end if;
