update public.learning_topics set short_description='Analyze strict schedules with dirty reads and dirty writes, distinguish recoverability from serializability, and understand the limits of lock and MVCC interpretations.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Analyze strict schedules with dirty reads and dirty writes, distinguish recoverability from serializability, and understand the limits of lock and MVCC interpretations.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Strict Schedule.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-23-strict-schedule' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-23-strict-schedule-application','MCQ Test 2',category,10,10,'Application and scenarios for Strict Schedule.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-23-strict-schedule' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-strict-schedule-1','pt-dbms-sql-23-strict-schedule','What is the defining rule of a strict schedule?','["No transaction may ever write the same item twice", "A transaction may not read OR write a data item written by another transaction until that other transaction has committed or aborted", "All transactions must be read-only", "Every schedule must be serial"]'::jsonb,1,'Strictness extends cascadelessness''s read restriction to also cover writes: nobody may touch an item another uncommitted transaction wrote, until that transaction resolves (commits or aborts).',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-strict-schedule-2','pt-dbms-sql-23-strict-schedule','In history w1(A),w2(A),c1,c2 with no reads,why can cascadelessness hold while strictness fails?','["Because T2 never actually writes A", "Because T2''s operation is a blind write (no read), so there is no dirty READ for another transaction to depend on — cascadelessness only restricts reads, not writes", "Because T1 commits immediately after", "Because cascadelessness doesn''t apply to numeric data"]'::jsonb,1,'Cascadelessness is purely about preventing dirty reads; since T2 never reads A, there''s no read-based dependency chain, so the schedule passes the cascadeless test even though it fails the stricter write-based test.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-strict-schedule-3','pt-dbms-sql-23-strict-schedule','Why can w1(A),w2(A),a1 complicate a naive item-before-image undo procedure?','["It doesn''t cause any real problem", "Blindly restoringT1’s old value could eraseT2’s intervening write; strict scheduling avoids that dirty-write ordering", "It causes a syntax error", "It only matters if T2 also aborts"]'::jsonb,1,'This is a simplified undo motivation,not a claim that every real logging/version algorithm cannot identify later writes.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-strict-schedule-4','pt-dbms-sql-23-strict-schedule','What is the correct ordering of strictness among the three properties in this mini-hierarchy?','["Recoverable is strictest, then cascadeless, then strict", "Strict implies cascadeless, and cascadeless implies recoverable (strict is the strongest guarantee, recoverable the weakest)", "All three properties are exactly equivalent", "Cascadeless is strictest, then strict, then recoverable"]'::jsonb,1,'The hierarchy is Strict ⊂ Cascadeless ⊂ Recoverable — every strict schedule is cascadeless, and every cascadeless schedule is recoverable, but not vice versa.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-strict-schedule-5','pt-dbms-sql-23-strict-schedule','Which real-world locking technique naturally produces strict schedules?','["Shared locks released immediately after a read", "Exclusive locks on written items held until the transaction commits or aborts (as in strict two-phase locking)", "No locking at all", "Locks that expire after a fixed timer, regardless of commit status"]'::jsonb,1,'In the classical single-version compatible-lock model,retained exclusive locks prevent access to the unresolved written value. Multiversion reads of older committed values need separate interpretation.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-strict-schedule-6','pt-dbms-sql-23-strict-schedule','Why is strict scheduling useful to a simple recovery design?','["Strict schedules run faster in every case", "It prevents another transaction’s unresolved overwrite/read dependencies on a writer, simplifying recovery reasoning", "Strict schedules eliminate the need for a precedence graph", "Cascadeless and recoverable schedules are illegal under the SQL standard"]'::jsonb,1,'The benefit is bounded to the stated model. Actual crash correctness and multiversion behavior require their own engine-specific evidence.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-strict-schedule-7','pt-dbms-sql-23-strict-schedule','Is strictness related to whether a schedule is conflict-serializable?','["Strictness guarantees conflict serializability automatically", "They are orthogonal/independent properties — a schedule can be strict but not conflict-serializable, or conflict-serializable but not strict; real systems aim to guarantee both", "Conflict serializability guarantees strictness automatically", "They are the exact same property under different names"]'::jsonb,1,'Serializability concerns the equivalence of results to a serial order; strictness concerns safe handling of commits/aborts for recovery — the two are independent axes a schedule can satisfy or fail separately.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-strict-schedule-8','pt-dbms-sql-23-strict-schedule','What does the term ''strict'' refer to in ''strict schedule''?','["A SQL engine configuration setting like strict mode for data types", "A formal scheduling property about blocking reads and writes to data written by an uncommitted transaction until it resolves", "A requirement that the schedule be serial", "A rule that transactions must strictly alternate operations one at a time"]'::jsonb,1,'This is a common point of confusion — ''strict'' here is unrelated to SQL strict mode; it''s purely a concurrency-control scheduling property.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-strict-schedule-new-9','pt-dbms-sql-23-strict-schedule','After w1(A),which T2 operation violates strictness beforec1 or a1?','["Only a read", "Either r2(A) or w2(A)", "Only a write", "Neither"]'::jsonb,1,'The rule forbids both dirty reads and dirty writes.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-strict-schedule-new-10','pt-dbms-sql-23-strict-schedule','May T1 reread its own uncommitted A under this cross-transaction rule?','["Never", "Only afterT2 commits", "Yes", "Only ifA is numeric"]'::jsonb,2,'Own changes are not another transaction’s unresolved write.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-strict-schedule-application-new-1','pt-dbms-sql-23-strict-schedule-application','Does working on an independent itemB require waiting solely becauseT1 wroteA?','["Yes, all database work stops", "Only for SELECT", "Only with one connection", "No under this item rule"]'::jsonb,3,'The restriction is scoped to the item written.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-strict-schedule-application-new-2','pt-dbms-sql-23-strict-schedule-application','Why can a blind-write history be cascadeless but not strict?','["It has no dirty read but can contain a dirty write", "Every write automatically reads", "Cascadeless means serial", "Strictness only concerns names"]'::jsonb,0,'The two properties restrict different accesses.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-strict-schedule-application-new-3','pt-dbms-sql-23-strict-schedule-application','Which implication is valid?','["Recoverable implies strict", "Strict implies cascadeless", "Cascadeless implies strict", "A cyclic graph implies strict"]'::jsonb,1,'The strict restriction includes the dirty-read prohibition.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-strict-schedule-application-new-4','pt-dbms-sql-23-strict-schedule-application','Does strictness alone guarantee an acyclic conflict graph?','["Yes, always", "Only for two transactions", "No", "Only with integers"]'::jsonb,2,'Read-before-write cycles can exist without dirty accesses.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-strict-schedule-application-new-5','pt-dbms-sql-23-strict-schedule-application','A reader sees an older committed version during another writer’s update. Is this necessarily a dirty read?','["Yes, every overlapping read is dirty", "Only when the version has an ID", "Only afterROLLBACK", "No"]'::jsonb,3,'Version semantics determine which value was observed.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-strict-schedule-application-new-6','pt-dbms-sql-23-strict-schedule-application','What additional concern remains with strict locking?','["Deadlock and contention handling", "No transaction can abort", "Locks become permissions", "Durability becomes unnecessary"]'::jsonb,0,'Holding write locks can cause waits and cycles.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-strict-schedule-application-new-7','pt-dbms-sql-23-strict-schedule-application','Does MySQL strict SQL mode prove strict schedules?','["Yes", "No", "Only if an index exists", "Only on weekends"]'::jsonb,1,'Data-conversion mode and concurrency history are separate.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-strict-schedule-application-new-8','pt-dbms-sql-23-strict-schedule-application','What makes the naive before-image recovery example hazardous?','["Every log is absent by definition", "Reads always change data", "Undo of an earlier writer can erase an intervening write", "Keys cannot be numeric"]'::jsonb,2,'It illustrates why unresolved overwrites complicate simple undo.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
