insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-subquery-in-select-application','MCQ Test 2',category,10,10,'Application and scenarios for Subquery in SELECT.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-17-subquery-in-select' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-subquery-in-select-1','pt-dbms-sql-17-subquery-in-select','A subquery placed in the SELECT list must be:','["Multi-row", "Scalar (one row, one column)", "Always uncorrelated", "Always an aggregate with GROUP BY"]'::jsonb,1,'SELECT-list subqueries fill in a single computed value per outer row, so they must be scalar.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-subquery-in-select-2','pt-dbms-sql-17-subquery-in-select','For employees e with correlated subquery SELECT COUNT(*) FROM employees e2 WHERE e2.department=e.department, why use distinct aliases?','["SQL requires all subqueries to use the alias e2", "To distinguish it from the outer alias `e` so the correlation `e2.department = e.department` isn''t ambiguous", "`e2` executes faster than `e`", "It''s purely cosmetic and has no effect on correctness"]'::jsonb,1,'A reused alias in the inner scope can shadow the outer alias, losing the intended correlation or producing a self-comparison. Distinct aliases make the outer and inner references explicit.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-subquery-in-select-3','pt-dbms-sql-17-subquery-in-select','If Marketing contains exactly Grace and Heidi, and the correlated department count uses that complete population, what headcount appears for each?','["3", "2", "8", "1"]'::jsonb,1,'Marketing has exactly two employees: Grace and Heidi.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-subquery-in-select-4','pt-dbms-sql-17-subquery-in-select','Why can a correlated scalar subquery in SELECT be a performance concern on large tables?','["It can''t use indexes ever", "It conceptually runs once per outer row, scaling with table size", "SELECT subqueries are always disallowed in production", "It always returns NULL on large tables"]'::jsonb,1,'Naive execution re-runs the inner aggregate once per output row, which scales poorly as the table grows.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-subquery-in-select-5','pt-dbms-sql-17-subquery-in-select','Which alternative can compute same-population per-partition counts when its filtering and NULL semantics preserve the intended result?','["A window function like COUNT(*) OVER (PARTITION BY ...)", "Removing the SELECT list entirely", "Using ANY instead", "Wrapping it in NOT EXISTS"]'::jsonb,0,'A window COUNT over a matching partition can express the result. A correlated equality lookup excludes NULL-equality matches while a window NULL partition groups them, so prove equivalence and measure the actual plan rather than promise a single pass.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-subquery-in-select-6','pt-dbms-sql-17-subquery-in-select','What happens if a SELECT-list subquery returns more than one row for some outer row?','["It silently picks the first row", "A runtime error", "It returns NULL", "It returns a comma-separated list"]'::jsonb,1,'Just like any scalar subquery, exceeding one row triggers a runtime error.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-subquery-in-select-7','pt-dbms-sql-17-subquery-in-select','Can multiple independent subqueries appear in the same SELECT list?','["No, only one per query", "Yes, each can be independently correlated or uncorrelated", "Only if they''re identical", "Only in the WHERE clause, not SELECT"]'::jsonb,1,'SQL allows any number of scalar subqueries as separate computed columns.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-subquery-in-select-8','pt-dbms-sql-17-subquery-in-select','If a correlated SELECT subquery finds zero matching rows for one particular outer row, what happens to that row''s result?','["The whole query fails", "That row''s computed column is NULL, other rows are unaffected", "That entire row is dropped from the output", "It defaults to 0 always"]'::jsonb,1,'A zero-row scalar subquery result is NULL for that specific row, not a query-wide failure.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
