insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-subquery-in-where-1','pt-dbms-sql-17-subquery-in-where','What should determine a WHERE subquery form?','["The shortest alias", "Its required result shape", "The table caption", "The number of comments"]'::jsonb,1,'Scalar comparison, set membership and existence require different inner outputs.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-subquery-in-where-2','pt-dbms-sql-17-subquery-in-where','What does a scalar subquery with zero rows supply?','["Zero automatically", "NULL", "An empty string always", "An arbitrary previous value"]'::jsonb,1,'An absent scalar result is treated as null in the comparison context.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
