insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-17-subquery-in-where-8','pt-dbms-sql-17-subquery-in-where','Does ordinary equality match two NULL categories?','["Yes always", "Only with AVG", "No", "Only with a unique index"]'::jsonb,2,'Unknown category values do not establish a true equality relationship.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
