- All-null average','[{"input": "INSERT INTO books VALUES (1,1,10),(2,1,30),(3,2,100),(4,2,NULL),(5,NULL,200);", "output": "book_id\tprice\n3\t100\n5\t200", "explanation": "The known global average is85, and unknown candidate prices do not pass."}]'::jsonb,'[{"seed_sql": "INSERT INTO books VALUES (1,1,NULL);", "expected": "", "hidden": true}, {"seed_sql": "", "expected": "", "hidden": true}]'::jsonb,'["Use supplied synthetic data.", "Return only requested columns."]'::jsonb,'["The known global average is85, and unknown candidate prices do not pass."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The known global average is85, and unknown candidate prices do not pass.','{"sql": "SELECT b.book_id,b.price FROM books AS b WHERE b.price>(SELECT AVG(x.price) FROM books AS x) ORDER BY b.book_id;"}'::jsonb,'The known global average is85, and unknown candidate prices do not pass.',array['sql'],'CREATE TABLE books(book_id INT PRIMARY KEY,category_id INT NULL,price INT NULL);','INSERT INTO books VALUES (1,1,10),(2,1,30),(3,2,100),(4,2,NULL),(5,NULL,200);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-17-subquery-in-where' on conflict(id) do nothing;
