insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-14-time-functions-8','pt-dbms-sql-14-time-functions','What does a missing ending timestamp imply for a duration calculation?','["Its completed duration is certainly zero", "Its completed duration is unknown", "The start is midnight", "The row must be deleted"]'::jsonb,1,'Without an end, the difference is unknown; it cannot establish a completed measurement of zero.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
