insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-14-time-functions-application-new-1','pt-dbms-sql-14-time-functions-application','Which interval convention avoids guessing the last instant of a day?','["Exclude both midnights", "Include the next noon", "Inclusive start and exclusive next-day start", "Compare only minute fields"]'::jsonb,2,'The next midnight is a precise exclusive endpoint regardless of stored fractional precision.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
