insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cp-dbms-sql-top-3-most-expensive-products',null::text,'Top 3 Most Expensive Products','Easy','top-3-most-expensive-products','Return id,name,price for the three most expensive products, highest price first. Break ties by id ascending. Return fewer rows if fewer products exist.

**MySQL dialect.**

```sql
CREATE TABLE products (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  price INTEGER NOT NULL
);
INSERT INTO products (id, name, category, price) VALUES
(1, ''ProLaptop'', ''Electronics'', 85000),
(2, ''Desk Lamp'', ''Home'', 900),
(3, ''ProPhone'', ''Electronics'', 45000),
(4, ''Python Basics'', ''Books'', 350),
(5, ''Novel'', ''Books'', 220),
(6, ''Headphones'', ''Electronics'', 3000),
(7, ''Rug'', ''Home'', 4500);
```

**Required ordering:** price descending, id ascending

**Edge cases:**
- Complete ties with identity.
- A short population returns fewer rows.','[{"input": "INSERT INTO products (id, name, category, price) VALUES\n(1, ''ProLaptop'', ''Electronics'', 85000),\n(2, ''Desk Lamp'', ''Home'', 900),\n(3, ''ProPhone'', ''Electronics'', 45000),\n(4, ''Python Basics'', ''Books'', 350),\n(5, ''Novel'', ''Books'', 220),\n(6, ''Headphones'', ''Electronics'', 3000),\n(7, ''Rug'', ''Home'', 4500);", "output": "id\tname\tprice\n1\tProLaptop\t85000\n3\tProPhone\t45000\n7\tRug\t4500", "explanation": "The sample''s leading prices belong to identities 1,3,7. A fixed row cap does not include extra peers beyond the third row.", "check_sql": ""}]'::jsonb,'[{"seed_sql": "INSERT INTO products (id, name, category, price) VALUES\n(1, ''Tablet'', ''Electronics'', 20000),\n(2, ''Sofa'', ''Home'', 30000),\n(3, ''Speaker'', ''Electronics'', 5000),\n(4, ''Cookbook'', ''Books'', 400),\n(5, ''Chair'', ''Home'', 2500),\n(6, ''Mouse'', ''Electronics'', 900);", "expected": "id\tname\tprice\n2\tSofa\t30000\n1\tTablet\t20000\n3\tSpeaker\t5000", "hidden": true}, {"seed_sql": "INSERT INTO products VALUES (9,''Nine'',''Lab'',5),(2,''Two'',''Lab'',5),(7,''Seven'',''Lab'',5),(1,''One'',''Lab'',5);", "expected": "id\tname\tprice\n1\tOne\t5\n2\tTwo\t5\n7\tSeven\t5", "hidden": true}, {"seed_sql": "INSERT INTO products VALUES (6,''Only'',''Lab'',2);", "expected": "id\tname\tprice\n6\tOnly\t2", "hidden": true}]'::jsonb,'["Return at most three rows.", "Preserve source data."]'::jsonb,'["Sort highest price first.", "Apply the row cap after defining a complete order."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The sample''s leading prices belong to identities 1,3,7. A fixed row cap does not include extra peers beyond the third row.','{"sql": "SELECT id,name,price FROM products ORDER BY price DESC,id ASC LIMIT 3;"}'::jsonb,'The sample''s leading prices belong to identities 1,3,7. A fixed row cap does not include extra peers beyond the third row.',array['sql'],'CREATE TABLE products (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  price INTEGER NOT NULL
);','INSERT INTO products (id, name, category, price) VALUES
(1, ''ProLaptop'', ''Electronics'', 85000),
(2, ''Desk Lamp'', ''Home'', 900),
(3, ''ProPhone'', ''Electronics'', 45000),
(4, ''Python Basics'', ''Books'', 350),
(5, ''Novel'', ''Books'', 220),
(6, ''Headphones'', ''Electronics'', 3000),
(7, ''Rug'', ''Home'', 4500);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-13-top-n-queries' on conflict(id) do update set description=excluded.description,examples=excluded.examples,test_cases=excluded.test_cases,constraints=excluded.constraints,hints=excluded.hints,editorial=excluded.editorial,solution_code=excluded.solution_code,solution_approach=excluded.solution_approach,updated_at=now() where (dsa_problems.description,dsa_problems.examples,dsa_problems.test_cases,dsa_problems.constraints,dsa_problems.hints,dsa_problems.editorial,dsa_problems.solution_code,dsa_problems.solution_approach) is distinct from (excluded.description,excluded.examples,excluded.test_cases,excluded.constraints,excluded.hints,excluded.editorial,excluded.solution_code,excluded.solution_approach);
