insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-boundaries-3','pt-dbms-sql-22-transaction-boundaries','With MySQL autocommit enabled, no explicit transaction active, and successful standalone InnoDB DML statements, what boundary normally applies?','["No transaction boundary exists at all", "Each successful standalone statement completes its own transaction", "All statements share one boundary for the entire session", "Autocommit disables all transactions"]'::jsonb,1,'This statement is scoped to transactional DML outside an explicit transaction, not every possible SQL command.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
