insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-concept-1','pt-dbms-sql-22-transaction-concept','What is a transaction?','["A single SQL keyword", "A sequence of operations treated as a single, indivisible logical unit of work", "A synonym for a database table", "A type of index"]'::jsonb,1,'A transaction bundles operations so they succeed or fail together.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-concept-2','pt-dbms-sql-22-transaction-concept','Why should both required supported debit and credit writes belong to the same correctly handled transaction?','["To make the two statements run faster", "So money can never leave one account without arriving at the other, even if something fails partway through", "Because SQL requires exactly two statements per transaction", "To avoid needing a WHERE clause"]'::jsonb,1,'Grouping supports one database commit outcome; the workflow must still verify both required effects, authorization and sufficient source state.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-concept-3','pt-dbms-sql-22-transaction-concept','With MySQL autocommit enabled and no explicit transaction active, is a successful standalone InnoDB INSERT ordinarily a transaction?','["No, only multi-statement blocks are transactions", "Yes, the successful standalone statement completes its own transaction", "Only if it inserts two rows", "Only after a manual ROLLBACK"]'::jsonb,1,'Scope the statement to a successful standalone transactional DML operation outside an explicit transaction.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-concept-4','pt-dbms-sql-22-transaction-concept','Does the database automatically figure out which operations should be grouped into one transaction?','["Yes, it infers this from the schema", "No — this is a business/application design decision; the database only enforces guarantees for whatever you explicitly group", "Only for foreign-key-related operations", "The database groups every statement in a session automatically"]'::jsonb,1,'Transaction boundaries must be deliberately chosen by whoever writes the application logic.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-concept-5','pt-dbms-sql-22-transaction-concept','Will transaction support automatically infer and group a related update the developer omitted from the intended boundary?','["Yes, it always detects missing related operations", "No — this is a design error the database has no way to catch, since it only knows about statements you actually group together", "Only if foreign keys are involved", "The database automatically adds the missing statement"]'::jsonb,1,'The engine enforces declared statements and constraints; a separate constraint might catch a violation, but transaction support does not infer the missing intended grouping.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-concept-6','pt-dbms-sql-22-transaction-concept','Do a transaction''s correctness guarantees depend on how many statements it contains?','["Yes, guarantees only apply to exactly two-statement transactions", "No — the guarantees apply regardless of statement count, though very long transactions have separate practical costs", "Guarantees only apply to single-statement transactions", "Transactions with more than 5 statements are not supported"]'::jsonb,1,'Atomicity/consistency guarantees are independent of transaction size, though performance considerations (22.13) are a separate concern.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-concept-7','pt-dbms-sql-22-transaction-concept','Which information is essential when defining a business transaction?','["Only the source file name", "Its participating operations, invariants and actual commit/rollback boundary", "Only the number of SQL comments", "Only the client screen color"]'::jsonb,1,'The operation must identify what succeeds together and how required effects are enforced, rather than rely on course-history trivia.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
