insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-concept-application-7','cx-transaction-concept-application','What should precede retry after a lost commit response?','["Blind repetition of all effects", "A new random identity every time", "An unsupported success claim", "Authorized reconciliation of the request outcome"]'::jsonb,3,'The server may already have committed the operation.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-concept-application-8','cx-transaction-concept-application','Why is reducing duration by committing the debit first unacceptable here?','["It breaks the required grouped movement boundary", "It changes the table name", "It prevents every SELECT", "It proves stronger isolation"]'::jsonb,0,'Performance work must preserve the business invariant.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-concept-application-9','cx-transaction-concept-application','Does a one-session arithmetic result prove concurrent safety?','["Yes, all engines are identical", "No", "Only if sorted", "Only with two rows"]'::jsonb,1,'Controlled sessions and actual interleavings are separate evidence.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-concept-application-10','cx-transaction-concept-application','What must a pooled connection not carry into another request?','["A documented stable identifier", "A confirmed completed outcome", "Unresolved transactional work", "An approved query template"]'::jsonb,2,'Pending state can leak locks and effects across unrelated borrowers.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
