update public.learning_topics set short_description='Follow active, partially committed, committed, failed and aborted transaction states, including statement-error scope, retry cleanup and uncertain commit outcomes.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Follow active, partially committed, committed, failed and aborted transaction states, including statement-error scope, retry cleanup and uncertain commit outcomes.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Transaction States.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-22-transaction-states' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-transaction-states-application','MCQ Test 2',category,10,10,'Application and scenarios for Transaction States.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-22-transaction-states' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-states-1','pt-dbms-sql-22-transaction-states','What is the initial state of a transaction when it begins executing?','["Committed", "Active", "Aborted", "Failed"]'::jsonb,1,'Active is the starting state while operations are executing.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-states-2','pt-dbms-sql-22-transaction-states','What state does a transaction reach after successfully executing its final operation, just before durability is fully confirmed?','["Aborted", "Partially Committed", "Failed", "Active"]'::jsonb,1,'Partially Committed is the brief transitional state before full commit confirmation.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-states-3','pt-dbms-sql-22-transaction-states','Can a Committed transaction be undone with a later ROLLBACK?','["Yes, ROLLBACK can undo any past transaction", "No — Committed is a terminal state; undoing a mistake requires a new, separate transaction", "Only within the same database session", "Only if no other transactions have run since"]'::jsonb,1,'Once committed, changes are permanent — no rollback can reach back into an already-committed transaction.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-states-4','pt-dbms-sql-22-transaction-states','What is the failure path through the transaction state machine?','["Active -> Committed -> Aborted", "Active -> Failed -> Aborted", "Failed -> Active -> Committed", "Aborted -> Failed -> Active"]'::jsonb,1,'A problem moves the transaction from Active to Failed, and it''s then rolled back into the Aborted state.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-states-5','pt-dbms-sql-22-transaction-states','Can a transaction move to the Failed state for reasons outside the application''s own logic?','["No, only application bugs cause failure", "Yes — a server crash or a deadlock the database detects and resolves can abort a transaction with no application-level cause", "Failure can only be triggered by an explicit ROLLBACK statement", "Failed transactions are always the application''s fault"]'::jsonb,1,'External factors like crashes and deadlock resolution are real, expected causes of transaction failure.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-states-6','pt-dbms-sql-22-transaction-states','After a transaction reaches the Aborted state, can it be ''resumed'' from where it left off?','["Yes, it resumes automatically", "No — it must be retried as an entirely new transaction, not resumed", "It resumes from the Partially Committed state", "Aborted transactions cannot ever be retried"]'::jsonb,1,'Aborted is terminal; recovery means starting over with a new transaction, not resuming the old one.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-states-7','pt-dbms-sql-22-transaction-states','Why is the ''Partially Committed'' state often omitted from simplified discussions of transactions?','["It doesn''t actually exist", "It''s typically a very brief, often invisible transitional state, so Active/Committed/Aborted covers most everyday purposes", "It only applies to SELECT statements", "It is identical to the Active state"]'::jsonb,1,'The full five-state model is more precise, but the brief transitional state is often elided in everyday explanations.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-22-transaction-states-8','pt-dbms-sql-22-transaction-states','Is ''Aborted'' the same state as ''Failed''?','["Yes, they are synonyms", "No — Failed means something went wrong and execution cannot continue; Aborted is the terminal state reached after the rollback that follows a failure", "Aborted happens before Failed in the sequence", "Failed is a terminal state, and Aborted precedes it"]'::jsonb,1,'Failed is the trigger state; Aborted is the resulting terminal state after rollback completes.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-states-fundamentals-9','pt-dbms-sql-22-transaction-states','Does partially committed mean half the rows are independently committed?','["No", "Yes, exactly half", "Only for two statements", "Only for integer tables"]'::jsonb,0,'It is a provisional lifecycle milestone before successful commit completion.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-states-fundamentals-10','pt-dbms-sql-22-transaction-states','What does the last UPDATE returning establish?','["The whole business operation is durable", "That statement completed, not that COMMIT succeeded", "Every external message was delivered", "All other snapshots refreshed"]'::jsonb,1,'Logical work and commit completion are separate milestones.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-states-application-1','cx-transaction-states-application','Does every SQL exception prove the entire transaction was undone?','["Yes, universally", "No", "Only with a SELECT", "Only if the client has one tab"]'::jsonb,1,'Engine failures can have statement or transaction scope.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-states-application-2','cx-transaction-states-application','What should a retry after abort reconstruct?','["Only the last write", "Only its old snapshot pointer", "The complete transaction’s reads and decisions", "An earlier lock that no longer exists"]'::jsonb,2,'A retry is a new attempt in a potentially changed state.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-states-application-3','cx-transaction-states-application','Can a committed transaction be reversed by ordinary later ROLLBACK?','["Yes, indefinitely", "Only on the same connection", "Only before a SELECT", "No"]'::jsonb,3,'Correction requires a new authorized action rather than rollback of a completed commit.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-states-application-4','cx-transaction-states-application','What does a lost commit response prove?','["The client lacks confirmation", "The server definitely aborted", "The server definitely committed", "Half the rows committed"]'::jsonb,0,'Different server outcomes can produce the same client connection failure.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-states-application-5','cx-transaction-states-application','Is unknown outcome necessarily a distinct unresolved database state?','["Yes, it proves partial persistence", "No, it describes the client’s knowledge", "Only when there are two accounts", "Only after a successful SELECT"]'::jsonb,1,'The server may have a definite outcome the client has not learned.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-states-application-6','cx-transaction-states-application','A required destination row is missing. What must the workflow check?','["Only whether UPDATE text had a semicolon", "Whether a caption exists", "Whether to roll back the unsuccessful business attempt", "Whether a table name sounds valid"]'::jsonb,2,'Statement execution does not establish required row effects.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-states-application-7','cx-transaction-states-application','What should happen to an unusable connection with unresolved work?','["Return it as a clean pooled connection", "Reuse its old snapshot blindly", "Grant it more privileges", "Discard it under the driver cleanup policy"]'::jsonb,3,'A later borrower must not inherit unresolved transactional state.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-states-application-8','cx-transaction-states-application','Can a read-only transaction still need explicit cleanup?','["Yes", "No, no writes means no resources", "Only for varchar columns", "Only after a schema change"]'::jsonb,0,'Snapshots and locks can remain associated with read-only work.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-states-application-9','cx-transaction-states-application','Does committed imply every existing snapshot immediately changes?','["Yes, by definition", "No", "Only if the client is authenticated", "Only for primary keys"]'::jsonb,1,'Visibility depends on each reader’s observation model.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-transaction-states-application-10','cx-transaction-states-application','What is a safe response to an uncertain commit before retrying?','["Repeat the business effect without checking", "Assert rollback from the network error alone", "Reconcile through an authorized stable request identity", "Publish a fabricated success"]'::jsonb,2,'Reconciliation prevents treating uncertainty as either confirmed failure or confirmed success.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
