if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-transitive-dependency-1' and (question_text,options,correct_index,explanation) is distinct from ('Which chain of functional dependencies demonstrates the transitive dependency in the running example?','["StudentID -> StudentName -> EnrollmentDate", "CourseID -> InstructorID -> InstructorOffice", "StudentID -> CourseID -> CourseName", "InstructorOffice -> InstructorID -> CourseID"]'::jsonb,1,'CourseID determines InstructorID, and InstructorID determines InstructorOffice, so InstructorOffice is only indirectly (transitively) dependent on CourseID.') and (question_text,options,correct_index,explanation) is distinct from ('For Course(CourseID, InstructorID, InstructorOffice), assume CourseID determines InstructorID and InstructorID determines InstructorOffice. Which chain shows the resulting indirect dependency?','["StudentID -> StudentName -> EnrollmentDate", "CourseID -> InstructorID -> InstructorOffice", "StudentID -> CourseID -> CourseName", "InstructorOffice -> InstructorID -> CourseID"]'::jsonb,1,'CourseID determines InstructorID, and InstructorID determines InstructorOffice, so InstructorOffice is only indirectly (transitively) dependent on CourseID.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-transitive-dependency-1'; end if;
