if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-transitive-dependency-2' and (question_text,options,correct_index,explanation) is distinct from ('Why is InstructorOffice''s dependency on CourseID called ''transitive'' rather than ''direct''?','["Because InstructorOffice is a text field", "Because there is no independent business rule linking a course directly to an office \u2014 the link only exists because the course determines its instructor, and the instructor determines the office", "Because CourseID is a foreign key", "Because InstructorOffice values are numeric"]'::jsonb,1,'The dependency CourseID -> InstructorOffice is only true because it passes through the intermediate attribute InstructorID; there''s no direct rule connecting courses to offices.') and (question_text,options,correct_index,explanation) is distinct from ('Why is InstructorOffice''s dependency on CourseID called ''transitive'' rather than ''direct''?','["Because InstructorOffice is a text field", "Because there is no independent business rule linking a course directly to an office \u2014 the link only exists because the course determines its instructor, and the instructor determines the office", "Because CourseID is a foreign key", "Because InstructorOffice values are numeric"]'::jsonb,1,'The dependency CourseID -> InstructorOffice is only true because it passes through the intermediate attribute InstructorID; there''s no direct rule connecting courses to offices.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-transitive-dependency-2'; end if;
