if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-transitive-dependency-4' and (question_text,options,correct_index,explanation) is distinct from ('Suppose a table is already in 2NF (no partial dependency) but still has the chain CourseID -> InstructorID -> InstructorOffice. Which anomaly can STILL occur?','["None \u2014 2NF eliminates all anomalies", "An update anomaly: changing an instructor''s office still requires updating every course row taught by that instructor", "An insertion anomaly for enrolling new students", "A deletion anomaly when dropping a single enrollment"]'::jsonb,1,'2NF only fixes partial dependency on the key; it does not address chains among non-key attributes, so the update anomaly for InstructorOffice can persist until 3NF removes the transitive dependency.') and (question_text,options,correct_index,explanation) is distinct from ('Suppose a table is already in 2NF (no partial dependency) but still has the chain CourseID -> InstructorID -> InstructorOffice. Which anomaly can STILL occur?','["None \u2014 2NF eliminates all anomalies", "An update anomaly: changing an instructor''s office still requires updating every course row taught by that instructor", "An insertion anomaly for enrolling new students", "A deletion anomaly when dropping a single enrollment"]'::jsonb,1,'2NF only fixes partial dependency on the key; it does not address chains among non-key attributes, so the update anomaly for InstructorOffice can persist until 3NF removes the transitive dependency.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-transitive-dependency-4'; end if;
