if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-transitive-dependency-5' and (question_text,options,correct_index,explanation) is distinct from ('Which decomposition removes the transitive dependency CourseID -> InstructorID -> InstructorOffice?','["Merging Course and Instructor into one wider table", "Splitting out Instructor(InstructorID, InstructorName, InstructorOffice) from Course, leaving Course(CourseID, CourseName, InstructorID) with just the foreign key", "Adding a unique index on InstructorOffice", "Removing InstructorID from the Course table entirely"]'::jsonb,1,'Once InstructorOffice lives in its own Instructor relation keyed directly by InstructorID, it is no longer transitively reached through CourseID.') and (question_text,options,correct_index,explanation) is distinct from ('Which decomposition removes the transitive dependency CourseID -> InstructorID -> InstructorOffice?','["Merging Course and Instructor into one wider table", "Splitting out Instructor(InstructorID, InstructorName, InstructorOffice) from Course, leaving Course(CourseID, CourseName, InstructorID) with just the foreign key", "Adding a unique index on InstructorOffice", "Removing InstructorID from the Course table entirely"]'::jsonb,1,'Once InstructorOffice lives in its own Instructor relation keyed directly by InstructorID, it is no longer transitively reached through CourseID.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-transitive-dependency-5'; end if;
