insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-transitive-dependency-1','pt-dbms-sql-21-transitive-dependency','For Course(CourseID, InstructorID, InstructorOffice), assume CourseID determines InstructorID and InstructorID determines InstructorOffice. Which chain shows the resulting indirect dependency?','["StudentID -> StudentName -> EnrollmentDate", "CourseID -> InstructorID -> InstructorOffice", "StudentID -> CourseID -> CourseName", "InstructorOffice -> InstructorID -> CourseID"]'::jsonb,1,'CourseID determines InstructorID, and InstructorID determines InstructorOffice, so InstructorOffice is only indirectly (transitively) dependent on CourseID.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
