insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-transitive-dependency-3','pt-dbms-sql-21-transitive-dependency','In the introductory 3NF-violating chain X→Y→Z with nonprime Z, what must be true of the intermediate determinant Y?','["It must be a foreign key", "It is not a superkey of the examined relation", "It must be nullable", "It must share Z’s type"]'::jsonb,1,'A non-superkey determinant of nonprime Z violates the formal3NF condition. Being merely not a candidate key is insufficient, because a proper superkey is also not minimal.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-transitive-dependency-4','pt-dbms-sql-21-transitive-dependency','Suppose a table is already in 2NF (no partial dependency) but still has the chain CourseID -> InstructorID -> InstructorOffice. Which anomaly can STILL occur?','["None — 2NF eliminates all anomalies", "An update anomaly: changing an instructor''s office still requires updating every course row taught by that instructor", "An insertion anomaly for enrolling new students", "A deletion anomaly when dropping a single enrollment"]'::jsonb,1,'2NF only fixes partial dependency on the key; it does not address chains among non-key attributes, so the update anomaly for InstructorOffice can persist until 3NF removes the transitive dependency.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-transitive-dependency-5','pt-dbms-sql-21-transitive-dependency','Which decomposition removes the transitive dependency CourseID -> InstructorID -> InstructorOffice?','["Merging Course and Instructor into one wider table", "Splitting out Instructor(InstructorID, InstructorName, InstructorOffice) from Course, leaving Course(CourseID, CourseName, InstructorID) with just the foreign key", "Adding a unique index on InstructorOffice", "Removing InstructorID from the Course table entirely"]'::jsonb,1,'Once InstructorOffice lives in its own Instructor relation keyed directly by InstructorID, it is no longer transitively reached through CourseID.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-21-transitive-dependency-6','pt-dbms-sql-21-transitive-dependency','Which describes the introductory problematic chain from a key through a non-superkey determinant to a nonprime attribute?','["Any dependency involving three or more attributes", "A non-key attribute Z depends on the key only indirectly, through another non-key attribute Y, rather than directly", "A dependency that changes over time", "Two attributes that are both foreign keys"]'::jsonb,1,'This is the nonprime teaching case of indirect dependency. General3NF classification uses the formal superkey-or-prime condition rather than banning every implied transitive chain.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
