update public.learning_topics set short_description='Combine compatible row sets, retain the intended identity and NULL semantics, and distinguish full-row deduplication from source provenance and final ordering.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Combine compatible row sets, retain the intended identity and NULL semantics, and distinguish full-row deduplication from source provenance and final ordering.';
