insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-union-sql-1','pt-dbms-sql-18-union-sql','What does UNION do?','["Returns rows common to two queries", "Combines the rows of two queries, keeping the distinct set from either", "Returns rows in the first query but not the second", "Joins two tables on a shared column"]'::jsonb,1,'UNION merges two result sets, removing duplicates.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-union-sql-2','pt-dbms-sql-18-union-sql','In the running example, does UNION include student 2 (enrolled in both years) once or twice?','["Twice", "Once — UNION removes duplicate rows automatically", "Zero times", "This depends on ORDER BY"]'::jsonb,1,'Automatic de-duplication means a student present in both source queries appears only once.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-union-sql-3','pt-dbms-sql-18-union-sql','Which ORDER BY establishes the final combined UNION result order?','["Any branch order automatically becomes the final order", "The ORDER BY on the combined result; parenthesized local branch selection can have separate engine-specific ordering", "Only a physical primary key", "No UNION query can be ordered"]'::jsonb,1,'A branch can use local ordering for selection under supported syntax, but only the final ordering establishes the combined output sequence.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-union-sql-4','pt-dbms-sql-18-union-sql','What must be true of the two queries combined by UNION?','["They must query the same table", "They must return the same number of columns with compatible types", "They must both include an ORDER BY", "They must both return at least 10 rows"]'::jsonb,1,'Union-compatibility (matching column count/types) is a hard requirement, checked before deduplication.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-union-sql-5','pt-dbms-sql-18-union-sql','What is the performance implication of UNION''s automatic de-duplication?','["It has no performance cost", "It has a real computational cost — comparing rows to remove duplicates — that UNION ALL avoids", "De-duplication is always instantaneous regardless of data size", "It only costs time on the second query, never the first"]'::jsonb,1,'De-duplication requires real comparison work, motivating UNION ALL when duplicates aren''t a concern.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-union-sql-6','pt-dbms-sql-18-union-sql','If enrolled_2025 has 4 students and enrolled_2026 has 3, with 2 students in both, how many rows does UNION return?','["7", "5", "2", "3"]'::jsonb,1,'For distinct source identity sets of sizes4 and3 with2 identities shared, the union has4+3-2=5 distinct students. Raw row counts with internal duplicates need separate treatment.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-union-sql-7','pt-dbms-sql-18-union-sql','Is UNION a relational-algebra concept, a SQL-specific feature, or both?','["A SQL-only feature with no theoretical basis", "Both — Union is a foundational relational algebra operation (7.4), and SQL''s UNION keyword implements it directly", "A relational-algebra-only concept with no SQL equivalent", "Exclusive to NoSQL query languages"]'::jsonb,1,'This chapter revisits the SQL syntax for a concept already introduced theoretically in Chapter 7.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-18-union-sql-8','pt-dbms-sql-18-union-sql','Can more than two queries be combined with UNION in a single statement?','["No, exactly two queries maximum", "Yes — any number of SELECT queries can be chained with UNION between each pair", "Only three queries maximum", "Only if they all query the same table"]'::jsonb,1,'Several compatible query blocks can be chained, subject to the engine’s practical limits and the expression’s grouping/duplicate rules; not a literally unlimited resource guarantee.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-union-sql-fundamentals-9','pt-dbms-sql-18-union-sql','What columns determine duplicate elimination in UNION?','["The complete projected row", "Only the first source primary key automatically", "Only the last alias", "Only numeric columns"]'::jsonb,0,'Distinctness uses the output row rather than an unseen business identifier.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
