update public.learning_topics set short_description='Understand unique indexes as write-time key invariants, including composite scope, MySQL NULL behavior, collation, concurrency and honest duplicate-preflight limits.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Understand unique indexes as write-time key invariants, including composite scope, MySQL NULL behavior, collation, concurrency and honest duplicate-preflight limits.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Unique Index.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-20-unique-index' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-test-unique-index-2','MCQ Test 2',category,10,10,'Application and scenarios for Unique Index.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-20-unique-index' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-unique-index-1','pt-dbms-sql-20-unique-index','For ordinary complete nonnull indexed keys, what roles does a unique index serve?','["It only removes display duplicates", "It enforces key uniqueness and provides an index access structure", "It only sorts the final result", "It makes every query use the index"]'::jsonb,1,'Nullability and comparison rules remain relevant; the optimizer need not choose the index for every lookup.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-unique-index-2','pt-dbms-sql-20-unique-index','In an InnoDB table, what is a normal consequence of declaring a primary key?','["No index is associated with the key", "Its unique nonnull key is used for the clustered index", "Every secondary key becomes unique", "The primary key permits repeated NULLs"]'::jsonb,1,'The lesson scopes this physical behavior to MySQL InnoDB rather than every SQL engine.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-unique-index-3','pt-dbms-sql-20-unique-index','Why is enforcing uniqueness via a database-level unique index better than only checking it in application code?','["Application-level checks are always faster", "A unique index atomically prevents race conditions where two simultaneous inserts could otherwise both succeed with duplicate values", "Unique indexes remove the need for a primary key", "Application code cannot check for duplicates at all"]'::jsonb,1,'Database-enforced uniqueness closes the race-condition window that application-only checks are vulnerable to under concurrent writes.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-unique-index-4','pt-dbms-sql-20-unique-index','For nonnull components, what does UNIQUE(department,id) enforce?','["Every department value is individually unique", "No repeated department-id pair, while id can be reused in another department", "Every id is globally unique", "Only the first component is checked"]'::jsonb,1,'The complete pair defines the invariant; nullable-key cases require separate reasoning.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-unique-index-5','pt-dbms-sql-20-unique-index','How does MySQL 8.4 treat multiple NULL values in an ordinary nullable unique index?','["They are always rejected", "They are permitted", "Exactly one is permitted in every index", "They become zero automatically"]'::jsonb,1,'This is a MySQL-specific nullability rule, not a universal claim across all engines.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-unique-index-6','pt-dbms-sql-20-unique-index','Which ordinary index type is relevant to the shown InnoDB unique-key example?','["BTREE", "FULLTEXT only", "SPATIAL only", "A client-side hash map"]'::jsonb,0,'The lesson concerns ordinary InnoDB ordered indexes; uniqueness alone does not specify every engine index implementation.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-unique-index-7','pt-dbms-sql-20-unique-index','What happens when creating a unique index over repeated complete nonnull keys that compare equal?','["The engine deletes duplicate records automatically", "Creation fails because the existing data violates the rule", "The engine keeps the newest row automatically", "The index silently becomes nonunique"]'::jsonb,1,'Preflight and reconciliation are needed; repeated nullable keys have different rules.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-unique-index-8','pt-dbms-sql-20-unique-index','What write cost can an ordinary unique index introduce?','["No cost because uniqueness is only a display rule", "Index maintenance and uniqueness checks on relevant writes", "Automatic table deletion", "Guaranteed blocking of all SELECTs"]'::jsonb,1,'The exact cost depends on the workload and engine; the approved invariant can justify it.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-unique-index-9','pt-dbms-sql-20-unique-index','A complete unique key is(event_id,code). Existing key(10,7) and proposed key(20,7) have no other conflicts. What does this rule permit?','["The second key, because its owner scope differs", "No other event may ever use7", "Only one registration in the table", "Both keys only when code is NULL"]'::jsonb,0,'Composite uniqueness compares the complete nonnull tuple. Global code uniqueness would impose a different rule.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-unique-index-10','pt-dbms-sql-20-unique-index','Every registration must have an assigned nonnull code as well as a unique code. What requiredness rule accompanies UNIQUE?','["Replace all missing codes with a blank string", "Declare the code NOT NULL under the approved schema contract", "Use SELECT DISTINCT in a dashboard", "Sort missing codes last"]'::jsonb,1,'MySQL nullable uniqueness allows missing values. Requiredness must be declared separately when absence is forbidden.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-unique-index-11','cx-test-unique-index-2','Two sessions attempt the same complete nonnull unique key. With no deletion or key change, how many conflicting inserts can remain committed?','["Both, if both SELECT checks saw no row", "Neither can ever be accepted", "At most one, with the other conflict handled or rolled back", "Any number if the requests have different users"]'::jsonb,2,'The trusted unique invariant prevents two committed rows with the same complete key. A prior application read cannot override enforcement.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-unique-index-12','cx-test-unique-index-2','Does SELECT DISTINCT enforce stored uniqueness?','["Yes, permanently", "Only for composite keys", "Only when ORDER BY exists", "No"]'::jsonb,3,'It changes one query result.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
