insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-updatable-views-1','pt-dbms-sql-19-updatable-views','Which of the following views is most likely to be directly updatable?','["A view with GROUP BY and COUNT(*)", "A view joining two tables", "A single-table view with a simple WHERE filter and no aggregation", "A view using UNION of two SELECTs"]'::jsonb,2,'Simple, single-table views without aggregation, GROUP BY, DISTINCT, or set operations are the classic case of an updatable view.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-updatable-views-2','pt-dbms-sql-19-updatable-views','Why can''t `UPDATE department_summary SET avg_salary = 75000 WHERE name = ''Sales''; ` be executed, given department_summary uses AVG(salary) GROUP BY department?','["Because UPDATE statements are never allowed on views", "Because the average is derived from many employee rows, so there''s no unambiguous way to determine which underlying rows to change and by how much", "Because department_summary has no WHERE clause", "Because AVG() columns are read-only by SQL syntax rule with no underlying reason"]'::jsonb,1,'The fundamental issue is semantic ambiguity: an aggregate value maps to many underlying rows, so there''s no defined way to push a single new value back down to specific row changes.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-updatable-views-3','pt-dbms-sql-19-updatable-views','What does WITH CHECK OPTION do on an updatable view?','["It makes a non-updatable view updatable", "It prevents INSERT/UPDATE operations from creating a row that would violate the view''s own WHERE clause", "It automatically refreshes materialized data", "It restricts which columns can be selected"]'::jsonb,1,'WITH CHECK OPTION ensures any row inserted or updated through the view still satisfies the view''s defining WHERE clause, rejecting changes that would ''escape'' the view''s visibility.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-updatable-views-4','pt-dbms-sql-19-updatable-views','Which of these is generally NOT a requirement for a view to be updatable?','["No aggregate functions in the SELECT list", "No GROUP BY or DISTINCT", "The requested writable column must map to a permitted underlying base-table column", "The view must include an ORDER BY clause"]'::jsonb,3,'ORDER BY is not an updatability requirement. Aggregation and DISTINCT restrict MySQL view writes, while the requested writable column needs a permitted base-column mapping; some join views support restricted updates.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
