if exists(select 1 from public.test_questions where id='tq-dbms-sql-21-update-anomaly-2' and (question_text,options,correct_index,explanation) is distinct from ('What specifically defines an update anomaly?','["A query returning stale cached results", "A single logical fact being duplicated across multiple rows, such that updating it correctly requires touching every copy, and a partial update leaves the data inconsistent", "A failed INSERT due to a missing key value", "A row being permanently locked during a transaction"]'::jsonb,1,'The defining feature is the multi-row duplication of one fact combined with the risk that not all copies get updated, producing contradictory data.') and (question_text,options,correct_index,explanation) is distinct from ('What specifically defines an update anomaly?','["A query returning stale cached results", "A single logical fact being duplicated across multiple rows, such that updating it correctly requires touching every copy, and a partial update leaves the data inconsistent", "A failed INSERT due to a missing key value", "A row being permanently locked during a transaction"]'::jsonb,1,'The defining feature is the multi-row duplication of one fact combined with the risk that not all copies get updated, producing contradictory data.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-21-update-anomaly-2'; end if;
