update public.learning_topics set short_description='Learn MySQL UPSERT with unique keys, incoming row aliases, replacement versus increments, retry risks, and worked SQL exercises.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Learn MySQL UPSERT with unique keys, incoming row aliases, replacement versus increments, retry risks, and worked SQL exercises.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for UPSERT Patterns.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-11-upsert-patterns' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
