insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-upsert-patterns-1','pt-dbms-sql-11-upsert-patterns','What identifies an upsert operation?','["A read that always locks every row", "An insert attempt with a defined update outcome on a protected identity conflict", "A command that removes all duplicates", "A transaction that can never fail"]'::jsonb,1,'Both the matching identity and update rule must be specified.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-upsert-patterns-2','pt-dbms-sql-11-upsert-patterns','Which MySQL clause defines the duplicate branch?','["ON CONFLICT DO UPDATE", "ON DUPLICATE KEY UPDATE", "UPSERT TABLE", "MERGE CONFLICT"]'::jsonb,1,'This package follows MySQL syntax.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-upsert-patterns-3','pt-dbms-sql-11-upsert-patterns','Which PostgreSQL form must be rewritten for MySQL?','["ORDER BY code", "ON CONFLICT (code) DO UPDATE", "SELECT code FROM items", "WHERE code = 4"]'::jsonb,1,'Conflict syntax and matching rules differ across engines.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-upsert-patterns-4','pt-dbms-sql-11-upsert-patterns','What protects the intended equipment identity?','["A repeated label alone", "A suitable PRIMARY KEY or UNIQUE index", "A display ordering rule", "An unrelated foreign key"]'::jsonb,1,'Duplicate handling relies on an enforced unique collision.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-upsert-patterns-5','pt-dbms-sql-11-upsert-patterns','What does the proposed-row alias represent?','["Only the previous stored values", "Values supplied for the attempted new row", "The database owner", "A sorted result cursor"]'::jsonb,1,'The alias separates incoming values from target values.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-upsert-patterns-6','pt-dbms-sql-11-upsert-patterns','What is the status of VALUES(column) in MySQL 8.4 duplicate-update expressions?','["Required in all new SQL", "Deprecated; prefer supported alias forms for new examples", "Identical to deleting a row", "The VALUES clause itself is forbidden"]'::jsonb,1,'The deprecated function usage differs from the insertion clause.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-upsert-patterns-7','pt-dbms-sql-11-upsert-patterns','Why is upsert SQL not directly interchangeable across engines?','["All SQL engines lack keys", "Conflict selection and supported statement forms differ", "Only capitalization differs", "Every engine uses the same conflict target"]'::jsonb,1,'Preserve business semantics while rewriting the dialect.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-upsert-patterns-8','pt-dbms-sql-11-upsert-patterns','Without uniqueness on the intended identity, what can happen?','["MySQL invents a unique constraint", "Repeated identity values can become separate rows", "Every repeated value is updated automatically", "The table must become read only"]'::jsonb,1,'Another independent unique collision could still trigger handling; the intended key needs protection.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
