insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-view-limitations-application-8','cx-view-limitations-application','Why test an exact INSERT separately from general updatability?','["Required base columns and operation restrictions also matter", "INSERT ignores all constraints", "Views accept no inserts under any circumstances", "An indicator guarantees all inserts"]'::jsonb,0,'Different modification operations have additional conditions.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-view-limitations-application-9','cx-view-limitations-application','Does saving a join as a view prevent detail fanout?','["Yes, all views use DISTINCT", "No", "Only for salary columns", "Only if COUNT(*) is present"]'::jsonb,1,'Saved definitions retain the underlying query semantics.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-view-limitations-application-10','cx-view-limitations-application','Why review SQL SECURITY and grants for a view?','["They determine final row ordering", "They automatically normalize tables", "The privilege context affects access to underlying data", "They convert aggregates into editable columns"]'::jsonb,2,'View exposure needs an intentional authorization contract.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
