select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-19-views/view-maintenance' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'view-maintenance'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'view-maintenance'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('fff05d5bf62851b55d08b8851c681c16','5821e7e1787ff8c60f95973ace97b02b')) then raise exception 'Notes changed since seed; review before applying: %', 'view-maintenance'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-19-view-maintenance' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'view-maintenance'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-19-view-maintenance' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'view-maintenance'; end if;
