if exists(select 1 from public.practice_tests where id='cx-view-maintenance-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'view-maintenance'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Definition maintenance versus result maintenance", "columns": ["Object", "Stored information", "Maintenance"], "rows": [["Ordinary view", "Query definition", "Preserve dependencies and interface"], ["Summary table", "Previously computed rows", "Refresh and reconcile with source"]], "description": "An ordinary view and a stored summary have different freshness responsibilities."}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'view-maintenance'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Definition maintenance versus result maintenance", "columns": ["Object", "Stored information", "Maintenance"], "rows": [["Ordinary view", "Query definition", "Preserve dependencies and interface"], ["Summary table", "Previously computed rows", "Refresh and reconcile with source"]], "description": "An ordinary view and a stored summary have different freshness responsibilities."}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Definition maintenance versus result maintenance", "columns": ["Object", "Stored information", "Maintenance"], "rows": [["Ordinary view", "Query definition", "Preserve dependencies and interface"], ["Summary table", "Previously computed rows", "Refresh and reconcile with source"]], "description": "An ordinary view and a stored summary have different freshness responsibilities."}]'::jsonb;
