if exists(select 1 from public.test_questions where id='tq-dbms-sql-19-view-maintenance-5' and (question_text,options,correct_index,explanation) is distinct from ('What does a dependency-tracking system (e.g., PostgreSQL''s pg_depend) prevent by default?','["Creating any new view", "Dropping a table that a view depends on, unless CASCADE is specified", "Granting SELECT on a view", "Renaming any column in the database"]'::jsonb,1,'Dependency tracking blocks a DROP TABLE (or similar) that would break a dependent view, unless the operation is explicitly forced with CASCADE, protecting against accidental breakage.') and (question_text,options,correct_index,explanation) is distinct from ('What does a dependency-tracking system (e.g., PostgreSQL''s pg_depend) prevent by default?','["Creating any new view", "Dropping a table that a view depends on, unless CASCADE is specified", "Granting SELECT on a view", "Renaming any column in the database"]'::jsonb,1,'Dependency tracking blocks a DROP TABLE (or similar) that would break a dependent view, unless the operation is explicitly forced with CASCADE, protecting against accidental breakage.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-19-view-maintenance-5'; end if;
