if exists(select 1 from public.test_questions where id='tq-dbms-sql-19-view-maintenance-6' and (question_text,options,correct_index,explanation) is distinct from ('Why should a team query the system catalog for view dependencies before running ALTER TABLE ... DROP COLUMN in production?','["It''s not necessary since SQL always warns automatically", "To identify every view that could break from the change and fix/update them proactively rather than discovering failures later", "Because ALTER TABLE requires listing dependent views by law of SQL syntax", "To automatically drop all dependent views"]'::jsonb,1,'Proactively checking dependencies (via information_schema.view_table_usage, pg_depend, etc.) lets a team fix or update all impacted views before the breaking change ships, avoiding delayed production failures.') and (question_text,options,correct_index,explanation) is distinct from ('Why should a team query the system catalog for view dependencies before running ALTER TABLE ... DROP COLUMN in production?','["It''s not necessary since SQL always warns automatically", "To identify every view that could break from the change and fix/update them proactively rather than discovering failures later", "Because ALTER TABLE requires listing dependent views by law of SQL syntax", "To automatically drop all dependent views"]'::jsonb,1,'Proactively checking dependencies (via information_schema.view_table_usage, pg_depend, etc.) lets a team fix or update all impacted views before the breaking change ships, avoiding delayed production failures.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-19-view-maintenance-6'; end if;
