update public.learning_topics set short_description='Understand ordinary view changes and stored-summary maintenance through enrollment counts, stale-result diagnostics, refresh design, and reconciliation labs.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Understand ordinary view changes and stored-summary maintenance through enrollment counts, stale-result diagnostics, refresh design, and reconciliation labs.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for View Maintenance.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-19-view-maintenance' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'cx-view-maintenance-application','MCQ Test 2',category,10,10,'Application and scenarios for View Maintenance.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-19-view-maintenance' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-view-maintenance-1','pt-dbms-sql-19-view-maintenance','What can happen if a column referenced by a view is dropped from the base table, in an engine that doesn''t eagerly check view dependencies?','["The view is automatically updated to remove the reference", "Nothing changes until the view is queried, at which point it fails with an error like ''column does not exist''", "The database refuses to start", "The view silently returns zero rows forever"]'::jsonb,1,'Without eager dependency checking, the break is deferred until query time, producing a delayed and easy-to-miss failure — a dangerous maintenance trap.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-view-maintenance-2','pt-dbms-sql-19-view-maintenance','In PostgreSQL, why can CREATE OR REPLACE VIEW be preferable to dropping and recreating a compatible view definition?','["It runs faster on large tables", "DROP VIEW typically removes the grants attached to the view object, which must then be manually re-issued; CREATE OR REPLACE VIEW preserves them", "DROP VIEW is not valid SQL syntax", "CREATE OR REPLACE VIEW automatically updates all dependent views too"]'::jsonb,1,'PostgreSQL replacement preserves object identity and associated ownership/permissions under its supported replacement contract. Privilege behavior must not be generalized unchanged across engines.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-view-maintenance-3','pt-dbms-sql-19-view-maintenance','A column `salary` is renamed to `base_salary`. How can a view preserve its external `salary` column name for existing client applications?','["By using SELECT * so all columns pass through automatically", "By redefining the view with `base_salary AS salary` in the SELECT list via CREATE OR REPLACE VIEW", "It is impossible to preserve the old column name in a view", "By creating a synonym table"]'::jsonb,1,'Aliasing the renamed physical column back to the original name in the view definition keeps the view''s output contract stable for consumers, even though the underlying column name changed.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-view-maintenance-4','pt-dbms-sql-19-view-maintenance','In MySQL, what should be understood about a view originally created using SELECT * when the base table changes?','["The view cannot ever be dropped", "Its definition is frozen at creation: added base columns do not automatically appear, and dropping referenced columns can invalidate it", "SELECTstar is forbidden in views", "Every such view always runs slower"]'::jsonb,1,'MySQL freezes the selected column definition at creation. Explicit projections make the intended output contract clearer; redefinition is deliberate.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-view-maintenance-5','pt-dbms-sql-19-view-maintenance','What does a dependency-tracking system (e.g., PostgreSQL''s pg_depend) prevent by default?','["Creating any new view", "Dropping a table that a view depends on, unless CASCADE is specified", "Granting SELECT on a view", "Renaming any column in the database"]'::jsonb,1,'Dependency tracking blocks a DROP TABLE (or similar) that would break a dependent view, unless the operation is explicitly forced with CASCADE, protecting against accidental breakage.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-view-maintenance-6','pt-dbms-sql-19-view-maintenance','Why should a team query the system catalog for view dependencies before running ALTER TABLE ... DROP COLUMN in production?','["It''s not necessary since SQL always warns automatically", "To identify every view that could break from the change and fix/update them proactively rather than discovering failures later", "Because ALTER TABLE requires listing dependent views by law of SQL syntax", "To automatically drop all dependent views"]'::jsonb,1,'Proactively checking dependencies (via information_schema.view_table_usage, pg_depend, etc.) lets a team fix or update all impacted views before the breaking change ships, avoiding delayed production failures.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-view-maintenance-7','pt-dbms-sql-19-view-maintenance','What compounding risk do nested views (a view built on another view) introduce for schema maintenance?','["None — nested views are fully isolated from each other", "A single base-table schema change can cascade through multiple layers of dependent views, widening the blast radius of a break", "Nested views cannot be created at all", "Nested views automatically fix themselves"]'::jsonb,1,'If view B is built on view A, a break in A (from a base-table change) propagates to B and anything built on B — increasing the scope of what must be checked and fixed.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-19-view-maintenance-8','pt-dbms-sql-19-view-maintenance','In PostgreSQL, what happens to a dependent parsed view when a referenced base column is renamed through a supported ALTER TABLE RENAME COLUMN?','["The view becomes a materialized view", "The dependent view remains bound to the same base attribute; its existing output alias need not change", "Every dependent view is automatically dropped", "Column renaming is universally blocked by view dependencies"]'::jsonb,1,'PostgreSQL tracks the referenced attribute through the rename. Renaming a view output column is a separate interface change; this differs from dropping a referenced column.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
