if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'view-serializability'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'view-serializability'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('9d51b3cf1d2890361f9a2b0197810d42','3b0bde67ac9cf1a4b6da660a89f9a1b0')) then raise exception 'Notes changed since seed; review before applying: %', 'view-serializability'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-23-view-serializability' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'view-serializability'; end if;
