if exists(select 1 from public.practice_tests where id='pt-dbms-sql-23-view-serializability-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'view-serializability'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Same view despite changed intermediate write order", "description": "Both histories preserve T1 initial read and T3 final write; only the interleaving has a conflict cycle.", "columns": ["Property", "Interleaving r1, w2, w1, w3", "Serial T1, T2, T3"], "rows": [["T1 read source", "Initial A", "Initial A"], ["Other reads", "None", "None"], ["Final writer of A", "T3", "T3"], ["Conflict cycle", "T1 toT2 toT1", "None"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'view-serializability'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Same view despite changed intermediate write order", "description": "Both histories preserve T1 initial read and T3 final write; only the interleaving has a conflict cycle.", "columns": ["Property", "Interleaving r1, w2, w1, w3", "Serial T1, T2, T3"], "rows": [["T1 read source", "Initial A", "Initial A"], ["Other reads", "None", "None"], ["Final writer of A", "T3", "T3"], ["Conflict cycle", "T1 toT2 toT1", "None"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Same view despite changed intermediate write order", "description": "Both histories preserve T1 initial read and T3 final write; only the interleaving has a conflict cycle.", "columns": ["Property", "Interleaving r1, w2, w1, w3", "Serial T1, T2, T3"], "rows": [["T1 read source", "Initial A", "Initial A"], ["Other reads", "None", "None"], ["Final writer of A", "T3", "T3"], ["Conflict cycle", "T1 toT2 toT1", "None"]]}]'::jsonb;
