if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-view-serializability-1' and (question_text,options,correct_index,explanation) is distinct from ('What are the three conditions for two schedules to be ''view equivalent''?','["Same number of transactions, same number of commits, same number of aborts", "Same initial reads, same read-from relationships between transactions, and the same transaction performing the final write to each item", "Same total execution time and same lock table state", "Same set of data items accessed, regardless of order"]'::jsonb,1,'View equivalence requires matching initial reads, matching read-from pairs, and matching final writers per data item — nothing about timing or locks.') and (question_text,options,correct_index,explanation) is distinct from ('What are the three conditions for two schedules to be ''view equivalent''?','["Same number of transactions, same number of commits, same number of aborts", "Same initial reads, same read-from relationships between transactions, and the same transaction performing the final write to each item", "Same total execution time and same lock table state", "Same set of data items accessed, regardless of order"]'::jsonb,1,'View equivalence requires matching initial reads, matching read-from pairs, and matching final writers per data item — nothing about timing or locks.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-view-serializability-1'; end if;
