if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-view-serializability-4' and (question_text,options,correct_index,explanation) is distinct from ('What kind of operation is essential for a schedule to be view-serializable but NOT conflict-serializable?','["A blind write \u2014 a write to an item with no preceding read of it by the same transaction", "A dirty read", "A phantom insert", "A two-phase commit"]'::jsonb,0,'Without blind writes, conflict and view serializability coincide; the extra permissiveness of view serializability specifically comes from ignoring the order of writes nobody ever reads.') and (question_text,options,correct_index,explanation) is distinct from ('What kind of operation is essential for a schedule to be view-serializable but NOT conflict-serializable?','["A blind write \u2014 a write to an item with no preceding read of it by the same transaction", "A dirty read", "A phantom insert", "A two-phase commit"]'::jsonb,0,'Without blind writes, conflict and view serializability coincide; the extra permissiveness of view serializability specifically comes from ignoring the order of writes nobody ever reads.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-view-serializability-4'; end if;
