if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-view-serializability-5' and (question_text,options,correct_index,explanation) is distinct from ('Is every conflict-serializable schedule also view-serializable?','["No, they are unrelated properties", "Yes \u2014 conflict serializability is strictly narrower, so anything satisfying it automatically satisfies the broader view-serializability definition too", "Only if the schedule has no blind writes", "Only for schedules with exactly two transactions"]'::jsonb,1,'Reordering by non-conflicting swaps always preserves initial reads, read-from relationships, and final writes, so conflict-serializable schedules are always a subset of view-serializable ones.') and (question_text,options,correct_index,explanation) is distinct from ('Is every conflict-serializable schedule also view-serializable?','["No, they are unrelated properties", "Yes \u2014 conflict serializability is strictly narrower, so anything satisfying it automatically satisfies the broader view-serializability definition too", "Only if the schedule has no blind writes", "Only for schedules with exactly two transactions"]'::jsonb,1,'Reordering by non-conflicting swaps always preserves initial reads, read-from relationships, and final writes, so conflict-serializable schedules are always a subset of view-serializable ones.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-view-serializability-5'; end if;
