if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-view-serializability-6' and (question_text,options,correct_index,explanation) is distinct from ('Why do real production DBMS concurrency control protocols enforce conflict serializability rather than the more general view serializability?','["View serializability is not a real academic concept", "Testing view serializability in general is NP-complete, while conflict serializability can be tested efficiently (polynomial time) via a precedence graph", "View serializability only applies to read-only transactions", "Conflict serializability produces higher final account balances"]'::jsonb,1,'The practical cost of testing/enforcing view serializability is prohibitive at scale, so systems accept the narrower but efficiently-checkable conflict serializability standard.') and (question_text,options,correct_index,explanation) is distinct from ('Why is the conflict-graph test a useful practical classroom criterion compared with general view-serializability testing?','["View serializability is not a real academic concept", "The conflict-graph criterion is efficiently testable; general view-serializability testing is NP-complete.", "View serializability only applies to read-only transactions", "Conflict serializability produces higher final account balances"]'::jsonb,1,'Real engines use different concurrency protocols and supported isolation levels; they do not all run this graph test.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-view-serializability-6'; end if;
