if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-view-serializability-7' and (question_text,options,correct_index,explanation) is distinct from ('When does conflict serializability and view serializability coincide exactly (produce the same verdict)?','["Always, they are identical definitions", "Never \u2014 they always disagree", "When the schedule contains no blind writes", "Only when there are exactly 2 transactions"]'::jsonb,2,'The gap between the two notions only opens up in the presence of blind writes; without them, every view-serializable schedule is also conflict-serializable.') and (question_text,options,correct_index,explanation) is distinct from ('When does conflict serializability and view serializability coincide exactly (produce the same verdict)?','["Always, they are identical definitions", "Never \u2014 they always disagree", "When the schedule contains no blind writes", "Only when there are exactly 2 transactions"]'::jsonb,2,'The gap between the two notions only opens up in the presence of blind writes; without them, every view-serializable schedule is also conflict-serializable.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-view-serializability-7'; end if;
