if exists(select 1 from public.test_questions where id='tq-dbms-sql-23-view-serializability-8' and (question_text,options,correct_index,explanation) is distinct from ('What does the ''final write'' condition of view equivalence require?','["Every transaction must write every data item", "For each data item, the same transaction must perform the last write to it in both schedules being compared", "The last operation of the schedule must be a COMMIT", "All writes must happen before all reads"]'::jsonb,1,'Final-write matching ensures that whichever value a subsequent reader (or the database state itself) ultimately sees for that item is attributable to the same transaction in both schedules.') and (question_text,options,correct_index,explanation) is distinct from ('What does the ''final write'' condition of view equivalence require?','["Every transaction must write every data item", "For each data item, the same transaction must perform the last write to it in both schedules being compared", "The last operation of the schedule must be a COMMIT", "All writes must happen before all reads"]'::jsonb,1,'Final-write matching ensures that whichever value a subsequent reader (or the database state itself) ultimately sees for that item is attributable to the same transaction in both schedules.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-23-view-serializability-8'; end if;
