update public.learning_topics set short_description='Prove view equivalence with initial reads, read-from sources and final writers; compare blind-write witnesses with cyclic conflict graphs and recovery limits.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Prove view equivalence with initial reads, read-from sources and final writers; compare blind-write witnesses with cyclic conflict graphs and recovery limits.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for View Serializability.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-23-view-serializability' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-23-view-serializability-application','MCQ Test 2',category,10,10,'Application and scenarios for View Serializability.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-23-view-serializability' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-view-serializability-1','pt-dbms-sql-23-view-serializability','What are the three conditions for two schedules to be ''view equivalent''?','["Same number of transactions, same number of commits, same number of aborts", "Same initial reads, same read-from relationships between transactions, and the same transaction performing the final write to each item", "Same total execution time and same lock table state", "Same set of data items accessed, regardless of order"]'::jsonb,1,'View equivalence requires matching initial reads, matching read-from pairs, and matching final writers per data item — nothing about timing or locks.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-view-serializability-2','pt-dbms-sql-23-view-serializability','In the worked example (R1(A), W2(A), W1(A), W3(A)), why does this schedule fail the conflict-serializability test?','["Because R1(A) and W3(A) don''t conflict", "Because the conflicts create a cycle: R1(A) before W2(A) implies T1→T2, but W2(A) before W1(A) implies T2→T1", "Because it involves three transactions instead of two", "Because W3(A) is a blind write"]'::jsonb,1,'The precedence graph has both a T1→T2 edge and a T2→T1 edge, forming a 2-node cycle — which means no serial reordering via legal swaps is possible.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-view-serializability-3','pt-dbms-sql-23-view-serializability','Despite failing conflict serializability, why is that same schedule view-serializable (equivalent to <T1, T2, T3>)?','["Because T2 and T3''s writes are blind (no read), so nobody observes their relative order — only the final writer (T3) and T1''s initial read matter, and both match the serial order", "Because view serializability ignores write operations entirely", "Because the schedule has no conflicts at all", "Because T1 commits first in both schedules"]'::jsonb,0,'The intermediate T1 and T2 writes change relative order, while T1 keeps its initial read and T3 remains final writer. Those are the only read/final-writer constraints in the stated history.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-view-serializability-4','pt-dbms-sql-23-view-serializability','What kind of operation is essential for a schedule to be view-serializable but NOT conflict-serializable?','["A blind write — a write to an item with no preceding read of it by the same transaction", "A dirty read", "A phantom insert", "A two-phase commit"]'::jsonb,0,'Without blind writes, conflict and view serializability coincide; the extra permissiveness of view serializability specifically comes from ignoring the order of writes nobody ever reads.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-view-serializability-5','pt-dbms-sql-23-view-serializability','Is every conflict-serializable schedule also view-serializable?','["No, they are unrelated properties", "Yes — conflict serializability is strictly narrower, so anything satisfying it automatically satisfies the broader view-serializability definition too", "Only if the schedule has no blind writes", "Only for schedules with exactly two transactions"]'::jsonb,1,'Reordering by non-conflicting swaps always preserves initial reads, read-from relationships, and final writes, so conflict-serializable schedules are always a subset of view-serializable ones.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-view-serializability-6','pt-dbms-sql-23-view-serializability','Why is the conflict-graph test a useful practical classroom criterion compared with general view-serializability testing?','["View serializability is not a real academic concept", "The conflict-graph criterion is efficiently testable; general view-serializability testing is NP-complete.", "View serializability only applies to read-only transactions", "Conflict serializability produces higher final account balances"]'::jsonb,1,'Real engines use different concurrency protocols and supported isolation levels; they do not all run this graph test.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-view-serializability-7','pt-dbms-sql-23-view-serializability','When does conflict serializability and view serializability coincide exactly (produce the same verdict)?','["Always, they are identical definitions", "Never — they always disagree", "When the schedule contains no blind writes", "Only when there are exactly 2 transactions"]'::jsonb,2,'The gap between the two notions only opens up in the presence of blind writes; without them, every view-serializable schedule is also conflict-serializable.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-23-view-serializability-8','pt-dbms-sql-23-view-serializability','What does the ''final write'' condition of view equivalence require?','["Every transaction must write every data item", "For each data item, the same transaction must perform the last write to it in both schedules being compared", "The last operation of the schedule must be a COMMIT", "All writes must happen before all reads"]'::jsonb,1,'Final-write matching ensures that whichever value a subsequent reader (or the database state itself) ultimately sees for that item is attributable to the same transaction in both schedules.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-23-view-serializability-c-new-1','pt-dbms-sql-23-view-serializability','T1 reads an initial value in the original history. What must a view-equivalent history preserve?','["That initial read", "Only a coincidentally equal number", "Only the table name", "Only the last SQL statement"]'::jsonb,0,'View equivalence preserves the source relationship, not merely one observed numeric equality.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
