insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-20-when-not-to-index-4','pt-dbms-sql-20-when-not-to-index','Why might a write-heavy table (like a high-volume event log) be a poor candidate for many indexes?','["Write-heavy tables cannot have any indexes by definition", "The cumulative write-overhead cost of maintaining many indexes can outweigh the benefit if reads against that table are rare or non-critical", "Indexes make writes faster on write-heavy tables, so more is always better", "Event logs never have any columns worth filtering on"]'::jsonb,1,'On write-dominated tables, the per-write index-maintenance cost (20.14) compounds and can exceed any read-side gain from having the index.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
