insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-when-not-to-index-19','cx-test-when-not-to-index-2','What is the difference between declining and removing an index?','["They are identical actions", "Declining deletes the table", "Removal changes an existing dependency and needs separate approval", "Removal never needs rollback"]'::jsonb,2,'Existing callers and constraints may depend on the structure.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('cx-q-when-not-to-index-20','cx-test-when-not-to-index-2','Which report best supports an index decision?','["Always use indexes", "Never index booleans", "Scans always mean failure", "Measured benefit, observed costs and evidence limits"]'::jsonb,3,'A bounded evidence claim is more useful than a universal slogan.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
