if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-where-vs-having-1' and (question_text,options,correct_index,explanation) is distinct from ('Which clause can reference an aggregate function such as SUM(amount) in its condition?','["WHERE only", "HAVING only", "Both equally", "Neither"]'::jsonb,1,'HAVING runs after aggregation so it can reference aggregate results; WHERE runs before grouping, when aggregates don''t exist yet.') and (question_text,options,correct_index,explanation) is distinct from ('Which clause chooses individual rows before grouping?','["HAVING on SUM", "WHERE", "ORDER BY", "A column alias"]'::jsonb,1,'WHERE defines which facts are available to the grouping stage.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-where-vs-having-1'; end if;
