if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-where-vs-having-2' and (question_text,options,correct_index,explanation) is distinct from ('To keep only orders where amount > 100 before any grouping happens, which clause should you use?','["HAVING amount > 100", "WHERE amount > 100", "GROUP BY amount > 100", "ORDER BY amount > 100"]'::jsonb,1,'amount > 100 is a row-level condition on raw data, evaluated before grouping — that''s exactly what WHERE is for.') and (question_text,options,correct_index,explanation) is distinct from ('Which clause filters groups by SUM(amount)?','["A same-level WHERE containing SUM", "HAVING", "LIMIT alone", "A primary key declaration"]'::jsonb,1,'A total is available for qualification at the grouped-result stage.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-where-vs-having-2'; end if;
