if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-where-vs-having-3' and (question_text,options,correct_index,explanation) is distinct from ('`SELECT region, SUM(amount) FROM orders WHERE region IN (''East'',''West'') GROUP BY region;` — why does this only ever aggregate 6 of the 8 rows?','["GROUP BY silently drops rows with duplicate regions", "WHERE removes the 2 North rows before grouping/aggregation happens", "HAVING is implicitly applied", "SUM() ignores rows outside alphabetical order"]'::jsonb,1,'WHERE executes before GROUP BY, physically excluding North''s 2 rows so only the remaining 6 (East+West) rows are ever grouped and summed.') and (question_text,options,correct_index,explanation) is distinct from ('Do two posted payments of sixty and fifty satisfy SUM(amount)>=100?','["No, each row must be 100", "Yes, their sum is 110", "Only with DISTINCT", "Only if sorted descending"]'::jsonb,1,'The threshold applies to sixty plus fifty, rather than independently to either row.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-where-vs-having-3'; end if;
