if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-where-vs-having-4' and (question_text,options,correct_index,explanation) is distinct from ('Why is `GROUP BY region HAVING region = ''West''` valid but generally worse practice than `WHERE region = ''West'' GROUP BY region`?','["HAVING version is invalid SQL", "The HAVING version aggregates all regions first then discards two whole groups, doing unnecessary work; the WHERE version filters rows before aggregation ever touches them", "They behave completely differently and can give different results", "WHERE cannot use string equality"]'::jsonb,1,'Both return the same result here, but HAVING forces full aggregation of North/East/West before discarding non-West groups, while WHERE avoids aggregating the excluded rows at all — a real, if often small, cost difference.') and (question_text,options,correct_index,explanation) is distinct from ('Why is WHERE amount>=100 a different request?','["It sorts the same groups", "It removes contributing rows before the group total", "It renames the sum", "It necessarily counts nulls"]'::jsonb,1,'Removing small facts before aggregation prevents them from contributing to a qualifying combined total.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-where-vs-having-4'; end if;
