if exists(select 1 from public.test_questions where id='tq-dbms-sql-15-where-vs-having-7' and (question_text,options,correct_index,explanation) is distinct from ('Is `WHERE SUM(amount) > 300` valid syntax in standard SQL?','["Yes, always", "No \u2014 aggregate functions cannot appear in WHERE because grouping/aggregation hasn''t happened yet at that stage", "Yes, but only in MySQL", "Yes, but only inside a subquery"]'::jsonb,1,'WHERE is evaluated per-row before GROUP BY forms groups and computes aggregates, so aggregate functions are illegal there in every mainstream SQL dialect.') and (question_text,options,correct_index,explanation) is distinct from ('What does SUM do with null amounts?','["It always rejects the group", "It ignores unknown numeric values", "It counts null as one", "It fills null with the previous amount"]'::jsonb,1,'A null expression supplies no known number for SUM to add.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-15-where-vs-having-7'; end if;
