insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-15-where-vs-having-1','pt-dbms-sql-15-where-vs-having','Which clause chooses individual rows before grouping?','["HAVING on SUM", "WHERE", "ORDER BY", "A column alias"]'::jsonb,1,'WHERE defines which facts are available to the grouping stage.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
