insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cp-dbms-sql-expensive-electronics',null::text,'Expensive Electronics','Easy','expensive-electronics','Return id,name,price for products whose category is Electronics and price is strictly greater than 50000. Order by id. Preserve all rows and do not add a stock requirement. An empty result is valid.

**MySQL dialect.**

```sql
CREATE TABLE products (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  price INTEGER NOT NULL,
  stock INTEGER
);
INSERT INTO products (id, name, category, price, stock) VALUES
(1, ''ProLaptop'', ''Electronics'', 85000, 12),
(2, ''Notebook'', ''Stationery'', 40, NULL),
(3, ''Python Basics'', ''Books'', 350, 5),
(4, ''ProPhone'', ''Electronics'', 45000, 0),
(5, ''Novel'', ''Books'', 220, NULL),
(6, ''Desk Lamp'', ''Home'', 900, 8);
```

**Required ordering:** As explicitly ordered in the result query.

**Edge cases:**
- An exact-threshold row is excluded.
- Zero stock does not exclude an otherwise qualifying retained product.','[{"input": "INSERT INTO products (id, name, category, price, stock) VALUES\n(1, ''ProLaptop'', ''Electronics'', 85000, 12),\n(2, ''Notebook'', ''Stationery'', 40, NULL),\n(3, ''Python Basics'', ''Books'', 350, 5),\n(4, ''ProPhone'', ''Electronics'', 45000, 0),\n(5, ''Novel'', ''Books'', 220, NULL),\n(6, ''Desk Lamp'', ''Home'', 900, 8);", "output": "id\tname\tprice\n1\tProLaptop\t85000", "explanation": "The category equality and strict price threshold must both hold. Stock is intentionally outside the retained requirement.", "check_sql": ""}]'::jsonb,'[{"seed_sql": "INSERT INTO products (id, name, category, price, stock) VALUES\n(1, ''ProTablet'', ''Electronics'', 32000, 4),\n(2, ''Pencil Set'', ''Stationery'', 60, NULL),\n(3, ''SQL Guide'', ''Books'', 500, 10),\n(4, ''ProSpeaker'', ''Electronics'', 6000, 0);", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO products VALUES (1,''Boundary'',''Electronics'',50000,5),(2,''Above'',''Electronics'',50001,0),(3,''Book'',''Books'',90000,9);", "expected": "id\tname\tprice\n2\tAbove\t50001", "hidden": true}, {"seed_sql": "INSERT INTO products VALUES (4,''Lower'',''Electronics'',40000,7);", "expected": "", "hidden": true}]'::jsonb,'["Use only the supplied synthetic tables and requested transition.", "Preserve unrelated rows."]'::jsonb,'["Combine category and price using AND.", "Use the strict threshold and retain id ordering."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The category equality and strict price threshold must both hold. Stock is intentionally outside the retained requirement.','{"sql": "SELECT id,name,price FROM products WHERE category=''Electronics'' AND price>50000 ORDER BY id;"}'::jsonb,'The category equality and strict price threshold must both hold. Stock is intentionally outside the retained requirement.',array['sql'],'CREATE TABLE products (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  price INTEGER NOT NULL,
  stock INTEGER
);','INSERT INTO products (id, name, category, price, stock) VALUES
(1, ''ProLaptop'', ''Electronics'', 85000, 12),
(2, ''Notebook'', ''Stationery'', 40, NULL),
(3, ''Python Basics'', ''Books'', 350, 5),
(4, ''ProPhone'', ''Electronics'', 45000, 0),
(5, ''Novel'', ''Books'', 220, NULL),
(6, ''Desk Lamp'', ''Home'', 900, 8);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-12-where' on conflict(id) do update set description=excluded.description,examples=excluded.examples,test_cases=excluded.test_cases,constraints=excluded.constraints,hints=excluded.hints,editorial=excluded.editorial,solution_code=excluded.solution_code,solution_approach=excluded.solution_approach,updated_at=now() where (dsa_problems.description,dsa_problems.examples,dsa_problems.test_cases,dsa_problems.constraints,dsa_problems.hints,dsa_problems.editorial,dsa_problems.solution_code,dsa_problems.solution_approach) is distinct from (excluded.description,excluded.examples,excluded.test_cases,excluded.constraints,excluded.hints,excluded.editorial,excluded.solution_code,excluded.solution_approach);
