);','INSERT INTO products VALUES (1,''Camera'',''Electronics'',500,0),(2,''Lamp'',''Home'',20,4),(3,''Book'',''Books'',10,8),(4,''Mic'',''Electronics'',80,2),(5,''Desk'',''Home'',50,NULL);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-12-where' on conflict(id) do nothing;
