if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-1' and (question_text,options,correct_index,explanation) is distinct from ('On a `students` table with 1,000,000 rows and no index on `email`, what must the engine do to find a row matching a specific email?','["Perform a binary search on the table file", "Perform a full table scan, checking rows one by one", "Automatically build a temporary index", "Reject the query as unsupported"]'::jsonb,1,'Without an index, the only way to guarantee correctness is to examine every row — a full table scan.') and (question_text,options,correct_index,explanation) is distinct from ('A students table has no useful access structure for an email predicate and no other narrowing condition. What basic strategy can find matching rows?','["Perform a binary search on the table file", "Perform a full table scan, checking rows one by one", "Automatically build a temporary index", "Reject the query as unsupported"]'::jsonb,1,'A scan examines rows for the predicate when no useful key-directed access path applies. Actual work depends on the complete query and plan.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-why-indexes-exist-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-2' and test_id<>'pt-dbms-sql-20-why-indexes-exist') then raise exception 'Question ID collision: %', 'tq-dbms-sql-20-why-indexes-exist-2'; end if;
