if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-2' and (question_text,options,correct_index,explanation) is distinct from ('What is the best conceptual description of a database index?','["A cached copy of the entire table", "A compressed version of the table stored in memory only", "A separate, organized structure mapping column values to row locations", "A rule that prevents duplicate values"]'::jsonb,2,'An index is an auxiliary structure — separate from the table itself — that maps indexed values to where the matching rows live.') and (question_text,options,correct_index,explanation) is distinct from ('What is the best conceptual description of a database index?','["A cached copy of the entire table", "A compressed version of the table stored in memory only", "An organized access structure over key values that locates or supplies required row data", "A rule that prevents duplicate values"]'::jsonb,2,'Secondary indexes may carry row locators, while clustered storage can contain base row values. An index supplies an access structure; it is not always physically separate from the table data.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-why-indexes-exist-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-3' and test_id<>'pt-dbms-sql-20-why-indexes-exist') then raise exception 'Question ID collision: %', 'tq-dbms-sql-20-why-indexes-exist-3'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-3' and test_id='pt-dbms-sql-20-why-indexes-exist') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-20-why-indexes-exist-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-3' and (question_text,options,correct_index,explanation) is distinct from ('Which of the following is a genuine cost of adding an index?','["Reads become slower", "Writes (INSERT/UPDATE/DELETE) become slower because the index must also be updated", "The table can no longer be queried without the index", "SELECT * queries stop working"]'::jsonb,1,'Every write that touches an indexed column must also update the index structure, adding overhead to writes.') and (question_text,options,correct_index,explanation) is distinct from ('Which of the following is a genuine cost of adding an index?','["Reads become slower", "Writes can incur additional work because relevant index entries must be maintained", "The table can no longer be queried without the index", "SELECT * queries stop working"]'::jsonb,1,'Inserts,deletes and changes to indexed keys can require index maintenance. The workload impact depends on which entries change and the engine.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-why-indexes-exist-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-4' and test_id<>'pt-dbms-sql-20-why-indexes-exist') then raise exception 'Question ID collision: %', 'tq-dbms-sql-20-why-indexes-exist-4'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-4' and test_id='pt-dbms-sql-20-why-indexes-exist') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-20-why-indexes-exist-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-4' and (question_text,options,correct_index,explanation) is distinct from ('A full table scan on a 1,000,000-row table looking for a single matching email averages how many row checks (assuming exactly one match exists)?','["log2(1,000,000) \u2248 20", "About 500,000", "Exactly 1", "1,000,000 always, no matter what"]'::jsonb,1,'On average, a linear scan finds a single match halfway through, so roughly half the rows (500,000) are checked before it''s found.') and (question_text,options,correct_index,explanation) is distinct from ('A simplified sequential search stops at the first match. Exactly one match is uniformly distributed among 1,000,000 rows. Approximately how many checks are expected?','["log2(1,000,000) \u2248 20", "About 500,000", "Exactly 1", "1,000,000 always, no matter what"]'::jsonb,1,'Under the stated stop-at-first and uniform-position assumptions, the mean position is (1,000,000+1)/2. A real query returning all matches may still scan the whole input; this is not an EXPLAIN row estimate.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-why-indexes-exist-4'; end if;
