if not exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-5' and test_id='pt-dbms-sql-20-why-indexes-exist') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-20-why-indexes-exist-5'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-5' and (question_text,options,correct_index,explanation) is distinct from ('Which analogy best captures how an index helps a query?','["Like memorizing the entire textbook", "Like the index at the back of a textbook, letting you jump straight to the right page instead of reading every page", "Like removing pages from the textbook you don''t need", "Like translating the textbook into another language"]'::jsonb,1,'A book index maps terms to page numbers so you skip irrelevant pages — exactly analogous to a DB index mapping values to row locations.') and (question_text,options,correct_index,explanation) is distinct from ('Which analogy best captures how an index helps a query?','["Like memorizing the entire textbook", "Like the index at the back of a textbook, letting you jump straight to the right page instead of reading every page", "Like removing pages from the textbook you don''t need", "Like translating the textbook into another language"]'::jsonb,1,'A book index maps terms to page numbers so you skip irrelevant pages — exactly analogous to a DB index mapping values to row locations.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-why-indexes-exist-5'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-6' and test_id<>'pt-dbms-sql-20-why-indexes-exist') then raise exception 'Question ID collision: %', 'tq-dbms-sql-20-why-indexes-exist-6'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-6' and test_id='pt-dbms-sql-20-why-indexes-exist') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-20-why-indexes-exist-6'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-6' and (question_text,options,correct_index,explanation) is distinct from ('Why might indexing every single column of a table be a bad idea?','["Databases technically cap the number of indexes at 2", "Each index adds storage and slows down every write, even if many indexes are rarely used for reads", "Indexes make SELECT queries return wrong results", "It is not possible to index more than one column total"]'::jsonb,1,'Indiscriminate indexing multiplies write overhead and storage cost without necessarily providing matching read benefit.') and (question_text,options,correct_index,explanation) is distinct from ('Why might indexing every single column of a table be a bad idea?','["Databases technically cap the number of indexes at 2", "Each index consumes storage and can add write maintenance even if it rarely benefits reads", "Indexes make SELECT queries return wrong results", "It is not possible to index more than one column total"]'::jsonb,1,'Index value must be assessed against storage,cache and relevant write costs instead of indexing every available field.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-20-why-indexes-exist-6'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-20-why-indexes-exist-7' and test_id<>'pt-dbms-sql-20-why-indexes-exist') then raise exception 'Question ID collision: %', 'tq-dbms-sql-20-why-indexes-exist-7'; end if;
